/* ============================================================
 * GLOBAL_COMMAND_CRASH_PROTECTION_V1
 * ============================================================ */

globalThis.__lastCommandContext = null;

function __formatFatalError(error) {

  const raw =
    error?.stack ||
    error?.message ||
    String(error);

  return String(raw)
    .split("\n")
    .map(x => x.trim())
    .filter(Boolean)
    .slice(0, 3)
    .join("\n");
}

async function __reportFatalCommand(error) {

  const ctx =
    globalThis.__lastCommandContext;

  console.error(
    "❌ ERROR PROTEGIDO:",
    error?.stack || error
  );

  if (
    !ctx ||
    !ctx.sock ||
    !ctx.jid
  ) {
    return;
  }

  try {

    await ctx.sock.sendMessage(
      ctx.jid,
      {
        text:
          "[Error comando]\n*" +
          __formatFatalError(error) +
          "*"
      }
    );

  } catch (sendError) {

    console.error(
      "⚠️ ERROR ENVIANDO ERROR:",
      sendError?.message || sendError
    );

  }

}

/*
 * IMPORTANTE:
 * No hacemos process.exit().
 *
 * Una excepción no controlada ya no debe matar
 * todo el bot.
 */

process.on(
  "uncaughtException",
  error => {

    __reportFatalCommand(error)
      .catch(() => {});

  }
);

process.on(
  "unhandledRejection",
  error => {

    __reportFatalCommand(error)
      .catch(() => {});

  }
);

