function getUserLanguage(sender) {
  if (!sender) return DEFAULT_LANGUAGE;
  const lang = db.users?.[sender]?.language;
  if (lang && I18N_STRINGS[lang]) return lang;
  return DEFAULT_LANGUAGE;
}

function setUserLanguage(sender, lang) {
  if (!sender || !I18N_STRINGS[lang]) return false;
  if (!db.users?.[sender]) return false;
  db.users[sender].language = lang;
  return true;
}

function normalizeLangText(text) {
  const map = {
    '\u1972': 'a', '\u1D72': 'a',
    '\u1974': 'c', '\u1D74': 'c',
    '\u13E7': 'd', '\u13A7': 'd', '\u13B8': 'd',
    '\u1971': 'e', '\u1D71': 'e',
    '\u0261': 'g', '\u0262': 'g',
    '\u03B9': 'i', '\u026A': 'i',
    '\u1963': 'l', '\u1D63': 'l', '\u029F': 'l',
    '\u0271': 'm', '\u1D0D': 'm',
    '\u1952': 'n', '\u1D52': 'n', '\u0274': 'n',
    '\u03C1': 'p', '\u1D18': 'p',
    '\u027E': 'r', '\u0280': 'r',
    '\u03C5': 'u', '\u1959': 'u', '\u1D59': 'u', '\u1D1C': 'u',
    '\u03BD': 'v', '\u1D20': 'v',
    '\u10E7': 'y', '\u028F': 'y',
    '\u03C3': 'o', '\u1D0F': 'o',
    '\u1472': 'b', '\u0299': 'b', '\u1D47': 'b',
    '\u1D00': 'a',
    '\u1D04': 'c',
    '\u1D05': 'd',
    '\u1D07': 'e',
    '\uA730': 'f',
    '\u029C': 'h',
    '\u1D0A': 'j',
    '\u1D0B': 'k',
    '\u01EB': 'q',
    '\uA731': 's', '\u0282': 's',
    '\u1D1B': 't', '\u1D57': 't',
    '\u1D21': 'w',
    '\u1D22': 'z'
  };
  let result = '';
  for (const ch of text) {
    result += map[ch] || ch;
  }
  return result;
}

function toBoldLang(text) {
  let result = '';
  let i = 0;
  while (i < text.length) {
    const ch = text[i];

    // BOLD_AT_MENTION_V1: no bolear @numero (rompe menciones de WhatsApp)
    if (ch === '@' && /[0-9]/.test(text[i + 1] || '')) {
      result += '@';
      i++;
      while (i < text.length && /[0-9]/.test(text[i])) {
        result += text[i];
        i++;
      }
      continue;
    }
    if (ch === '\u0060') {
      const end = text.indexOf('\u0060', i + 1);
      if (end !== -1) {
        const inner = text.slice(i + 1, end);
        if (/^(EN|JP|ES)$/i.test(inner)) {
          result += '\u0060' + inner + '\u0060';
        } else if (/^\d+$/.test(inner)) {
          result += '\u0060' + inner + '\u0060';
        } else if (/^\d{1,3}([.,]\d{3})+$/.test(inner)) {
          let b = '';
          for (const c2 of inner) {
            const cc = c2.charCodeAt(0);
            if (cc >= 48 && cc <= 57) b += String.fromCodePoint(0x1D7CE + cc - 48);
            else b += c2;
          }
          result += '\u0060' + b + '\u0060';
        } else {
          let b = '';
          for (const c2 of inner) {
            const cc = c2.charCodeAt(0);
            if (cc >= 65 && cc <= 90) b += String.fromCodePoint(0x1D400 + cc - 65);
            else if (cc >= 97 && cc <= 122) b += String.fromCodePoint(0x1D41A + cc - 97);
            else if (cc >= 48 && cc <= 57) b += String.fromCodePoint(0x1D7CE + cc - 48);
            else b += c2;
          }
          result += '\u0060' + b + '\u0060';
        }
        i = end + 1;
        continue;
      }
    }
    const code = ch.charCodeAt(0);
    if (code >= 65 && code <= 90) result += String.fromCodePoint(0x1D400 + code - 65);
    else if (code >= 97 && code <= 122) result += String.fromCodePoint(0x1D41A + code - 97);
    else if (code >= 48 && code <= 57) result += String.fromCodePoint(0x1D7CE + code - 48);
    else result += ch;
    i++;
  }
  return result;
}
function toGoodFancy(text) {
  const map = {
    'a': '\u1972', 'b': '\u1472', 'c': '\u1974',
    'd': '\u13E7', 'e': '\u1971', 'g': '\u0261',
    'i': '\u03B9', 'l': '\u1963', 'm': '\u0271',
    'n': '\u1952', 'p': '\u03C1', 'r': '\u027E',
    'u': '\u03C5', 'v': '\u03BD', 'y': '\u10E7'
  };
  let result = '';
  for (const ch of String(text || '')) {
    result += map[ch] || ch;
  }
  return result;
}

function applyLangStyle(text, lang) {
  if (!lang) lang = 'ES';
  const s = String(text || '');
  if (!s) return text;
  const plain = normalizeLangText(s);
  // FANCY_UNIFIED_V1: todos los idiomas usan el mismo fancy ES.
  return toGoodFancy(plain);
}

function i18n(sender, key, vars = {}) {
  const lang = getUserLanguage(sender);
  const dict = I18N_STRINGS[lang] || I18N_STRINGS[DEFAULT_LANGUAGE];
  let text = dict[key] ?? I18N_STRINGS[DEFAULT_LANGUAGE][key] ?? key;
  for (const [k, v] of Object.entries(vars)) {
    text = text.split(`{${k}}`).join(String(v));
  }
  return applyLangStyle(text, lang);
}

function tCmd(sender, es, en) {
  const lang = getUserLanguage(sender);
  return applyLangStyle(lang === 'EN' ? en : es, lang);
}

function t(sender, key, vars) {
  return i18n(sender, key, vars);
}
function tRaw(sender, key, vars = {}) {
  const lang = getUserLanguage(sender);
  const dict = I18N_STRINGS[lang] || I18N_STRINGS[DEFAULT_LANGUAGE];
  let text = dict[key] ?? I18N_STRINGS[DEFAULT_LANGUAGE][key] ?? key;
  for (const [k, v] of Object.entries(vars)) {
    text = text.split(`{${k}}`).join(String(v));
  }
  return text;
}

function resolveLanguageInput(input) {
  if (!input) return null;
  const raw = String(input).trim().toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  if (/^[a-z]{2}$/.test(raw)) {
    const code = raw.toUpperCase();
    if (I18N_STRINGS[code]) return code;
  }
  for (const [code, aliases] of Object.entries(I18N_LANGUAGE_ALIASES)) {
    if (!I18N_STRINGS[code]) continue;
    if (aliases.includes(raw)) return code;
  }
  for (const [code, aliases] of Object.entries(I18N_LANGUAGE_ALIASES)) {
    if (!I18N_STRINGS[code]) continue;
    for (const alias of aliases) {
      if (alias.length >= 4 && raw.length >= 3 && raw.includes(alias)) return code;
      if (alias.length >= 4 && raw.length >= 3 && alias.includes(raw)) return code;
    }
  }
  return null;
}

function countCommandsForLang(lang) {
  const set = I18N_TRANSLATED_COMMANDS[lang];
  if (!set) return '0';
  if (set.has('*')) return '∞';
  return String(set.size);
}

function buildLanguageStats() {
  const counts = { ES: 0, EN: 0, JP: 0 };
  let total = 0;
  for (const user of Object.values(db.users || {})) {
    if (!user || typeof user !== 'object') continue;
    total++;
    const lang = user.language;
    if (lang && counts[lang] !== undefined) counts[lang]++;
    else counts.ES++;
  }
  return { users: counts, total };
}

async function handleLanguageCommand(sock, msg, sender, args) {
  const jid = msg.key.remoteJid;
  const user = initUser(sender, msg.pushName);
  if (!user) {
    return sock.sendMessage(jid, { text: '❌ No se pudo cargar tu cuenta.' }, { quoted: msg });
  }
  const input = args.join(' ').trim();
  if (!input) {
    const stats = buildLanguageStats();
    const title = t(sender, 'lang.menu.title');
    const header = t(sender, 'lang.menu.header');
    const footer = t(sender, 'lang.menu.footer');
    const langOrder = ['EN', 'JP', 'ES'];
    const lines = langOrder.map(code => {
      const users = stats.users[code] || 0;
      const cmds = countCommandsForLang(code);
      return t(sender, 'lang.menu.line', { code, users, cmds });
    });
    const globalLine = t(sender, 'lang.menu.global', { total: stats.total });
    const text = title + '\n\n' + header + '\n' + lines.join('\n') + '\n' + globalLine + '\n\n' + footer;
    return sock.sendMessage(jid, { text }, { quoted: msg });
  }
  const code = resolveLanguageInput(input);
  if (!code) {
    return sock.sendMessage(jid, { text: t(sender, 'lang.invalid') }, { quoted: msg });
  }
  const oldLang = getUserLanguage(sender);
  setUserLanguage(sender, code);
  saveDB();
  const displayName = (I18N_DISPLAY_NAMES[oldLang] || I18N_DISPLAY_NAMES.ES)[code] || code;
  const successText = (I18N_STRINGS[oldLang] || I18N_STRINGS.ES)['lang.success'].split('{lang}').join(displayName);
  const styledSuccess = applyLangStyle(successText, oldLang);
  return sock.sendMessage(jid, { text: styledSuccess }, { quoted: msg });
}


