// ============================================================
// INDEX_UPDATE_NOTIFIER_V1
// Detecta cuando index.js crece >= 100 bytes desde la ultima
// notificacion y avisa en todos los grupos donde esta el bot
// (principal + subbots). Solo avisa una vez por actualizacion.
// ============================================================
const INDEX_FILE_PATH = path.join(process.cwd(), 'dist', 'index.js');
const INDEX_UPDATE_MIN_GROWTH = 100;
const INDEX_UPDATE_CHECK_MS = 60 * 1000;

db.indexSizeNotifier ??= { lastSize: 0, lastNotifiedAt: 0 };

let __notifyingIndex = false;

async function notifyIndexUpdate(isStartup = false) {
  if (__notifyingIndex) return;
  __notifyingIndex = true;
  try {
    const currentSize = fs.statSync(INDEX_FILE_PATH).size;
    const lastSize = Number(db.indexSizeNotifier.lastSize) || 0;

    if (!lastSize) {
      db.indexSizeNotifier.lastSize = currentSize;
      saveDB();
      console.log('[INDEX UPDATE] Baseline inicial:', currentSize, 'bytes');
      return;
    }

    const delta = currentSize - lastSize;
    const absDelta = Math.abs(delta);
    const minChange = isStartup ? 1 : INDEX_UPDATE_MIN_GROWTH;

    if (absDelta < minChange) {
      if (isStartup) {
        console.log('[INDEX UPDATE] Startup: sin cambios (' + currentSize + ' bytes)');
      }
      return;
    }

    const sockets = [];
    const seenSocks = new Set();
    const addSock = (s, label) => {
      if (!s || !s.user || !s.user.id || seenSocks.has(s)) return;
      seenSocks.add(s);
      sockets.push({ sock: s, label });
    };
    addSock(globalThis.MAIN_BOT_SOCK, 'MAIN');
    const subs = globalThis.SUBBOT_SOCKETS;
    if (subs instanceof Map) {
      for (const [key, s] of subs.entries()) addSock(s, 'SUB:' + key);
    } else if (subs && typeof subs === 'object') {
      for (const [key, s] of Object.entries(subs)) addSock(s, 'SUB:' + key);
    }

    if (!sockets.length) {
      console.log('[INDEX UPDATE] Sin sockets conectados. Reintentando en proximo ciclo.');
      return;
    }

    const groupSet = new Set();
    for (const entry of sockets) {
      try {
        const groups = await entry.sock.groupFetchAllParticipating();
        for (const gid of Object.keys(groups || {})) {
          groupSet.add(gid);
        }
      } catch (e) {
        console.log('[INDEX UPDATE] Error obteniendo grupos de', entry.label + ':', e?.message || e);
      }
    }

    if (!groupSet.size) {
      console.log('[INDEX UPDATE] Sin grupos detectados. Reintentando en proximo ciclo.');
      return;
    }

    const direction = delta >= 0 ? '+' : '-';
    console.log('[INDEX UPDATE] Detectado' + (isStartup ? ' (startup)' : '') + ':', lastSize, '->', currentSize, '(' + direction + absDelta + ' bytes)');
    console.log('[INDEX UPDATE] Enviando a', groupSet.size, 'grupos...');

    // ============================================================
    // MENSAJE CON EL ESTILO CORRECTO
    // Usa __gifpaseFancy() que ya existe en index.js
    // Borde: U+22B9 U+22B1 = el bueno (NO U+2299 U+229F)
    // ============================================================
    const fmt = n => Number(n).toLocaleString('en-US').replace(/,/g, '.');
    const deltaStr = direction + fmt(absDelta);
    const _fancy = (typeof __gifpaseFancy === 'function')
      ? __gifpaseFancy
      : (s) => String(s);
    const _border = '\u22B9\u22B1\u2022\u2022\u2022\u300A \u272E \u300B\u2022\u2022\u2022\u22B0\u22B9';
    const _borderFull = _border + _border;
    const text =
      _borderFull + '\n' +
      '`' + _fancy('Mio Haimiya') + '` ' + _fancy('Fue actualizado') + '.\n' +
      '> ' + _fancy('Bytes Anteriores') + ' `' + fmt(lastSize) + '`\n' +
      '> ' + _fancy('Bytes Ahora') + ' `' + fmt(currentSize) + '`\n' +
      '> ' + _fancy('Diferencia') + ' `' + deltaStr + '`\n' +
      _borderFull;

    let sent = 0;
    let errors = 0;

    for (const gid of groupSet) {
      let sockToUse = null;
      for (const entry of sockets) {
        try {
          const meta = await entry.sock.groupMetadata(gid);
          if (meta && meta.id) { sockToUse = entry.sock; break; }
        } catch {}
      }
      if (!sockToUse) continue;

      try {
        await sockToUse.sendMessage(gid, { text });
        sent++;
        await new Promise(r => setTimeout(r, 250));
      } catch (e) {
        errors++;
        console.log('[INDEX UPDATE] Error enviando a', gid + ':', e?.message || e);
      }
    }

    console.log('[INDEX UPDATE] Enviado:', sent, '| Errores:', errors);

    db.indexSizeNotifier.lastSize = currentSize;
    db.indexSizeNotifier.lastNotifiedAt = Date.now();
    saveDB();
  } catch (e) {
    console.error('[INDEX UPDATE] Error general:', e?.message || e);
  } finally {
    __notifyingIndex = false;
  }
}
// Startup check: esperar a que MAIN_BOT_SOCK este listo, luego notificar
(function waitStartupIndexCheck() {
  let attempts = 0;
  const maxAttempts = 20;
  const check = setInterval(() => {
    attempts++;
    if (globalThis.MAIN_BOT_SOCK && globalThis.MAIN_BOT_SOCK.user && globalThis.MAIN_BOT_SOCK.user.id) {
      clearInterval(check);
      setTimeout(() => {
        notifyIndexUpdate(true).catch(() => {});
      }, 5000);
    } else if (attempts >= maxAttempts) {
      clearInterval(check);
      console.log('[INDEX UPDATE] Startup: timeout esperando conexion, siguiente ciclo lo hara');
    }
  }, 3000);
})();

if (!global.__indexUpdateTimer) {
  global.__indexUpdateTimer = setInterval(() => {
    notifyIndexUpdate().catch(() => {});
  }, INDEX_UPDATE_CHECK_MS);
  console.log('[INDEX UPDATE] Notificador iniciado (chequeo cada ' + (INDEX_UPDATE_CHECK_MS / 1000) + 's)');
}


