function liveCharValue(h) {
  if (!h) return 0;
  const key = typeof h === 'string' ? h : h?.key;
  const live = key ? characterKeyMap.get(key) : null;
  const base = (typeof h === 'object') ? h.value : null;
  return Number(live?.value ?? base ?? 0);
}
function liveCharName(h) {
  if (!h) return 'Desconocido';
  const key = typeof h === 'string' ? h : h?.key;
  const live = key ? characterKeyMap.get(key) : null;
  const base = (typeof h === 'object') ? h.name : null;
  return String(live?.name ?? base ?? 'Desconocido');
}

