function loadCharactersCache() {
  try {
    charactersCache = JSON.parse(
      fs.readFileSync(CHARACTERS_FILE, 'utf8')
    );

    characterMap.clear();
    characterKeyMap.clear();

    for (const c of charactersCache) {
      characterMap.set(c.name.toLowerCase(), c);
      characterKeyMap.set(c.key, c);

      if (!c.claimedBy) c.claimedBy = {};
      if (typeof c.claimedBy !== 'object') c.claimedBy = {};

      if (!Number.isFinite(Number(c.coinGen)) || Number(c.coinGen) <= 0) {
        const v = Number(c.value) || 0;
        if (v > 0) {
          c.coinGen = Math.floor(55 * v);
        }
      }

      // FIX_CREATORS_AUTO_V1: asignar owner principal si creator es inválido
      if (!c.creator || String(c.creator).trim() === '' ||
          ['null', 'undefined', 'desconocido', 'unknown', 'n/a', 'na', 'none']
            .includes(String(c.creator).trim().toLowerCase())) {
        try {
          const __op = (typeof getMainOwner === 'function') ? getMainOwner() : (db.primaryOwner || OWNER_NUMBER);
          if (__op) c.creator = String(__op).trim();
        } catch (e) {}
      }

      // FIX_RARITY_NORMAL_TO_COMUN_V1
      if (c.rarity && String(c.rarity).trim().toLowerCase() === 'normal') {
        c.rarity = 'Comun';
      }
    }

    buildOwnerIndex();

    rebuildHarems(); // ← AQUÍ

  } catch {
    charactersCache = [];
  }
}

