function smartSearch(list, query, getName){

  query =
    query
      .toLowerCase()
      .trim();

  if (!query)
    return null;

  const normalize = str =>
    str
      .toLowerCase()
      .replace(/[^a-z0-9 ]/g,' ')
      .replace(/\s+/g,' ')
      .trim();

  const q =
    normalize(query);

  let best = null;
  let score = -1;

  for (const item of list){

    const name =
      normalize(
        getName(item)
      );

    let s = 0;

    if (name === q)
      s = 1000;

    else if (
      name.startsWith(q + ' ')
    )
      s = 900;

    else if (
      name.startsWith(q)
    )
      s = 800;

    else if (
      name.includes(' ' + q + ' ')
    )
      s = 700;

    else if (
      name.includes(q)
    )
      s = 600;

    else{

      const words =
        q.split(' ');

      let ok = true;

      for (const w of words){

        if (!name.includes(w)){
          ok = false;
          break;
        }

      }

      if (ok)
        s = 500;

    }

    if (s > score){

      score = s;
      best = item;

    }

  }

  return best;

}

