function stripAccents(s) {
  return String(s || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function findCharacter(query){

  const raw = String(query || "").trim();
  if (!raw) return null;

  const lower = raw.toLowerCase();

  // 1) Coincidencia exacta por mapa
  let char = characterMap.get(lower);
  if (char) return char;

  // 2) Coincidencia exacta normalizada (sin acentos)
  const target = stripAccents(raw).toLowerCase().trim();

  for (const c of charactersCache) {
    const normalized = stripAccents(c.name || "").toLowerCase().trim();
    if (normalized === target) return c;
  }

  // 3) startsWith normalizado
  char = charactersCache.find(c => {
    const normalized = stripAccents(c.name || "").toLowerCase().trim();
    return normalized.startsWith(target);
  });
  if (char) return char;

  // 4) includes normalizado
  char = charactersCache.find(c => {
    const normalized = stripAccents(c.name || "").toLowerCase().trim();
    return normalized.includes(target);
  });

  return char || null;
}

function findSeries(query){

  query =
    query
      .toLowerCase()
      .trim();

  for(const serie of seriesCache.values()){

    if(
      serie.name
        .toLowerCase()
        .startsWith(query)
    ){
      return serie;
    }

    if(
      serie.name
        .toLowerCase()
        .includes(query)
    ){
      return serie;
    }

  }

  for(const official in db.seriesAliases){

    const aliases =
      db.seriesAliases[official];

    if(
      official
        .toLowerCase()
        .startsWith(query)
    ){

      return seriesCache.get(
        official.toLowerCase()
      );

    }

    if(
      aliases.some(
        a =>
          a.includes(query)
      )
    ){

      return seriesCache.get(
        official.toLowerCase()
      );

    }

  }

  return null;

}

