// ━━━━━━━ SISTEMA DE SERIES ━━━━━━━
const seriesCache = new Map(); // serieName -> { name, characters: Set<key> }

// ============================================================
// PROTECCION DE SERIES EN DATABASE.JSON
// - Copia todas las series en db.seriesBackup
// - Restaura series que perdieron su archivo JSON
// ============================================================
function sincronizarSeriesDatabase() {
  try {
    db.seriesBackup ??= {};

    for (const [key, serie] of seriesCache.entries()) {
      db.seriesBackup[key] = {
        id: Number(serie.id) || 0,
        name: String(serie.name || ''),
        characters: Array.from(serie.characters || []),
        owner: serie.owner || null,
        updatedAt: Date.now()
      };
    }

    if (typeof saveDB === 'function') saveDB();
  } catch (e) {
    console.error('[SERIES BACKUP]', e);
  }
}

function restaurarSeriesDesdeBackup() {
  if (!db.seriesBackup || typeof db.seriesBackup !== 'object') {
    return;
  }

  fs.mkdirSync(SERIES_DIR, { recursive: true });

  let restauradas = 0;

  for (const [key, backup] of Object.entries(db.seriesBackup)) {
    if (!backup || !backup.name) continue;
    if (seriesCache.has(key)) continue;

    const characters = new Set();
    for (const rawKey of (backup.characters || [])) {
      const charKey = String(rawKey || '').trim();
      if (charKey && characterKeyMap.has(charKey)) {
        characters.add(charKey);
      }
    }

    const serie = {
      id: Number(backup.id) || 0,
      name: String(backup.name || '').trim(),
      characters,
      owner: backup.owner || null
    };

    seriesCache.set(key, serie);

    try {
      const fileName = key.replace(/[^\w]/g, '_');
      fs.writeFileSync(
        path.join(SERIES_DIR, fileName + '.json'),
        JSON.stringify(
          {
            id: serie.id,
            name: serie.name,
            owner: serie.owner,
            characters: [...serie.characters]
          },
          null,
          2
        )
      );
    } catch (e) {
      console.error('[SERIES RESTORE]', e);
    }

    restauradas++;
  }

  if (restauradas > 0) {
    console.log('[SERIES BACKUP] Series restauradas:', restauradas);
  }
}
// SERIES_RECONCILE_V1
function normalizeSerieKey(name) {
  return String(name || '')
    .trim()
    .replace(/\s+/g, ' ')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function slugifySerieName(name) {
  return String(name || '')
    .trim()
    .replace(/\s+/g, ' ')
    .toLowerCase()
    .replace(/[^\w]/g, '_');
}

function reconciliarSeries() {
  try {
    if (!Array.isArray(charactersCache) || !charactersCache.length) {
      return null;
    }

    characterKeyMap.clear();
    for (const char of charactersCache) {
      if (char && char.key) {
        characterKeyMap.set(String(char.key), char);
      }
    }

    const animeGroups = new Map();
    for (const char of charactersCache) {
      const animeName = String(char.anime || '').trim();
      if (!animeName) continue;
      const normKey = normalizeSerieKey(animeName);
      if (!normKey) continue;
      if (!animeGroups.has(normKey)) {
        animeGroups.set(normKey, { canonicalName: animeName, keys: new Set() });
      }
      animeGroups.get(normKey).keys.add(String(char.key));
    }

    fs.mkdirSync(SERIES_DIR, { recursive: true });
    const files = fs.readdirSync(SERIES_DIR).filter(f => f.endsWith('.json'));
    const fileSeries = new Map();
    for (const file of files) {
      try {
        const filePath = path.join(SERIES_DIR, file);
        const data = JSON.parse(fs.readFileSync(filePath, 'utf8'));
        if (!data || !data.name) continue;
        const normKey = normalizeSerieKey(data.name);
        if (!normKey) continue;
        if (!fileSeries.has(normKey)) {
          fileSeries.set(normKey, {
            name: String(data.name).trim(),
            id: Number(data.id) || 0,
            keys: new Set(),
            fileName: file
          });
        }
        const entry = fileSeries.get(normKey);
        if (Array.isArray(data.characters)) {
          for (const k of data.characters) {
            const key = String(k || '').trim();
            if (key) entry.keys.add(key);
          }
        }
        if (entry.id === 0 && Number(data.id) > 0) entry.id = Number(data.id);
      } catch (e) {
        console.warn('[SERIES RECONCILE] Archivo invalido:', file, e.message);
      }
    }

    const allNormKeys = new Set([...animeGroups.keys(), ...fileSeries.keys()]);

    let maxId = 0;
    for (const s of fileSeries.values()) if (s.id > maxId) maxId = s.id;
    for (const serie of seriesCache.values()) {
      const n = Number(serie.id);
      if (Number.isInteger(n) && n > maxId) maxId = n;
    }

    const nuevasSeries = new Map();
    let creadas = 0, actualizadas = 0, sinCambios = 0;

    for (const normKey of allNormKeys) {
      const fromFile = fileSeries.get(normKey);
      const fromChars = animeGroups.get(normKey);
      const canonicalName = (fromFile && fromFile.name) || (fromChars && fromChars.canonicalName) || '';
      if (!canonicalName) continue;

      const validKeys = new Set();
      if (fromChars) for (const k of fromChars.keys) if (characterKeyMap.has(k)) validKeys.add(k);
      if (fromFile) for (const k of fromFile.keys) if (characterKeyMap.has(k)) validKeys.add(k);

      let id = (fromFile && fromFile.id) || 0;
      if (!id || id <= 0) id = ++maxId;

      const existed = fileSeries.has(normKey) || seriesCache.has(normKey);
      nuevasSeries.set(normKey, { id, name: canonicalName, characters: validKeys });

      const fileName = slugifySerieName(canonicalName) + '.json';
      const filePath = path.join(SERIES_DIR, fileName);

      let needsWrite = false;
      if (!fromFile) {
        needsWrite = true;
      } else {
        if (fromFile.keys.size !== validKeys.size) needsWrite = true;
        else {
          for (const k of validKeys) { if (!fromFile.keys.has(k)) { needsWrite = true; break; } }
        }
        if (Number(fromFile.id) !== id) needsWrite = true;
        if (fromFile.fileName !== fileName) needsWrite = true;
      }

      if (needsWrite) {
        fs.writeFileSync(filePath, JSON.stringify({ id, name: canonicalName, characters: [...validKeys] }, null, 2));
        if (fromFile && fromFile.fileName && fromFile.fileName !== fileName) {
          try { fs.unlinkSync(path.join(SERIES_DIR, fromFile.fileName)); } catch {}
        }
        if (existed) actualizadas++; else creadas++;
      } else {
        sinCambios++;
      }
    }

    seriesCache.clear();
    for (const serie of nuevasSeries.values()) {
      seriesCache.set(normalizeSerieKey(serie.name), serie);
    }

    if (creadas > 0 || actualizadas > 0) {
      console.log('[SERIES RECONCILE] Creadas: ' + creadas + ', actualizadas: ' + actualizadas + ', sin cambios: ' + sinCambios + ', total: ' + nuevasSeries.size);
    }

    return { creadas, actualizadas, sinCambios, total: nuevasSeries.size };
  } catch (error) {
    console.error('[SERIES RECONCILE] ERROR:', error);
    return null;
  }
}

function loadSeries() {

  console.log('📚 Cargando sistema de series...');

  seriesCache.clear();

  /*
   * ============================================================
   * LOAD SERIES DEFINITIVO
   * ============================================================
   *
   * Las series almacenan únicamente las keys.
   * Los personajes reales se obtienen desde characterKeyMap.
   *
   * No se eliminan keys del JSON.
   * Solo se ignoran temporalmente las que realmente no existan
   * en characters.json.
   */

  if (!fs.existsSync(SERIES_DIR)) {

    console.log(
      '⚠️ SERIES_DIR no existe:',
      SERIES_DIR
    );

    return;

  }

  /*
   * Asegurar que characters.json esté cargado.
   */

  if (
    !Array.isArray(charactersCache) ||
    !charactersCache.length
  ) {

    loadCharactersCache();

  }

  /*
   * Reconstruir mapa por seguridad.
   */

  characterKeyMap.clear();

  for (const character of charactersCache) {

    if (
      character &&
      character.key
    ) {

      characterKeyMap.set(
        String(character.key),
        character
      );

    }

  }

  const files =
    fs.readdirSync(SERIES_DIR)
      .filter(
        file =>
          file.endsWith('.json')
      );

  console.log(
    '📁 Archivos de series:',
    files.length
  );

  let cargadas = 0;
  let personajesAsociados = 0;

  for (const file of files) {

    try {

      const filePath =
        path.join(
          SERIES_DIR,
          file
        );

      const data =
        JSON.parse(
          fs.readFileSync(
            filePath,
            'utf8'
          )
        );

      if (
        !data ||
        !data.name ||
        !Array.isArray(
          data.characters
        )
      ) {

        console.log(
          '⚠️ Serie ignorada:',
          file
        );

        continue;

      }

      /*
       * ID permanente.
       */

      const id =
        Number(data.id);

      /*
       * Mantener solamente IDs válidos.
       * Si falta el ID, se conserva 0 temporalmente
       * para no alterar los archivos desde aquí.
       */

      const serieId =
        Number.isInteger(id) &&
        id > 0
          ? id
          : 0;

      /*
       * Construir Set usando las keys del JSON.
       */

      const characters =
        new Set();

      for (
        const rawKey
        of data.characters
      ) {

        const key =
          String(
            rawKey || ''
          ).trim();

        if (!key) {
          continue;
        }

        /*
         * La key debe existir realmente
         * en characters.json.
         */

        if (
          characterKeyMap.has(key)
        ) {

          characters.add(key);

          personajesAsociados++;

        }

      }

      const serie = {

        id: serieId,

        name:
          String(
            data.name
          ).trim(),

        characters

      };

      seriesCache.set(
        serie.name.toLowerCase(),
        serie
      );

      cargadas++;

      console.log(
        '✓ Serie:',
        serie.id,
        '->',
        serie.name,
        '| Personajes:',
        serie.characters.size
      );

    } catch (err) {

      console.error(
        '❌ Error cargando:',
        file,
        err.message
      );

    }

  }

  console.log('');
  console.log(
    '✓ Series cargadas:',
    cargadas
  );

  console.log(
    '➢ Asociaciones cargadas:',
    personajesAsociados
  );

}

