// HAREM_STARTUP_AUDIT_V1
// Detecta inconsistencias entre db.groups[].harems[user] y char.claimedBy
// NO modifica nada - solo loguea para que el owner ejecute /fixharems
setTimeout(() => {
  try {
    let mismatchTotal = 0;
    const samples = [];
    const sample = (obj) => { if (samples.length < 8) samples.push(obj); };

    for (const char of charactersCache) {
      if (!char || !char.claimedBy) continue;
      for (const [gid, claim] of Object.entries(char.claimedBy)) {
        if (!claim || !claim.user) continue;
        const harem = db.groups?.[gid]?.harems?.[claim.user];
        if (!Array.isArray(harem)) {
          mismatchTotal++;
          sample({ type: 'claim_no_harem', char: char.key, gid, user: claim.user });
          continue;
        }
        if (!harem.some(c => c && c.key === char.key)) {
          mismatchTotal++;
          sample({ type: 'claim_missing_in_harem', char: char.key, gid, user: claim.user });
        }
      }
    }

    for (const gid of Object.keys(db.groups || {})) {
      const harems = db.groups[gid]?.harems;
      if (!harems || typeof harems !== 'object') continue;
      for (const [user, harem] of Object.entries(harems)) {
        if (!Array.isArray(harem)) continue;
        for (const h of harem) {
          if (!h || !h.key) continue;
          const c = characterKeyMap.get(h.key);
          if (!c) continue;
          const owner = c.claimedBy?.[gid]?.user;
          if (owner !== user) {
            mismatchTotal++;
            sample({ type: 'harem_without_claim', char: h.key, gid, user, realOwner: owner });
          }
        }
      }
    }

    if (mismatchTotal > 0) {
      console.warn('[HAREM AUDIT] Inconsistencias detectadas:', mismatchTotal);
      for (const s of samples) console.warn('[HAREM AUDIT] Ejemplo:', JSON.stringify(s));
      console.warn('[HAREM AUDIT] >>> Ejecuta /fixharems como owner para reparar <<<');
    } else {
      console.log('[HAREM AUDIT] Harems sincronizados correctamente (0 inconsistencias).');
    }
  } catch (e) {
    console.warn('[HAREM AUDIT] Error:', e?.message || e);
  }
}, 20000);

