const DEATH_API_BASE = process.env.DEATH_API_BASE || 'https://deathapi.optishield.uk';
const DEATH_API_KEY = process.env.DEATH_API_KEY || 'esd_owner_esdeath_7f3a9c2e1b8d4f6a0e5c9b7d3a1f8e2c';

async function deathApiTikTok(url) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 30000);
  try {
    const res = await fetch(DEATH_API_BASE + '/api/tiktok', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': DEATH_API_KEY
      },
      body: JSON.stringify({ url, type: 'video', upload: true }),
      signal: controller.signal
    });
    if (!res.ok) {
      const errText = await res.text().catch(() => '');
      throw new Error('HTTP ' + res.status + (errText ? ': ' + errText.slice(0, 200) : ''));
    }
    const data = await res.json();
    if (!data || data.success !== true || !data.url) {
      throw new Error('Respuesta inválida: ' + JSON.stringify(data).slice(0, 300));
    }
    return data;
  } finally {
    clearTimeout(timer);
  }
}

export async function handleTt(sock, msg, url) {
  const jid = msg.key.remoteJid;
  const estiloNumero = (n) => String(n).split('').map(d => String.fromCodePoint(0x1D7CE + Number(d))).join('');
  const barra = (porcentaje) => {
    const llenos = Math.floor(porcentaje / 10);
    return '[' + '■'.repeat(llenos) + '□'.repeat(10 - llenos) + ']';
  };

  let cargando;
  try { cargando = await sock.sendMessage(jid, { text: barra(0) + ' ' + estiloNumero(0) + '%' }, { quoted: msg }); } catch (e) { return; }

  let animacionActiva = true;
  const animar = async () => {
    let progreso = 0;
    while (animacionActiva && progreso < 90) {
      progreso = Math.min(progreso + Math.floor(Math.random() * 5) + 1, 90);
      try { await sock.sendMessage(jid, { text: barra(progreso) + ' ' + estiloNumero(progreso) + '%', edit: cargando.key }); } catch (e) {}
      await new Promise(r => setTimeout(r, 250));
    }
  };
  const promesaAnimacion = animar();

  try {
    let videoUrl = null, coverUrl = null, author = 'Desconocido', views = '0', duration = 'Desconocida', title = 'Sin descripción', id = '—', sizeBytes = 0;

    // Intento 1: API DEATH
    try {
      const res = await fetch('https://deathapi.optishield.uk/api/tiktok', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-api-key': 'esd_owner_esdeath_7f3a9c2e1b8d4f6a0e5c9b7d3a1f8e2c' },
        body: JSON.stringify({ url, type: 'video', upload: false }),
        signal: AbortSignal.timeout(15000)
      });
      if (res.ok) {
        const data = await res.json();
        if (data.success && data.url) {
          videoUrl = data.url; coverUrl = data.cover; author = data.author || author; views = Number(data.views || 0).toLocaleString('en-US');
          duration = data.duration || duration; title = data.title || title; id = data.id || id; sizeBytes = data.size_bytes || 0;
        }
      }
    } catch (e) { console.log('[TT] Death API fallo, usando Fallback...'); }

    // Intento 2: Fallback TikWM
    if (!videoUrl) {
      const res = await fetch('https://www.tikwm.com/api/?url=' + encodeURIComponent(url));
      const json = await res.json();
      if (json.code === 0 && json.data && json.data.play) {
        videoUrl = json.data.hdplay || json.data.play; coverUrl = json.data.cover; author = json.data.author?.unique_id || author;
        views = Number(json.data.play_count || 0).toLocaleString('en-US'); duration = (json.data.duration || 0) + 's'; title = json.data.title || title; id = json.data.id || id;
      } else { throw new Error('Ninguna API pudo descargar el video.'); }
    }

    animacionActiva = false; try { await promesaAnimacion; } catch (e) {}
    try { await sock.sendMessage(jid, { text: barra(90) + ' ' + estiloNumero(90) + '%', edit: cargando.key }); } catch (e) {}

    const videoRes = await fetch(videoUrl, { headers: { 'User-Agent': 'Mozilla/5.0', 'Referer': 'https://www.tiktok.com/' } });
    if (!videoRes.ok) throw new Error('HTTP ' + videoRes.status);
    const buffer = Buffer.from(await videoRes.arrayBuffer());
    if (sizeBytes === 0) sizeBytes = buffer.length;
    const sizeHuman = (sizeBytes / 1024 / 1024).toFixed(2) + ' MB';

    try { await sock.sendMessage(jid, { delete: cargando.key }); } catch (e) {}

    if (coverUrl) {
      try {
        const coverRes = await fetch(coverUrl);
        if (coverRes.ok) {
          const cap = '🎬 *TikTok descargado*\n\n👤 Autor: @' + author + '\n👁️ Vistas: ' + views + '\n⏱️ Duración: ' + duration + '\n📦 Peso: ' + sizeHuman + '\n🆔 ID: ' + id + '\n\n✎ *Descripción*\n' + title + '\n\n🔗 ' + url;
          await sock.sendMessage(jid, { image: Buffer.from(await coverRes.arrayBuffer()), caption: cap }, { quoted: msg });
        }
      } catch (e) {}
    }

    const videoCap = '🎬 *TikTok* — @' + author + '\n👁️ ' + views + ' views · ⏱️ ' + duration;
    await sock.sendMessage(jid, { video: buffer, mimetype: 'video/mp4', caption: videoCap }, { quoted: msg });

  } catch (e) {
    animacionActiva = false; try { await promesaAnimacion; } catch (err) {}
    try { await sock.sendMessage(jid, { delete: cargando.key }); } catch (err) {}
    console.error('[TT] Error:', e?.message || e);
    await sock.sendMessage(jid, { text: '● Error al descargar: ' + (e?.message || 'Desconocido') }, { quoted: msg });
  }
}

function buildYtAudioCaption(meta) {
  const safe = (v, def = '') => {
    const s = String(v ?? '').trim();
    return s || def;
  };
  const title = safe(meta.title, 'Audio');
  const views = safe(meta.viewsText, 'Desconocidas');
  const quality = safe(meta.qualityText, 'Desconocida');
  const uploader = safe(meta.uploader, 'Desconocido');
  const duration = safe(meta.duration, 'Desconocida');
  const sizeMB = safe(meta.sizeMB, '0');
  const link = safe(meta.audioUrl, '');
  const dlTime = safe(meta.downloadTime, '');

  const lines = [
    '\u208A\u02DA\u0E51 \u2B27 (\u00AC\u203F\u00AC) \u028F\u1D0F\u1D1C\u1D1B\u1D1C\u0299\u1D07 \u2B27 \u0E51\u02DA\u208A',
    '',
    '\u2A69 \u300A\u2606\u300B`' + title + '`',
    '',
    '\u27E1 \u1D20\u026A\u0455\u1D1B\u1D00\u0455 \u203A `' + views + '`',
    '\u27E1 \u1D04\u1D00\u029F\u026A\u1D05\u1D00\u1D05 \u203A `' + quality + '`',
    '\u27E1 \u1D04\u1D00\u0274\u1D00\u029F \u203A `' + uploader + '`',
    '\u27E1 \u1D05\u1D1C\u0280\u1D00\u1D04\u026A\u00F3\u0274 \u203A `' + duration + '`',
    '\u27E1 \u1D1B\u1D00\u1D0D\u1D00\u00F1\u1D0F \u203A `' + sizeMB + ' \u1D0D\u0299`',
    '\u27E1 \u029F\u026A\u0274\u1D0B \u203A `' + link + '`'
  ];

  if (dlTime) {
    lines.push('\u1D1B\u1D00\u0280\u1D05\u1D07 ' + dlTime);
  }

  lines.push('');
  lines.push('\u2727 \uFF61\uFF9F\u2022\u2508\u2508\u0E51\u2661 \u0E51\u2508\u2508\u2022\uFF9F\uFF61 \u2727');

  return lines.join('\n');
}
export async function handleIg(sock, msg, url) {
  await sock.sendMessage(msg.key.remoteJid, { text: '⏳ Descargando Instagram...' }, { quoted: msg });
  try {
    if (!url.includes('instagram.com')) throw new Error('No es un enlace de Instagram');
    const temp = path.join(TEMP_DIR, `ig_${Date.now()}.mp4`);
    const final = await ytDlpDownloadToFile(url, temp);
    try {
      await sock.sendMessage(msg.key.remoteJid, { video: fs.createReadStream(final), caption: '➢ Video de Instagram (HD)', mimetype: 'video/mp4' }, { quoted: msg });
    } catch {
      const rebuilt = path.join(TEMP_DIR, `ig_rebuilt_${Date.now()}.mp4`);
      await new Promise((resolve, reject) => {
        const proc = spawn(FFMPEG_PATH, ['-i', final, '-c:v', 'libx264', '-preset', 'ultrafast', '-crf', '28', '-c:a', 'aac', '-b:a', '128k', '-movflags', '+faststart', rebuilt], { stdio: 'pipe' });
        proc.on('close', code => code === 0 ? resolve() : reject(new Error('ffmpeg error')));
        proc.on('error', reject);
      });
      await sock.sendMessage(msg.key.remoteJid, { video: fs.createReadStream(rebuilt), caption: '➢ Video de Instagram (comprimido)', mimetype: 'video/mp4' }, { quoted: msg });
      fs.unlinkSync(rebuilt);
    }
    fs.unlinkSync(final);
  } catch (e) { await sock.sendMessage(msg.key.remoteJid, { text: '❌ No se pudo descargar el video de Instagram.' }, { quoted: msg }); }
}

// ━━━━━━━ NUEVO SISTEMA GACHA ━━━━━━━
const CLAIM_CD = 5 * 60 * 1000;  // 5 minutos
const VOTE_CD = 20 * 60 * 1000;  // 20 minutos

function formatTimeAgo(ts) {
  if (!ts || ts === 0) return 'nunca';
  const diff = Date.now() - ts;
  if (diff < 0) return 'ahora';
  const s = Math.floor(diff / 1000), m = Math.floor(s / 60), h = Math.floor(m / 60), d = Math.floor(h / 24);
  if (s < 60) return `hace ${s}s`;
  if (m < 60) return `hace ${m}m ${s % 60}s`;
  if (h < 24) return `hace ${h}h ${m % 60}m ${s % 60}s`;
  return `hace ${d}d ${h % 24}h`;
}
function calcularProbabilidad(valor) {
  const inicial = 60;
  const minimo = 0.1;
  const valorInicial = 50;
  const valorLimite = 18000;
  const progreso = (valor - valorInicial) / (valorLimite - valorInicial);
  return Math.max(minimo, inicial - progreso * (inicial - minimo));
}

function getRandomCharacter(sender, groupId) {
  const user = initUser(sender);
  let totalWeight = 0;
  let selected = null;

  for (const char of charactersCache) {
    if (char.pendienteTag && !(char.tag && String(char.tag).trim())) continue;

    let chance = calcularProbabilidad(Number(char.value) || 0);
    chance = Math.max(0.01, chance);

    totalWeight += chance;
    if (Math.random() * totalWeight < chance) {
      selected = char;
    }
  }

  return selected;
}
  


