export async function handleDelCar(
sock,
msg,
query
) {
try {
loadCars();

if (!query) {
  return sock.sendMessage(
    msg.key.remoteJid,
    {
      text:

`Uso:

/delcar ID

o

/delcar Personaje | Nombre del carro`
},
{
quoted: msg
}
);
}

let car = null;

if (
  /^\d+$/.test(
    query.trim()
  )
) {
  car = carsCache.find(
    c =>
      c.id ===
      Number(
        query.trim()
      )
  );

} else {
  const parts = query
    .split("|")
    .map(
      x => x.trim()
    );

  if (
    parts.length < 2
  ) {
    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:

`Uso:

/delcar Personaje | Nombre del carro`
},
{
quoted: msg
}
);
}

  const personaje =
    parts[0]
      .toLowerCase();

  const nombre =
    parts[1]
      .toLowerCase()
      .replace(
        /[^\w]/g,
        "_"
      );

  car = carsCache.find(
    c =>
      c.personaje.toLowerCase() === personaje &&
      c.key === nombre
  );


if (!car) {
  return sock.sendMessage(
    msg.key.remoteJid,
    {
      text:
        " Vehículo no encontrado."
    },
    {
      quoted: msg
    }
  );
}

// Obtener todas las imágenes existentes.
const rutasValidas =
  Array.isArray(
    car.images
  )
    ? car.images.filter(
        p =>
          typeof p ===
            "string" &&
          fs.existsSync(p)
      )
    : [];

const buffersAlbum = [];

for (
  const ruta of rutasValidas
) {
  try {
    buffersAlbum.push(
      fs.readFileSync(
        ruta
      )
    );

  } catch (e) {
    console.log(
      "⚠️ No se pudo leer imagen del vehículo:",
      ruta,
      e.message
    );
  }
}

const folder = path.join(
  CAR_IMAGES,
  car.personaje
    .toLowerCase(),
  car.key
);

if (
  fs.existsSync(
    folder
  )
) {
  try {
    fs.rmSync(
      folder,
      {
        recursive: true,
        force: true
      }
    );

  } catch (e) {
    console.log(
      "⚠️ Error borrando la carpeta del vehículo:",
      e.message
    );
  }
}

// Eliminar el vehículo de los garajes.
for (
  const uid in db.users
) {
  if (
    Array.isArray(
      db.users[uid].garage
    )
  ) {
    db.users[uid].garage =
      db.users[
        uid
      ].garage.filter(
        x =>
          x !==
          car.key
      );
  }
}


carMap.delete(
  car.key
);

carsCache.splice(
  0,
  carsCache.length,
  ...carsCache.filter(
    x =>
      x.key !== car.key
  )
);

saveCars();
saveDB();

const texto =

` Vehículo eliminado

■ ${car.carName}

➢ ${car.personaje}
🆔 ${car.id}`;

if (
  buffersAlbum.length === 1
) {
  await sock.sendMessage(
    msg.key.remoteJid,
    {
      image:
        buffersAlbum[0],
      caption:
        texto
    },
    {
      quoted: msg
    }
  );

} else if (
  buffersAlbum.length > 1
) {
  await sock.sendMessage(
    msg.key.remoteJid,
    {
      text:
        texto
    },
    {
      quoted: msg
    }
  );

  for (
    const buffer of buffersAlbum
  ) {
    await sock.sendMessage(
      msg.key.remoteJid,
      {
        image:
          buffer
      }
    );
  }

} else {
  await sock.sendMessage(
    msg.key.remoteJid,
    {
      text:
        texto
    },
    {
      quoted: msg
    }
  );
}
}
} catch (error) {
console.log(
"❌ Error en handleDelCar:",
error
);

await sock.sendMessage(
  msg.key.remoteJid,
  {
    text:
      " Ocurrió un error al eliminar el vehículo. " +
      "Revisa la consola para más detalles."
  },
  {
    quoted: msg
  }
).catch(
  () => {}
);

}
}


export async function handlePjAudio(
  sock,
  msg,
  args,
  sender
){
  

  const text =
    args.join(' ');

  if (!text) {
    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
'Uso:\n/pjaudio Nombre del personaje'
      },
      { quoted: msg }
    );
  }

  const ctx =
    msg.message?.extendedTextMessage
      ?.contextInfo;

  const quoted =
    ctx?.quotedMessage;

  if (
    !quoted?.audioMessage
  ){
    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
'Debes responder un audio.'
      },
      { quoted: msg }
    );
  }

  const char =
    findCharacter(text);

  if (!char){
    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
'Personaje no encontrado.'
      },
      { quoted: msg }
    );
  }

  const buffer =
    await downloadMediaMessage(
      {
        message: quoted,
        key:{
          remoteJid:
            msg.key.remoteJid
        }
      },
      'buffer',
      {}
    );

  const dir =
    './audios';

  if (!fs.existsSync(dir))
    fs.mkdirSync(dir);

  const file =
    `${dir}/${char.key}.mp3`;

  fs.writeFileSync(
    file,
    buffer
  );

  db.characterAudios[
    char.key
  ] = file;

  saveDB();

  await sock.sendMessage(
    msg.key.remoteJid,
    {
      text:
`✓ Audio guardado para ${char.name}`
    },
    { quoted: msg }
  );
}

