async function handleAction(sock, msg, actionName) {
  const folder = path.join(ACTIONS_PATH, actionName);
  if (!fs.existsSync(folder)) {
    return await sock.sendMessage(msg.key.remoteJid, { text: 'No hay GIFs para ' + actionName }, { quoted: msg });
  }
  let targetData = __reactionReadTexts(actionName);
  if (!targetData) targetData = ACTION_TEXTS[actionName];
  if (!targetData) {
    return await sock.sendMessage(msg.key.remoteJid, { text: 'Accion no configurada. Usa /giftext ' + actionName + ' / username hace algo a username' }, { quoted: msg });
  }
  let targetName = null, targetJid = null;
  const mentioned = msg.message?.extendedTextMessage?.contextInfo?.mentionedJid || [];
  if (mentioned.length) targetJid = mentioned[0];
  else { const q = msg.message?.extendedTextMessage?.contextInfo; if (q?.participant) targetJid = q.participant; }
  if (targetJid) {
    const user = db.users[targetJid];
    targetName = user?.name || user?.pushName || targetJid.split('@')[0];
  }
  let text;
  if (targetName && Array.isArray(targetData.target) && targetData.target.length) {
    const action = targetData.target[Math.floor(Math.random() * targetData.target.length)];
    text = '*' + (msg.pushName || 'Usuario') + '* ' + action + ' *' + targetName + '*';
  } else if (Array.isArray(targetData.self) && targetData.self.length) {
    const action = targetData.self[Math.floor(Math.random() * targetData.self.length)];
    text = '*' + (msg.pushName || 'Usuario') + '* ' + action;
  } else {
    return await sock.sendMessage(msg.key.remoteJid, { text: 'Configura el texto con /giftext ' + actionName + ' / username hace algo' }, { quoted: msg });
  }
  const senderJid = msg.key.participant || msg.key.remoteJid;
  const senderUser = db.users?.[senderJid] || {};
  const senderGender = senderUser.gender || null;
  const filePath = __reactionPickFile(actionName, senderGender);
  if (!filePath) {
    return await sock.sendMessage(msg.key.remoteJid, { text: 'No hay GIFs disponibles.' }, { quoted: msg });
  }
  await sock.sendMessage(msg.key.remoteJid, { video: fs.readFileSync(filePath), gifPlayback: true, caption: text }, { quoted: msg });
}

export async function handleSetLigue(
  sock,
  msg,
  args,
  sender
){

  if (
    !isMainOwnerId(sender) &&
    !isSecondaryOwnerId(sender)
  ){
    return;
  }

  const query =
    args.join(' ').trim();

  if (!query){

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
`◈ Uso

/setligue Nombre del personaje

Ejemplo

/setligue Nazuna Nanakusa`
      },
      {
        quoted: msg
      }
    );

  }

  const queryNormalized =
    query
      .trim()
      .toLowerCase();

  const character =
    charactersCache.find(
      c =>
        String(c.name || '')
          .trim()
          .toLowerCase() === queryNormalized
    ) ||
    charactersCache.find(
      c =>
        String(c.key || '')
          .trim()
          .toLowerCase() === queryNormalized
    ) ||
    charactersCache.find(
      c =>
        String(c.name || '')
          .toLowerCase()
          .includes(queryNormalized)
    );

  if (!character){

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
'◈ Personaje no encontrado.'
      },
      {
        quoted: msg
      }
    );

  }

  db.waifus ??= {};

  if (
    db.waifus[
      character.key
    ]
  ){

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
` ${character.name} ya está registrada como waifu.`
      },
      {
        quoted: msg
      }
    );

  }

  db.waifus[
    character.key
  ] = {

    key: character.key,

    id: character.id,

    name: character.name,

    anime: character.anime,

    creator: sender,

    createdAt: Date.now(),

    enabled: true

  };

  saveDB();

  await sock.sendMessage(
    msg.key.remoteJid,
    {
      text:
`♡ Waifu registrada

◈ Nombre »
${character.name}

☆ Anime »
${character.anime}

□ ID »
${character.id}

> Disponible para /ligue`
    },
    {
      quoted: msg
    }
  );

}

export async function handleTin(
  sock,
  msg,
  groupId,
  sender
){

  const user =
    initUser(sender);

  const economy =
    getGroupEconomy(
      groupId,
      sender
    );

  if (
    user.training
  ){

    const left =
      user.training.finish -
      Date.now();

    if (left > 0){

      const h =
        Math.floor(
          left / 3600000
        );

      const m =
        Math.floor(
          (left % 3600000)
          / 60000
        );

      const s =
        Math.floor(
          (left % 60000)
          / 1000
        );

      return sock.sendMessage(
        msg.key.remoteJid,
        {
          text:
` Ya estás entrenando.

ⴵ Tiempo restante

${h}h ${m}m ${s}s`
        },
        {
          quoted: msg
        }
      );

    }

    user.level++;

    user.atk +=
      user.training.atk;

    user.def +=
      user.training.def;

    user.vel +=
      user.training.vel;

    user.pres +=
      user.training.pres;

    const oldRank =
      getTrainingRank(
        user.level - 1
      );

    const newRank =
      getTrainingRank(
        user.level
      );

    user.training = null;

    saveDB();

    if (
      oldRank !== newRank
    ){

      await sock.sendMessage(
        msg.key.remoteJid,
        {        
          text:
`AVISO: @${sender.split('@')[0]}

haz subido de rango

Rango:
\`${oldRank}\` ➜ \`${newRank}\``,
          mentions:[
            sender
          ]
        },
        {
          quoted: msg
        }
      );

    }

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
`✓ Entrenamiento completado

✰ Nivel »
\`${user.level}\`

➠ Atk »
\`${user.atk}\`

➡ Dfa »
\`${user.def}\`

⥉ Vel »
\`${user.vel}\`

⊗ Pres »
\`${user.pres}\``
      },
      {
        quoted: msg
      }
    );

  }

  const cost =
    getTrainingCost(
      user.level
    );

  if (
    economy.coins < cost
  ){

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
`◈ Necesitas

¥${cost.toLocaleString()}

para entrenar.`
      },
      {
        quoted: msg
      }
    );

  }

  economy.coins -= cost;

  const stats =
    generateTrainingStats(
      user
    );

  user.training = {

    finish:
      Date.now() +
      3600000,

    cost,

    nextLevel:
      user.level + 1,

    atk:
      stats.atk,

    def:
      stats.def,

    vel:
      stats.vel,

    pres:
      stats.pres

  };

  saveDB();

  // La etapa B continuará aquí.

let pfp;

try{

  pfp =
    await sock.profilePictureUrl(
      sender,
      'image'
    );

}catch{

  pfp =
'https://files.catbox.moe/6m8m6i.jpg';

}

const rank =
  getTrainingRank(
    user.level
  );

const atkBefore =
  user.atk;

const defBefore =
  user.def;

const velBefore =
  user.vel;

const presBefore =
  user.pres;

const atkAfter =
  atkBefore +
  stats.atk;

const defAfter =
  defBefore +
  stats.def;

const velAfter =
  velBefore +
  stats.vel;

const presAfter =
  presBefore +
  stats.pres;

const caption =
`Entrenamiento iniciado

♠︎ *Usuario* : \`${user.name}\`
✢ *Rango* : \`${rank}\`
✰ *Nivel* : \`${user.level} ➪ ${user.level + 1}\`
✎ *Modo* : \`Todos los stats\`
⛀ *Costo dinero* : \`${cost.toLocaleString()}\` coins
ⴵ *Duración* : \`1h\`

✎ *Subida de stats*

➢ *➠ Atk*: \`${atkBefore} → ${atkAfter} (+${stats.atk})\`
➢ *➡ Dfa*: \`${defBefore} → ${defAfter} (+${stats.def})\`
➢ *⥉ Vel*: \`${velBefore} → ${velAfter} (+${stats.vel})\`
➢ *⊗ Pres*: \`${presBefore} → ${presAfter} (+${stats.pres})\`

> Cuando termine usa */tin* para aplicar.`;

await sock.sendMessage(
  msg.key.remoteJid,
  {
    image:{
      url: pfp
    },
    caption
  },
  {
    quoted: msg
  }
);

}

