export async function handleTopCmd(sock, msg, args) {

  const sender = msg.key.participant || msg.key.remoteJid;
  const jid = msg.key.remoteJid;

  // Página solicitada
  let page = parseInt(args[0], 10);

  if (!Number.isInteger(page) || page < 1) {
    page = 1;
  }

  const perPage = 10;

  // Obtener usuarios con comandos registrados
  const users = Object.entries(db.users || {})
    .map(([userJid, user]) => ({
      jid: userJid,
      name: user?.name || 'Usuario',
      commands: Number(user?.totalCommands || 0)
    }))
    .filter(user => user.commands > 0)
    .sort((a, b) => {
      // Mayor cantidad primero
      if (b.commands !== a.commands) {
        return b.commands - a.commands;
      }

      // Si empatan, ordenar por nombre
      return a.name.localeCompare(b.name);
    });

  // Si no hay usuarios
  if (!users.length) {
    return sock.sendMessage(
      jid,
      {
        text: '♧ No hay usuarios con comandos registrados ♧'
      },
      {
        quoted: msg
      }
    );
  }

  const totalPages =
    Math.ceil(users.length / perPage);

  // Página fuera de rango
  if (page > totalPages) {
    return sock.sendMessage(
      jid,
      {
        text:
          tCmd(sender, ` Top de usuarios con más comandos \n\n`, ` Top users with most commands \n\n`) +
          `➢ La página *${page}* no existe.\n` +
          `➢ Hay *${totalPages}* páginas disponibles.`
      },
      {
        quoted: msg
      }
    );
  }

  const start =
    (page - 1) * perPage;

  const pageUsers =
    users.slice(start, start + perPage);

  let text =
    ` Top de usuarios con más comandos \n\n`;

  for (let i = 0; i < pageUsers.length; i++) {

    const user = pageUsers[i];

    const position =
      start + i + 1;

    // Corona especial solamente para el #1
    const crown =
      position === 1
        ? '♔ '
        : '';

    text +=
      `✧ ${crown}${position} » *${user.name}* » \`${user.commands.toLocaleString()}\`\n`;

    if (i < pageUsers.length - 1) {
      text += `\n`;
    }
  }

  text +=
    `\n\n➢ Página *${page}* de *${totalPages}*`;

  // Mostrar siguiente página solamente si existe
  if (page < totalPages) {
    text +=
      `\n➢ Para ver la siguiente página usa: */topcmd ${page + 1}*`;
  }

  // Mostrar página anterior si corresponde
  if (page > 1) {
    text +=
      `\n➢ Página anterior: */topcmd ${page - 1}*`;
  }

  await sock.sendMessage(
    jid,
    {
      text
    },
    {
      quoted: msg
    }
  );
}



export async function handleDelSerie(
  sock,
  msg,
  args,
  sender
){


  const query =
    args.join(' ').trim();

  if (!query){

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
`◈ Uso

/delserie Nombre de la serie`
      },
      {
        quoted: msg
      }
    );

  }
  const serie =
    findSeries(query);

  if (
    !isMainOwnerId(sender) &&
    serie &&
    serie.owner &&
    serie.owner !== sender
  ) {

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
          '◈ Acceso denegado.\\n\\n' +
          '□ Esta serie pertenece al Secondary Owner que la creo.\\n' +
          '◈ Solo su creador puede eliminarla.'
      },
      {
        quoted: msg
      }
    );

  }
  if (!serie){

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
'◈ Serie no encontrada.'
      },
      {
        quoted: msg
      }
    );

  }

  const chars = [];

  for (
    const key of serie.characters
  ){

    const c =
      characterKeyMap.get(key);

    if (c)
      chars.push(c);

  }

  const confirm =
    await sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
`⚠ Confirmación @${sender.split('@')[0]}

¿Está seguro de eliminar la serie?

◈ Serie »
${serie.name}

□ Personajes »
${chars.length}

 Esta acción eliminará:

➢ Todos los personajes
➢ Sus imágenes
➢ Sus videos
➢ Sus reclamaciones
➢ Los alias de la serie

Responde citando este mensaje:

\`si\``,
        mentions:[
          sender
        ]
      },
      {
        quoted: msg
      }
    );

  db.pendingDeleteSeries ??= {};

  db.pendingDeleteSeries[
    confirm.key.id
  ] = {

    owner: sender,

    group:
      msg.key.remoteJid,

    series:
      serie.name,

    created:
      Date.now()

  };

  saveDB();

}

async function handleDeleteSerieReply(
  sock,
  msg,
  sender
){

  const quoted =
    msg.message?.extendedTextMessage
    ?.contextInfo?.stanzaId;

  if (!quoted)
    return false;

  db.pendingDeleteSeries ??= {};

  const pending =
    db.pendingDeleteSeries[
      quoted
    ];

  if (!pending)
    return false;

  if (
    pending.owner !== sender
  ){
    return true;
  }

  const text =
    (
      msg.message?.conversation ||
      msg.message?.extendedTextMessage?.text ||
      ''
    )
    .trim()
    .toLowerCase();

  if (
    text !== 'si' &&
    text !== 'sí' &&
    text !== 'no'
  ){
    return true;
  }

  delete db.pendingDeleteSeries[
    quoted
  ];

  if (
    text === 'no'
  ){

    saveDB();

    await sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
'◈ Eliminación cancelada.'
      },
      {
        quoted: msg
      }
    );

    return true;

  }
  const serie =
    findSeries(
      pending.series
    );

  if (
    !isMainOwnerId(sender) &&
    serie &&
    serie.owner &&
    serie.owner !== sender
  ) {

    saveDB();

    await sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
          '◈ Eliminacion denegada.\\n\\n' +
          '□ Esta serie pertenece a otro Secondary Owner.\\n' +
          '◈ Solo su creador puede eliminarla.'
      },
      {
        quoted: msg
      }
    );

    return true;
  }
  if (!serie){

    saveDB();

    await sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
'◈ La serie ya no existe.'
      },
      {
        quoted: msg
      }
    );

    return true;

  }

  const removed = [];

  for (
    const key of serie.characters
  ){

    const char =
      characterKeyMap.get(
        key
      );

    if (!char)
      continue;

    removed.push(
      char.name
    );

    charactersCache =
      charactersCache.filter(
        c =>
          c.key !== key
      );

    characterMap.delete(
      char.name.toLowerCase()
    );

    characterKeyMap.delete(
      key
    );

    for (
      const file of
      getCharacterImages(key)
    ){

      try{

        fs.unlinkSync(
          path.join(
            GACHA_IMAGES,
            file
          )
        );

      }catch{}

    }

    for (
      const file of
      getCharacterVideos(key)
    ){

      try{

        fs.unlinkSync(
          path.join(
            GACHA_VIDEOS,
            file
          )
        );

      }catch{}

    }

  }

  seriesCache.delete(
    serie.name.toLowerCase()
  );

  try{

    fs.unlinkSync(
      path.join(
        SERIES_DIR,
        `${serie.name
          .toLowerCase()
          .replace(/[^\w]/g,'_')}.json`
      )
    );

  }catch{}

  if (db.seriesAliases) {
    const serieNameLower = serie.name.toLowerCase();
    
    for (const key of Object.keys(db.seriesAliases)) {
      // Si la clave (nombre oficial) coincide con la serie que se borra
      if (key.toLowerCase() === serieNameLower) {
        delete db.seriesAliases[key];
      } 
      // Si el valor es un array (lista de alias), limpiamos si contenía el nombre de la serie
      else if (Array.isArray(db.seriesAliases[key])) {
        db.seriesAliases[key] = db.seriesAliases[key].filter(
          a => String(a).toLowerCase() !== serieNameLower
        );
      }
    }
  }

  buildOwnerIndex();

  rebuildHarems();

  saveCharacters();

  /* ========================================================
   * CHARACTER_UNDEFINED_GUARD_V1
   * ======================================================== */

  if (
    typeof character !== "undefined" &&
    character
  ) {

    await checkMissionProgress(
      sock,
      msg,
      character
    );

  }

  saveDB();

  await sock.sendMessage(
    msg.key.remoteJid,
    {
      text:
`✓ Serie eliminada

◈ Serie »
${serie.name}

□ Personajes eliminados »
${removed.length}`
    },
    {
      quoted: msg
    }
  );

  return true;

}

