function getStaffProfile(staffId) {

  db.staffProfiles ??= {};

  db.staffProfiles[
    staffId
  ] ??= {
    status: 0,
    completedSeries: []
  };

  const profile =
    db.staffProfiles[
      staffId
    ];

  profile.status =
    Number(
      profile.status
    ) || 0;

  if (
    !Array.isArray(
      profile.completedSeries
    )
  ) {

    profile.completedSeries = [];

  }

  return profile;

}

async function resolvePhoneToLid(sock, phone) {
  const normalizedPhone =
    String(phone || '').replace(/\D/g, '');

  if (
    !normalizedPhone ||
    normalizedPhone.length < 7 ||
    normalizedPhone.length > 15
  ) {
    return null;
  }

  const result =
    (await sock.onWhatsApp(
      `${normalizedPhone}@s.whatsapp.net`
    ))?.find(item => item?.exists);

  if (!result?.lid) {
    return null;
  }

  db.missionLidToJid ??= {};
  db.missionLidToJid[result.lid] =
    result.jid ||
    `${normalizedPhone}@s.whatsapp.net`;
  missionLidToJid.set(
    result.lid,
    db.missionLidToJid[result.lid]
  );
  saveDB();

  return {
    phone: normalizedPhone,
    jid: result.jid || `${normalizedPhone}@s.whatsapp.net`,
    lid: result.lid
  };
}

async function handleLid(sock, msg, args) {
  const jid = msg.key.remoteJid;

  const contextInfo =
    msg.message?.extendedTextMessage?.contextInfo ||
    msg.message?.imageMessage?.contextInfo ||
    msg.message?.videoMessage?.contextInfo ||
    msg.message?.documentMessage?.contextInfo;

  const mentioned = contextInfo?.mentionedJid || [];
  const quotedParticipant = contextInfo?.participant || null;

  let targetJid = null;
  let phoneInput = null;

  if (mentioned.length > 0) {
    targetJid = mentioned[0];
  } else if (quotedParticipant) {
    targetJid = quotedParticipant;
  } else if (args[0]) {
    const cleanPhone = String(args[0]).replace(/\D/g, '');
    if (cleanPhone.length >= 7 && cleanPhone.length <= 15) {
      phoneInput = cleanPhone;
    } else {
      return sock.sendMessage(jid, {
        text: '\u25C7 Uso: /lid n\u00FAmero\n\u25C7 O responde/menciona a un usuario.'
      }, { quoted: msg });
    }
  } else {
    return sock.sendMessage(jid, {
      text: '\u25C7 Uso: /lid n\u00FAmero\n\u25C7 O responde/menciona a un usuario.'
    }, { quoted: msg });
  }

  try {
    const result = { jid: null, lid: null, phone: null, name: null, source: null };
    let shouldSave = false;

    if (targetJid) {
      const normalized = String(targetJid).trim();
      const isLid = normalized.toLowerCase().endsWith('@lid');

      if (isLid) {
        result.lid = normalized;

        const mapped =
          db.missionLidToJid?.[normalized] ||
          missionLidToJid.get(normalized) ||
          null;

        if (mapped) {
          result.jid = mapped;
          result.phone = String(mapped).split('@')[0].replace(/\D/g, '');
          result.source = 'mapeo guardado';
        } else if (jid.endsWith('@g.us')) {
          try {
            const metadata = await sock.groupMetadata(jid);
            const participant = metadata?.participants?.find(p =>
              p?.id === normalized || p?.lid === normalized || p?.jid === normalized
            );
            if (participant) {
              const possiblePhone = participant.phoneNumber || participant.jid || participant.id;
              if (possiblePhone && !String(possiblePhone).toLowerCase().endsWith('@lid')) {
                result.jid = possiblePhone;
                result.phone = String(possiblePhone).split('@')[0].replace(/\D/g, '');
                result.source = 'metadata del grupo';
                db.missionLidToJid ??= {};
                if (db.missionLidToJid[normalized] !== possiblePhone) {
                  db.missionLidToJid[normalized] = possiblePhone;
                  missionLidToJid.set(normalized, possiblePhone);
                  shouldSave = true;
                }
              }
            }
          } catch (e) {
            console.log('[LID] metadata error:', e?.message || e);
          }
        }
      } else {
        result.jid = normalized;
        result.phone = String(normalized).split('@')[0].replace(/\D/g, '');

        try {
          const onWa = await sock.onWhatsApp(normalized);
          const found = Array.isArray(onWa) ? onWa.find(x => x && x.exists) : null;
          if (found?.lid) {
            result.lid = found.lid;
            result.source = 'WhatsApp (onWhatsApp)';
            const finalJid = found.jid || normalized;
            db.missionLidToJid ??= {};
            if (db.missionLidToJid[found.lid] !== finalJid) {
              db.missionLidToJid[found.lid] = finalJid;
              missionLidToJid.set(found.lid, finalJid);
              shouldSave = true;
            }
          }
        } catch (e) {
          console.log('[LID] onWhatsApp error:', e?.message || e);
        }
      }

      const lookupIds = [normalized, result.jid, result.lid].filter(Boolean);
      for (const id of lookupIds) {
        const userRecord = db.users?.[id];
        if (userRecord?.name) {
          result.name = userRecord.name;
          break;
        }
      }
    } else if (phoneInput) {
      const resolved = await resolvePhoneToLid(sock, phoneInput);
      if (!resolved) {
        return sock.sendMessage(jid, {
          text: '\u274C No pude resolver ese n\u00FAmero a un LID.\n> Verifica que la cuenta exista en WhatsApp.'
        }, { quoted: msg });
      }
      result.jid = resolved.jid;
      result.lid = resolved.lid;
      result.phone = resolved.phone;
      result.source = 'WhatsApp (onWhatsApp)';

      const lookupIds = [resolved.jid, resolved.lid].filter(Boolean);
      for (const id of lookupIds) {
        const userRecord = db.users?.[id];
        if (userRecord?.name) {
          result.name = userRecord.name;
          break;
        }
      }
    }

    const lines = ['\u2713 Datos del usuario', ''];
    if (result.name) lines.push('\u25C7 Nombre \u00BB ' + result.name);
    if (result.phone) lines.push('\u25C7 N\u00FAmero \u00BB ' + result.phone);
    if (result.jid) lines.push('\u25C7 JID \u00BB ' + result.jid);
    if (result.lid) lines.push('\u25C7 LID \u00BB ' + result.lid);
    if (!result.jid && !result.lid) lines.push('\u25C7 No se pudieron obtener datos.');
    if (result.source) {
      lines.push('');
      lines.push('> Fuente \u00BB ' + result.source);
    }

    if (shouldSave) saveDB();

    return sock.sendMessage(jid, { text: lines.join('\n') }, { quoted: msg });

  } catch (error) {
    console.error('ERROR RESOLVIENDO LID:', error);
    return sock.sendMessage(jid, {
      text: '\u274C No se pudo consultar ese usuario en WhatsApp.\n\u25C7 Error \u00BB ' + (error?.message || error)
    }, { quoted: msg });
  }
}
async function handleDelStatus(
  sock,
  msg,
  args,
  mentioned = [],
  quotedJid = null,
  sender
) {
  const jid = msg.key.remoteJid;

  if (!isMainOwnerId(sender)) {
    return sock.sendMessage(
      jid,
      {
        text: '❌ Solo el owner principal puede usar este comando.'
      },
      { quoted: msg }
    );
  }

  const amount = Number(
    String(args[0] || '').replace(/[^\d]/g, '')
  );

  const inputParts =
    args
      .slice(1)
      .join(' ')
      .split('/')
      .map(part => part.trim())
      .filter(Boolean);

  let target =
    mentioned?.[0] ||
    quotedJid ||
    null;

  const targetInput =
    inputParts[0] || '';
  const numericTarget =
    /^\+?\d{7,15}$/.test(
      targetInput.replace(/\s/g, '')
    );
  const lidTarget =
    /^\d{7,20}@lid$/i.test(targetInput);

  if (
    !target &&
    lidTarget &&
    isSecondaryOwnerId(targetInput)
  ) {
    target = targetInput;
  }

  if (!target && numericTarget) {
    const requestedNumber =
      targetInput.replace(/\D/g, '');
    const ownerIds = [
      ...SECONDARY_OWNERS,
      ...(Array.isArray(db.secondaryOwners)
        ? db.secondaryOwners
        : [])
    ].filter(Boolean);

    const matchingOwner =
      ownerIds.find(owner =>
        normalizeOwnerId(owner)
          .replace(/\D/g, '') === requestedNumber
      ) ||
      Object.entries(db.missionLidToJid || {})
        .find(([lid, linkedJid]) =>
          normalizeOwnerId(linkedJid)
            .replace(/\D/g, '') === requestedNumber &&
          ownerIds.some(owner =>
            normalizeOwnerId(owner) === normalizeOwnerId(lid)
          )
        )?.[0];

    if (matchingOwner) {
      target = matchingOwner;
    } else {
      try {
        const resolved =
          await resolvePhoneToLid(
            sock,
            requestedNumber
          );

        if (
          resolved &&
          ownerIds.some(owner =>
            normalizeOwnerId(owner)
              .replace(/\D/g, '') ===
            normalizeOwnerId(resolved.lid)
              .replace(/\D/g, '')
          ) ||
          resolved &&
          ownerIds.some(owner =>
            normalizeOwnerId(owner)
              .replace(/\D/g, '') ===
            normalizeOwnerId(resolved.jid)
              .replace(/\D/g, '')
          )
        ) {
          target = resolved.lid;
        }
      } catch (error) {
        console.warn(
          '⚠️ No se pudo convertir el número a JID:',
          error?.message || error
        );
      }
    }
  }

  const reasonParts =
    inputParts;
  const reason =
    reasonParts[reasonParts.length - 1] || '';

  if (
    !Number.isSafeInteger(amount) ||
    amount <= 0 ||
    !target ||
    !reason
  ) {
    const targetError =
      numericTarget && !target
        ? '\n◈ Ese número no está registrado como secondary owner o aún no tiene un LID asociado.'
        : lidTarget && !target
          ? '\n◈ Ese LID no pertenece a un secondary owner configurado.'
        : '';

    return sock.sendMessage(
      jid,
      {
        text:
          '◈ Uso:\n/delstatus cantidad / @mención / motivo\n' +
          '/delstatus cantidad / motivo (respondiendo al mensaje del usuario)' +
          targetError
      },
      { quoted: msg }
    );
  }

  const profile =
    getStaffProfile(target);
  const currentStatus =
    Number(profile.status) || 0;

  if (amount > currentStatus) {
    return sock.sendMessage(
      jid,
      {
        text:
          `❌ ${getStaffDisplayName(target, target)} no tiene suficiente status.\n` +
          `Status actual: ${currentStatus.toLocaleString()}`
      },
      {
        quoted: msg,
        mentions: [target]
      }
    );
  }

  profile.status =
    currentStatus - amount;

  saveDB();

  const targetName =
    getStaffDisplayName(target, target);

  if (db.suggestLogs) {
    const secondaryOwners = [
      ...SECONDARY_OWNERS,
      ...(Array.isArray(db.secondaryOwners)
        ? db.secondaryOwners
        : [])
    ].filter((owner, index, owners) =>
      owner &&
      owners.findIndex(candidate =>
        normalizeOwnerId(candidate) === normalizeOwnerId(owner)
      ) === index
    );

    try {
      await sock.sendMessage(
        db.suggestLogs,
        {
          text:
            `⚠️ Se retiraron ${amount.toLocaleString()} status a ` +
            `${targetName}.\n` +
            `Motivo: ${reason}\n` +
            `Status actual: ${profile.status.toLocaleString()}\n\n` +
            secondaryOwners.map(owner =>
              `@${String(owner).split('@')[0]}`
            ).join(' '),
          mentions: [target, ...secondaryOwners]
        }
      );
    } catch (error) {
      console.error(
        '⚠️ No se pudo enviar el aviso de Del Status:',
        error?.message || error
      );
    }
  }

  return sock.sendMessage(
    jid,
    {
      text:
        `✓ Se retiraron ${amount.toLocaleString()} status a ` +
        `${targetName}.\n` +
        `Motivo: ${reason}\n` +
        `Status actual: ${profile.status.toLocaleString()}`,
      mentions: [target]
    },
    { quoted: msg }
  );
}

async function handleAddStatus(
  sock,
  msg,
  args,
  mentioned = [],
  quotedJid = null,
  sender
) {
  const jid = msg.key.remoteJid;

  if (!isMainOwnerId(sender)) {
    return sock.sendMessage(
      jid,
      {
        text: '❌ Solo el owner principal puede usar este comando.'
      },
      { quoted: msg }
    );
  }

  const parts =
    args
      .join(' ')
      .split('/')
      .map(part => part.trim())
      .filter(Boolean);

  let target =
    mentioned?.[0] ||
    quotedJid ||
    null;

  const isAmountPart = value =>
    /^\d+$/.test(String(value || '').trim());

  let amountText = '';
  let targetInput = '';

  if (target || parts.length === 1) {
    amountText =
      parts.find(isAmountPart) ||
      (isAmountPart(parts[0]) ? parts[0] : '');
    targetInput =
      parts.find(part => !isAmountPart(part)) || '';
  } else if (isAmountPart(parts[0])) {
    // También acepta /addstatus cantidad / objetivo.
    amountText = parts[0];
    targetInput = parts[1] || '';
  } else {
    // Formato preferido: /addstatus objetivo / cantidad.
    targetInput = parts[0] || '';
    amountText = parts[1] || '';
  }

  if (!target && /^\d{7,20}@lid$/i.test(targetInput)) {
    target = targetInput;
  }

  if (!target && /^\+?\d{7,15}$/.test(targetInput)) {
    const resolved =
      await resolvePhoneToLid(sock, targetInput);
    target = resolved?.lid || null;
  }

  const amount =
    isAmountPart(amountText)
      ? Number(amountText)
      : NaN;

  if (
    !target ||
    !Number.isSafeInteger(amount) ||
    amount <= 0
  ) {
    return sock.sendMessage(
      jid,
      {
        text:
          '◈ Uso:\n' +
          '/addstatus LID / cantidad\n' +
          '/addstatus cantidad (respondiendo al mensaje del usuario)\n' +
          '/addstatus @mención / cantidad'
      },
      { quoted: msg }
    );
  }

  const profile =
    getStaffProfile(target);
  profile.status =
    (Number(profile.status) || 0) + amount;

  saveDB();

  return sock.sendMessage(
    jid,
    {
      text:
        `✓ Se otorgaron ${amount.toLocaleString()} status a ` +
        `${getStaffDisplayName(target, target)}.\n` +
        `Status actual: ${profile.status.toLocaleString()}`,
      mentions: [target]
    },
    { quoted: msg }
  );
}

const INVALID_MEDIA_REPAIR_REWARD = 5_000;

function canRepairCharacterMedia(character, sender) {
  const isCreator = String(character.creator || '') === String(sender || '');
  const isMainOwner =
    isMainOwnerId(sender);
  const isSecondaryOwner =
    isSecondaryOwnerId(sender);
  const isStaff = Array.isArray(db.staff) && db.staff.includes(sender);

  return isCreator || isMainOwner || isSecondaryOwner || isStaff;
}

function rewardInvalidMediaRepair(character, repairer) {
  // Una recompensa por personaje evita cobrar repetidamente por el mismo arreglo.
  if (character.invalidMediaRepairRewardedAt) return null;

  const profile = getStaffProfile(repairer);
  profile.status = (Number(profile.status) || 0) + INVALID_MEDIA_REPAIR_REWARD;
  character.invalidMediaRepairRewardedAt = Date.now();
  character.invalidMediaRepairRewardedBy = repairer;

  saveDB();
  saveCharacters();

  return profile.status;
}

async function notifyEvents(sock, text, mentions = []) {
  if (!db.eventsGroup) return;
  await sock.sendMessage(db.eventsGroup, {
    text,
    mentions: mentions.filter(Boolean)
  });
}

async function handleEvents(sock, msg, jid, sender, args) {
  if (!isMainOwnerId(sender)) {
    return sock.sendMessage(jid, {
      text: '❌ Solo el owner principal puede usar este comando.'
    }, { quoted: msg });
  }

  const action = String(args[0] || '').toLowerCase();
  if (!['on', 'off'].includes(action)) {
    return sock.sendMessage(jid, {
      text: '◈ Uso: /events on o /events off'
    }, { quoted: msg });
  }

  if (action === 'on') {
    if (!jid.endsWith('@g.us')) {
      return sock.sendMessage(jid, {
        text: '◈ Debes activar /events on dentro de un grupo.'
      }, { quoted: msg });
    }
    db.eventsGroup = jid;
    saveDB();
    return sock.sendMessage(jid, {
      text: '✓ Eventos activados en este grupo.'
    }, { quoted: msg });
  }

  db.eventsGroup = null;
  saveDB();
  return sock.sendMessage(jid, {
    text: '✓ Eventos desactivados.'
  }, { quoted: msg });
}

function getStaffRank(status) {

  const ranks = db.staffRanks || [

    {
  name:
    "Staff Maestro",
  min: 6000
},

{
  name:
    "Staff Avanzado",
  min: 10000
},

{
  name:
    "Staff Superior",
  min: 16000
},

{
  name:
    "Staff Profesional",
  min: 25000
},

{
  name:
    "Staff Experto Plus",
  min: 40000
},

{
  name:
    "Staff Veterano",
  min: 60000
},

{
  name:
    "Staff Élite",
  min: 90000
},

{
  name:
    "Staff Diamante",
  min: 130000
},

{
  name:
    "Staff Legendario",
  min: 180000
},

{
  name:
    "Staff Supremo",
  min: 250000
},

{
  name:
    "Staff Campeón",
  min: 350000
},

{
  name:
    "Staff Máximo",
  min: 500000
}

  ].map(rank => ({
    name: String(rank.name),
    min: Number(rank.min)
  })).sort((a, b) => a.min - b.min);

  let current =
    ranks[0];

  for (
    const rank of ranks
  ) {

    if (
      status >=
      rank.min
    ) {

      current = rank;

    }

  }

  return current;

}

function getStaffRanks() {
  db.staffRanks ??= [
    { name: "Staff Maestro", min: 6000 },
    { name: "Staff Avanzado", min: 10000 },
    { name: "Staff Superior", min: 16000 },
    { name: "Staff Profesional", min: 25000 },
    { name: "Staff Experto Plus", min: 40000 },
    { name: "Staff Veterano", min: 60000 },
    { name: "Staff Élite", min: 90000 },
    { name: "Staff Diamante", min: 130000 },
    { name: "Staff Legendario", min: 180000 },
    { name: "Staff Supremo", min: 250000 },
    { name: "Staff Campeón", min: 350000 },
    { name: "Staff Máximo", min: 500000 }
  ];

  return db.staffRanks
    .map(rank => ({
      name: String(rank.name),
      min: Number(rank.min)
    }))
    .filter(rank => rank.name && Number.isFinite(rank.min) && rank.min >= 0)
    .sort((a, b) => a.min - b.min);
}

async function handleStaffRanks(sock, msg) {
  const ranks = getStaffRanks();
  const text = ranks.length
    ? "☆ RANGOS DEL STAFF\n\n" +
      ranks.map((rank, index) =>
        `${index + 1}. *${rank.name}*\n> Necesitas: \`${rank.min.toLocaleString()}\` status`
      ).join("\n\n")
    : "◈ No hay rangos configurados.";

  await sock.sendMessage(
    msg.key.remoteJid,
    { text },
    { quoted: msg }
  );
}

async function handleTopStatus(sock, msg, args = []) {
  const requestedPage = Number.parseInt(args[0] || "1", 10);
  const page = Number.isInteger(requestedPage) && requestedPage > 0
    ? requestedPage
    : 1;
  const perPage = 10;

  const ranking = Object.entries(db.staffProfiles || {})
    .map(([id, profile]) => ({
      id,
      name:
        db.users?.[id]?.name ||
        id.split("@")[0] ||
        "Usuario",
      status: Number(profile?.status) || 0
    }))
    .filter(staff => staff.status > 0)
    .sort((a, b) => {
      if (b.status !== a.status) {
        return b.status - a.status;
      }

      return a.name.localeCompare(b.name);
    });

  const totalPages = Math.max(1, Math.ceil(ranking.length / perPage));

  if (!ranking.length) {
    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text: '♧ No hay usuarios con status registrado ♧'
      },
      { quoted: msg }
    );
  }

  if (page > totalPages) {
    await sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
          ` Top de usuarios con más status \n\n` +
          `✧ La página *${page}* no existe.\n` +
          `✧ Hay *${totalPages}* páginas disponibles.`
      },
      { quoted: msg }
    );
    return;
  }

  const start = (page - 1) * perPage;
  const visible = ranking.slice(start, start + perPage);

  let text =
    ` Top de usuarios con más status \n\n`;

  for (let i = 0; i < visible.length; i++) {
    const staff = visible[i];
    const position = start + i + 1;
    const crown = position === 1 ? '♔ ' : '';
    const rank = getStaffRank(staff.status);

    text +=
      `✧ ${crown}${position} » *${staff.name}* » \`${staff.status.toLocaleString()}\`\n` +
      `   > Rango: ${rank.name}`;

    if (i < visible.length - 1) {
      text += "\n\n";
    }
  }

  text +=
    `\n\n✧ Página *${page}* de *${totalPages}*`;

  if (page < totalPages) {
    text +=
      `\n✧ Para ver la siguiente página usa: */topstatus ${page + 1}*`;
  }

  if (page > 1) {
    text +=
      `\n✧ Página anterior: */topstatus ${page - 1}*`;
  }

  await sock.sendMessage(
    msg.key.remoteJid,
    { text },
    { quoted: msg }
  );
}

function getStaffRanking() {

  db.staffStats ??= {};

  const ranking = [];

  const creators =
    new Set(
      charactersCache
        .filter(
          char =>
            char.creator
        )
        .map(
          char =>
            char.creator
        )
    );

  for (
    const creator
    of creators
  ) {

    const total =
      charactersCache
        .filter(
          char =>
            char.creator ===
            creator
        )
        .length;

    const fans =
      Number(
        db.staffStats?.[
          creator
        ]?.fans
      ) || 0;

    ranking.push({

      id:
        creator,

      total,

      fans

    });

  }

  ranking.sort(
    (a, b) => {

      if (
        b.fans !==
        a.fans
      ) {

        return (
          b.fans -
          a.fans
        );

      }

      return (
        b.total -
        a.total
      );

    }
  );

  return ranking;

}

export async function handleStaffInfo(
  sock,
  msg,
  args,
  sender
) {

  const target =
    sender;

  const profile =
    getStaffProfile(
      target
    );

  const ranking =
    getStaffRanking();

  const position =
    ranking.findIndex(
      staff =>
        staff.id ===
        target
    ) + 1;

  // -----------------------------------------------
  // PERSONAJES CREADOS
  // -----------------------------------------------

  const totalCharacters =
    charactersCache
      .filter(
        char =>
          char.creator ===
          target
      )
      .length;

  // -----------------------------------------------
  // FANS
  // -----------------------------------------------

  const fans =
    Number(
      db.staffStats?.[
        target
      ]?.fans
    ) || 0;

  // -----------------------------------------------
  // RANGO
  // -----------------------------------------------

  const rank =
    getStaffRank(
      profile.status
    );

  // -----------------------------------------------
  // NOMBRE
  // -----------------------------------------------

  const name =
    db.users?.[
      target
    ]?.name ||
    target
      .split("@")[0];

  // -----------------------------------------------
  // DUEÑO DE SERIE
  //
  // Una serie cuenta como "Dueño de serie"
  // cuando todos sus personajes pertenecen
  // al mismo staff.
  // -----------------------------------------------

  let ownedSeries = 0;

  try {

    for (
      const serie of seriesCache.values()
    ) {

      if (
        !serie ||
        !serie.characters ||
        typeof serie.characters[Symbol.iterator] !==
          "function"
      ) {
        continue;
      }

      const characterKeys =
        Array.from(
          serie.characters
        );

      if (
        !characterKeys.length
      ) {
        continue;
      }

      const characters =
        characterKeys
          .map(
            key =>
              charactersCache.find(
                char =>
                  char.key === key ||
                  char.id === key ||
                  char.name === key
              )
          )
          .filter(Boolean);

      if (
        !characters.length
      ) {
        continue;
      }

      const allOwned =
        characters.every(
          char =>
            char.creator ===
            target
        );

      if (
        allOwned
      ) {
        ownedSeries++;
      }

    }

  } catch (error) {

    console.error(
      "⚠️ Error calculando Dueño de serie:",
      error
    );

  }

  // -----------------------------------------------
  // MISIONES COMPLETADAS
  // -----------------------------------------------

  let completedMissions = 0;

  try {

    const store =
      getMissionStore();

    const missions =
      Array.isArray(
        store?.list
      )
        ? store.list
        : [];

    const targetId =
      String(
        target || ""
      )
        .replace(/\D/g, "");

    completedMissions =
      missions.filter(
        mission => {

          if (
            mission?.status !==
            "completed"
          ) {
            return false;
          }

          const missionStaff =
            String(
              mission.staff || ""
            )
              .replace(/\D/g, "");

          return (
            missionStaff ===
            targetId
          );

        }
      ).length;

  } catch (error) {

    console.error(
      "⚠️ Error calculando misiones:",
      error
    );

  }

  // -----------------------------------------------
  // TEXTO
  // -----------------------------------------------

  const text = [

    "♤ STAFF INFO",

    "",

    "♡ Staff » " +
    name,

    "",

    "▪︎ *Personajes totales* » \`" +
    totalCharacters +
    "\`",

    "☆ *Series completadas* » \`" +
    profile
      .completedSeries
      .length +
    "\`",

    "♠︎ *Dueño de serie* » \`" +
    ownedSeries +
    "\`",

    "♡ *Fans totales* » \`" +
    fans
      .toLocaleString() +
    "\`",

    "",

    "➢ *Status* » \`" +
    profile
      .status
      .toLocaleString() +
    "\`",

    "♛ *Rango* » \`" +
    rank.name +
    "\`",

    "♤ *Puesto* » \`" +
    (
      position ||
      "Sin puesto"
    ) +
    "\`",

    "¤ *Misiones completadas* » \`" +
    completedMissions +
    "\`",

    "",

    "> Usa /rangs para ver los rangos."

  ].join(
    "\n"
  );

  // -----------------------------------------------
  // FOTO DE PERFIL
  // -----------------------------------------------

  let profilePictureUrl = null;

  try {

    profilePictureUrl =
      await sock.profilePictureUrl(
        target,
        "image"
      );

  } catch (error) {

    profilePictureUrl = null;

  }

  // -----------------------------------------------
  // ENVIAR FOTO + TEXTO
  // -----------------------------------------------

  if (
    profilePictureUrl
  ) {

    try {

      await sock.sendMessage(
        msg.key.remoteJid,
        {
          image: {
            url:
              profilePictureUrl
          },
          caption:
            text
        },
        {
          quoted:
            msg
        }
      );

      return;

    } catch (error) {

      console.error(
        "⚠️ No se pudo enviar la foto de perfil:",
        error
      );

    }

  }

  // -----------------------------------------------
  // FALLBACK: SOLO TEXTO
  // -----------------------------------------------

  await sock.sendMessage(
    msg.key.remoteJid,
    {
      text
    },
    {
      quoted:
        msg
    }
  );

}

export async function handleSerieC(
  sock,
  msg,
  args,
  sender
) {

  const isStaff =
    isMainOwnerId(sender) ||
    isSecondaryOwnerId(sender);

  if (
    !isStaff
  ) {

    return;

  }

  const anime =
    args
      .join(
        " "
      )
      .trim();

  if (
    !anime
  ) {

    return sock.sendMessage(

      msg.key.remoteJid,

      {

        text:

          "♤ Uso\n\n" +

          "/seriec Nombre de la serie"

      },

      {

        quoted:
          msg

      }

    );

  }

  const characters =

    charactersCache
      .filter(

        char =>

          String(

            char.anime ||

            ""

          )

          .toLowerCase()

          .trim()

          ===

          anime

          .toLowerCase()

          .trim()

      );

  if (
    !characters.length
  ) {

    return sock.sendMessage(

      msg.key.remoteJid,

      {

        text:

          "♤ Serie no encontrada\n\n" +

          "▪︎ No hay personajes registrados de:\n\n" +

          anime

      },

      {

        quoted:
          msg

      }

    );

  }

  // SERIEC_SERIESKEY_FIX_V2
const seriesKey =

    anime

      .toLowerCase()

      .normalize(
        "NFD"
      )

      .replace(

        /[\u0300-\u036f]/g,

        ""

      )

      .trim();

  const cachedInfo =
    db.seriesInfoCache?.[
      seriesKey
    ];

  if (
    !cachedInfo ||
    !Number.isInteger(Number(cachedInfo.total)) ||
    Number(cachedInfo.total) < 1
  ) {
    db.pendingSeriesChecks ??= {};
    const verification = await sock.sendMessage(
      msg.key.remoteJid,
      {
        text: `#ainfo ${anime}`
      },
      { quoted: msg }
    );

    if (verification?.key?.id) {
      db.pendingSeriesChecks[verification.key.id] = {
        seriesKey,
        anime,
        jid: msg.key.remoteJid,
        sender,
        createdAt: Date.now()
      };
      saveDB();
    }

    return;
  }

 const uniqueCharacters = new Map();

const registeredTotal = (() => {
  for (const char of characters) {
    const uniqueKey =
      char.key ||
      char.name?.toLowerCase();

    if (!uniqueCharacters.has(uniqueKey)) {
      uniqueCharacters.set(uniqueKey, char);
    }
  }

  return uniqueCharacters.size;
})();

const expectedTotal = Number(cachedInfo.total);

  if (
    !Number.isInteger(
      expectedTotal
    ) ||
    expectedTotal < 1
  ) {

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
          " El total guardado de esta serie no es válido."
      },
      {
        quoted:
          msg
        }
    );

  }

  if (
    registeredTotal <
    expectedTotal
  ) {

    const missing =
      expectedTotal -
      registeredTotal;

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
          "❌ SERIE INCOMPLETA\n\n" +
          "♤ Serie » " +
          anime +
          "\n\n" +
          "▪︎ Registrados » " +
          registeredTotal +
          "\n" +
          "▪︎ Total » " +
          expectedTotal +
          "\n" +
          "▪︎ Faltan » " +
          missing +
          "\n\n" +
          " La serie todavía no puede firmarse."
      },
      {
        quoted:
          msg
      }
    );

  }

  if (
    registeredTotal >
    expectedTotal
  ) {

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
          "⚠️ DATOS NO COINCIDEN\n\n" +
          "▪︎ Registrados » " +
          registeredTotal +
          "\n" +
          "▪︎ Total externo » " +
          expectedTotal +
          "\n\n" +
          "♧ La firma fue bloqueada para evitar errores."
      },
      {
        quoted:
          msg
      }
    );

  }

  const creators = [
    ...new Set(
      characters.map(
        char => char.creator
      )
      .filter(Boolean)
    )
  ];

  if (
    creators.length !== 1
  ) {

    const creatorsDisplay =
      creators
        .map(
          creator =>
            db.users?.[creator]?.name ||
            creator?.split("@")[0] ||
            "Desconocido"
        )
        .filter(
          (name, index, array) =>
            array.indexOf(name) === index
        );

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
          "》 La serie tiene creadores distintos\n" +
          creatorsDisplay
            .map(name => `✿ ${name}`)
            .join("\n") +
          "\n> Consulta con la owner May."
      },
      {
        quoted:
          msg
      }
    );

  }

  const creator =
    creators[0];

  const profile =
    getStaffProfile(
      creator
    );



  if (

    profile

      .completedSeries

      .includes(

        seriesKey

      )

  ) {

    return sock.sendMessage(

      msg.key.remoteJid,

      {

        text:

          "♤ Esta serie ya fue completada.\n\n" +

          "▪︎ No se puede obtener Status dos veces."

      },

      {

        quoted:
          msg

      }

    );

  }

  const reward =
    registeredTotal * 1000;

  profile.status +=

    reward;

  profile

    .completedSeries

    .push(

      seriesKey

    );

  saveDB();

  const rank =

    getStaffRank(

      profile.status

    );

  const text = [

    "☆ SERIE COMPLETADA",

    "",

    "♤ Serie » " +
    anime,

    "▪︎ Personajes verificados » " +
    registeredTotal +
    "/" +
    expectedTotal,

    "♡ Recompensa » +" +

    reward +

    " Status",

    "➢ Status total » " +

    profile.status,

    "◈ Rango actual » " +

    rank.name,

    "",

    "♧ Serie firmada correctamente."

  ].join(
    "\n"
  );

  await sock.sendMessage(

    msg.key.remoteJid,

    {

      text

    },

    {

      quoted:
        msg

    }

  );

}


export async function handleTopStaffGacha(
  sock,
  msg,
  args
){

  db.staffStats ??= {};

  const page =
    Math.max(
      1,
      Number(args[0]) || 1
    );

  const perPage = 10;

  const staffMap = new Map();

  for (const char of charactersCache) {

    if (!char.creator)
      continue;

    if (!staffMap.has(char.creator)) {

      staffMap.set(
        char.creator,
        {
          id: char.creator,
          name:
            db.users?.[char.creator]?.name ||
            char.creator.split('@')[0],
          fans:
            db.staffStats?.[
              char.creator
            ]?.fans || 0,
          total: 0
        }
      );

    }

    staffMap.get(
      char.creator
    ).total++;

  }

  const ranking =
    [...staffMap.values()]
      .sort((a,b)=>{

        if (b.fans !== a.fans)
          return b.fans - a.fans;

        return b.total - a.total;

      });

  if (!ranking.length){

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
'No hay estadísticas.'
      },
      {
        quoted: msg
      }
    );

  }

  const totalPages =
    Math.max(
      1,
      Math.ceil(
        ranking.length / perPage
      )
    );

  const start =
    (page-1) * perPage;

  const end =
    start + perPage;

  let text =
`Top staff con más Reclamaciones\n\n`;

  let pos = start + 1;

  for (
    const staff of
    ranking.slice(start,end)
  ){

    text +=
`☆ ${pos} » ${staff.name}
    ☆ Fans \`${Number(
      staff.fans
    ).toLocaleString()}\` ➭ PJ totales \`${Number(
      staff.total
    ).toLocaleString()}\`\n\n`;

    pos++;

  }

  text +=
` Página \`${page}/${totalPages}\`  usa \`/topstaffgacha ${Math.min(page+1,totalPages)}\` para avanzar`;

  await sock.sendMessage(
    msg.key.remoteJid,
    {
      text
    },
    {
      quoted: msg
    }
  );

}

export async function handleTopCoinsChar(
  sock,
  msg,
  args
){

  const page =
    parseInt(args[0]) || 1;

  const perPage = 10;

  const chars =
    [...charactersCache]
    .filter(c =>
      Number(c.coinGen || 0) > 0
    )
    .sort(
      (a,b) =>
        Number(b.coinGen || 0)
        -
        Number(a.coinGen || 0)
    );

  const pages =
    Math.max(
      1,
      Math.ceil(
        chars.length / perPage
      )
    );

  const slice =
    chars.slice(
      (page - 1) * perPage,
      page * perPage
    );

  let text =
` Personajes con más dinero pasivo

`;

  let pos =
    (page - 1) * perPage + 1;

  for (const char of slice) {

    text +=
`✰ ${pos} » *${char.name}*
→ coins: *${Number(
  char.coinGen || 0
).toLocaleString()}/h*

`;

    pos++;

  }

  text +=
`> ➢ Página *${page}* de *${pages}*`;

  await sock.sendMessage(
    msg.key.remoteJid,
    { text },
    { quoted: msg }
  );

}

export async function handleSetClaimMsg(sock, msg, args, jid, sender) {

  const text = args.join(' ').trim();

  if (!text) {
    return sock.sendMessage(jid,{
      text:
`《✧》Debes incluir las variables *$user* y *$character* en el mensaje.

> Ejemplos de mensajes:
> *#setclaimmsg $user ha reclamado el personaje $character!*
> *#setclaimmsg $character ha sido reclamado por $user*
> *#setclaimmsg Ahora $user es el dueño de $character!*`
    },{ quoted: msg });
  }

  if (
    !text.includes('$user') ||
    !text.includes('$character')
  ) {

    return sock.sendMessage(jid,{
      text:
`《✧》Debes incluir las variables *$user* y *$character* en el mensaje.`
    },{ quoted: msg });
  }

if (/\d/.test(text)) {
  return sock.sendMessage(jid,{
    text:'《✧》No puedes incluir números en el mensaje de reclamación.'
  },{ quoted: msg });
}

  if (text.length > 70) {
    return sock.sendMessage(jid,{
      text:'《✧》El mensaje no puede superar los *70 caracteres*.'
    },{ quoted: msg });
  }

 const user = initUser(sender);

try {

  collectPassiveCoins(
    jid,
    sender
  );

} catch (error) {

  console.error(
    '[ERROR PASSIVE COINS]',
    error?.stack || error?.message || error
  );

}

  user.claimMsg = text;

  saveDB();

  await sock.sendMessage(jid,{
    text:'✰ Mensaje de reclamación modificado.'
  },{ quoted: msg });
}

