async function mioTagHasOnlineImage(tag) {
  const query = String(tag || '').trim();
  if (!query) return false;

  try {
    const gelbooruCandidates =
      await getGelbooruApiImageCandidates(query);

    for (const imageUrl of (gelbooruCandidates || []).slice(0, 5)) {
      const image = await downloadGelbooruImage(imageUrl);
      if (image?.buffer?.length) return true;
    }

    const danbooruImageUrl =
      await getDanbooruImage(query);
    if (!danbooruImageUrl) return false;

    const image =
      await downloadDanbooruImage(danbooruImageUrl);
    return Boolean(image?.buffer?.length);
  } catch (error) {
    console.error('[PENDIENTES2] No se pudo comprobar el tag Mio:', error?.message || error);
    return false;
  }
}

async function getCharacterMedia(character){
  // ============================================================
  // MEDIA_PRIORITY_LOCAL_V2
  // Prioridad:
  //   1. Imagen local (siempre, si existe)
  //   2. Tag manual (Bulguru)
  //   3. Danbooru (char.tag) / Gelbooru (char.gelbooruTag)
  //      -> 50/50 aleatorio si ambos tags existen
  //      -> fallback a la otra fuente si la primera falla
  //      -> si solo un tag existe, se usa ese
  //      -> si no hay tags, se usa char.name en ambas
  // ============================================================

  // 1) Imagen local: SIEMPRE tiene prioridad
  const localImages =
    getCharacterImages(character.key)
      .map(imageName => path.join(GACHA_IMAGES, imageName))
      .filter(imagePath => {
        try { return fs.existsSync(imagePath); } catch { return false; }
      });

  if (localImages.length) {
    const img = localImages[Math.floor(Math.random() * localImages.length)];
    const buffer = imageCache.get(img) || fs.readFileSync(img);
    imageCache.set(img, buffer);
    return { image: buffer };
  }

  const danbooruTag = String(character.tag || '').trim();
  const gelbooruTag = String(character.gelbooruTag || '').trim();
  const hasAnyTag = Boolean(danbooruTag || gelbooruTag);

  // 2) Tag manual (Bulguru): prueba con cada tag disponible
  if (hasAnyTag) {
    for (const tag of [danbooruTag, gelbooruTag].filter(Boolean)) {
      try {
        const manualImage = await getManualCharacterImage(tag);
        if (manualImage) return manualImage;
      } catch (e) {}
    }
  }

  // 3) Fuentes online: pool con shuffle
  const sourcePool = [];
  if (danbooruTag) sourcePool.push({ source: 'danbooru', tag: danbooruTag });
  if (gelbooruTag) sourcePool.push({ source: 'gelbooru', tag: gelbooruTag });

  // Fallback: sin tags -> intentar con el nombre en ambas
  if (!sourcePool.length) {
    const nameFallback = String(character.name || '').trim();
    if (nameFallback) {
      sourcePool.push({ source: 'danbooru', tag: nameFallback });
      sourcePool.push({ source: 'gelbooru', tag: nameFallback });
    }
  }

  // Shuffle aleatorio
  for (let i = sourcePool.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [sourcePool[i], sourcePool[j]] = [sourcePool[j], sourcePool[i]];
  }

  for (const entry of sourcePool) {
    try {
      let imgUrl = null;

      if (entry.source === 'gelbooru') {
        const candidates = await getGelbooruApiImageCandidates(entry.tag);
        if (Array.isArray(candidates) && candidates.length) {
          imgUrl = candidates[Math.floor(Math.random() * candidates.length)];
        }
      }

      if (entry.source === 'danbooru') {
        imgUrl = await getDanbooruImage(entry.tag);
        if (!imgUrl) {
          // Fallback con auth por si el tag necesita credenciales
          try { imgUrl = await getDanbooruImageWithAuth(entry.tag); } catch (e) {}
        }
      }

      if (!imgUrl) continue;

      const downloaded =
        entry.source === 'danbooru'
          ? await downloadDanbooruImage(imgUrl)
          : await downloadGelbooruImage(imgUrl);

      if (downloaded?.buffer && Buffer.isBuffer(downloaded.buffer) && downloaded.buffer.length) {
        console.log(
          '[MEDIA] fuente usada:',
          entry.source,
          '| tag:', entry.tag,
          '| char:', character.name
        );
        return { image: downloaded.buffer, mimetype: downloaded.mimetype };
      }
    } catch (error) {
      console.log(
        '[MEDIA]',
        entry.source + ' falló:',
        '| tag:', entry.tag,
        '| char:', character.name,
        '|',
        error?.message || error
      );
    }
  }

  return null;
}


export async function handleSetv(sock, msg, args, sender) {
  const permitido =
    isMainOwnerId(sender) ||
    isSecondaryOwnerId(sender);

  if (!permitido) return;

  const raw = args.join(" ").trim();
  const partes = raw.split("/").map(x => x.trim());

  if (partes.length < 3) {
    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
          "◈ Uso:\n\n" +
          "/setv 1 en 382023 / Nombre del personaje / Nombre de la serie\n\n" +
          "◈ Ejemplo:\n\n" +
          "/setv 1 en 382023 / Miko (Dandadan) / Dandadan"
      },
      { quoted: msg }
    );
  }

  const oddsPart = partes[0];
  const characterName = partes[1];
  const seriesName = partes.slice(2).join(" / ").trim();

  const match = oddsPart.match(/^1\s+(?:en|in)\s+([0-9]+(?:[,.][0-9]{3})*)$/i);

  if (!match) {
    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
          " Formato inválido.\n\n" +
          "Usa:\n\n" +
          "/setv 1 en 382023 / Nombre / Serie"
      },
      { quoted: msg }
    );
  }

  const odds = Number(
    match[1].replace(/[.,]/g, "")
  );

  if (!Number.isSafeInteger(odds) || odds < 1) {
    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
          "◈ El valor de 1 en debe ser un número entero mayor que 0."
      },
      { quoted: msg }
    );
  }

  if (!characterName || !seriesName) {
    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text: "◈ Debes indicar el personaje y la serie."
      },
      { quoted: msg }
    );
  }

  if (!charactersCache.length) {
    loadCharactersCache();
    loadSeries();
  }

  const normalizar = value =>
    String(value || "")
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase()
      .trim();

  const nombreBuscado = normalizar(characterName);
  const serieBuscada = normalizar(seriesName);

  let encontrados = charactersCache.filter(char => {
    const nombre = normalizar(char.name);
    const anime = normalizar(char.anime);

    return nombre === nombreBuscado && anime === serieBuscada;
  });

  if (!encontrados.length) {
    encontrados = charactersCache.filter(char => {
      const nombre = normalizar(char.name);
      const anime = normalizar(char.anime);

      return (
        (nombre.includes(nombreBuscado) ||
          nombreBuscado.includes(nombre)) &&
        (anime === serieBuscada ||
          anime.includes(serieBuscada) ||
          serieBuscada.includes(anime))
      );
    });
  }

  if (!encontrados.length) {
    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
          "◈ Personaje no encontrado.\n\n" +
          "◈ Personaje » " + characterName + "\n" +
          "◈ Serie » " + seriesName
      },
      { quoted: msg }
    );
  }

    if (encontrados.length > 1) {
    const activos = encontrados.filter(char =>
      Number(char.coinGen || 0) > 0
    );

    if (activos.length === 1) {
      encontrados = activos;
    } else {
      return sock.sendMessage(
        msg.key.remoteJid,
        {
          text:
            "◈ Se encontraron varios personajes compatibles.\n\n" +
            "Usa el nombre exacto del personaje y de la serie.\n\n" +
            "◈ Personaje » " + characterName + "\n" +
            "◈ Serie » " + seriesName + "\n\n" +
            "◈ No se realiz¿ ningún cambio."
        },
        { quoted: msg }
      );
    }
  }

  const character = encontrados[0];

  character.displayOdds = odds;

  saveCharacters();

  const oddsFormatted =
    odds.toLocaleString("en-US");

  await sock.sendMessage(
    msg.key.remoteJid,
    {
      text:
        "◈ Probabilidad visual actualizada.\n\n" +
        "◈ Nombre » " + character.name + "\n" +
        "☆ Anime » " + character.anime + "\n\n" +
        "`1` *en* `" + oddsFormatted + "`"
    },
    { quoted: msg }
  );
}
// ==== RW: diseno estilizado compartido por /rw y /rwp ====
const RW_STYLE_MAP = {
  a: "\u1972", e: "\u1971", i: "\u03B9", l: "\u1963", n: "\u1952", u: "\u1959", c: "\u1974", p: "\u03C1",
  "\u00E1": "\u1972\u0301", "\u00E9": "\u1971\u0301", "\u00ED": "\u03B9\u0301", "\u00FA": "\u1959\u0301"
};

function estilizarRW(texto) {
  return Array.from(String(texto ?? ""))
    .map(ch => RW_STYLE_MAP[ch] ?? ch)
    .join("");
}

const RW_LABELS = {
  ES: {
    name: 'Nombre', anime: 'Anime', gender: 'G\u00E9nero',
    status: 'Estado', rarity: 'Rareza', value: 'Valor',
    chance: 'Chance', creator: 'Creador',
    free: 'Libre', unknown: 'Desconocido', common: 'Comun'
  },
  EN: {
    name: 'Name', anime: 'Anime', gender: 'Gender',
    status: 'Status', rarity: 'Rarity', value: 'Value',
    chance: 'Chance', creator: 'Creator',
    free: 'Free', unknown: 'Unknown', common: 'Common'
  }
};

const RW_FIELD_TRANSLATIONS = {
  EN: {
    gender: {
      'mujer': 'Woman', 'femenino': 'Female',
      'hombre': 'Man', 'masculino': 'Male',
      'femboy': 'Femboy', 'tomboy': 'Tomboy',
      'no binario': 'Non-binary', 'nobinario': 'Non-binary',
      'desconocido': 'Unknown'
    },
    status: {
      'libre': 'Free'
    },
    rarity: {
      'comun': 'Common', 'raro': 'Rare',
      'epico': 'Epic', 'legendario': 'Legendary',
      'mitico': 'Mythic', 'mod': 'Mod'
    }
  }
};

function normalizeFieldKey(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function translateRwField(field, value, lang) {
  if (!lang || lang === 'ES') return value;
  const dict = RW_FIELD_TRANSLATIONS[lang];
  if (!dict) return value;
  const fieldDict = dict[field];
  if (!fieldDict) return value;
  const key = normalizeFieldKey(value);
  return fieldDict[key] || value;
}

function buildRwCaption(character, estadoTxt, creatorName, sender) {
  const lang = getUserLanguage(sender);
  const labels = RW_LABELS[lang] || RW_LABELS.ES;
  const displayOdds = Number(character.displayOdds);
  const oddsLabel = lang === 'EN' ? 'in' : 'en';
  const displayOddsText =
    Number.isSafeInteger(displayOdds) && displayOdds > 0
      ? "\u00601\u0060 *" + oddsLabel + "* \u0060" + displayOdds.toLocaleString("en-US") + "\u0060"
      : "";
  const valor =
    typeof character.value === "number"
      ? character.value.toLocaleString()
      : String(character.value ?? 0);
  const genderTrans = translateRwField("gender", character.gender || labels.unknown, lang);
  const rarityTrans = translateRwField("rarity", character.rarity || labels.common, lang);
  const estadoTrans = translateRwField("status", estadoTxt || labels.free, lang);
  const text =
    "\u2727 *" + labels.name + "* \u00BB \u0060" + (character.name || "") + "\u0060\n" +
    "\u273F *" + labels.anime + "* \u00BB \u0060" + (character.anime || "") + "\u0060\n" +
    "\uD83D\uDF1A *" + labels.gender + "* \u00BB \u0060" + genderTrans + "\u0060\n" +
    "\u265B *" + labels.status + "* \u00BB \u0060" + estadoTrans + "\u0060\n\n" +
    "\u2730 *" + labels.rarity + "* \u00BB \u0060" + rarityTrans + "\u0060\n" +
    "\u272F *" + labels.value + "* \u00BB \u0060" + valor + "\u0060\n" +
    "\u225B  *" + labels.chance + "* \u00BB \u0060" + calcularProbabilidad(Number(character.value) || 0).toFixed(2) + "%" + "\u0060\n\n" +
    "> \u2605 *" + labels.creator + "* \u00BB \u0060" + creatorName + "\u0060\n\n" +
    displayOddsText;
  return applyLangStyle(text, lang);
}

async function getDanbooruImageWithAuth(tag) {
  const creds = getDanbooruCredentials();
  if (!creds || !creds.login || !creds.api_key) return null;
  const t = String(tag || '').trim();
  if (!t) return null;
  try {
    const url = 'https://danbooru.donmai.us/posts.json?tags=' + encodeURIComponent(t) + '&limit=20&login=' + encodeURIComponent(creds.login) + '&api_key=' + encodeURIComponent(creds.api_key);
    const res = await fetch(url, { headers: { 'User-Agent': 'MioHaimiyaBot/1.0', 'Accept': 'application/json' } });
    if (!res.ok) return null;
    const posts = await res.json();
    if (!Array.isArray(posts) || !posts.length) return null;
    const valid = posts.filter(p => p && p.file_url && !['mp4','webm'].includes(String(p.file_ext||'').toLowerCase()));
    if (!valid.length) return null;
    const pick = valid[Math.floor(Math.random() * valid.length)];
    return pick.large_file_url || pick.file_url;
  } catch (e) { return null; }
}

