export async function handleCn(sock, msg, groupId, sender) {
  return carCommandLock(groupId, async () => {
    const cooldowns = getGroupCooldowns(groupId, sender);
    const now = Date.now();
    const existingCooldown =
      getCooldownRemainingMs(cooldowns.cn, now);
    if (existingCooldown > 0) {
      return sock.sendMessage(
        msg.key.remoteJid,
        {
          text:
            `𖤛 Dᴇbᴇs ᴇsρᴇrɴr \`${formatCooldown(existingCooldown)}\` ` +
            `ρɴrɴ voʟvᴇr ɴ ᴠsɴr \`${db.prefix || '/'}cn\` .`
        },
        { quoted: msg }
      );
    }

    const car = getRandomCar(candidate =>
      Array.isArray(candidate.images) &&
      candidate.images.some(image =>
        typeof image === 'string' && fs.existsSync(image)
      )
    );

    if (!car) {
      return sock.sendMessage(
        msg.key.remoteJid,
        { text: 'No hay vehículos con imágenes disponibles.' },
        { quoted: msg }
      );
    }

    const images = car.images.filter(
      image => typeof image === 'string' && fs.existsSync(image)
    );
    const randomImage = getRandomCarImage(images);
    if (!randomImage) {
      return sock.sendMessage(
        msg.key.remoteJid,
        { text: `El vehículo ${car.carName} no tiene imágenes disponibles.` },
        { quoted: msg }
      );
    }

    const img = fs.readFileSync(randomImage);
    const user = initUser(sender);
    if (!user) {
      return sock.sendMessage(
        msg.key.remoteJid,
        { text: 'No pude validar tu cuenta para guardar el vehículo.' },
        { quoted: msg }
      );
    }

    const cooldown = tryStartCooldown(cooldowns, now);
    if (!cooldown.allowed) {
      return sock.sendMessage(
        msg.key.remoteJid,
        {
          text:
            `𖤛 Dᴇbᴇs ᴇsρᴇrɴr \`${formatCooldown(cooldown.remainingMs)}\` ` +
            `ρɴrɴ voʟvᴇr ɴ ᴠsɴr \`${db.prefix || '/'}cn\` .`
        },
        { quoted: msg }
      );
    }

    const owner = car.claimedBy?.[groupId];
    const state = owner ? 'Rᴇᴘʟɴmɴdo' : 'Dιsρoᴛιbʟᴇ';
    const prefix =
      typeof db.prefix === 'string' && db.prefix.length > 0
        ? db.prefix
        : '/';

    user.lastVehicleByGroup ??= {};
    user.lastVehicleByGroup[groupId] = {
      id: car.id,
      key: car.key,
      timestamp: now
    };
    await saveDB();

    const caption =
`■ Cɴrro : *${car.carName}*

☆ Rɴᴛgo : *${car.rarity || 'Sin rango'}*
⛀ Prᴇᴘιo : \`${Number(car.price || 0).toLocaleString('es-CL')}\`
𖤛 Vᴇʟoᴘιdɴd : \`${car.speed || 0} KM/H\`
❀ Aᴘᴇʟᴇrɴᴘιoᴛ : \`${Number.isFinite(Number(car.acceleration)) && Number(car.acceleration) > 0 ? car.acceleration : 'Pendiente'}\`
♧ Estɴdo : *${state}*
♡ Asoᴘιɴdo : *${car.personaje || 'No asociado'}*

> Rᴇᴘʟɴ́mɴʟo ᴘoᴛ *${prefix}cv* ᴘιtɴᴛdo ᴇstᴇ mᴇᴛsɴjᴇ`;

    await sock.sendMessage(
      msg.key.remoteJid,
      { image: img, caption },
      { quoted: msg }
    );
  });
}

export async function handleCv(sock, msg, groupId, sender) {
  return carCommandLock(groupId, async () => {
    const user = initUser(sender);
    if (!user) {
      return sock.sendMessage(
        msg.key.remoteJid,
        { text: 'No pude validar tu cuenta para reclamar el vehículo.' },
        { quoted: msg }
      );
    }

    const lastVehicle = user.lastVehicleByGroup?.[groupId];
    if (!lastVehicle) {
      return sock.sendMessage(
        msg.key.remoteJid,
        { text: `❌ Primero usa ${db.prefix || '/'}cn en este grupo.` },
        { quoted: msg }
      );
    }

    const car = carsCache.find(
      candidate => Number(candidate.id) === Number(lastVehicle.id)
    );
    if (!car) {
      return sock.sendMessage(
        msg.key.remoteJid,
        { text: 'El vehículo mostrado ya no existe.' },
        { quoted: msg }
      );
    }

    const price = Number(car.price);
    if (!Number.isSafeInteger(price) || price < 0) {
      return sock.sendMessage(
        msg.key.remoteJid,
        { text: 'No se puede comprar este vehículo: su precio no es válido.' },
        { quoted: msg }
      );
    }

    const economy = getGroupEconomy(groupId, sender);
    const previousCoins = Number(economy.coins);
    const previousBank = Number(economy.bank);
    const claimResult = claimCar(car, groupId, sender, economy);
    if (claimResult.status === 'already-claimed') {
      const owner =
        db.users?.[claimResult.owner]?.name ||
        String(claimResult.owner || '').split('@')[0] ||
        'otro usuario';
      return sock.sendMessage(
        msg.key.remoteJid,
        { text: `Ese vehículo ya fue reclamado por *${owner}* en este grupo.` },
        { quoted: msg }
      );
    }
    if (claimResult.status === 'insufficient-funds') {
      const available =
        (Number(economy.coins) || 0) + (Number(economy.bank) || 0);
      return sock.sendMessage(
        msg.key.remoteJid,
        {
          text:
            `No tienes fondos suficientes para comprarlo. Precio: ${price.toLocaleString()}; ` +
            `disponible entre wallet y banco: ${available.toLocaleString()}.`
        },
        { quoted: msg }
      );
    }

    if (claimResult.status !== 'claimed') {
      return sock.sendMessage(
        msg.key.remoteJid,
        { text: 'No se pudo validar el vehículo para la compra.' },
        { quoted: msg }
      );
    }
    const payment = claimResult.payment;
    delete user.lastVehicleByGroup[groupId];

    try {
      saveCars();
      await saveDB();
    } catch (error) {
      delete car.claimedBy[groupId];
      economy.coins = previousCoins;
      economy.bank = previousBank;
      user.lastVehicleByGroup[groupId] = lastVehicle;
      saveCars();
      await saveDB();
      throw error;
    }

    const name = db.users?.[sender]?.name || sender.split('@')[0];
    const currency = getBotCurrency(sock);
    await sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
          `■ *${name}* reclamó *${car.carName}* en este grupo.\n` +
          `Precio pagado: ${price.toLocaleString()} ${currency} ` +
          `(wallet ${payment.fromCoins.toLocaleString()}, banco ${payment.fromBank.toLocaleString()}).`
      },
      { quoted: msg }
    );
  });
}

export async function handleGarage(sock, msg, args, groupId, sender) {
  loadCars();
  const prefix =
    typeof db.prefix === 'string' && db.prefix.length > 0
      ? db.prefix
      : '/';
  const input = String(args[0] || '1').trim();
  if (args.length > 1 || !/^[1-9]\d*$/.test(input)) {
    return sock.sendMessage(
      msg.key.remoteJid,
      { text: `Uso: ${prefix}garaje [número de página positivo].` },
      { quoted: msg }
    );
  }

  const requestedPage = Number(input);
  if (!Number.isSafeInteger(requestedPage)) {
    return sock.sendMessage(
      msg.key.remoteJid,
      { text: 'El número de página debe ser un entero positivo válido.' },
      { quoted: msg }
    );
  }

  const getSpeed = car => {
    const speed = Number(car.speed);
    return Number.isFinite(speed) ? speed : 0;
  };

  const ownedCars = getGroupOwnedCars(carsCache, groupId, sender)
    .sort((first, second) =>
      getSpeed(second) - getSpeed(first) ||
      String(first.carName || '').localeCompare(String(second.carName || ''), 'es') ||
      Number(first.id || 0) - Number(second.id || 0)
    );

  if (!ownedCars.length) {
    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
          `❀ Aᴠtos Rᴇᴘʟɴmɴdos ❀\n` +
          `❦ Usᴠɴrιo: \`${db.users?.[sender]?.name || sender.split('@')[0]}\`\n` +
          '♡ Aᴠtos: `(0)`\n\n' +
          '> No tienes autos reclamados en este grupo.'
      },
      { quoted: msg }
    );
  }

  const page = paginateCars(ownedCars, requestedPage);
  if (!page.valid) {
    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text: `Página inválida. Las páginas disponibles van de 1 a ${page.pageCount}.`
      },
      { quoted: msg }
    );
  }

  const rows = page.cars.map(car =>
    `» \`${car.carName || 'Auto sin nombre'}\` 𖤛 \`${getSpeed(car)}km\` ✶ \`${Number.isFinite(Number(car.acceleration)) && Number(car.acceleration) > 0 ? car.acceleration : 'Pendiente'}\``
  );
  const text =
    `❀ Aᴠtos Rᴇᴘʟɴmɴdos ❀\n` +
    `❦ Usᴠɴrιo: \`${db.users?.[sender]?.name || sender.split('@')[0]}\`\n` +
    `♡ Aᴠtos: \`(${ownedCars.length})\`\n\n` +
    `${rows.join('\n')}\n\n` +
    `> ❦ *Pɴ́gιᴛɴ *${page.page}* dᴇ *${page.pageCount}**`;

  return sock.sendMessage(
    msg.key.remoteJid,
    { text },
    { quoted: msg }
  );
}


// GIFTSHOP_V4_CONSTANTS
const DEFAULT_GIFT_PRICE = 50000000;
const BUYLUCK_COOLDOWN_MS = 60 * 1000;
const GIFT_ABANDON_MS = 3 * 24 * 60 * 60 * 1000;
const GIFT_GEMS_PER_PERCENT = 10000000;

function calcGiftLoveGain(price) {
  return Math.max(1, Math.floor(Number(price) / GIFT_GEMS_PER_PERCENT));
}

const GIFT_FANCY_NAMES = {
  'rosa': 'Rosa',
  'peluche': 'Peluche',
  'carta de amor': 'Carta de amor',
  'anillo': 'Anillo',
  'collar': 'Collar',
  'caja de chocolates': 'Caja de chocolates',
  'ramo de flores': 'Ramo de flores',
  'viaje romantico': 'Viaje romantico',
  'cena especial': 'Cena especial',
  'pulsera de oro': 'Pulsera de oro'
};

function fancyGiftName(name) {
  const key = String(name || '').toLowerCase().trim();
  return GIFT_FANCY_NAMES[key] || name;
}

function formatGiftPrice(price) {
  const n = Math.max(0, Math.floor(Number(price) || 0));
  const s = n.toLocaleString('en-US').replace(/,/g, '.');
  return s.split('').map(ch => {
    const code = ch.charCodeAt(0);
    if (code >= 48 && code <= 57) return String.fromCodePoint(0x1D7CE + code - 48);
    return ch;
  }).join('');
}

function ensureGiftShop() {
  db.giftshop ??= {};
  const defaults = [
    { id: 1,  name: 'Rosa' },
    { id: 2,  name: 'Peluche' },
    { id: 3,  name: 'Carta de amor' },
    { id: 4,  name: 'Anillo' },
    { id: 5,  name: 'Collar' },
    { id: 6,  name: 'Caja de chocolates' },
    { id: 7,  name: 'Ramo de flores' },
    { id: 8,  name: 'Viaje romantico' },
    { id: 9,  name: 'Cena especial' },
    { id: 10, name: 'Pulsera de oro' }
  ];
  for (const g of defaults) {
    if (!db.giftshop[g.id] || typeof db.giftshop[g.id] !== 'object') {
      db.giftshop[g.id] = { name: g.name, price: DEFAULT_GIFT_PRICE };
    }
    if (!db.giftshop[g.id].name) db.giftshop[g.id].name = g.name;
    if (typeof db.giftshop[g.id].price !== 'number') {
      db.giftshop[g.id].price = DEFAULT_GIFT_PRICE;
    }
  }
  return db.giftshop;
}


export async function handleGiftShop(sock, msg) {
  const shop = ensureGiftShop();
  const jid = msg.key.remoteJid;
  
  let texto = '꒰ ♡ ꒱ Ƭιεηԃα ԃε Rεɠαʅσʂ ꒰ ♡ ꒱\n\n';
  
  const ids = Object.keys(shop).sort((a, b) => Number(a) - Number(b));
  for (const id of ids) {
    const g = shop[id];
    texto += '♡⃕ ' + id + ' » `' + fancyGiftName(g.name) + '`\n';
    texto += '💎 ' + formatGiftPrice(g.price) + ' ɠεɱαʂ\n\n';
  }
  
  texto += '> 🛒 Compra con /giftbuy ID o nombre.';
  texto += '> 🎁 Regala con /giftgive nombre / waifu.';
  
  await sock.sendMessage(jid, { text: texto }, { quoted: msg });
}

export async function handleSetGiftPrice(sock, msg, args, sender, isOwner) {
  const jid = msg.key.remoteJid;
  if (!isOwner) {
    return sock.sendMessage(jid, { text: '❌ Solo el owner puede cambiar precios.' }, { quoted: msg });
  }
  const raw = String(args.join(' ')).trim();
  const match = raw.match(/^(\d+)\s*\/\s*([\d]+(?:[.,]\d+)?)$/);
  if (!match) {
    return sock.sendMessage(jid, { text: '◈ Uso: /prex ID / precio\n\nEjemplo: /prex 1 / 75000000' }, { quoted: msg });
  }
  const id = String(match[1]);
  const price = parseFloat(match[2].replace(',', '.'));
  if (!Number.isFinite(price) || price <= 0) {
    return sock.sendMessage(jid, { text: '◈ Precio invalido.' }, { quoted: msg });
  }
  const shop = ensureGiftShop();
  if (!shop[id]) {
    return sock.sendMessage(jid, { text: '◈ No existe el regalo ID ' + id + '. Usa /giftshop.' }, { quoted: msg });
  }
  shop[id].price = price;
  saveDB();
  const loveGain = calcGiftLoveGain(price);
  await sock.sendMessage(jid, {
    text: '✓ Precio actualizado\n\n◈ ' + shop[id].name + '\n🆔 ID: ' + id + '\n💎 ' + price.toLocaleString() + ' gemas\n❤️ Amor por compra: +' + loveGain + '%'
  }, { quoted: msg });
}

function ensureGroupGiftInventory(groupId) {
  db.groups ??= {};
  db.groups[groupId] ??= {};
  db.groups[groupId].giftInventory ??= {};
  return db.groups[groupId].giftInventory;
}

function getUserGiftInventory(groupId, userId) {
  const inv = ensureGroupGiftInventory(groupId);
  inv[userId] ??= {};
  return inv[userId];
}

function __giftFancyLocal(str) {
  const map = { 'a': 'α', 'e': 'ε', 'i': 'ι', 'l': 'ʅ', 'n': 'η', 'o': 'σ', 'u': 'υ', 'y': 'ყ' };
  return String(str || '').split('').map(ch => map[ch] || ch).join('');
}

export async function handleGiftBuy(sock, msg, args, sender, jid) {
  const shop = ensureGiftShop();
  const raw = String(args.join(' ')).trim();
  if (!raw) {
    return sock.sendMessage(jid, { text: '◈ Uso: /giftbuy ID o nombre' }, { quoted: msg });
  }

  let giftId = null;
  if (/^\d+$/.test(raw)) {
    if (shop[raw]) giftId = raw;
  } else {
    const wanted = raw.toLowerCase();
    for (const id of Object.keys(shop)) {
      if (String(shop[id].name).toLowerCase() === wanted) { giftId = id; break; }
    }
    if (!giftId) {
      for (const id of Object.keys(shop)) {
        if (String(shop[id].name).toLowerCase().includes(wanted)) { giftId = id; break; }
      }
    }
  }

  if (!giftId) {
    return sock.sendMessage(jid, { text: '◈ Nσ ɦαყ nιngυn rεgαlσ cσn εsε nσmbrε.\n> Usα */giftshop* pαrα vεr lαs σpcισnεs dιspσnιblεs. 𖴓' }, { quoted: msg });
  }

  const gift = shop[giftId];
  const user = initUser(sender);
  if (!user) {
    return sock.sendMessage(jid, { text: '❌ No se pudo cargar tu cuenta.' }, { quoted: msg });
  }

  const price = Number(gift.price) || 0;
  const currentGems = Number(user.gems) || 0;

  if (currentGems < price) {
    return sock.sendMessage(jid, {
      text: '◈ Gemas insuficientes.\n> Precio: ' + price.toLocaleString() + ' gemas.\n> Tu saldo: ' + currentGems.toLocaleString() + ' gemas.\n> Te faltan: ' + (price - currentGems).toLocaleString() + ' gemas.'
    }, { quoted: msg });
  }

  user.gems = currentGems - price;

  const inv = getUserGiftInventory(jid, sender);
  inv[giftId] = (Number(inv[giftId]) || 0) + 1;
  const totalOwned = inv[giftId];

  saveDB();

  return sock.sendMessage(jid, {
    text:
      '✦ Cσɱρɾαstε `' + __giftFancyLocal(gift.name) + '` !\n\n' +
      '> ✦ Cαηƚιԃαԃ: `1`\n' +
      '> ✦ Ƭσƚαʅ εη ιηvεηƚαɾισ: `' + totalOwned + '`\n' +
      '> ✦ 💎 Gεɱαʂ ɾεʂƚαηƚεʂ: `' + user.gems.toLocaleString() + '`\n\n' +
      '> ❥ Usα `/giftgive ' + gift.name + ' / NombreWaifu` ραɾα ɾεɠαʅαɾʅσ.'
  }, { quoted: msg });
}

export async function handleGiftGive(sock, msg, args, sender, jid) {
  const raw = String(args.join(' ')).trim();
  if (!raw) {
    return sock.sendMessage(jid, {
      text: '◈ Uso: /giftgive Nombre del regalo / Nombre de la waifu\n\n> Ejemplo: /giftgive Anillo / Seyoung Na'
    }, { quoted: msg });
  }

  const parts = raw.split('/').map(x => x.trim()).filter(Boolean);
  if (parts.length < 2) {
    return sock.sendMessage(jid, {
      text: '◈ Uso: /giftgive Nombre del regalo / Nombre de la waifu'
    }, { quoted: msg });
  }

  const giftName = parts[0];
  const waifuName = parts.slice(1).join(' / ');

  const shop = ensureGiftShop();

  let giftId = null;
  const wantedGift = giftName.toLowerCase();
  for (const id of Object.keys(shop)) {
    if (String(shop[id].name).toLowerCase() === wantedGift) { giftId = id; break; }
  }
  if (!giftId) {
    for (const id of Object.keys(shop)) {
      if (String(shop[id].name).toLowerCase().includes(wantedGift)) { giftId = id; break; }
    }
  }
  if (!giftId) {
    return sock.sendMessage(jid, {
      text: '◈ Nσ ɦαყ nιngυn rεgαlσ cσn εsε nσmbrε.\n> Usα */giftshop* pαrα vεr lαs σpcισnεs dιspσnιblεs. 𖴓'
    }, { quoted: msg });
  }

  const user = initUser(sender);
  if (!user) {
    return sock.sendMessage(jid, { text: '❌ No se pudo cargar tu cuenta.' }, { quoted: msg });
  }

  user.waifu ??= { current: null, totalLove: 0, maxLove: 0, ligues: {}, groupLigues: {}, lastLigue: 0 };
  user.waifu.groupLigues ??= {};

  const chatLigues = user.waifu.groupLigues[jid] || {};
  const ligueEntries = Object.entries(chatLigues);

  if (!ligueEntries.length) {
    return sock.sendMessage(jid, {
      text: '◈ No tienes waifus ligadas en este grupo.\n> Usa /ligue Nombre.'
    }, { quoted: msg });
  }

  const normalize = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  const wantedWaifu = normalize(waifuName);

  let targetEntry = null;
  for (const [charKey, ligue] of ligueEntries) {
    const character = characterKeyMap.get(charKey);
    const name = normalize(character?.name || ligue?.name || charKey);
    if (name === wantedWaifu) { targetEntry = { charKey, ligue, character }; break; }
  }
  if (!targetEntry) {
    for (const [charKey, ligue] of ligueEntries) {
      const character = characterKeyMap.get(charKey);
      const name = normalize(character?.name || ligue?.name || charKey);
      if (name.includes(wantedWaifu)) { targetEntry = { charKey, ligue, character }; break; }
    }
  }

  if (!targetEntry) {
    return sock.sendMessage(jid, {
      text:
        '◈ No tienes ninguna waifu llamada `' + waifuName + '` en tus /ligues.\n\n' +
        '> Ligue con ella primero con /ligue ' + waifuName
    }, { quoted: msg });
  }

  const inv = getUserGiftInventory(jid, sender);
  const owned = Number(inv[giftId]) || 0;

  if (owned <= 0) {
    return sock.sendMessage(jid, {
      text:
        '◈ No tienes `' + shop[giftId].name + '` en tu inventario.\n\n' +
        '> Compra uno con /giftbuy ' + shop[giftId].name
    }, { quoted: msg });
  }

  const { charKey, ligue, character } = targetEntry;
  const charName = character?.name || ligue?.name || charKey;
  const currentLove = Number(ligue.love) || 0;

  inv[giftId] = owned - 1;
  if (inv[giftId] <= 0) delete inv[giftId];

  const price = Number(shop[giftId].price) || 0;
  const loveGain = calcGiftLoveGain(price);
  const newLove = Math.min(100, currentLove + loveGain);
  const actualGain = newLove - currentLove;

  ligue.love = newLove;
  ligue.gifts = (Number(ligue.gifts) || 0) + 1;
  ligue.lastGift = Date.now();
  ligue.lastGiftName = shop[giftId].name;

  if (user.waifu.groupLigues[jid]) user.waifu.groupLigues[jid][charKey] = ligue;
  if (user.waifu.ligues) user.waifu.ligues[charKey] = ligue;
  user.waifu.totalLove = (Number(user.waifu.totalLove) || 0) + actualGain;
  if (newLove > (Number(user.waifu.maxLove) || 0)) user.waifu.maxLove = newLove;

  saveDB();

  let sent = null;
  try {
    sent = await sock.sendMessage(jid, { text: 'Eᴛtrᴇgɴᴛdoʟᴇ ᴇʟ rᴇgɴʟo...' }, { quoted: msg });
  } catch (e) {
    console.error('[GIFTGIVE] Error enviando mensaje inicial:', e?.message || e);
  }

  await new Promise(resolve => setTimeout(resolve, 3000));

  let design =
    '۶ৎ Lε rεgαlαstε ' + __giftFancyLocal(shop[giftId].name) + ' α `' + __giftFancyLocal(charName) + '`.' +
    '\n> ✦ Amσr gαnαdσ: `+' + actualGain + '%`' +
    '\n> ✦ Amσr αctυαl: `' + newLove + '% / 100%`';

  if (newLove >= 100) {
    design += '\n> ✧ ¡Amσr αl `100%`!';
  }

  if (sent && sent.key && sent.key.id) {
    try {
      await sock.sendMessage(jid, { text: design, edit: sent.key });
      return;
    } catch (e) {
      console.error('[GIFTGIVE] Error editando:', e?.message || e);
    }
  }

  try {
    await sock.sendMessage(jid, { text: design }, { quoted: msg });
  } catch (e) {
    console.error('[GIFTGIVE] Error enviando fallback:', e?.message || e);
  }
}

export async function handleGives(sock, msg, jid, sender) {
  const shop = ensureGiftShop();
  const inv = getUserGiftInventory(jid, sender);

  const entries = Object.entries(inv)
    .filter(([, count]) => Number(count) > 0)
    .sort((a, b) => Number(b[1]) - Number(a[1]));

  if (!entries.length) {
    return sock.sendMessage(jid, {
      text:
        '꒰ ♡ ꒱ Ƭυʂ Rεɠαʅσʂ ꒰ ♡ ꒱\n\n' +
        '> ◈ No tienes regalos en este grupo.\n\n' +
        '> ❥ Compra uno con /giftbuy'
    }, { quoted: msg });
  }

  let texto = '꒰ ♡ ꒱ Ƭυʂ Rεɠαʅσʂ εη εʂƚε ɠɾυρσ ꒰ ♡ ꒱\n\n';
  let total = 0;

  for (const [giftId, count] of entries) {
    const gift = shop[giftId];
    if (!gift) continue;
    const qty = Number(count) || 0;
    total += qty;
    texto += '> ◈ ' + __giftFancyLocal(gift.name) + ' × `' + qty + '`\n';
  }

  texto += '\n> ✦ Ƭσƚαʅ ɾεɠαʅσʂ: `' + total + '`\n';
  texto += '\n> ❥ Usα `/giftgive Nombre / Waifu` ραɾα ɾεɠαʅαɾ.\n';
  texto += '> ❥ Lσʂ ɾεɠαʅσʂ ʂση ρσɾ ɠɾυρσ.';

  return sock.sendMessage(jid, { text: texto }, { quoted: msg });
}

export async function handleWainfo(sock, msg, args, jid, sender) {
  const user = initUser(sender);
  if (!user) {
    return sock.sendMessage(jid, { text: '❌ No se pudo cargar tu cuenta.' }, { quoted: msg });
  }

  user.waifu ??= { current: null, totalLove: 0, maxLove: 0, ligues: {}, groupLigues: {}, lastLigue: 0 };
  user.waifu.groupLigues ??= {};

  const chatLigues = user.waifu.groupLigues[jid] || {};
  const entries = Object.entries(chatLigues);

  if (!entries.length) {
    return sock.sendMessage(jid, {
      text:
        'ꓰ ๑ ꓱ Wαιɳϝσ ꓰ ๑ ꓱ\n\n' +
        '> ◈ No tienes waifus ligadas en este grupo.\n' +
        '> Usa /ligue Nombre.'
    }, { quoted: msg });
  }

  const query = String(args.join(' ')).trim();
  const normalize = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();

  let target = null;

  if (query) {
    const wanted = normalize(query);
    for (const [charKey, ligue] of entries) {
      const character = characterKeyMap.get(charKey);
      const name = normalize(character?.name || ligue?.name || charKey);
      if (name === wanted) { target = { charKey, ligue, character }; break; }
    }
    if (!target) {
      for (const [charKey, ligue] of entries) {
        const character = characterKeyMap.get(charKey);
        const name = normalize(character?.name || ligue?.name || charKey);
        if (name.includes(wanted)) { target = { charKey, ligue, character }; break; }
      }
    }
    if (!target) {
      return sock.sendMessage(jid, {
        text: '◈ No tienes ninguna waifu llamada `' + query + '` en tus /ligues.'
      }, { quoted: msg });
    }
  } else {
    const [charKey, ligue] = entries[0];
    target = { charKey, ligue, character: characterKeyMap.get(charKey) };
  }

  const { charKey, ligue, character } = target;
  const charName = character?.name || ligue?.name || charKey;
  const love = Number(ligue.love) || 0;
  const gifts = Number(ligue.gifts) || 0;
  const started = Number(ligue.started) || Date.now();
  const lastGiftName = ligue.lastGiftName || null;

  const chileDateStr = (ms) => {
    try {
      const parts = new Intl.DateTimeFormat('en-CA', {
        timeZone: 'America/Santiago',
        year: 'numeric', month: '2-digit', day: '2-digit'
      }).format(new Date(ms)).split('-');
      return parts[2] + '/' + parts[1] + '/' + parts[0];
    } catch (e) {
      const d = new Date(ms);
      return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear();
    }
  };

  const boldDigits = (s) => String(s || '').split('').map(ch => {
    const n = ch.charCodeAt(0);
    if (n >= 48 && n <= 57) return String.fromCodePoint(0x1D7CE + (n - 48));
    return ch;
  }).join('');

  const fancy = __giftFancyLocal;
  const dateStrFancy = boldDigits(chileDateStr(started));

  const THREE_DAYS = 3 * 24 * 60 * 60 * 1000;
  const ref = Number(ligue.lastGift) || started;
  const elapsed = Math.max(0, Date.now() - ref);
  const riskPercent = Math.min(100, Math.floor((elapsed / THREE_DAYS) * 100));

  const caption =
       '꒰ 𔘓 ꒱ Wαιɳϝσ ꒰ 𔘓 ꒱\n\n' +
        '୨୧ ' + fancy('NσɱႦɾҽ') + ' » `' + fancy(charName) + '`\n\n' +
        '♡ ' + fancy('Víɳƈυʅσ') + ' » \n' +
        '「💗」 `' + fancy('Aϝιɳιԃαԃ|') + '`\n' +
        '↳ *' + love + '% / 100%*\n\n' +
        '「🎁」 `' + fancy('Rҽɠαʅσʂ ԃαԃσʂ') + '`\n' +
        '↳ *' + gifts + ' ' + fancy('ɾҽɠαʅσʂ') + '*\n\n' +
        '「📅」 `' + fancy('Fҽƈԋα ԃҽ ɾҽʅαƈιóɳ') + '`\n' +
        '↳ *' + dateStrFancy + '*\n\n' +
        '「🎀」 `' + fancy('Úʅƚιɱσ ɾҽɠαʅσ') + '`\n' +
        '↳ *' + (lastGiftName ? fancy(lastGiftName) : fancy('Aɳιʅʅσ')) + '*\n\n' +
        '「☁️」 `' + fancy('PɾσႦαႦιʅιԃαԃ ԃҽ Ⴆαʝαɾ') + '`\n' +
        '↳ *' + riskPercent + '% ' + fancy('ԃҽ ɾιҽʂɠσ') + '*\n\n' +
        '> ꒰ ♡ ꒱ ' + fancy('Cυιԃα ƚυ αɱσɾ ყ ɳσ ԃҽʝҽʂ ԃҽ ɾҽɠαʅαɾʅҽ') + '. ♡'
   

  let media = null;

  // 1) Imagen local (rapido)
  try {
    const localImages = getCharacterImages(charKey);
    if (localImages.length) {
      const img = localImages[Math.floor(Math.random() * localImages.length)];
      const imgPath = path.join(GACHA_IMAGES, img);
      const buffer = imageCache.get(imgPath) || fs.readFileSync(imgPath);
      imageCache.set(imgPath, buffer);
      media = { image: buffer };
    }
  } catch (e) {
    console.log('[WAINFO] Local error:', e?.message || e);
  }

  // 2) Manual tag (bulguru)
  if (!media && character?.tag) {
    try {
      const manualImage = await getManualCharacterImage(character.tag);
      if (manualImage) media = manualImage;
    } catch (e) {
      console.log('[WAINFO] Manual error:', e?.message || e);
    }
  }

  // 3) Danbooru
  if (!media && character?.tag) {
    try {
      const du = await getDanbooruImageWithAuth(character.tag) || await getDanbooruImage(character.tag);
      if (du) {
        const dd = await downloadImage(du);
        if (dd && dd.buffer && dd.buffer.length) media = { image: dd.buffer, mimetype: dd.mimetype };
      }
    } catch (e) {
      console.log('[WAINFO] Danbooru error:', e?.message || e);
    }
  }

  // 4) Gelbooru (ultimo recurso)
  if (!media && character?.tag) {
    try {
      const url = await getGelbooruImage(character.tag);
      if (url) {
        const downloaded = await downloadImage(url);
        if (downloaded) media = { image: downloaded.buffer, mimetype: downloaded.mimetype };
      }
    } catch (e) {
      console.log('[WAINFO] Gelbooru error:', e?.message || e);
    }
  }

  if (media) {
    return sock.sendMessage(jid, { ...media, caption }, { quoted: msg });
  }

  return sock.sendMessage(jid, { text: caption }, { quoted: msg });
}



// Reintenta obtener la imagen de un personaje (fallos temporales de red/booru)
async function rwMediaRetry(character, intentos = 3) {
  for (let i = 1; i <= intentos; i++) {
    try {
      const media = await getCharacterMedia(character);
      if (media) return media;
    } catch (e) {
      console.error("[RWP] Error de imagen (intento " + i + "/" + intentos + ") ID " + (character && character.id) + ": " + (e && e.message ? e.message : e));
    }
    if (i < intentos) await new Promise(r => setTimeout(r, 1500));
  }
  return null;
}

const rwpCommandLock = createKeyedLock();

export async function handleRwp(sock, msg, args, groupId, sender) {
  const jid = msg.key.remoteJid;
  const user = initUser(sender);

  if (!hasXPremium(user)) {
    return sock.sendMessage(jid, { text: t(sender, 'rwp.xpremium_required') }, { quoted: msg });
  }

  const nameArgs =
    (args.length > 1 && /^\d+%?$/.test(String(args[0])))
      ? args.slice(1)
      : args;
  const charName = nameArgs.join(" ").trim();

  if (!charName) {
    return sock.sendMessage(jid, { text: t(sender, 'rwp.usage', { chance: 100 }) }, { quoted: msg });
  }

  if (!charactersCache.length) { loadCharactersCache(); loadSeries(); }

  const needle = charName.toLowerCase();
  const target =
    charactersCache.find(c => String(c.name || "").toLowerCase() === needle) ||
    charactersCache.find(c => String(c.name || "").toLowerCase().includes(needle));

  if (!target) {
    return sock.sendMessage(jid, { text: t(sender, 'rwp.not_found') }, { quoted: msg });
  }

  return rwpCommandLock(`${sender}:${groupId}`, async () => {
    const RWP_COOLDOWN_MS = 5 * 60 * 60 * 1000;
    const _rwpCooldowns = getGroupCooldowns(groupId, sender);
    _rwpCooldowns.rwp ??= 0;

    const now = Date.now();
    const elapsed = now - _rwpCooldowns.rwp;

    if (elapsed < RWP_COOLDOWN_MS) {
      const remaining = RWP_COOLDOWN_MS - elapsed;
      const h = Math.floor(remaining / 3600000);
      const m = Math.floor((remaining % 3600000) / 60000);
      const s = Math.floor((remaining % 60000) / 1000);
      return sock.sendMessage(
        jid,
        { text: `\u23F3 Espera ${h}h ${m}m ${s}s para volver a usar /rwp en este grupo.` },
        { quoted: msg }
      );
    }

    const imageData = await rwMediaRetry(target, 3);

    if (!imageData) {
      try {
        await notifyEvents(
          sock,
          "\u274C Error de imagen (/rwp)\n\nPersonaje: " + target.name + "\nID: " + target.id + "\nSolicitado por: @" + String(sender).split("@")[0],
          [sender]
        );
      } catch (e) {}
      return sock.sendMessage(jid, { text: t(sender, 'rwp.image_error', { id: target.id }) }, { quoted: msg });
    }

    const claimEntry = target.claimedBy?.[groupId];
    const alreadyClaimed = claimEntry ? claimEntry.user : null;
    const economy = getGroupEconomy(groupId, sender);

    economy.lastClaim = {
      id: target.id,
      key: target.key,
      name: target.name,
      anime: target.anime,
      gender: target.gender,
      value: target.value,
      rarity: target.rarity,
      claimed: !!alreadyClaimed,
      claimedBy: alreadyClaimed,
      timestamp: now,
      invoker: sender
    };

    saveDB();

    const creatorName = getCharacterCreatorName(target);
    const estadoTxt =
      alreadyClaimed
        ? (db.users?.[alreadyClaimed]?.name || alreadyClaimed.split("@")[0])
        : "Libre";

    let rwpResult;
    try {
      rwpResult = await sock.sendMessage(
        jid,
        {
          ...imageData,
          caption: buildRwCaption(target, estadoTxt, creatorName, sender)
        },
        { quoted: msg }
      );
    } catch (sendError) {
      console.error('[RWP] Error enviando:', sendError?.message || sendError);
      economy.lastClaim = null;
      saveDB();
      return;
    }

    _rwpCooldowns.rwp = Date.now();

    try {
      const __trackU = initUser(sender);
      if (__trackU) {
        __trackU.rwpUsed = (Number(__trackU.rwpUsed) || 0) + 1;
        db.stats.rwpUsed = (Number(db.stats.rwpUsed) || 0) + 1;
      }
    } catch (__e) {}

    saveDB();
    rememberRwResultMessage(jid, rwpResult);
  });
}


export async function handleRwr(sock, msg, args, groupId, sender) {
  const isMainOwner =
    isMainOwnerId(sender);
  const isSecondaryOwner =
    isSecondaryOwnerId(sender);

  if (!isMainOwner && !isSecondaryOwner) return;

  const charName = args.join(' ').trim();
  if (!charName) {
    return sock.sendMessage(
      msg.key.remoteJid,
      { text: '◈ Uso:\n/rwr Nombre del personaje' },
      { quoted: msg }
    );
  }

  const user = initUser(sender);
  if (!user) return;

  const COOLDOWN_MS = 5_000;
  const now = Date.now();
  const elapsed = now - (Number(user.lastRwr) || 0);
  if (elapsed < COOLDOWN_MS) {
    const remaining = Math.ceil((COOLDOWN_MS - elapsed) / 1_000);
    return sock.sendMessage(
      msg.key.remoteJid,
      { text: `⏳ Espera ${remaining} segundo(s) para volver a usar /rwr.` },
      { quoted: msg }
    );
  }

  const target = charactersCache.find(
    character => character.name.toLowerCase().includes(charName.toLowerCase())
  );
  if (!target) {
    return sock.sendMessage(
      msg.key.remoteJid,
      { text: '◈ Personaje no encontrado.' },
      { quoted: msg }
    );
  }

  // Guardarlo antes de cargar la imagen evita dos invocaciones simultáneas.
  user.lastRwr = now;
  saveDB();

  const imageData = await getCharacterMedia(target);
  if (!imageData) {
    return sock.sendMessage(
      msg.key.remoteJid,
      { text: `Error > Personaje \`ID ${target.id}\`\n\nSi el problema persiste avísanos con */report*` },
      { quoted: msg }
    );
  }

  const claimEntry = target.claimedBy?.[groupId];
  const alreadyClaimed = claimEntry ? claimEntry.user : null;
  const economy = getGroupEconomy(groupId, sender);
  economy.lastClaim = {
    id: target.id,
    key: target.key,
    name: target.name,
    anime: target.anime,
    gender: target.gender,
    value: target.value,
    rarity: target.rarity,
    claimed: !!alreadyClaimed,
    claimedBy: alreadyClaimed,
    timestamp: now,
    invoker: sender
  };
  saveDB();

  const cap =
`☆ INVOCACIÓN DE OWNER

❬ Nombre » ${target.name}
☆ Rareza » ${target.rarity || 'Comun'}
◈ Suerte usada » 1000%
✰ Valor » ${target.value}`;

  await sock.sendMessage(
    msg.key.remoteJid,
    { ...imageData, caption: cap },
    { quoted: msg }
  );
}

export async function handleRwpx(
  sock,
  msg,
  args,
  sender
){

  if (sender !== OWNER_NUMBER)
  return;

  const raw =
  args.join(' ');

const data =
  raw
  .split('/')
  .map(x => x.trim());

  if (data.length < 2) {

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
'◈ Uso:\n/rwpx 30% / 10000000'
      },
      { quoted: msg }
    );

  }

  const chance =
    data[0]
    .replace('%','')
    .trim();

  const cost =
    Number(
      data[1]
      .trim()
      .replace(/\./g,'')
    );

  if (
  !chance ||
  isNaN(cost)
){
  return sock.sendMessage(
    msg.key.remoteJid,
    {
      text: ' Datos inválidos.'
    },
    {
      quoted: msg
    }
  );
}

  db.rwpChances[chance] =
    cost;

  saveDB();

  await sock.sendMessage(
    msg.key.remoteJid,
    {
      text:
`◈ Chance agregada

Chance » ${chance}%
Costo » ¥${cost.toLocaleString()}`
    },
    {
      quoted: msg
    }
  );

}

export async function handleDelX(
  sock,
  msg,
  args,
  sender
){

  const chance =
    args[0]
    ?.replace('%','');

  if (!chance)
    return;

  delete db.rwpChances[chance];

  saveDB();

  await sock.sendMessage(
    msg.key.remoteJid,
    {
      text:
`◈ Eliminado ${chance}%`
    },
    {
      quoted: msg
    }
  );

}

export async function handleResetGacha({ sock, jid, msg, sender }) {

  if (sender !== OWNER_NUMBER) {
    return sock.sendMessage(jid, {
      text: '◈ Solo el owner puede usar esto.'
    }, { quoted: msg });
  }

  const groups = db.groups || {};

  for (const groupId in groups) {

    groups[groupId].claimedCharacters = {};

    groups[groupId].harems = {};

    groups[groupId].training = {};

  }

  saveDB();

  await sock.sendMessage(jid, {
    text: ' Gacha reiniciado correctamente.\nTodos los personajes ahora están libres.'
  }, { quoted: msg });

for (const char of characterMap.values()) {
  delete char.claimedBy;
  delete char.owner;
}
}

export async function handleResetHarem(sock, msg, jid, sender) {

  if (sender !== OWNER_NUMBER) {
    return sock.sendMessage(
      jid,
      {
        text: '◈ Solo el owner puede usar esto.'
      },
      { quoted: msg }
    );
  }

  const groups = db.groups || {};

  let revisados = 0;
  let reparados = 0;
  let yaCorrectos = 0;

  for (const [groupId, group] of Object.entries(groups)) {

    if (!group) continue;

    group.harems ??= {};

    for (const character of characterMap.values()) {

      const claimedBy = character?.claimedBy?.[groupId];

      if (!claimedBy?.user) {
        continue;
      }

      revisados++;

      const owner = claimedBy.user;

      group.harems[owner] ??= [];

      const harem = group.harems[owner];

      const existsInHarem = harem.some(
        item => item?.key === character.key
      );

      if (existsInHarem) {
        yaCorrectos++;
      } else {

        harem.push({
          id: character.id,
          key: character.key,
          name: character.name,
          anime: character.anime,
          gender: character.gender,
          value: character.value,
          rarity: character.rarity,
          image: character.image || null,
          claimed: false,
          claimedBy: null,
          timestamp: claimedBy.time,
          invoker: owner
        });

        reparados++;
      }

      const user = db.users?.[owner];

      if (user && typeof user === 'object') {
        user.harem ??= [];

        if (!user.harem.includes(character.key)) {
          user.harem.push(character.key);
        }
      }
    }
  }

  buildOwnerIndex();

  saveCharacters();
  saveDB();

  await sock.sendMessage(
    jid,
    {
      text:
`◈ Reparación de harems completada.

□ Reclamaciones revisadas » ${revisados}
◈ Personajes reparados » ${reparados}
◈ Ya estaban correctos » ${yaCorrectos}

◈ Las reclamaciones no fueron liberadas.
◈ Los personajes huérfanos fueron devueltos a sus harems.`
    },
    { quoted: msg }
  );
}

export async function handleClaim(sock, msg, groupId, sender) {
  const jid = msg.key.remoteJid;
  const group = db.groups[groupId];

  // CLAIM_CITE_RW_V1: obligatorio citar el mensaje de /rw (o /rwp)
  const ctx =
    msg.message?.extendedTextMessage?.contextInfo ||
    msg.message?.imageMessage?.contextInfo ||
    msg.message?.videoMessage?.contextInfo;
  const quotedId = ctx?.stanzaId;

  if (!quotedId || !rwResultMessageIds.has(`${jid}:${quotedId}`)) {
    return sock.sendMessage(
      jid,
      {
        text: '𐂂 𝘙𝘦𝘴𝘱𝘰𝘯𝘥𝘦 𝘦𝘭 𝘮𝘦𝘯𝘴𝘢𝘫𝘦 𝘥𝘦 `𝘳𝘸` 𝘱𝘢𝘳𝘢 𝘳𝘦𝘤𝘭𝘢𝘮𝘢𝘳𝘭𝘰.'
      },
      { quoted: msg }
    );
  }

  const economy = getGroupEconomy(groupId, sender);
  const lc = economy.lastClaim;

  if (!lc) {
    return sock.sendMessage(
      jid,
      {
        text:
          '〩 𝘕𝘰 𝘩𝘢𝘺 𝘯𝘪𝘯𝘨𝘶𝘯 𝘱𝘦𝘳𝘴𝘰𝘯𝘢𝘫𝘦 𝘱𝘦𝘯𝘥𝘪𝘦𝘯𝘵𝘦.\n' +
          '> 𝘏𝘢𝘻 𝘱𝘳𝘪𝘮𝘦𝘳𝘰 `/𝘳𝘸`.'
      },
      { quoted: msg }
    );
  }

  if (lc.claimed) {
    const _ownerId = lc.claimedBy;
    const _ownerName =
      db.users?.[_ownerId]?.name ||
      String(_ownerId || '').split('@')[0] ||
      'Usuario';
    return sock.sendMessage(
      jid,
      {
        text:
          '♛ Estᴇ ρᴇrsoᴛɴjᴇ ყɴ fᴠᴇ rᴇᴘʟɴmɴdo ρor `' + _ownerName + '`.'
      },
      { quoted: msg }
    );
  }

  const cooldowns = getGroupCooldowns(groupId, sender);
  const now = Date.now();

  if (now - cooldowns.claim < CLAIM_CD) {
    const w = Math.ceil((CLAIM_CD - (now - cooldowns.claim)) / 1000);
    return sock.sendMessage(
      jid,
      {
        text: `⏳ Debes esperar ${Math.floor(w / 60)}m ${w % 60}s para reclamar de nuevo.`
      },
      { quoted: msg }
    );
  }

  const elapsed = now - lc.timestamp;

  if (elapsed < 20000 && sender !== lc.invoker) {
    return sock.sendMessage(
      jid,
      {
        text: '◈ Solo el invocador puede reclamar en los primeros 20s.'
      },
      { quoted: msg }
    );
  }

  if (elapsed > 30000) {
    economy.lastClaim = null;
    saveDB();
    return sock.sendMessage(
      jid,
      {
        text:
          '〩 𝘕𝘰 𝘩𝘢𝘺 𝘯𝘪𝘯𝘨𝘶𝘯 𝘱𝘦𝘳𝘴𝘰𝘯𝘢𝘫𝘦 𝘱𝘦𝘯𝘥𝘪𝘦𝘯𝘵𝘦.\n' +
          '> 𝘏𝘢𝘻 𝘱𝘳𝘪𝘮𝘦𝘳𝘰 `/𝘳𝘸`.'
      },
      { quoted: msg }
    );
  }

  const character = characterKeyMap.get(lc.key);
  if (!character) return;

  if (!character.claimedBy) character.claimedBy = {};

  if (character.claimedBy[groupId] && character.claimedBy[groupId].user !== sender) {
    const _ownerId = character.claimedBy[groupId].user;
    const _ownerName =
      db.users?.[_ownerId]?.name ||
      String(_ownerId || '').split('@')[0] ||
      'Usuario';
    return sock.sendMessage(
      jid,
      {
        text:
          '♛ Estᴇ ρᴇʀsᴏɴᴀᴊᴇ ʏᴀ ᴇsᴛᴀ ᴿᴇᴄʟᴀᴍᴀᴅᴏ ᴘᴏʀ `' + _ownerName + '`.'
      },
      { quoted: msg }
    );
  }

  character.claimedBy[groupId] = {
    user: sender,
    time: now
  };

  if (character.creator) {
    db.staffStats ??= {};
    db.staffStats[character.creator] ??= { fans: 0, claimed: {} };
    const claimed = db.staffStats[character.creator].claimed;
    claimed[character.id] ??= [];
    if (!claimed[character.id].includes(sender)) {
      claimed[character.id].push(sender);
      db.staffStats[character.creator].fans++;
    }
  }

  if (!global.ownerIndex[groupId]) global.ownerIndex[groupId] = {};
  if (!global.ownerIndex[groupId][sender]) global.ownerIndex[groupId][sender] = new Set();
  global.ownerIndex[groupId][sender].add(lc.key);
  saveCharacters();

  if (!group.harems[sender]) {
    group.harems[sender] = [];
  }

  if (!group.harems[sender].some(c => c.key === lc.key)) {
    group.harems[sender].push(lc);
  }

  await checkHarem100Reward(sock, msg, groupId, sender);

  const owner = initUser(sender);
  owner.harem ??= [];
  if (!owner.harem.includes(lc.key)) {
    owner.harem.push(lc.key);
  }

  cooldowns.claim = now;
  economy.lastClaim = null;

  saveCharacters();
  saveDB();

  // CLAIM_MSG_DEFAULT_V2: formato nuevo por defecto
  let claimText =
    owner.claimMsg ||
    '✦ `$character` 𝘈𝘩𝘰𝘳𝘢 𝘦𝘴 𝘶𝘯𝘢 𝘤𝘰𝘭𝘭𝘦𝘤𝘪𝘰𝘯 𝘥𝘦 `$user`';

  claimText = claimText
    .replace(/\$user/g, owner.name || 'Usuario')
    .replace(/\$character/g, character.name);

  await sock.sendMessage(
    jid,
    { text: claimText },
    { quoted: msg }
  );
}

export async function handleVote(sock, msg, args, groupId, sender) {
  const name =
  args.join(' ')
      .toLowerCase()
      .trim();
  if (!name) return sock.sendMessage(msg.key.remoteJid, { text: t(sender, 'vote.usage') }, { quoted: msg });
  if (!charactersCache.length) loadCharactersCache();
  const char = charactersCache.find(c => c.name.toLowerCase() === name);
  if (!char) return sock.sendMessage(msg.key.remoteJid, { text: t(sender, 'vote.not_found') }, { quoted: msg });

  const now = Date.now();
  const globalCD = db.globalCooldowns.vote[sender] || 0;
  if (now - globalCD < VOTE_CD) {
    const rem = VOTE_CD - (now - globalCD);
    const mins = Math.floor(rem / 60000);
    const secs = Math.floor((rem % 60000) / 1000);
    return sock.sendMessage(msg.key.remoteJid, { text: t(sender, 'vote.cooldown', { minutes: mins, seconds: secs }) }, { quoted: msg });
  }

  char.value += 20;
  char.votes = (char.votes || 0) + 1;
  char.lastVote = now;
  if (char.creator) {

  db.staffStats ??= {};

  db.staffStats[char.creator] ??= {
    fans: 0,
    claimed: {}
  };

  const claimed =
    db.staffStats[
      char.creator
    ].claimed;

  claimed[char.id] ??= [];

  if (
    !claimed[
      char.id
    ].includes(sender)
  ){

    claimed[
      char.id
    ].push(sender);

    db.staffStats[
      char.creator
    ].fans++;

  }

}
  db.globalCooldowns.vote[sender] = now;
  saveCharacters();
  saveDB();
  await sock.sendMessage(msg.key.remoteJid, { text: t(sender, 'vote.success', { name: char.name, value: char.value }) }, { quoted: msg });
}

// ━━━━━━━ COMANDOS DE SERIES ━━━━━━━
export async function handleSlist(sock, msg, args) {
  const sender = msg.key.participant || msg.key.remoteJid;
  const jid = msg.key.remoteJid;
  const page = Math.max(1, parseInt(args[0], 10) || 1);
  const perPage = 10;

  const estilizar = (texto) => {
    const mapa = {
      'a': '\u1972',
      'e': '\u1971',
      'i': '\u03B9',
      'l': '\u1963',
      'n': '\u1952',
      'u': '\u1959',
      'c': '\u1974',
      'p': '\u03C1',
      'y': '\u10E7'
    };
    return String(texto).replace(/[aeiulncpy]/g, ch => mapa[ch] || ch);
  };

  const allSeries = Array.from(seriesCache.values());

  if (!allSeries.length) {
    return sock.sendMessage(
      jid,
      { text: tCmd(sender, '\u25C7 No hay series disponibles.', '\u25C7 No series available.') },
      { quoted: msg }
    );
  }

  // Orden: mayor cantidad de personajes -> menor
  const sorted = [...allSeries].sort((a, b) => {
    const na = Number(a.characters?.size || 0);
    const nb = Number(b.characters?.size || 0);
    if (nb !== na) return nb - na;
    return String(a.name).localeCompare(String(b.name));
  });

  const total = sorted.length;
  const pages = Math.max(1, Math.ceil(total / perPage));
  const safePage = Math.min(page, pages);
  const slice = sorted.slice((safePage - 1) * perPage, safePage * perPage);

  let text =
    '\u274F ' +
    estilizar(tCmd(sender, 'Lista de series', 'Series list')) +
    ' `' + total + '`:\n\n';

  for (const s of slice) {
    const count = s.characters?.size || 0;
    text +=
      '\u00BB `' +
      estilizar(s.name) +
      ' (' + count + ')`\n';
  }

  text +=
    '\n> ' +
    estilizar(tCmd(sender, 'Pagina', 'Page')) +
    ' `' + safePage + '/' + pages + '`';

  await sock.sendMessage(
    jid,
    { text },
    { quoted: msg }
  );
}
export async function handleMergeSerie(
  sock,
  msg,
  args,
  sender
){

  const raw =
    args.join(' ');

  const parts =
    raw.split('/')
       .map(v => v.trim())
       .filter(Boolean);

  if (parts.length < 2){

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
`◈ Uso

/mergeserie Serie origen / Serie destino

Ejemplo

/mergeserie Oshi no Ko / [Oshi No Ko]`
      },
      {
        quoted: msg
      }
    );

  }

  const from =
    findSeries(parts[0]);

  const to =
    findSeries(parts[1]);

  if (!from){

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
`◈ No encontró la serie:

${parts[0]}`
      },
      {
        quoted: msg
      }
    );

  }

  if (!to){

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
`◈ No encontró la serie:

${parts[1]}`
      },
      {
        quoted: msg
      }
    );

  }

  if (
    from.name.toLowerCase() ===
    to.name.toLowerCase()
  ){

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
'◈ No puedes fusionar la misma serie.'
      },
      {
        quoted: msg
      }
    );

  }

  const totalOrigen =
    from.characters.size;

  const totalDestino =
    to.characters.size;

  const confirm =
    await sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
`⚠ Confirmación @${sender.split('@')[0]}

¿Está seguro de fusionar las series?

◈ Serie origen »
${from.name}

□ Personajes »
${totalOrigen}

⬇

◈ Serie destino »
${to.name}

□ Personajes »
${totalDestino}

⚠ Esta acción mover¿:

➢ Todos los personajes
➢ Todos los alias
➢ Todas las reclamaciones
➢ Todas las imágenes
➢ Todos los videos

La serie origen será eliminada.

Responde citando este mensaje:

\`si\`

o

\`no\``,
        mentions:[sender]
      },
      {
        quoted: msg
      }
    );

  db.pendingMergeSeries[
    confirm.key.id
  ] = {

    from:
      from.name,

    to:
      to.name,

    sender,

    chat:
      msg.key.remoteJid,

    created:
      Date.now()

  };

  saveDB();

}

async function handleMergeSerieReply(
  sock,
  msg,
  sender
){

  const quoted =
    msg.message?.extendedTextMessage
    ?.contextInfo;

  if (!quoted) return false;

  const pending =
    db.pendingMergeSeries?.[
      quoted.stanzaId
    ];

  if (!pending)
    return false;

  delete db.pendingMergeSeries[
    quoted.stanzaId
  ];

  saveDB();

  if (sender !== pending.sender)
    return true;

  const answer =
    (
      msg.message?.conversation ||
      msg.message?.extendedTextMessage?.text ||
      ''
    )
    .trim()
    .toLowerCase();

  if (answer === 'no'){

    await sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
'◈ Fusión cancelada.'
      },
      {
        quoted: msg
      }
    );

    return true;

  }

  if (answer !== 'si')
    return true;

  const from =
    seriesCache.get(
      pending.from.toLowerCase()
    );

  const to =
    seriesCache.get(
      pending.to.toLowerCase()
    );

  if (!from || !to){

    await sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
'◈ Una de las series ya no existe.'
      },
      {
        quoted: msg
      }
    );

    return true;

  }

  let moved = 0;

  for (const key of from.characters){

    const char =
      characterKeyMap.get(key);

    if (!char)
      continue;

    char.anime =
      to.name;

    to.characters.add(key);

    moved++;

  }

  from.characters.clear();

  seriesCache.delete(
    from.name.toLowerCase()
  );

  const oldFile =
    path.join(
      SERIES_DIR,
      `${from.name
        .toLowerCase()
        .replace(/[^\w]/g,'_')}.json`
    );

  if (
    fs.existsSync(oldFile)
  ){
    fs.unlinkSync(oldFile);
  }

  const newFile =
    path.join(
      SERIES_DIR,
      `${to.name
        .toLowerCase()
        .replace(/[^\w]/g,'_')}.json`
    );

  fs.writeFileSync(
    newFile,
    JSON.stringify({
      name:to.name,
      characters:[
        ...to.characters
      ]
    },null,2)
  );

  saveCharacters();

  await sock.sendMessage(
    msg.key.remoteJid,
    {
      text:
`✓ Series fusionadas

◈ Serie eliminada »
${from.name}

◈ Serie destino »
${to.name}

□ Personajes movidos »
${moved}`
    },
    {
      quoted: msg
    }
  );

  return true;

}

export async function handleAinfo(sock, msg, args, groupId) {
  const sender = msg.key.participant || msg.key.remoteJid;
  const queryRaw = args.join(' ').trim();

  if (!queryRaw) {
    return sock.sendMessage(
      msg.key.remoteJid,
      { text: tCmd(sender, '\u25C7 Uso: /ainfo <serie> [pagina]', '\u25C7 Usage: /ainfo <series> [page]') },
      { quoted: msg }
    );
  }

  let querySerie = queryRaw;
  let requestedPage = 1;

  const pageSlashMatch = queryRaw.match(/^(.+?)\s*\/\s*(\d+)\s*$/);
  const pageEndMatch = queryRaw.match(/^(.+?)\s+(\d+)\s*$/);
  const pageStartMatch = queryRaw.match(/^(\d+)\s+(.+)$/);

  if (pageSlashMatch) {
    querySerie = pageSlashMatch[1].trim();
    requestedPage = parseInt(pageSlashMatch[2], 10);
  } else if (pageStartMatch) {
    requestedPage = parseInt(pageStartMatch[1], 10);
    querySerie = pageStartMatch[2].trim();
  } else if (pageEndMatch) {
    querySerie = pageEndMatch[1].trim();
    requestedPage = parseInt(pageEndMatch[2], 10);
  }

  if (!Number.isInteger(requestedPage) || requestedPage < 1) {
    requestedPage = 1;
  }

  const query = querySerie.toLowerCase();

  const normalize = v =>
    String(v || '')
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/\s+/g, ' ')
      .trim();

  const queryNorm = normalize(querySerie);

  let serie = seriesCache.get(query);

  if (!serie) {
    for (const s of seriesCache.values()) {
      if (normalize(s.name) === queryNorm) {
        serie = s;
        break;
      }
    }
  }

  if (!serie && db.seriesAliases) {
    for (const [official, aliases] of Object.entries(db.seriesAliases)) {
      if (!Array.isArray(aliases)) continue;
      if (aliases.some(a => normalize(a) === queryNorm)) {
        for (const s of seriesCache.values()) {
          if (normalize(s.name) === normalize(official)) {
            serie = s;
            break;
          }
        }
        if (serie) break;
      }
    }
  }

  if (!serie) {
    serie = smartSearch(
      [...seriesCache.values()],
      querySerie,
      s => s.name
    );
  }

  if (!serie) {
    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text: tCmd(sender, 'La serie *' + querySerie + '* no existe.\n> Usa `/suggest` para sugerirla.', 'The series *' + querySerie + '* does not exist.\n> Use `/suggest` to suggest it.')
      },
      { quoted: msg }
    );
  }

  const chars = [];
  for (const key of serie.characters) {
    const c = characterKeyMap.get(key);
    if (c) chars.push(c);
  }

  chars.sort((a, b) => (Number(b.value) || 0) - (Number(a.value) || 0));

  const total = chars.length;
  const claimed = chars.filter(c => c.claimedBy?.[groupId]).length;
  const percent = total ? ((claimed / total) * 100).toFixed(1) : '0';

  const PER_PAGE = 100;
  const totalPages = Math.max(1, Math.ceil(total / PER_PAGE));
  const safePage = Math.min(requestedPage, totalPages);
  const start = (safePage - 1) * PER_PAGE;
  const end = start + PER_PAGE;
  const pageChars = chars.slice(start, end);

  // Codepoints CORRECTOS del bloque Limbu (U+19XX).
  // El patch anterior usaba U+1CXX (Lepcha) que se veia corrupto.
  const labelMap = {
    'a': '\u1972',   // ɴ
    'e': '\u1971',   // ᴇ
    'i': '\u03B9',   // ι
    'o': '\u1946',   // ᥆
    'u': '\u1959'    // ᴠ
  };

  const nameMap = {
    'a': '\u1972',   // ɴ
    'e': '\u1971',   // ᴇ
    'i': '\u03B9',   // ι
    'u': '\u1959',   // ᴠ
    'l': '\u1963',   // ʟ
    'n': '\u1952',   // ᴛ
    'p': '\u03C1',   // ρ
    'y': '\u10E7'    // ყ
  };

  function fLabel(text) {
    return String(text || '').split('').map(ch => labelMap[ch] || ch).join('');
  }

  function fName(text) {
    return String(text || '').split('').map(ch => nameMap[ch] || ch).join('');
  }

  function fNum(n) {
    return String(n).split('').map(d => {
      const code = d.charCodeAt(0);
      if (code >= 48 && code <= 57) {
        return String.fromCodePoint(0x1D7CE + code - 48);
      }
      return d;
    }).join('');
  }

  let es = true;
  try {
    if (typeof getUserLanguage === 'function' && getUserLanguage(sender) === 'EN') {
      es = false;
    }
  } catch {}

  const lbl = {
    name: es ? fLabel('Nombre') : 'Name',
    chars: es ? fLabel('Personajes') : 'Characters',
    claimed: es ? fLabel('Reclamados') : 'Claimed',
    list: es ? fLabel('Lista de personajes') : 'Character list',
    free: es ? fLabel('Libre') : 'Free',
    by: es ? fLabel('Reclamado por') : 'Claimed by',
    page: es ? fLabel('Pagina') : 'Page',
    use: es ? fLabel('Usa') : 'Use',
    next: es ? fLabel('para la siguiente pagina') : 'for the next page'
  };

  let text =
    '\u270E ' + lbl.name + ': `' + fName(String(serie.name)) + '`\n' +
    '\u274F ' + lbl.chars + ' \u00BB `' + fNum(total) + '`\n' +
    '\u265B ' + lbl.claimed + ' \u00BB `' + fNum(claimed) + '/' + fNum(total) + ' (' + percent + '%)`\n' +
    '\u274F ' + lbl.list + ':\n\n';

  for (const c of pageChars) {
    const owner = c.claimedBy?.[groupId];
    const ownerData = owner ? db.users?.[owner.user] : null;
    const ownerName =
      ownerData?.name ||
      (owner?.user ? String(owner.user).split('@')[0] : 'Usuario');

    const namePart = fName(c.name);
    const valuePart = fNum(c.value || 0);

    if (owner) {
      text +=
        '\u00BB `' + namePart + '` | `' + valuePart + '` *' +
        lbl.by + ' ' + fName(ownerName) + '*\n';
    } else {
      text +=
        '\u00BB `' + namePart + '` | `' + valuePart + '` *' + lbl.free + '*\n';
    }
  }

  text +=
    '\n> ' + lbl.page + ' `' + fNum(safePage) + '/' + fNum(totalPages) + '`';

  if (safePage < totalPages) {
    text +=
      ' ' + lbl.use + ' `/' + fName('ainfo') + ' ' +
      fName(String(serie.name).toLowerCase()) + ' ' + fNum(safePage + 1) + '` ' +
      lbl.next + '.';
  }

  await sock.sendMessage(
    msg.key.remoteJid,
    { text },
    { quoted: msg }
  );
}

export async function handleSetSerie(
  sock,
  msg,
  args,
  sender
){

  if(
    !isMainOwnerId(sender) &&
    !isSecondaryOwnerId(sender)
  ) return;

  const raw =
    args.join(' ');

  const parts =
    raw
      .split('/')
      .map(x=>x.trim())
      .filter(Boolean);

  if(parts.length < 2){

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
`◈ Uso

/setserie Nombre oficial / Alias 1 / Alias 2

Ejemplo

/setserie Zenless Zone Zero / zzz / zenless`
      },
      { quoted: msg }
    );

  }

  const official =
    parts.shift();

  db.seriesAliases[official] =
    parts.map(x=>x.toLowerCase());

  saveDB();

  await sock.sendMessage(
    msg.key.remoteJid,
    {
      text:
`✓ Alias guardados

◈ Serie »
${official}

□ Alias

${parts.map(x=>"➢ "+x).join("\n")}`
    },
    { quoted: msg }
  );

}

export async function handleDelNameSerie(
  sock,
  msg,
  args,
  sender
){

  if(
    !isMainOwnerId(sender) &&
    !isSecondaryOwnerId(sender)
  ) return;

  const alias =
    args
      .slice(1)
      .join(' ')
      .toLowerCase()
      .trim();

  if(!alias){

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
'◈ Uso:\n/delnameserie alias'
      },
      { quoted: msg }
    );

  }

  let found = false;

  for(const serie in db.seriesAliases){

    const list =
      db.seriesAliases[serie];

    const index =
      list.indexOf(alias);

    if(index !== -1){

      list.splice(index,1);

      found = true;

      if(!list.length)
        delete db.seriesAliases[serie];

      break;

    }

  }

  if(!found){

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
'◈ Alias no encontrado.'
      },
      { quoted: msg }
    );

  }

  saveDB();

  await sock.sendMessage(
    msg.key.remoteJid,
    {
      text:
`◈ Alias eliminado

${alias}`
    },
    { quoted: msg }
  );

}

