// MISIONS_SYSTEM_V1

function normalizarMision(texto) {

  return String(
    texto || ""
  )
    .toLowerCase()
    .normalize("NFD")
    .replace(
      /[\u0300-\u036f]/g,
      ""
    )
    .replace(
      /\s+/g,
      " "
    )
    .trim();

}

function formatMissionTime(
  milliseconds
) {

  let total =
    Math.max(
      0,
      Math.floor(
        milliseconds / 1000
      )
    );

  const dias =
    Math.floor(
      total / 86400
    );

  total %= 86400;

  const horas =
    Math.floor(
      total / 3600
    );

  total %= 3600;

  const minutos =
    Math.floor(
      total / 60
    );

  const segundos =
    total % 60;

  const partes = [];

  if (dias) {
    partes.push(
      dias +
      " día" +
      (
        dias === 1
          ? ""
          : "s"
      )
    );
  }

  if (horas) {
    partes.push(
      horas +
      " hora" +
      (
        horas === 1
          ? ""
          : "s"
      )
    );
  }

  if (minutos) {
    partes.push(
      minutos +
      " minuto" +
      (
        minutos === 1
          ? ""
          : "s"
      )
    );
  }

  if (
    !partes.length ||
    (
      !dias &&
      !horas &&
      !minutos
    )
  ) {
    partes.push(
      segundos +
      " segundo" +
      (
        segundos === 1
          ? ""
          : "s"
      )
    );
  }

  return partes
    .slice(
      0,
      3
    )
    .join(", ");

}

function getMissionStore() {

  db.misions ??= {
    lastId: 0,
    list: []
  };

  if (
    !Array.isArray(
      db.misions.list
    )
  ) {
    db.misions.list = [];
  }

  if (
    typeof db.misions.lastId !==
    "number"
  ) {
    db.misions.lastId = 0;
  }

  return db.misions;

}

function formatMissionMention(jid) {
  const value = String(jid || '').trim();
  return value ? `@${value.split('@')[0]}` : '@usuario';
}

function normalizeStaffId(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  if (raw.includes('@')) return raw.toLowerCase();
  return `${raw}@lid`;
}

function getStaffDisplayName(staffJid, fallbackJid = staffJid) {
  const key = normalizeStaffId(staffJid);
  const name = db.staffNames?.[key];
  return name ? `@${name}` : formatMissionMention(fallbackJid);
}

async function handleNameStaff(sock, msg, args, jid, sender) {
  if (!isMainOwnerId(sender)) {
    return sock.sendMessage(jid, {
      text: '❌ Solo el owner principal puede usar este comando.'
    }, { quoted: msg });
  }

  const input = args.join(' ').trim();
  const separator = input.indexOf('/');
  if (separator <= 0) {
    return sock.sendMessage(jid, {
      text: '◈ Uso: /namestaff LID / nombre de usuario'
    }, { quoted: msg });
  }

  const staffId = normalizeStaffId(input.slice(0, separator));
  const displayName = input.slice(separator + 1).trim().replace(/^@+/, '');
  if (!staffId.endsWith('@lid') || !displayName) {
    return sock.sendMessage(jid, {
      text: '◈ Debes indicar un LID y un nombre después de /.'
    }, { quoted: msg });
  }

  db.staffNames[staffId] = displayName;
  saveDB();

  await sock.sendMessage(jid, {
    text: `✓ Nombre de staff actualizado.\n\nLID: ${staffId}\nNombre: @${displayName}`
  }, { quoted: msg });
}

async function resolveMissionMentionTarget(sock, groupJid, participantJid) {
  const stored = String(participantJid || '').trim();
  if (!stored.endsWith('@lid')) {
    return stored;
  }

  const cached = missionLidToJid.get(stored);
  if (cached) {
    return cached;
  }

  try {
    if (groupJid?.endsWith('@g.us')) {
      const metadata = await sock.groupMetadata(groupJid);
      const participant = metadata.participants?.find(item =>
        item.id === stored || item.lid === stored
      );
      const resolved = participant?.jid || participant?.id;
      if (resolved && !resolved.endsWith('@lid')) {
        missionLidToJid.set(stored, resolved);
        return resolved;
      }
    }
  } catch (error) {
    console.warn('⚠️ No se pudo resolver LID de misión:', error.message);
  }

  return stored;
}

export async function handleCreateMission(
  sock,
  msg,
  args,
  jid,
  sender
) {

  if (!isMainOwnerId(sender)) {

    return sock.sendMessage(
      jid,
      {
        text:
`❌ Solo el owner principal puede crear misiones.`
      },
      {
        quoted: msg
      }
    );

  }

  const text =
    args
      .join(" ")
      .trim();

  const missionParts = text
    .replace(/^\+/, "")
    .split("/")
    .map(part => part.trim())
    .filter(Boolean);

  const partes = missionParts[0]?.split(/\s+/) || [];

  const staffNumber =
    Number(
      partes[0]
    );

  const accion =
    String(
      partes[1] || ""
    )
      .toLowerCase();

  const missionAmount =
    Number(
      partes[2]
    );

  const palabra =
    String(
      partes[3] || ""
    )
      .toLowerCase();

  const de =
    String(
      partes[4] || ""
    )
      .toLowerCase();

  const missionAnime =
    partes.slice(5).join(" ").trim();

  const rewardStatus =
    Number(missionParts[1]);

  const match =
    Number.isInteger(
      staffNumber
    ) &&
    staffNumber > 0 &&
    [
      "haz",
      "crea",
      "crear"
    ].includes(
      accion
    ) &&
    Number.isInteger(
      missionAmount
    ) &&
    missionAmount > 0 &&
    (
      palabra ===
      "personaje" ||
      palabra ===
      "personajes"
    ) &&
    de ===
    "de" &&
    missionAnime
      &&
    Number.isInteger(rewardStatus) &&
    rewardStatus > 0
      ? [
          null,
          String(
            staffNumber
          ),
          String(
            missionAmount
          ),
          missionAnime,
          String(rewardStatus)
        ]
      : null;

  if (!match) {
    const staffMentionTargets = await Promise.all(
      SECONDARY_OWNERS.map(staff =>
        resolveMissionMentionTarget(sock, jid, staff)
      )
    );

    return sock.sendMessage(
      jid,
      {
        text:
`☆ USO DE MISIÓN

♤ Formato »

/mision +número haz cantidad personajes de Anime / status

♡ Ejemplo »

/mision +1 haz 20 personajes de Zenless Zone Zero / 829339

▪︎ Staff disponibles »

${SECONDARY_OWNERS
  .map(
    (
      staff,
      index
    ) =>
      `+${index + 1} » ${getStaffDisplayName(staff, staffMentionTargets[index])}`
  )
  .join("\n")}`
      },
      {
        quoted: msg,
        mentions:
          staffMentionTargets
      }
    );

  }

  const staffIndex =
    Number(
      match[1]
    ) - 1;

  const amount =
    Number(
      match[2]
    );

  const anime =
    match[3]
      .trim();
  const missionReward =
    Number(match[4]);

  const staff =
    SECONDARY_OWNERS[
      staffIndex
    ];
  const staffMentionTarget =
    await resolveMissionMentionTarget(sock, jid, staff);

  if (!staff) {

    return sock.sendMessage(
      jid,
      {
        text:
`❌ El staff +${staffIndex + 1} no existe.`
      },
      {
        quoted: msg
      }
    );

  }

  if (
    !Number.isInteger(
      amount
    ) ||
    amount < 1
  ) {

    return sock.sendMessage(
      jid,
      {
        text:
          "❌ La cantidad debe ser un número mayor a 0."
      },
      {
        quoted: msg
      }
    );

  }

  fs.appendFileSync("debug-misions.log", "sender=" + sender + "\n");

  const store =
    getMissionStore();

  const activeMission =
    store.list.find(
      mission =>
        mission.status ===
          "active" &&
        mission.staff ===
          staff
    );

  if (activeMission) {

    return sock.sendMessage(
      jid,
      {
        text:
`❌ Ese staff ya tiene una misión activa.

♤ Staff »
${getStaffDisplayName(staff, staffMentionTarget)}

♡ Objetivo »
Crear ${activeMission.amount} personajes de ${activeMission.anime}

◈ Recompensa »
${Number(activeMission.rewardStatus || 0).toLocaleString()} status

▪︎ Progreso »
${activeMission.progress}/${activeMission.amount}`
      },
      {
        quoted: msg,
        mentions: [
          staffMentionTarget
        ]
      }
    );

  }

  store.lastId++;

  const mission = {

    id:
      store.lastId,

    staff,

    amount,

    anime,
    rewardStatus: missionReward,
    rewardClaimed: false,

    progress: 0,

    status:
      "active",

    createdAt:
      Date.now(),

    completedAt:
      null

  };

  store.list.push(
    mission
  );

  saveDB();

  // MISSION_SUGGESTLOGS_NOTICE_V1
  // Envía el aviso al grupo configurado con /suggestlogs on.
  // Si falla el aviso, la misión seguirá creada normalmente.
  if (db.suggestLogs) {

    try {

      await sock.sendMessage(
        db.suggestLogs,
        {
          text:
`${getStaffDisplayName(staff, staffMentionTarget)} Tienes una nueva misión, revísala con */misions*.`,

          mentions: [
            staffMentionTarget
          ]
        }
      );

    } catch (error) {

      console.error(
        "⚠️ No se pudo enviar el aviso de misión a Suggest Logs:",
        error?.message || error
      );

    }

  }

  await sock.sendMessage(
    jid,
    {
      text:
`☆ MISIÓN ASIGNADA

♤ Staff »
${getStaffDisplayName(staff, staffMentionTarget)}

♡ Objetivo »
Crear ${amount} personajes de ${anime}

◈ Recompensa »
${missionReward.toLocaleString()} status

▪︎ Progreso »
0/${amount}

➢ Estado »
En progreso

 La misión se firmará automáticamente al completarse.`,

      mentions: [
        staffMentionTarget
      ]

    },
    {
      quoted: msg
    }
  );

}



export async function handleDelMision(
  sock,
  msg,
  jid,
  sender,
  args
) {

  if (
    sender !== OWNER_NUMBER
  ) {

    return sock.sendMessage(
      jid,
      {
        text:
          "❌ Solo el owner principal puede usar este comando."
      },
      {
        quoted: msg
      }
    );

  }

  const idText =
    (args[0] || "")
      .replace("+", "")
      .trim();

  const id =
    Number(idText);

  if (
    !id ||
    isNaN(id)
  ) {

    return sock.sendMessage(
      jid,
      {
        text:
`❌ Uso correcto:

/delmision +ID

Ejemplo:
/delmision +1`
      },
      {
        quoted: msg
      }
    );

  }

  const store =
    getMissionStore();

  const index =
    store.list.findIndex(
      mission =>
        mission.id === id
    );

  if (
    index === -1
  ) {

    return sock.sendMessage(
      jid,
      {
        text:
          "❌ No existe una misión con ese ID."
      },
      {
        quoted: msg
      }
    );

  }

  const mission =
    store.list[index];
  const missionMentionTarget =
    await resolveMissionMentionTarget(sock, jid, mission.staff);

  store.list.splice(
    index,
    1
  );

  saveDB();

  await sock.sendMessage(
    jid,
    {
      text:
`✓ Misión eliminada.

ID:
${mission.id}

Staff:
${getStaffDisplayName(mission.staff, missionMentionTarget)}

Objetivo:
Crear ${mission.amount} personajes de ${mission.anime}`,
      mentions: [
        missionMentionTarget
      ]
    },
    {
      quoted: msg
    }
  );

}

export async function handleMisions(
  sock,
  msg,
  jid,
  sender
) {

  const store =
    getMissionStore();

  let missions =
    store.list;

  if (
    sender !== OWNER_NUMBER
  ) {

    missions =
      missions.filter(
        mission => {
          const missionStaff =
            String(mission.staff || "")
              .replace(/\\D/g, "");

          const senderId =
            String(sender || "")
              .replace(/\\D/g, "");

          return missionStaff === senderId;
        }
      );

  }

  for (
    const mission of missions
  ) {

    if (
      mission.status !==
      "active"
    ) continue;

    const count =
      charactersCache.filter(
        char =>
          char.creator?.split("@")[0] ===
            mission.staff.split("@")[0] &&
          normalizarMision(
            char.anime
          ) ===
          normalizarMision(
            mission.anime
          )
      ).length;

    if (
      count >
      mission.progress
    ) {

      mission.progress =
        Math.min(
          count,
          mission.amount
        );

      if (
        mission.progress >=
        mission.amount
      ) {

        mission.status =
          "completed";

        mission.completedAt =
          Date.now();

        if (!mission.rewardClaimed) {
          const profile = getStaffProfile(mission.staff);
          profile.status += Number(mission.rewardStatus) || 0;
          mission.rewardClaimed = true;
        }

      }

    }

  }

  saveDB();

  const active =
    missions.filter(
      mission =>
        mission.status ===
        "active"
    );

  if (!active.length) {

    return sock.sendMessage(
      jid,
      {
        text:
          "☆ No hay misiones activas."
      },
      {
        quoted: msg
      }
    );

  }

  const activeMentionTargets = await Promise.all(
    active.map(mission =>
      resolveMissionMentionTarget(sock, jid, mission.staff)
    )
  );

  const text =
    active
      .map(
        (
          mission,
          index
        ) =>
`☆ MISIÓN ${index + 1}

♤ Staff »
${getStaffDisplayName(mission.staff, activeMentionTargets[index])}

♡ Objetivo »
Crear ${mission.amount} personajes de ${mission.anime}

◈ Recompensa »
${Number(mission.rewardStatus || 0).toLocaleString()} status

▪︎ Progreso »
${mission.progress}/${mission.amount}

➢ Estado »
En progreso`
      )
      .join(
        "\\n\\n"
      );

  await sock.sendMessage(
    jid,
    {
      text,

      mentions:
        [
          ...new Set(
            activeMentionTargets.filter(Boolean)
          )
        ]

    },
    {
      quoted: msg
    }
  );

}

async function checkMissionProgress(
  sock,
  msg,
  character
) {

  const sender =
    msg.key.participant ||
    msg.participant;

  const store =
    getMissionStore();

  const mission =
    store.list.find(
      item =>
        item.status ===
          "active" &&
        item.staff ===
          sender &&
        normalizarMision(
          item.anime
        ) ===
        normalizarMision(
          character.anime
        )
    );

  if (!mission) {
    return;
  }

  mission.progress++;

  const jid =
    msg.key.remoteJid;

  if (
    mission.progress <
    mission.amount
  ) {

    saveDB();

    return sock.sendMessage(
      jid,
      {
        text:
`☆ MISIÓN AVANZANDO

♤ Staff »
${getStaffDisplayName(sender)}

♡ Objetivo »
Crear ${mission.amount} personajes de ${mission.anime}

◈ Recompensa »
${Number(mission.rewardStatus || 0).toLocaleString()} status

▪︎ Progreso »
${mission.progress}/${mission.amount}

➢ Restantes »
${mission.amount - mission.progress}`,

        mentions: [
          sender
        ]

      },
      {
        quoted: msg
      }
    );

  }

  mission.progress =
    mission.amount;

  mission.status =
    "completed";

  mission.completedAt =
    Date.now();

  if (!mission.rewardClaimed) {
    const profile = getStaffProfile(mission.staff);
    profile.status += Number(mission.rewardStatus) || 0;
    mission.rewardClaimed = true;
  }

  saveDB();

  const tiempo =
    formatMissionTime(
      mission.completedAt -
      mission.createdAt
    );

  const staffTag =
    getStaffDisplayName(sender);

  const privateText =
`☆ MISIÓN COMPLETADA

♤ Staff »
${staffTag}

♡ Objetivo »
Crear ${mission.amount} personajes de ${mission.anime}

◈ Recompensa »
${Number(mission.rewardStatus || 0).toLocaleString()} status

▪︎ Resultado »
${mission.progress}/${mission.amount}

➢ Tiempo »
${tiempo}

 Misión firmada automáticamente.`;

  const groupText =
`☆ MISIÓN FINALIZADA

♤ ${staffTag} cumpli¿ su misión.

♡ Objetivo »
Crear ${mission.amount} personajes de ${mission.anime}

▪︎ Resultado »
${mission.progress}/${mission.amount}

➢ Tiempo »
${tiempo}

☆ Misión completada.`;

  try {

    await sock.sendMessage(
      OWNER_NUMBER,
      {
        text:
          privateText,

        mentions: [
          sender
        ]

      }
    );

  } catch (
    error
  ) {

    console.log(
      "⚠️ No se pudo enviar el aviso privado de misión:",
      error.message
    );

  }

  await sock.sendMessage(
    jid,
    {
      text:
        groupText,

      mentions: [
        sender
      ]

    },
    {
      quoted: msg
    }
  );

}

export async function handleSetCoinsG(
  sock,
  msg,
  args,
  jid,
  sender
){

  const text =
    args.join(' ');

  const parts =
    text.split('/').map(x => x.trim());

  if (parts.length < 3) {
    return sock.sendMessage(jid,{
      text:
`Uso:

/setcoinsg nombre / anime / coins

Ejemplo:
/setcoinsg Nazuna Nanakusa / Yofukashi no Uta / 5230`
    },{ quoted: msg });
  }

  const nombre = parts[0];
  const anime = parts[1];
  const coins = Number(parts[2]);

  if (isNaN(coins) || coins < 0) {
    return sock.sendMessage(jid,{
      text:'Cantidad inválida.'
    },{ quoted: msg });
  }

  const char =
findCharacter(nombre);

  if (!char) {
    return sock.sendMessage(jid,{
      text:'Personaje no encontrado.'
    },{ quoted: msg });
  }

  char.coinGen = coins;

  saveCharacters();

  await sock.sendMessage(jid,{
    text:
`✰ Generación modificada.

❬ Personaje » ${char.name}
❖ Fuente » ${char.anime}
◈ Coins/min » ${coins}`
  },{ quoted: msg });
}

export async function handleAinfoCoinsG(
  sock,
  msg,
  args,
  sender
){

  if (sender != OWNER_NUMBER)
  return;

  const anime =
    args
    .join(' ')
    .trim();

  if (!anime) {

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
'◈ Uso: /ainfocoinsg [anime]'
      },
      {
        quoted: msg
      }
    );

  }

  const chars =
    charactersCache.filter(
      c =>
        c.anime
        .toLowerCase()
        .includes(
          anime.toLowerCase()
        )
    );

  if (!chars.length) {

    return sock.sendMessage(
      msg.key.remoteJid,
      {
        text:
'◈ Serie no encontrada.'
      },
      {
        quoted: msg
      }
    );

  }

  let text =
`❬ ${anime}

□ Personajes » ${chars.length}

Lista:

`;

  for (
  const char of chars.filter(
    c =>
      Number(
        c.coinGen || 0
      ) <= 0
  )
) {

    text +=
`*${char.name}* = \`${Number(
  char.coinsGen || 0
).toLocaleString()}/m\`\n`;

  }

  await sock.sendMessage(
    msg.key.remoteJid,
    { text },
    { quoted: msg }
  );

}

export async function handleCoinsG(
  sock,
  msg,
  groupId,
  sender
){

  const user =
    initUser(sender);

  const harem =
    db.groups[groupId]
    ?.harems?.[sender] || [];

  let totalPerHour = 0;

  let text =
`◈ Fɴrmᴇo dᴇ Dιɴmɴᴛtᴇs (ρɴsιvo)\n\n`;

  for (const char of harem) {

    const original =
      characterKeyMap.get(char.key);

    const gen =
      Number(original?.coinGen || 0);

    if (gen <= 0) continue;

    totalPerHour += gen;

    text +=
`${char.name} » ${gen} 💎/hora\n`;
  }

  if (totalPerHour <= 0) {
    text +=
`\n◈ No tienes personajes que generen diamantes.\n` +
`> Reclama personajes con /rw.`;
  } else {
    const premiumMultiplier =
      hasPremium(user) ? 2 : 1;
    const userMultiplier =
      Number(user?.coinsgMultiplier) > 0
        ? Number(user.coinsgMultiplier)
        : 1;
    const effectivePerHour =
      Math.floor(
        totalPerHour *
        premiumMultiplier *
        userMultiplier
      );

    const lastCollect =
      Number(user?.lastCoinCollect) ||
      Number(user?.lastDiamondCollect) ||
      Date.now();

    const hoursElapsed =
      Math.max(0, (Date.now() - lastCollect) / 3600000);

    const pending =
      Math.floor(effectivePerHour * hoursElapsed);

    text +=
`\n◈ Bɴsᴇ » ${totalPerHour.toLocaleString()} 💎/hora\n` +
`◈ Prᴇmιᴠm » x${premiumMultiplier}\n` +
`◈ Mᴠʟtιρʟιᴘɴdor » x${userMultiplier}\n` +
`◈ Tσtɴʟ ᴘfᴇᴘtιvo » ${effectivePerHour.toLocaleString()} 💎/hora\n\n` +
`◈ Pᴇᴛdιᴇᴛtᴇ ρor rᴇᴘojᴇr » ${pending.toLocaleString()} 💎\n` +
`> Sᴇ ɴᴘrᴇdιtɴ ɴᴠtomɴ́tιᴘɴmᴇᴛtᴇ ɴʟ usɴr ᴘuɴʟquιᴇr ᴘomɴᴛdo.`;
  }

  await sock.sendMessage(
    msg.key.remoteJid,
    { text },
    { quoted: msg }
  );
}


