const ECONOMY_RESET_VERSION = 2;

(async () => {
  try {
    db.economyMeta ??= {};
    const lastReset = Number(db.economyMeta.resetVersion) || 0;

    if (lastReset >= ECONOMY_RESET_VERSION) {
      console.log('[ECONOMY RESET] Ya aplicado (v' + lastReset + '). Omitiendo.');
      return;
    }

    console.log('[ECONOMY RESET] Aplicando v' + ECONOMY_RESET_VERSION + '...');

    // --------------------------------------------------------
    // 1. RESET DE ECONOMÍA EN TODOS LOS GRUPOS
    // --------------------------------------------------------
    let groupUsersReset = 0;
    for (const gid of Object.keys(db.groups || {})) {
      const group = db.groups[gid];
      if (!group || !group.economy) continue;

      for (const uid of Object.keys(group.economy)) {
        const eco = group.economy[uid];
        if (!eco || typeof eco !== 'object') continue;

        eco.coins = 0;
        eco.bank = 0;
        eco.lastWork = 0;
        eco.lastSlut = 0;
        eco.lastCrime = 0;
        eco.lastDaily = 0;
        eco.lastMine = 0;
        eco.lastRob = 0;
        eco.dailyStreak = 0;
        eco.timeReduction = 0;
        groupUsersReset++;
      }
    }

    // --------------------------------------------------------
    // 2. RESET DE PERFIL DE USUARIO
    // --------------------------------------------------------
    let usersReset = 0;
    for (const uid of Object.keys(db.users || {})) {
      const user = db.users[uid];
      if (!user || typeof user !== 'object') continue;

      user.diamonds = 0;
      user.gems = 0;
      user.coinsgMultiplier = 1;
      user.cooldownReduction = 0;
      user.harem100Reward = false;

      user.luck = {
        total: 0,
        mod: 0,
        mythic: 0,
        legendary: 0,
        epic: 0,
        rare: 0,
        common: 0
      };

      user.lastCoinCollect = Date.now();
      user.lastDiamondCollect = Date.now();

      usersReset++;
    }

    db.economyMeta.resetVersion = ECONOMY_RESET_VERSION;
    db.economyMeta.resetAt = Date.now();

    console.log(
      '[ECONOMY RESET] Hecho. Usuarios:', usersReset,
      '| registros de economía:', groupUsersReset
    );

    saveDB();
  } catch (e) {
    console.error('[ECONOMY RESET] ERROR:', e);
  }
})();

// ============================================================
/* ============================================================
 * GETCHILEDAYKEY_AUTONOMO_V1
 * ------------------------------------------------------------
 * getChileDayKey está definida en commands/economia/daily.ts
 * (módulo separado), pero CLEANUP_7D_CHILE y otros timers
 * viven en index.ts y NO tienen acceso al scope del módulo.
 *
 * Por eso se define aquí, de forma autónoma, con su propio
 * Intl.DateTimeFormat local. No depende de commands/ ni de
 * chileDayFmt/chileTimeFmt del módulo.
 *
 * Se expone en globalThis para que runCleanup (que corre en un
 * setTimeout) siempre la encuentre.
 * ============================================================ */

const __chileDayFmtLocal = new Intl.DateTimeFormat("en-CA", {
  timeZone: "America/Santiago",
  year: "numeric",
  month: "2-digit",
  day: "2-digit"
});

function getChileDayKey(ms = Date.now()) {
  return __chileDayFmtLocal.format(new Date(ms)); // YYYY-MM-DD
}

// Exponer en globalThis por si algún timer corre fuera de scope
try { globalThis.__getChileDayKey = getChileDayKey; } catch (__e) {}
try { globalThis.getChileDayKey = getChileDayKey; } catch (__e) {}


/* ============================================================
 * FIX_DAILY_FUNCTIONS_V1
 * ------------------------------------------------------------
 * shiftDayKey, getUserLastDailyDay, getMsUntilChileMidnight,
 * getDailyRemainingMs, chileTimeFmt
 *
 * Estaban en el index.ts original pero se perdieron en algún
 * refactor/movida. El __ctx del MIGRATION_HOOK las referencia
 * (líneas ~25924-25927 de dist/index.js) y commands/economia/daily.ts
 * las usa desde ctx, pero en runtime no existen.
 * ============================================================ */

const chileTimeFmt = new Intl.DateTimeFormat("en-GB", {
  timeZone: "America/Santiago",
  hourCycle: "h23",
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit"
});

function shiftDayKey(key, days) {
  const [y, m, d] = key.split("-").map(Number);
  const t = new Date(Date.UTC(y, m - 1, d + days));
  return t.getUTCFullYear() + "-" +
    String(t.getUTCMonth() + 1).padStart(2, "0") + "-" +
    String(t.getUTCDate()).padStart(2, "0");
}

function getUserLastDailyDay(user) {
  if (user.lastDailyDay) return user.lastDailyDay;
  if (user.lastDailyGlobal) return getChileDayKey(user.lastDailyGlobal);
  return "";
}

function getMsUntilChileMidnight(now = Date.now()) {
  const p = chileTimeFmt.format(new Date(now)).split(":").map(Number);
  const passed = (p[0] % 24) * 3600 + p[1] * 60 + p[2];
  return Math.max(1000, (86400 - passed) * 1000);
}

function getDailyRemainingMs(user, now = Date.now()) {
  const last = getUserLastDailyDay(user);
  if (!last) return 0;
  return last === getChileDayKey(now) ? getMsUntilChileMidnight(now) : 0;
}

// Exponer en globalThis para timers fuera de scope
try { globalThis.shiftDayKey = shiftDayKey; } catch (__e) {}
try { globalThis.getUserLastDailyDay = getUserLastDailyDay; } catch (__e) {}
try { globalThis.getMsUntilChileMidnight = getMsUntilChileMidnight; } catch (__e) {}
try { globalThis.getDailyRemainingMs = getDailyRemainingMs; } catch (__e) {}

// CLEANUP_7D_CHILE: borra usuarios inactivos por 7 días
// ============================================================
// Usa el mismo reloj de Chile que /daily (getChileDayKey).
// Compara días calendario en America/Santiago.
// Se ejecuta cada 6 horas. NO toca db.groups.economy.
// Protege: owner principal, secondary owners, baneados.
// ============================================================

if (!global.__cleanup7dTimer) {
  const CLEANUP_INTERVAL_MS = 6 * 60 * 60 * 1000; // cada 6 horas
  const CUTOFF_DAYS = 7;

  // Compara dos "day keys" YYYY-MM-DD en hora de Chile
  // Devuelve cuántos días calendario han pasado entre ellas.
  const diffChileDays = (fromKey, toKey) => {
    try {
      const [fy, fm, fd] = String(fromKey).split('-').map(Number);
      const [ty, tm, td] = String(toKey).split('-').map(Number);
      const fromUTC = Date.UTC(fy, fm - 1, fd);
      const toUTC = Date.UTC(ty, tm - 1, td);
      return Math.floor((toUTC - fromUTC) / (24 * 60 * 60 * 1000));
    } catch {
      return 0;
    }
  };

  const runCleanup = () => {
    try {
      const todayKey = globalThis.getChileDayKey(Date.now());
      let deleted = 0;
      const protectedIds = new Set([
        OWNER_NUMBER,
        ...(Array.isArray(db.secondaryOwners) ? db.secondaryOwners : [])
      ].filter(Boolean));

      for (const uid of Object.keys(db.users || {})) {
        if (protectedIds.has(uid)) continue;
        if (db.bannedUsers?.[uid]) continue;

        const user = db.users[uid];
        if (!user || typeof user !== 'object') {
          delete db.users[uid];
          deleted++;
          continue;
        }

        const lastTs =
          Number(user.lastCommandAt) ||
          Number(user.lastMessageAt) ||
          Number(user.lastXpGain) ||
          0;

        // Nunca usó nada: usar createdAt como referencia.
        if (!lastTs) {
          if (!user.createdAt) {
            user.createdAt = Date.now();
          }
          const createdKey = globalThis.getChileDayKey(Number(user.createdAt));
          if (diffChileDays(createdKey, todayKey) >= CUTOFF_DAYS) {
            delete db.users[uid];
            deleted++;
          }
          continue;
        }

        const lastKey = globalThis.getChileDayKey(lastTs);
        if (diffChileDays(lastKey, todayKey) >= CUTOFF_DAYS) {
          delete db.users[uid];
          deleted++;
        }
      }

      if (deleted > 0) {
        console.log(
          '[CLEANUP 7D CHILE] Usuarios eliminados:',
          deleted,
          '| día actual (Chile):', todayKey
        );
        saveDB();
      }
    } catch (e) {
      console.error('[CLEANUP 7D CHILE] ERROR:', e);
    }
  };

  global.__cleanup7dTimer = setInterval(runCleanup, CLEANUP_INTERVAL_MS);

  // Primera pasada a los 2 minutos del arranque
  setTimeout(runCleanup, 120000);

  console.log(
    '[CLEANUP 7D CHILE] Timer iniciado (cada 6 h, cutoff 7 días calendario Chile)'
  );
}

