/* WAIFU_ABANDON_TIMER_V3 - -10% amor cada 3 dias sin regalos (Chile) */
const WAIFU_ABANDON_MS = 3 * 24 * 60 * 60 * 1000;
const WAIFU_LOVE_PENALTY = 10;
const WAIFU_ABANDON_CHECK_MS = 15 * 60 * 1000;

if (!global.__waifuAbandonTimer) {
  global.__waifuAbandonTimer = setInterval(async () => {
    try {
      const now = Date.now();
      let penalizadas = 0;
      let rotas = 0;

      const socks = [];
      if (globalThis.MAIN_BOT_SOCK?.user?.id) socks.push(globalThis.MAIN_BOT_SOCK);
      const subs = globalThis.SUBBOT_SOCKETS;
      if (subs instanceof Map) {
        for (const [, s] of subs.entries()) if (s?.user?.id) socks.push(s);
      } else if (subs && typeof subs === 'object') {
        for (const s of Object.values(subs)) if (s?.user?.id) socks.push(s);
      }
      const socket = socks[0] || null;
      if (!socket) return;

      const chileDayKey = (ms) => {
        try {
          return new Intl.DateTimeFormat('en-CA', {
            timeZone: 'America/Santiago',
            year: 'numeric', month: '2-digit', day: '2-digit'
          }).format(new Date(ms));
        } catch (e) {
          return new Date(ms).toISOString().slice(0, 10);
        }
      };

      const __chile = (str) => {
        const map = { 'a': 'α', 'e': 'ε', 'i': 'ι', 'o': 'σ', 'u': 'υ' };
        return String(str || '').split('').map(ch => map[ch] || ch).join('');
      };

      for (const [userId, user] of Object.entries(db.users || {})) {
        if (!user?.waifu?.groupLigues) continue;

        for (const [chatId, ligues] of Object.entries(user.waifu.groupLigues)) {
          if (!ligues || typeof ligues !== 'object') continue;

          for (const [charKey, ligue] of Object.entries(ligues)) {
            if (!ligue || typeof ligue !== 'object') continue;

            const lastGift = Number(ligue.lastGift) || 0;
            const started  = Number(ligue.started)  || 0;
            const ref = lastGift > 0 ? lastGift : started;
            if (!ref) continue;

            const elapsed = now - ref;
            if (elapsed < WAIFU_ABANDON_MS) continue;
            if (chileDayKey(ref) === chileDayKey(now)) continue;

            const character = characterKeyMap.get(charKey);
            const charName = character?.name || ligue?.name || charKey;

            const currentLove = Number(ligue.love) || 0;
            const newLove = Math.max(0, currentLove - WAIFU_LOVE_PENALTY);

            ligue.love = newLove;
            ligue.lastGift = now;
            ligue.lastPenalty = now;
            ligue.penalties = (Number(ligue.penalties) || 0) + 1;

            if (user.waifu.groupLigues[chatId]) user.waifu.groupLigues[chatId][charKey] = ligue;
            if (user.waifu.ligues) user.waifu.ligues[charKey] = ligue;

            user.waifu.totalLove = Math.max(
              0,
              (Number(user.waifu.totalLove) || 0) - (currentLove - newLove)
            );

            if (newLove <= 0) {
              delete user.waifu.groupLigues[chatId][charKey];
              if (user.waifu.ligues) delete user.waifu.ligues[charKey];
              if (user.waifu.current === charKey) user.waifu.current = null;
              if (
                user.waifu.groupLigues[chatId] &&
                Object.keys(user.waifu.groupLigues[chatId]).length === 0
              ) {
                delete user.waifu.groupLigues[chatId];
              }
              rotas++;

              try {
                await socket.sendMessage(chatId, {
                  text:
                    '\uD83D\uDC94 @' + userId.split('@')[0] +
                    ' tu waifu *' + charName + '* rompió contigo.\n\n' +
                    '> Su amor llegó a `0%` por falta de regalos.\n' +
                    '> Puedes intentarlo de nuevo con /ligue ' + charName + '.',
                  mentions: [userId]
                });
              } catch (e) {
                console.log('[WAIFU_ABANDON] no se pudo avisar:', e?.message || e);
              }
            } else {
              penalizadas++;

              try {
                await socket.sendMessage(chatId, {
                  text:
                    '\uD83D\uDC94 @' + userId.split('@')[0] +
                    ' tu waifu *' + charName + '* perdió amor por falta de regalos.\n\n' +
                    '> Amor perdido: `-' + WAIFU_LOVE_PENALTY + '%`\n' +
                    '> Amor actual: `' + newLove + '% / 100%`\n\n' +
                    '> Regálale algo con /giftbuy para recuperar su amor.',
                  mentions: [userId]
                });
              } catch (e) {
                console.log('[WAIFU_ABANDON] no se pudo avisar:', e?.message || e);
              }
            }
          }
        }
      }

      if (penalizadas > 0 || rotas > 0) {
        saveDB();
        console.log('[WAIFU_ABANDON] penalizadas:', penalizadas, '| rotas:', rotas);
      }
    } catch (e) {
      console.error('[WAIFU_ABANDON] error:', e?.message || e);
    }
  }, WAIFU_ABANDON_CHECK_MS);

  console.log('[WAIFU_ABANDON] timer iniciado (cada 15 min, -10% amor cada 3 dias sin regalos)');
}
/* ==== Handlers de apagado reubicados por repair-index.mjs (antes muertos dentro de messages.upsert) ==== */
let shuttingDown = false;

async function apagadoSeguro(signal) {
  if (shuttingDown) {
    console.log('[SAFE SHUTDOWN] Apagado ya en proceso.');
    return;
  }

  shuttingDown = true;

  console.log('');
  console.log('========================================');
  console.log('[SAFE SHUTDOWN] Iniciando apagado seguro...');
  console.log('========================================');

  try {
    // 1. Limpiar usuarios inválidos y baneados.
    if (typeof limpiarUsuariosInvalidos === 'function') {
      limpiarUsuariosInvalidos();
    }

    // 2. Crear la copia protegida de usuarios.
    //    Esta función usa escritura síncrona,
    //    por lo que termina completamente antes de continuar.
    if (typeof guardarUsuariosProtegidos === 'function') {
      guardarUsuariosProtegidos();
      console.log('[SAFE SHUTDOWN] users-protected.json terminado.');
    }

    // 3. Solicitar guardado de database.json.
    saveDB();

    // 4. Esperar TODA la cola de escrituras de saveDB.
    await saveDBQueue;

    console.log('[SAFE SHUTDOWN] database.json terminado.');
    console.log('[SAFE SHUTDOWN] Todas las escrituras finalizaron.');

  } catch (error) {
    console.error('[SAFE SHUTDOWN ERROR]', error);
  } finally {
    console.log('[SAFE SHUTDOWN] Cerrando Node...');
    console.log('========================================');

    process.exit(0);
  }
}

process.on('SIGINT', () => {
  apagadoSeguro('SIGINT');
});

process.on('SIGTERM', () => {
  apagadoSeguro('SIGTERM');
});

process.on('uncaughtException', err => {
  console.error(err);
  saveDB();
});

process.on('unhandledRejection', err => {
  console.error(err);
  saveDB();
});

