const __gelbooruQueue = [];
let __gelbooruProcessing = false;
let __gelbooruLastRequestAt = 0;

function __gelbooruSleep(ms) {
  return new Promise(r => setTimeout(r, ms));
}

async function __gelbooruFetchJson(pathAndQuery) {
  return new Promise((resolve) => {
    __gelbooruQueue.push({ pathAndQuery, resolve });
    __processGelbooruQueue();
  });
}

async function __processGelbooruQueue() {
  if (__gelbooruProcessing) return;
  __gelbooruProcessing = true;
  try {
    while (__gelbooruQueue.length) {
      const job = __gelbooruQueue.shift();
      const now = Date.now();
      const wait = Math.max(0, GELBOORU_MIN_INTERVAL_MS - (now - __gelbooruLastRequestAt));
      if (wait > 0) await __gelbooruSleep(wait);
      __gelbooruLastRequestAt = Date.now();

      try {
        const url =
          'https://gelbooru.com/index.php?page=dapi&s=tag&q=index&json=1' +
          '&api_key=' + GELBOORU_API_KEY +
          '&user_id=' + GELBOORU_USER_ID +
          '&' + job.pathAndQuery;

        const res = await fetch(url, {
          headers: {
            'User-Agent': 'MioHaimiyaBot/1.0',
            'Accept': 'application/json'
          }
        });

        if (res.status === 401 || res.status === 403 || res.status === 429 || res.status >= 500) {
          job.resolve({ temporal: true, status: res.status });
          continue;
        }
        if (!res.ok) {
          job.resolve({ error: true, status: res.status });
          continue;
        }
        const data = await res.json();
        job.resolve({ data });
      } catch (e) {
        job.resolve({ temporal: true, status: 0, error: e?.message || String(e) });
      }
    }
  } finally {
    __gelbooruProcessing = false;
  }
}

async function mioGelbooruTag(tag) {
  const cleanTag = String(tag || '').trim().replace(/\s+/g, '_');
  if (!cleanTag) return { exists: false };

  const pickArr = (resp) => {
    if (!resp || !resp.data) return [];
    if (Array.isArray(resp.data)) return resp.data;
    if (Array.isArray(resp.data.tag)) return resp.data.tag;
    return [];
  };

  // 1) Primer intento: wildcard para atrapar variantes tipo tag_(serie)
  let r = await __gelbooruFetchJson(
    'name_pattern=' + encodeURIComponent('*' + cleanTag + '*') + '&limit=20&orderby=count&order=desc'
  );
  if (r.temporal) return { temporal: true };
  let arr = pickArr(r);

  // 2) Segundo intento: exacto sin wildcard
  if (!arr.length) {
    r = await __gelbooruFetchJson(
      'name_pattern=' + encodeURIComponent(cleanTag) + '&limit=10&orderby=count&order=desc'
    );
    if (r.temporal) return { temporal: true };
    arr = pickArr(r);
  }

  if (!arr.length) return { exists: false };

  const wanted = cleanTag.toLowerCase();
  const normalizeGel = (v) => String(v || '').toLowerCase().replace(/\s+/g, '_');
  const exact = arr.find(x => normalizeGel(x.name || x.tag) === wanted);
  const chosen = exact || arr[0];
  const name = String(chosen.name || chosen.tag || cleanTag);
  const count = Number(chosen.count || chosen.post_count || 0) || 0;

  return { exists: true, name, count, exact: Boolean(exact) };
}

async function mioDanbooruTag(tag) {
  const r = await mioHttpJson(
    'https://danbooru.donmai.us/tags.json?search%5Bname_matches%5D=' +
    encodeURIComponent(tag + '*') +
    '&search%5Bhide_empty%5D=yes&limit=10'
  );

  if (r.temporal) return { temporal: true };
  if (!r.data || !Array.isArray(r.data)) return { exists: false };

  const wanted = String(tag).toLowerCase().trim();

  const t = r.data.find(function (x) {
    if (!x) return false;
    const nm = String(x.name || '').toLowerCase();
    if (nm === wanted) return true;
    if (nm.startsWith(wanted + '_(')) return true;
    if (nm.startsWith(wanted + ' (')) return true;
    return false;
  });

  if (!t) return { exists: false };

  return {
    exists: true,
    name: String(t.name || tag),
    category: Number(t.category),
    count: Number(t.post_count) || 0
  };
}

async function mioDanbooruCopyrights(tag) {
  const r = await mioHttpJson(
    'https://danbooru.donmai.us/related_tag.json?commit=Search&search%5Bquery%5D=' +
    encodeURIComponent(tag) +
    '&search%5Bcategory%5D=3'
  );

  if (r.temporal) return { temporal: true };

  const d = r.data;

  if (!d) return null;

  const list =
    Array.isArray(d)
      ? d
      : (d.related_tags || d.tags || []);

  const names = list
    .slice(0, 8)
    .map(function (x) {
      return (
        (x && x.tag && x.tag.name) ||
        (x && x.name) ||
        (Array.isArray(x) ? x[0] : null)
      );
    })
    .filter(Boolean);

  return {
    names: names
  };
}

function mioSerieMatches(serie, names) {
  const sn = mioNorm(serie);

  const stop = [
    'with',
    'from',
    'that',
    'this',
    'story',
    'girls',
    'love',
    'high',
    'school',
    'anime',
    'world',
    'life',
    'part'
  ];

  const toks = sn
    .split(' ')
    .filter(function (t) {
      return t.length >= 4 && stop.indexOf(t) < 0;
    });

  for (const raw of names) {
    const cn = mioNorm(
      String(raw).replace(/_/g, ' ')
    );

    if (!cn) continue;

    if (
      cn === sn ||
      cn.indexOf(sn) >= 0 ||
      (cn.length >= 4 && sn.indexOf(cn) >= 0)
    ) {
      return true;
    }

    const ct = cn.split(' ');

    if (
      toks.some(function (t) {
        return ct.indexOf(t) >= 0;
      })
    ) {
      return true;
    }
  }

  return false;
}

async function mioDanbooruSearchTags(pattern, limit) {
  const lim = Math.min(Math.max(Number(limit) || 20, 1), 30);

  const url =
    'https://danbooru.donmai.us/tags.json?' +
    'search%5Bname_matches%5D=' + encodeURIComponent(pattern) +
    '&search%5Bhide_empty%5D=yes' +
    '&limit=' + lim;

  const r = await mioHttpJson(url);

  if (r.temporal) return { temporal: true };
  if (!Array.isArray(r.data)) return { names: [] };

  return {
    names: r.data
      .filter(function (x) {
        return x && x.name;
      })
      .map(function (x) {
        return {
          name: String(x.name),
          category: Number(x.category),
          count: Number(x.post_count) || 0
        };
      })
  };
}

async function mioGelbooruSearchTags(pattern, limit) {
  const lim = Math.min(Math.max(Number(limit) || 20, 1), 30);

  const r = await __gelbooruFetchJson(
    'name_pattern=' + encodeURIComponent(pattern) + '&limit=' + lim + '&orderby=count&order=desc'
  );

  if (r.temporal) {
    console.log('[MIO GELBOORU] temporal (rate limit o red):', r.status);
    return { names: [] };
  }
  if (r.error && (r.status === 401 || r.status === 403)) {
    console.log('[MIO GELBOORU] 401/403: no se usa esta fuente.');
    return { names: [] };
  }
  if (!r.data) return { names: [] };

  const arr = Array.isArray(r.data)
    ? r.data
    : Array.isArray(r.data.tag)
      ? r.data.tag
      : [];

  return {
    names: arr
      .filter(x => x && (x.name || x.tag))
      .map(x => ({
        name: String(x.name || x.tag),
        category: Number(x.type || x.category || 0),
        count: Number(x.count || x.post_count || 0) || 0
      }))
  };
}

function mioTagNameScore(nombre, serie, candidate) {
  const target = mioNorm(nombre);
  const cand = mioNorm(candidate).replace(/\s*\([^)]*\)\s*/g, ' ').trim();

  if (!target || !cand) return 0;

  let score = 0;

  if (cand === target) score += 100;

  const targetWords = target.split(' ').filter(Boolean);
  const candWords = cand.split(' ').filter(Boolean);

  if (targetWords.length === candWords.length) {
    let same = 0;

    for (const w of targetWords) {
      if (candWords.indexOf(w) >= 0) same++;
    }

    if (same === targetWords.length) score += 75;
    else if (same >= Math.max(1, targetWords.length - 1)) score += 35;
  }

  if (cand.indexOf(target) >= 0) score += 30;
  if (target.indexOf(cand) >= 0 && cand.length >= 4) score += 20;

  const reversed = targetWords.slice().reverse().join(' ');

  if (cand === reversed) score += 55;

  const serieNorm = mioNorm(serie);

  if (
    candidate.toLowerCase().indexOf(
      serieNorm.replace(/\s+/g, '_')
    ) >= 0
  ) {
    score += 35;
  }

  return score;
}

function mioScoreTagCandidate(nombre, serie, candidate) {
  const tag = String(candidate.name || candidate.tag || '').trim();

  if (!tag) return -999;

  let score = mioTagNameScore(nombre, serie, tag);

  const category = Number(candidate.category);
  const count = Number(candidate.count) || 0;

  // Danbooru category 4 = character.
  if (category === 4) score += 45;
  else if (category && category !== 4) score -= 45;

  if (count >= 10000) score += 15;
  else if (count >= 1000) score += 10;
  else if (count >= 100) score += 5;
  else if (count < MIO_MIN_POSTS) score -= 50;

  // Los tags extremadamente largos suelen ser poco útiles como
  // identificadores directos de personaje.
  if (tag.length > 100) score -= 20;

  return score;
}

function mioUniqueTagCandidates(list) {
  const map = new Map();

  for (const item of list || []) {
    if (!item) continue;

    const name = String(item.name || item.tag || '').trim();
    if (!name) continue;

    const key = name.toLowerCase();

    const old = map.get(key);

    if (!old || Number(item.count || 0) > Number(old.count || 0)) {
      map.set(key, {
        name: name,
        category: Number(item.category || 0),
        count: Number(item.count || 0)
      });
    }
  }

  return Array.from(map.values());
}

async function mioCheckCandidate(tag, needCp, serie) {
  await mioSleep(1100);

  const r = await mioDanbooruTag(tag);

  if (r.temporal) return { temporal: true };

  if (
    !r.exists ||
    r.category !== 4 ||
    !(r.count >= MIO_MIN_POSTS)
  ) {
    return { ok: false };
  }

  if (!needCp) {
    return {
      ok: true,
      tag: r.name || tag,
      count: r.count,
      category: r.category
    };
  }

  await mioSleep(1100);

  const cp = await mioDanbooruCopyrights(tag);

  if (cp && cp.temporal) return { temporal: true };

  if (!cp || !cp.names || !cp.names.length) {
    return { ok: false };
  }

  return {
    ok: mioSerieMatches(serie, cp.names),
    tag: r.name || tag,
    count: r.count,
    category: r.category,
    copyrights: cp.names
  };
}

async function mioFindDeepCandidates(nombre, serie) {
  const base = String(nombre)
    .replace(/\s*\([^)]*\)\s*/g, ' ')
    .replace(/\s+/g, ' ')
    .trim() || String(nombre);

  const slug = function (s) {
    return String(s)
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/['™.]/g, '')
      .replace(/[^a-z0-9]+/g, '_')
      .replace(/^_+|_+$/g, '');
  };

  const words = base.split(' ').filter(Boolean);
  const direct = slug(base);
  const reversed = words.length > 1
    ? slug(words.slice().reverse().join(' '))
    : null;

  const patterns = [];

  function addPattern(x) {
    if (x && patterns.indexOf(x) < 0) {
      patterns.push(x);
    }
  }

  addPattern(direct);
  addPattern(reversed);

  // Búsqueda por fragmento del nombre.
  for (const w of words) {
    if (w.length >= 3) {
      addPattern(slug(w) + '*');
    }
  }

  if (words.length > 1) {
   addPattern(direct + '*');
addPattern(reversed + '*');
  }

  const candidates = [];

  for (const pattern of patterns) {
    const d = await mioDanbooruSearchTags(pattern, 20);

    if (d.temporal) {
      return { temporal: true };
    }

    candidates.push.apply(candidates, d.names || []);

    // Pequeña pausa para no martillar la API.
    await mioSleep(700);
  }

  // Gelbooru se utiliza como segunda fuente.
  const gp = direct.length >= 4
    ? '%' + direct + '%'
    : '%' + slug(base) + '%';

  const g = await mioGelbooruSearchTags(gp, 20);

  if (g.temporal) {
    // Gelbooru puede estar temporalmente limitado.
    // No abortamos todo MIO por esta fuente secundaria.
  } else {
    candidates.push.apply(candidates, g.names || []);
  }

  const unique = mioUniqueTagCandidates(candidates);

  unique.forEach(function (x) {
    x.score = mioScoreTagCandidate(nombre, serie, x);
  });

  unique.sort(function (a, b) {
    return b.score - a.score;
  });

  return {
    candidates: unique.slice(0, 20)
  };
}

async function mioAskGeminiTag(nombre, serie) {
  try {
    const prompt =
      'Necesito el tag EXACTO de Danbooru para el personaje "' + nombre + '" de la serie "' + serie + '". ' +
      'Responde SOLO con el tag (minusculas, guiones bajos, sin espacios, sin explicaciones). ' +
      'Si el tag incluye la serie entre parentesis, usa el formato: nombre_del_personaje_(nombre_de_la_serie). ' +
      'Si el personaje no existe o no tiene tag, responde exactamente: NONE';

    const result = await geminiAsk({
      prompt,
      chatId: null,
      images: [],
      language: 'es-ES'
    });

    let t = String(result.text || '')
      .split('\n')[0]
      .trim();

    t = t.replace(/[\u0060*"'`]/g, '').trim();

    if (!t || /^none$/i.test(t) || /no (tiene|existe)/i.test(t)) {
      console.log('[MIO GEMINI] Sin tag para:', nombre, '| serie:', serie);
      return null;
    }

    if (/\s/.test(t)) {
      console.log('[MIO GEMINI] Respuesta con espacios, ignorada:', t);
      return null;
    }

    t = t.toLowerCase();

    if (!/^[a-z0-9_()'.!:+-]{2,80}$/.test(t)) {
      console.log('[MIO GEMINI] Tag con formato invalido:', t);
      return null;
    }

    console.log('[MIO GEMINI] Tag obtenido:', nombre, '->', t);
    return t;
  } catch (e) {
    console.log('[MIO GEMINI] Error:', e?.message || e);
    return null;
  }
}

async function mioFindTag(nombre, serie) {
  const base = String(nombre)
    .replace(/\s*\([^)]*\)\s*/g, ' ')
    .replace(/\s+/g, ' ')
    .trim() || String(nombre);

  const slug = function (s) {
    return String(s)
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/['™.]/g, '')
      .replace(/[^a-z0-9]+/g, '_')
      .replace(/^_+|_+$/g, '');
  };

  const words = base.split(' ').filter(Boolean);
  const direct = slug(base);
  const rev = words.length > 1
    ? slug(words.slice().reverse().join(' '))
    : null;

  const ser = slug(serie);
  const cands = [];

  const add = function (tag, needCp) {
    if (
      tag &&
      !cands.some(function (c) {
        return c.tag === tag;
      })
    ) {
      cands.push({
        tag: tag,
        needCp: needCp
      });
    }
  };

  // ============================================================
  // CAPA 1 ” 10 FORMAS DETERMINISTAS
  // ============================================================

  add(direct, true);                              // 1
  if (rev) add(rev, true);                        // 2
  add(direct + '_(' + ser + ')', false);          // 3
  if (rev) add(rev + '_(' + ser + ')', false);    // 4
  add(direct + ' (' + serie + ')', false);        // 5
  if (rev) add(rev + ' (' + serie + ')', false);  // 6
  add(direct + '_' + ser, false);                 // 7
  if (rev) add(rev + '_' + ser, false);            // 8
  add(direct + '*', false);                       // 9
  if (rev) add(rev + '*', false);                 // 10

  console.log(
    '[MIO TAG] probando 10 formas:',
    nombre,
    '=>',
    cands.map(function (x) {
      return x.tag;
    }).join(' | ')
  );

  // ============================================================
  // CAPA 1.5 ” GELBOORU (fallback de las 10 formas)
  // Si Danbooru no encontró tag en las 10 formas, probamos las
  // mismas 10 formas en Gelbooru antes de pasar a la CAPA 2.
  // ============================================================

  async function mioFindTagGelbooruFallback() {
    const candsGel = [];
    const addGel = function (tag) {
      if (tag && !candsGel.some(function (c) { return c === tag; })) {
        candsGel.push(tag);
      }
    };

    addGel(direct);
    if (rev) addGel(rev);
    addGel(direct + '_(' + ser + ')');
    if (rev) addGel(rev + '_(' + ser + ')');
    addGel(direct + ' (' + serie + ')');
    if (rev) addGel(rev + ' (' + serie + ')');
    addGel(direct + '_' + ser);
    if (rev) addGel(rev + '_' + ser);
    addGel(direct + '*');
    if (rev) addGel(rev + '*');

    console.log(
      '[MIO TAG GELBOORU] probando 10 formas:',
      nombre,
      '=>',
      candsGel.join(' | ')
    );

    for (const c of candsGel) {
      if (!c) continue;
      // Las formas con '*' ya se prueban como pattern más abajo.
      if (c.indexOf('*') >= 0) continue;
      try {
        const r = await mioGelbooruTag(c);
        if (r.temporal) {
          console.log('[MIO TAG GELBOORU] temporal, se omite esta forma:', c);
          continue;
        }
        if (r.exists && r.exact) {
          console.log('[MIO TAG GELBOORU] match exacto:', nombre, '=>', r.name);
          return { tag: r.name, source: 'gelbooru' };
        }
        if (r.exists && !r.exact) {
          const base = String(r.name || '').toLowerCase();
          const wanted = String(c || '').toLowerCase().replace(/\s+/g, '_');
          if (base === wanted || base.startsWith(wanted + '_(') || base.startsWith(wanted + ' (')) {
            console.log('[MIO TAG GELBOORU] variante aceptada:', nombre, '=>', r.name);
            return { tag: r.name, source: 'gelbooru' };
          }
        }
      } catch (e) {
        console.log('[MIO TAG GELBOORU] error:', c, e?.message || e);
      }
    }

    // Si ninguna forma fue exacta, búsqueda por patrón en Gelbooru
    for (const pattern of [direct + '*', rev ? rev + '*' : null]) {
      if (!pattern) continue;
      try {
        const r = await mioGelbooruSearchTags(pattern, 20);
        if (r.temporal) {
          console.log('[MIO TAG GELBOORU] pattern temporal, se omite:', pattern);
          continue;
        }
        for (const item of (r.names || [])) {
          const nm = String(item.name || '').toLowerCase();
          if (nm === direct || (rev && nm === rev)) {
            console.log('[MIO TAG GELBOORU] patrón exacto:', nombre, '=>', item.name);
            return { tag: item.name, source: 'gelbooru' };
          }
          const isVariant =
            (direct && nm.startsWith(direct + '_(')) ||
            (rev && nm.startsWith(rev + '_('));
          if (isVariant) {
            console.log('[MIO TAG GELBOORU] variante:', nombre, '=>', item.name);
            return { tag: item.name, source: 'gelbooru' };
          }
        }
      } catch (e) {
        console.log('[MIO TAG GELBOORU] pattern error:', e?.message || e);
      }
    }

    return { tag: null };
  }

  // ============================================================
  // CAPA 2 ” COINCIDENCIAS EXACTAS
  // ============================================================

  // Las primeras 8 formas son tags concretos.
  // Si Danbooru confirma exactamente un tag de personaje,
  // tiene prioridad absoluta.

  // CAPA 2 reordenada:
  // primero variantes needCp=false (rapidas, no consumen 2 requests),
  // luego las needCp=true (una por una) solo si las rapidas fallaron.
  const needCpFalse = [];
  const needCpTrue = [];
  for (let i = 0; i < 8; i++) {
    const c = cands[i];
    if (!c || c.tag.indexOf('*') >= 0) continue;
    if (c.needCp) needCpTrue.push({ c, i });
    else needCpFalse.push({ c, i });
  }

  const tryOrder = async (list) => {
    for (const { c, i } of list) {
      const r = await mioCheckCandidate(c.tag, c.needCp, serie);
      if (r.temporal) return { temporal: true };
      if (r.ok) return { r, i, c };
    }
    return null;
  };

  let hitCapa2 = await tryOrder(needCpFalse);
  if (!hitCapa2) {
    hitCapa2 = await tryOrder(needCpTrue);
  }

  // Si Danbooru falló por rate limit / 403 / 5xx en la CAPA 2,
  // NO abortamos: pasamos inmediatamente al fallback Gelbooru.
  if (hitCapa2 && hitCapa2.temporal) {
    console.log('[MIO TAG] Danbooru temporal en CAPA 2, pasando a Gelbooru');
    try {
      const gelEarly = await mioFindTagGelbooruFallback();
      if (gelEarly && gelEarly.tag) {
        console.log('[MIO TAG] Gelbooru (early) encontrado:', nombre, '=>', gelEarly.tag);
        return {
          tag: gelEarly.tag,
          gelbooruTag: gelEarly.tag,
          tagSource: 'gelbooru'
        };
      }
    } catch (e) {
      console.log('[MIO TAG] error en Gelbooru early:', e?.message || e);
    }
    return { tag: null, temporal: true };
  }
  if (hitCapa2 && hitCapa2.r) {
    const danTag = hitCapa2.r.tag || hitCapa2.c.tag;
    console.log(
      '[MIO TAG] exacto #' + (hitCapa2.i + 1) + ':',
      nombre,
      '=>',
      danTag
    );

    // Buscar también en Gelbooru
    let gelTag = '';
    try {
      const gel = await mioGelbooruTag(danTag);
      if (gel && gel.exists) {
        gelTag = gel.name;
        console.log('[MIO TAG] también en Gelbooru:', gelTag);
      }
    } catch (e) {
      console.log('[MIO TAG] error Gelbooru (danbooru hit):', e?.message || e);
    }

    return {
      tag: danTag,
      gelbooruTag: gelTag,
      tagSource: gelTag ? 'danbooru+gelbooru' : 'danbooru'
    };
  }

  // ============================================================
  // CAPA 3 ” BÚSQUEDA POR PATRÓN
  // ============================================================

  const patterns = [
    direct + '*',
    rev ? rev + '*' : null
  ];

  for (const pattern of patterns) {
    if (!pattern || pattern === '**') continue;

    const r = await mioDanbooruSearchTags(pattern, 20);

    if (r.temporal) {
      console.log('[MIO TAG] Danbooru temporal en CAPA 3, saltando pattern:', pattern);
      continue;
    }

    const list = Array.isArray(r.names)
      ? r.names
      : [];

    // Primero buscamos coincidencia exacta dentro
    // de los resultados del patrón.
    for (const item of list) {
      const itemName = String(item.name || '').toLowerCase();

          const isExact = itemName === direct || itemName === rev;
    const isVariant =
      (direct && itemName.startsWith(direct + '_(')) ||
      (rev && itemName.startsWith(rev + '_('));
    if (isExact || isVariant) {
        if (
          Number(item.category) === 4 &&
          Number(item.count) >= MIO_MIN_POSTS
        ) {
          console.log(
            '[MIO TAG] patrón encontró exacto:',
            nombre,
            '=>',
            item.name
          );

          return {
            tag: item.name
          };
        }
      }
    }

    await mioSleep(700);
  }

  // ============================================================
  // CAPA 4 ” BÚSQUEDA PROFUNDA ROBUSTA
  // ============================================================

  let deep;

  try {
    deep = await mioFindDeepCandidates(
      nombre,
      serie
    );
  } catch (e) {
    console.log(
      '[MIO TAG SEARCH]',
      e && e.message
    );
    deep = null;
  }

  if (deep && deep.temporal) {
    console.log('[MIO TAG] Danbooru temporal en CAPA 4 (deep), pasando a Gelbooru');
    try {
      const gelDeep = await mioFindTagGelbooruFallback();
      if (gelDeep && gelDeep.tag) {
        console.log('[MIO TAG] Gelbooru (deep) encontrado:', nombre, '=>', gelDeep.tag);
        return {
          tag: gelDeep.tag,
          gelbooruTag: gelDeep.tag,
          tagSource: 'gelbooru'
        };
      }
    } catch (e) {
      console.log('[MIO TAG] error en Gelbooru deep:', e?.message || e);
    }
    return { tag: null, temporal: true };
  }

  const candidates =
    deep && Array.isArray(deep.candidates)
      ? deep.candidates
      : [];

  console.log(
    '[MIO TAG] candidatos:',
    nombre,
    '=>',
    candidates
      .slice(0, 8)
      .map(function (x) {
        return x.name + '[' + x.score + ']';
      })
      .join(', ')
  );

  // ============================================================
  // CAPA 5 ” VALIDACIÓN DE LOS MEJORES CANDIDATOS
  // ============================================================

  for (const candidate of candidates.slice(0, 8)) {
    if (
      Number(candidate.category) !== 4 ||
      Number(candidate.count) < MIO_MIN_POSTS
    ) {
      continue;
    }

    const r = await mioCheckCandidate(
      candidate.name,
      true,
      serie
    );

    if (r.temporal) {
      console.log('[MIO TAG] Danbooru temporal en CAPA 5, saltando:', candidate.name);
      continue;
    }

    if (r.ok) {
      console.log(
        '[MIO TAG] profundo validado:',
        nombre,
        '=>',
        candidate.name
      );

      let gelTag = '';
      try {
        const gel = await mioGelbooruTag(candidate.name);
        if (gel && gel.exists) {
          gelTag = gel.name;
          console.log('[MIO TAG] también en Gelbooru:', gelTag);
        }
      } catch (e) {}

      return {
        tag: candidate.name,
        gelbooruTag: gelTag,
        tagSource: gelTag ? 'danbooru+gelbooru' : 'danbooru'
      };
    }
  }

  // ============================================================
  // CAPA 6 ” GEMINI COMO ÚLTIMO RECURSO
  // ============================================================

  const aiTag = await mioAskGeminiTag(
    nombre,
    serie
  );

  if (aiTag) {
    const r = await mioCheckCandidate(
      aiTag,
      true,
      serie
    );

    if (r.temporal) {
      console.log('[MIO TAG] Danbooru temporal en CAPA 6 (Gemini), pasando a Gelbooru');
      try {
        const gelGem = await mioFindTagGelbooruFallback();
        if (gelGem && gelGem.tag) {
          console.log('[MIO TAG] Gelbooru (gemini) encontrado:', nombre, '=>', gelGem.tag);
          return {
            tag: gelGem.tag,
            gelbooruTag: gelGem.tag,
            tagSource: 'gelbooru'
          };
        }
      } catch (e) {
        console.log('[MIO TAG] error en Gelbooru gemini:', e?.message || e);
      }
      return { tag: null, temporal: true };
    }

    if (r.ok) {
      const danTag = r.tag || aiTag;
      console.log(
        '[MIO TAG] Gemini validado:',
        nombre,
        '=>',
        danTag
      );

      let gelTag = '';
      try {
        const gel = await mioGelbooruTag(danTag);
        if (gel && gel.exists) {
          gelTag = gel.name;
        }
      } catch (e) {}

      return {
        tag: danTag,
        gelbooruTag: gelTag,
        tagSource: gelTag ? 'danbooru+gelbooru' : 'danbooru'
      };
    }
  }

  // ============================================================
  // CAPA 7 ” GELBOORU FALLBACK FINAL
  // Si Danbooru no encontró tag en ninguna capa, probamos
  // las 10 formas en Gelbooru.
  // ============================================================

  try {
    const gel = await mioFindTagGelbooruFallback();
    if (gel && gel.temporal) {
      // Gelbooru también está temporalmente caído.
      // Devolvemos tag:null SIN temporal para que el personaje
      // se cree como pendienteTag en lugar de romper toda la cola.
      console.log('[MIO TAG] Gelbooru también temporal para:', nombre);
      return { tag: null };
    }
    if (gel && gel.tag) {
      console.log('[MIO TAG] encontrado solo en Gelbooru:', nombre, '=>', gel.tag);
      return {
        tag: gel.tag,
        gelbooruTag: gel.tag,
        tagSource: 'gelbooru'
      };
    }
  } catch (e) {
    console.log('[MIO TAG] error en fallback Gelbooru:', e?.message || e);
  }

  console.log(
    '[MIO TAG] sin tag:',
    nombre,
    '| serie:',
    serie
  );

  return {
    tag: null
  };
}

function mioCreateManualTag() {
  // MANUAL_TAGS_REMOVED_V1: siempre vacío
  return { tag: null };
}

function mioAddCharacter(serieName, nombre, valor, genero, tag, owner, tagCreatedByMio = false, gelbooruTag = '', tagSource = '') {
  const rango = calcularRarezaAddP(valor);
  let maxId = 0;
  for (const c of charactersCache) { const n = Number(c.id) || 0; if (n > maxId) maxId = n; }
  const key = String(nombre).toLowerCase().trim().replace(/[^\w]+/g, '_').replace(/^_+|_+$/g, '');
  if (!key || characterKeyMap.has(key) || characterMap.has(String(nombre).toLowerCase())) return null;

  const personaje = {
    id: maxId + 1,
    name: nombre,
    key: key,
    anime: serieName,
    tag: tag || '',
    gelbooruTag: gelbooruTag || '',
    tagSource: tagSource || (tag ? 'danbooru' : (gelbooruTag ? 'gelbooru' : '')),
    gender: genero,
    estado: 'Libre',
    value: valor,
    rarity: rango.rarity,
    chance: rango.chance,
    creator: owner,
    coinGen: Math.floor(55 * Number(valor)),
    images: [],
    claimedBy: {}
  };
  if (tagCreatedByMio) {
    personaje.mioTagCreatedAt = Date.now();
  }
  if (!tag && !gelbooruTag) personaje.pendienteTag = true;

  charactersCache.push(personaje);
  characterMap.set(String(nombre).toLowerCase(), personaje);
  characterKeyMap.set(key, personaje);

  const skey = String(serieName).toLowerCase().trim();
  let s = seriesCache.get(skey) || Array.from(seriesCache.values()).find(function (v) { return mioNorm(v.name) === mioNorm(serieName); });
  if (!s) {
    let maxS = 0;
    for (const v of seriesCache.values()) { const n = Number(v.id); if (Number.isInteger(n) && n > maxS) maxS = n; }
    s = { id: maxS + 1, name: serieName, characters: new Set() };
    seriesCache.set(skey, s);
  }
  if (!s.characters || typeof s.characters.add !== 'function') {
    s.characters = new Set(Array.isArray(s.characters) ? s.characters : []);
  }
  s.characters.add(key);

  fs.mkdirSync(SERIES_DIR, { recursive: true });
  const fileKey = String(s.name).toLowerCase().trim().replace(/[^\w]/g, '_');
  fs.writeFileSync(
    path.join(SERIES_DIR, fileKey + '.json'),
    JSON.stringify({ id: Number(s.id), name: s.name, characters: Array.from(s.characters) }, null, 2)
  );
  saveCharacters();
  return personaje;
}

async function mioProcessSeries(sock, st, pick) {
  const gid = st.gid;
  const logJid = db.creatingLogs;
  const chars = [];
  let p = 1;
  let tp = 1;
  while (st.active && p <= tp) {
    const cmd = p === 1 ? '#ainfo ' + pick.name : '#ainfo ' + pick.name + ' page=' + p;
    const txt = await mioAsk(sock, st.logJid, 'ainfo', cmd, pick.name);
    const r = mioParseAinfo(txt);
    if (!r.chars.length) throw new Error('Respuesta inesperada de #ainfo: ' + mioClean(txt).slice(0, 80));
    chars.push.apply(chars, r.chars);
    tp = r.totalPages || 1;
    p++;
  }

  const res = { serie: pick.name, total: chars.length, existentes: 0, creados: 0, pendientes: 0, fallos: 0, truncado: false };
  if (!st.active) return res;

  const have = new Set(
    charactersCache
      .filter(function (c) { return mioNorm(c.anime) === mioNorm(pick.name); })
      .map(function (c) { return mioNorm(c.name); })
  );
  const missing = chars.filter(function (c) {
    return !have.has(mioNorm(c.name)) && !characterMap.has(String(c.name).toLowerCase());
  });
  res.existentes = chars.length - missing.length;
  const todo = missing.slice(0, MIO_CHARS_PER_SERIES);
  res.truncado = missing.length > todo.length;

  if (st.stats) {
    st.stats.total += todo.length;
  }

  try {
    await sock.sendMessage(st.logJid, {
      text:
        'ყɴ vᴇo, ʟɴ sᴇrιᴇ `' +
        pick.name +
        '` tιᴇᴛᴇ `' +
        chars.length +
        '` ρᴇrsoᴛɴjᴇs, ʟo hɴrᴇ.'
    });
  } catch (e) {}

  let consecutive = 0;
  for (const c of todo) {
    if (!st.active) break;

    try {

    let info;
    try {
      const txt = await mioAsk(sock, st.logJid, 'winfo', '#winfo ' + c.name, c.name);
      info = mioParseWinfo(txt);
      consecutive = 0;
    } catch (e) {
      const em = e && e.message ? e.message : '';
      if (em.indexOf('sin respuesta|') === 0) {
        res.fallos++;
        consecutive++;
        if (consecutive >= 3) throw e;
        continue;
      }
      throw e;
    }

    if (!info.nombre) { res.fallos++; continue; }

    const valor = info.valor || c.value || 100;
    const genero = info.genero || 'Desconocido';

    let tagRes = { tag: null };
    try {
      tagRes = await mioFindTag(c.name, pick.name);
    } catch (e) {
      console.log('[MIO TAG]', c.name, e && e.message);
    }
    if (!tagRes.tag && !tagRes.temporal) {
      // MIO_NO_FAKE_TAGS_V1
      // Ya NO se crean tags manuales falsos cuando Danbooru no encuentra
      // el tag real. El personaje se crea SIN tag (pendienteTag=true)
      // y queda registrado como pendiente para revisión con /pendientes
      // o /mgs (que muestra personajes sin imagen local).
      console.log('[MIO] Sin tag real para', c.name, '| serie:', pick.name, '-> se creará SIN tag');
      tagRes = { tag: null };
    }

    const pj = mioAddCharacter(
      pick.name,
      c.name,
      valor,
      genero,
      tagRes.tag,
      st.owner,
      tagRes.createdManually === true,
      tagRes.gelbooruTag || '',
      tagRes.tagSource || ''
    );
    if (!pj) { res.existentes++; continue; }

    res.creados++;

    if (!tagRes.tag) {
      res.pendientes++;
      try {
        await sock.sendMessage(st.logJid, {
          text:
            'Creé el personaje `' +
            pj.name +
            '`, pero no pude comprobar su tag porque el servicio está temporalmente limitado.'
        });
      } catch (e) {}
    } else if (tagRes.manualTag) {
      try {
        await sock.sendMessage(st.logJid, {
          text:
            'Bien, creé el personaje `' +
            pj.name +
            '`. No encontré su tag, pero reutilicé el tag `' +
            tagRes.tag +
            '`.'
        });
      } catch (e) {}
    } else {
      try {
        await sock.sendMessage(st.logJid, {
          text:
            'ρᴇrfᴇᴘto, ᴘrᴇᴇ ᴇʟ ρᴇrsoᴛɴjᴇ `' +
            pj.name +
            '` ᴘorrᴇᴘtɴmᴇᴛᴛᴇ ᴘoᴛ tɴg.'
        });
      } catch (e) {}
    }

    const currentIndex = todo.indexOf(c);

    if (currentIndex !== todo.length - 1 && st.active) {
      const siguiente = todo[currentIndex + 1];
      try {
        await sock.sendMessage(st.logJid, {
          text:
            'ρɴsɴrᴇ ɴʟ sιgᴠιᴇᴛtᴇ ρᴇrsoᴛɴjᴇ `' +
            siguiente.name +
            '`.'
        });
      } catch (e) {}
    }

    console.log(
      '[MIO] creado:',
      pj.name,
      '| serie:',
      pick.name,
      '| tag:',
      tagRes.tag || '(pendiente)'
    );

    } finally {
      if (st.stats) {
        st.stats.processed++;
        try {
          await mioActualizarBarra(sock, st, st.stats.processed, st.stats.total);
        } catch (e) {}
      }
    }
  }
  return res;
}
async function mioRunCycle(sock) {
  const st = global.__mio;
  st.stats = { processed: 0, total: 0, startTime: Date.now() };
  const gid = st.gid;
  const report = [];
  const used = new Set();
  let pool = [];
  let page = 0;
  let totalPages = 1;

  try {
    if (typeof CHARACTERS_FILE !== 'undefined' && fs.existsSync(CHARACTERS_FILE)) {
      fs.copyFileSync(CHARACTERS_FILE, CHARACTERS_FILE + '.mio_' + Date.now());
    }
  } catch (error) {
    console.error('[MIO] no se pudo crear la copia de seguridad:', error?.message || error);
  }

  const needsWork = function (s) {
    const local = charactersCache.filter(function (c) { return mioNorm(c.anime) === mioNorm(s.name); }).length;
    return local < s.count;
  };

  if (Array.isArray(st.series) && st.series.length) {
    for (let n = 0; n < st.series.length && st.active; n++) {
      const requested = st.series[n];
      const pick = { name: requested, count: 0 };
      const r = await mioProcessSeries(sock, st, pick);
      report.push(r);
    }
  } else {
    for (let n = 0; n < MIO_MAX_SERIES && st.active; n++) {
      pool = pool.filter(function (s) { return !used.has(mioNorm(s.name)) && needsWork(s); });
      while (st.active && !pool.length && page < totalPages) {
        page++;
        const txt = await mioAsk(sock, st.logJid, 'slist', page === 1 ? '#slist' : '#slist ' + page);
        const parsed = mioParseSlist(txt);
        if (!parsed.series.length) throw new Error('Respuesta inesperada de #slist: ' + mioClean(txt).slice(0, 80));
        totalPages = parsed.totalPages || 1;
        pool = parsed.series.filter(function (s) { return !used.has(mioNorm(s.name)) && needsWork(s); });
      }
      if (!st.active) return report;
      if (!pool.length) break;
      const pick = pool.splice(Math.floor(Math.random() * pool.length), 1)[0];
      used.add(mioNorm(pick.name));
      const r = await mioProcessSeries(sock, st, pick);
      report.push(r);
    }
  }

  return report;
}
// ============================================================
// MIO_DANBOORU_AUTH_DIRECT_V3
// Lee danbooru-config.json (el mismo que /rw, /winfo, etc.)
// ============================================================
function mioReadDanbooruCredsDirect() {
  try {
    const cfgPath = path.join(process.cwd(), 'danbooru-config.json');
    if (!fs.existsSync(cfgPath)) return null;
    const raw = fs.readFileSync(cfgPath, 'utf8');
    const data = JSON.parse(raw);
    if (!data || !data.login || !data.api_key) return null;
    const login = String(data.login).trim();
    const api_key = String(data.api_key).trim();
    if (!login || !api_key) return null;
    return { login, api_key };
  } catch (e) {
    console.log('[MIO AUTH] error leyendo danbooru-config.json:', e?.message || e);
    return null;
  }
}

async function mioEnsureDanbooruCreds() {
  try {
    const direct = mioReadDanbooruCredsDirect();
    if (direct) {
      console.log('[MIO AUTH] credenciales Danbooru desde danbooru-config.json:', direct.login, '(' + direct.api_key.length + ' chars)');
      return direct;
    }
    if (typeof getDanbooruCredentials === 'function') {
      const c = getDanbooruCredentials();
      if (c && c.login && c.api_key) {
        console.log('[MIO AUTH] credenciales Danbooru desde getDanbooruCredentials():', c.login);
        return c;
      }
    }
    console.log('[MIO AUTH] AVISO: no hay danbooru-config.json valido y getDanbooruCredentials() devolvio null.');
    return null;
  } catch (e) {
    console.log('[MIO AUTH] error verificando credenciales:', e?.message || e);
    return null;
  }
}
/* ============================================================
 * MIO_TAG_FILL_V2 - RESILIENTE
 * ------------------------------------------------------------
 * Mejoras sobre V1:
 * - Persiste estado en db.mioTagFill para reanudar tras reinicio
 * - try/catch por personaje (un error no mata el loop)
 * - saveCharacters cada 50 tags (no en cada uno)
 * - Progreso editado cada 30 personajes (reduce edits a ~900)
 * - Pausa adaptativa si Gelbooru devuelve 'temporal'
 * - Heartbeat en consola cada 60s para detectar cuelgues
 * - Timeout de seguridad por personaje (30s)
 * - Reintento de guardado si saveCharacters falla
 * ============================================================ */

const MIO_FILL_V2_SAVE_EVERY = 50;
const MIO_FILL_V2_PROGRESS_EVERY = 30;
const MIO_FILL_V2_HEARTBEAT_MS = 60 * 1000;
const MIO_FILL_V2_TIMEOUT_MS = 30 * 1000;
const MIO_FILL_V2_TEMPORAL_PAUSE_MS = 5000;

async function __mioFillSearchTagGelbooru(nombre, serie) {
  const base = String(nombre || '')
    .replace(/\s*\([^)]*\)\s*/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  if (!base) return { tag: null, temporal: false };

  const slug = s => String(s || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/['\u2122.]/g, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');

  const words = base.split(' ').filter(Boolean);
  const direct = slug(base);
  const rev = words.length > 1 ? slug(words.slice().reverse().join(' ')) : null;
  const ser = slug(serie);

  const cands = [];
  const add = t => {
    if (t && !cands.some(c => c === t)) cands.push(t);
  };

  add(direct);
  if (rev) add(rev);
  add(direct + '_(' + ser + ')');
  if (rev) add(rev + '_(' + ser + ')');
  add(direct + ' (' + serie + ')');
  if (rev) add(rev + ' (' + serie + ')');
  add(direct + '_' + ser);
  if (rev) add(rev + '_' + ser);
  add(direct + '*');
  if (rev) add(rev + '*');

  for (const c of cands) {
    if (!c) continue;
    if (c.indexOf('*') >= 0) continue;
    try {
      const r = await mioGelbooruTag(c);
      if (r.temporal) return { tag: null, temporal: true };
      if (r.exists && r.exact) return { tag: r.name, temporal: false };
      if (r.exists && !r.exact) {
        const b = String(r.name || '').toLowerCase();
        const w = String(c || '').toLowerCase().replace(/\s+/g, '_');
        if (b === w || b.startsWith(w + '_(') || b.startsWith(w + ' (')) {
          return { tag: r.name, temporal: false };
        }
      }
    } catch (e) {
      console.log('[MIO-FILL-GEL] error tag:', c, e?.message || e);
    }
  }

  for (const pattern of [direct + '*', rev ? rev + '*' : null]) {
    if (!pattern) continue;
    try {
      const r = await mioGelbooruSearchTags(pattern, 20);
      if (r.temporal) return { tag: null, temporal: true };
      for (const item of (r.names || [])) {
        const nm = String(item.name || '').toLowerCase();
        if (nm === direct || (rev && nm === rev)) return { tag: item.name, temporal: false };
        const isVar =
          (direct && nm.startsWith(direct + '_(')) ||
          (rev && nm.startsWith(rev + '_('));
        if (isVar) return { tag: item.name, temporal: false };
      }
    } catch (e) {
      console.log('[MIO-FILL-GEL] error pattern:', pattern, e?.message || e);
    }
  }

  return { tag: null, temporal: false };
}

async function __mioFillSearchTagDanbooru(nombre, serie) {
  const base = String(nombre || '')
    .replace(/\s*\([^)]*\)\s*/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  if (!base) return { tag: null, temporal: false };

  const slug = s => String(s || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/['\u2122.]/g, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');

  const words = base.split(' ').filter(Boolean);
  const direct = slug(base);
  const rev = words.length > 1 ? slug(words.slice().reverse().join(' ')) : null;
  const ser = slug(serie);

  const cands = [];
  const add = (t, needCp) => {
    if (t && !cands.some(c => c.tag === t)) cands.push({ tag: t, needCp });
  };

  add(direct, true);
  if (rev) add(rev, true);
  add(direct + '_(' + ser + ')', false);
  if (rev) add(rev + '_(' + ser + ')', false);
  add(direct + ' (' + serie + ')', false);
  if (rev) add(rev + ' (' + serie + ')', false);
  add(direct + '_' + ser, false);
  if (rev) add(rev + '_' + ser, false);
  add(direct + '*', false);
  if (rev) add(rev + '*', false);

  const needCpFalse = [];
  const needCpTrue = [];
  for (let i = 0; i < 8; i++) {
    const c = cands[i];
    if (!c || c.tag.indexOf('*') >= 0) continue;
    if (c.needCp) needCpTrue.push(c);
    else needCpFalse.push(c);
  }

  const tryOrder = async list => {
    for (const c of list) {
      try {
        const r = await mioCheckCandidate(c.tag, c.needCp, serie);
        if (r.temporal) return { temporal: true };
        if (r.ok) return { r };
      } catch (e) {
        console.log('[MIO-FILL-DAN] error candidate:', c.tag, e?.message || e);
      }
    }
    return null;
  };

  let hit = await tryOrder(needCpFalse);
  if (!hit) hit = await tryOrder(needCpTrue);
  if (hit && hit.temporal) return { tag: null, temporal: true };
  if (hit && hit.r) return { tag: hit.r.tag || null, temporal: false };

  for (const pattern of [direct + '*', rev ? rev + '*' : null]) {
    if (!pattern || pattern === '**') continue;
    try {
      const r = await mioDanbooruSearchTags(pattern, 20);
      if (r.temporal) return { tag: null, temporal: true };
      for (const item of (r.names || [])) {
        const it = String(item.name || '').toLowerCase();
        const isEx = it === direct || it === rev;
        const isVar =
          (direct && it.startsWith(direct + '_(')) ||
          (rev && it.startsWith(rev + '_('));
        if ((isEx || isVar) &&
            Number(item.category) === 4 &&
            Number(item.count) >= MIO_MIN_POSTS) {
          return { tag: item.name, temporal: false };
        }
      }
    } catch (e) {
      console.log('[MIO-FILL-DAN] error pattern:', pattern, e?.message || e);
    }
  }

  let deep = null;
  try {
    deep = await mioFindDeepCandidates(nombre, serie);
  } catch (e) {
    console.log('[MIO-FILL-DAN] deep error:', e?.message || e);
  }
  if (deep && deep.temporal) return { tag: null, temporal: true };

  const candidates = deep && Array.isArray(deep.candidates) ? deep.candidates : [];
  for (const candidate of candidates.slice(0, 8)) {
    if (Number(candidate.category) !== 4 || Number(candidate.count) < MIO_MIN_POSTS) continue;
    try {
      const r = await mioCheckCandidate(candidate.name, true, serie);
      if (r.temporal) return { tag: null, temporal: true };
      if (r.ok) return { tag: candidate.name, temporal: false };
    } catch (e) {
      console.log('[MIO-FILL-DAN] error deep candidate:', candidate.name, e?.message || e);
    }
  }

  try {
    const aiTag = await mioAskGeminiTag(nombre, serie);
    if (aiTag) {
      const r = await mioCheckCandidate(aiTag, true, serie);
      if (r.ok) return { tag: r.tag || aiTag, temporal: false };
    }
  } catch (e) {
    console.log('[MIO-FILL-DAN] gemini error:', e?.message || e);
  }

  return { tag: null, temporal: false };
}

async function __mioFillSendProgress(sock, jid, st) {
  if (!st.barraMsg || !st.barraMsg.key) return;
  const percent = st.total > 0 ? Math.min(100, Math.floor((st.processed / st.total) * 100)) : 0;
  const lines = [
    '\u300E ' + st.mode.toUpperCase() + ' FILL V2 \u300F',
    '',
    mioBarra(percent) + ' ' + mioEstiloNumero(percent) + '%',
    '',
    '\u00BB Procesados: ' + st.processed + '/' + st.total,
    '\u2705 Agregados: ' + st.added,
    '\u23ED\uFE0F Ya ten\u00EDan tag: ' + st.skipped,
    '\u274C No encontrados: ' + st.notFound,
    '\u26A0\uFE0F Errores: ' + st.errors
  ];
  try {
    await sock.sendMessage(jid, { text: lines.join('\n'), edit: st.barraMsg.key });
  } catch (e) { /* ignore edit errors */ }
}

async function __mioFillRun(sock, jid, mode) {
  const isGelbooru = mode === 'gelbooru';
  const isDanbooru = mode === 'danbooru';
  if (!isGelbooru && !isDanbooru) return;

  const botLabel = isGelbooru ? 'Gelbooru' : 'Danbooru';

  if (!Array.isArray(charactersCache) || !charactersCache.length) {
    return sock.sendMessage(jid, { text: '\u25C7 No hay personajes.' });
  }

  // Inicializar db.mioTagFill si no existe
  db.mioTagFill ??= {};
  db.mioTagFill[mode] ??= { lastIndex: 0, startedAt: 0, finished: false };
  const fillState = db.mioTagFill[mode];

  // ¿Reanudar o empezar de cero?
  let startIdx = 0;
  if (fillState.lastIndex > 0 && fillState.lastIndex < charactersCache.length && !fillState.finished) {
    startIdx = fillState.lastIndex;
    console.log('[MIO-FILL] Reanudando desde índice', startIdx, 'de', charactersCache.length);
  } else {
    fillState.lastIndex = 0;
    fillState.startedAt = Date.now();
    fillState.finished = false;
  }
  saveDB();

  const snapshot = [...charactersCache];
  const st = {
    mode: mode,
    total: snapshot.length,
    processed: startIdx,
    added: 0,
    skipped: 0,
    notFound: 0,
    errors: 0,
    barraMsg: null,
    lastSaveAt: 0,
    pendingSaves: 0
  };

  // Mensaje inicial
  try {
    const reanudMsg = startIdx > 0 ? ' (reanudando desde ' + startIdx + ')' : '';
    st.barraMsg = await sock.sendMessage(jid, {
      text:
        '\u300E ' + botLabel + ' FILL V2' + reanudMsg + ' \u300F\n\n' +
        mioBarra(0) + ' ' + mioEstiloNumero(0) + '%\n\n' +
        '\u00BB Personajes: ' + startIdx + '/' + st.total
    });
  } catch (e) {
    console.log('[MIO-FILL] barra inicial error:', e?.message || e);
  }

  // Heartbeat: loguea cada 60s para verificar que el loop sigue vivo
  const heartbeat = setInterval(() => {
    const elapsed = Math.floor((Date.now() - fillState.startedAt) / 1000);
    console.log('[MIO-FILL-HEARTBEAT]',
      'mode=' + mode,
      'idx=' + st.processed + '/' + st.total,
      'added=' + st.added,
      'notFound=' + st.notFound,
      'errors=' + st.errors,
      'elapsed=' + elapsed + 's'
    );
  }, MIO_FILL_V2_HEARTBEAT_MS);

  const addedList = [];
  const notFoundList = [];
  const errorList = [];

  try {
    for (let i = startIdx; i < snapshot.length; i++) {
      const c = snapshot[i];

      // Guardar índice para reanudar
      fillState.lastIndex = i;

      if (!c || !c.name) {
        st.skipped++;
        st.processed = i + 1;
        continue;
      }

      // Omitir si ya tiene el tag
      if (isGelbooru) {
        if (c.gelbooruTag && String(c.gelbooruTag).trim()) {
          st.skipped++;
          st.processed = i + 1;
          if (st.processed % MIO_FILL_V2_PROGRESS_EVERY === 0) {
            await __mioFillSendProgress(sock, jid, st);
          }
          continue;
        }
      } else {
        const hasDan = c.tag && String(c.tag).trim() && c.pendienteTag !== true;
        if (hasDan) {
          st.skipped++;
          st.processed = i + 1;
          if (st.processed % MIO_FILL_V2_PROGRESS_EVERY === 0) {
            await __mioFillSendProgress(sock, jid, st);
          }
          continue;
        }
      }

      // Buscar con timeout de seguridad
      let result = { tag: null, temporal: false };
      try {
        const searchPromise = isGelbooru
          ? __mioFillSearchTagGelbooru(c.name, c.anime || '')
          : __mioFillSearchTagDanbooru(c.name, c.anime || '');

        result = await Promise.race([
          searchPromise,
          new Promise((_, reject) =>
            setTimeout(() => reject(new Error('timeout')), MIO_FILL_V2_TIMEOUT_MS)
          )
        ]);
      } catch (e) {
        st.errors++;
        errorList.push({ name: c.name, error: e?.message || String(e) });
        console.log('[MIO-FILL] Error buscando', c.name, ':', e?.message || e);
      }

      // Si fue temporal, pausa adaptativa y NO avanzar el índice
      if (result && result.temporal) {
        console.log('[MIO-FILL] Temporal, pausando', MIO_FILL_V2_TEMPORAL_PAUSE_MS, 'ms');
        await new Promise(r => setTimeout(r, MIO_FILL_V2_TEMPORAL_PAUSE_MS));
        continue;
      }

      if (result && result.tag) {
        if (isGelbooru) {
          c.gelbooruTag = String(result.tag).trim();
          if (!c.tagSource) c.tagSource = 'gelbooru';
          else if (!c.tagSource.includes('gelbooru')) c.tagSource = c.tagSource + '+gelbooru';
        } else {
          c.tag = String(result.tag).trim();
          if (c.pendienteTag) delete c.pendienteTag;
          if (!c.tagSource) c.tagSource = 'danbooru';
          else if (!c.tagSource.includes('danbooru')) c.tagSource = 'danbooru+' + c.tagSource;
        }
        st.added++;
        addedList.push({ name: c.name, tag: result.tag });
        st.pendingSaves++;

        // Guardar cada 50 tags (o al final)
        if (st.pendingSaves >= MIO_FILL_V2_SAVE_EVERY || i === snapshot.length - 1) {
          try {
            saveCharacters();
            st.pendingSaves = 0;
            st.lastSaveAt = Date.now();
          } catch (e) {
            console.log('[MIO-FILL] saveCharacters error:', e?.message || e);
          }
        }
      } else {
        st.notFound++;
        notFoundList.push(c.name);
      }

      st.processed = i + 1;

      // Progreso cada 30 personajes (antes era cada 3)
      if (st.processed % MIO_FILL_V2_PROGRESS_EVERY === 0 || st.processed === st.total) {
        await __mioFillSendProgress(sock, jid, st);
      }

      // Guardar índice cada 100 personajes
      if (st.processed % 100 === 0) {
        try { saveDB(); } catch (e) {}
      }

      // Sleep entre personajes
      await new Promise(r => setTimeout(r, isGelbooru ? 900 : 1200));
    }

    // Guardado final
    try {
      saveCharacters();
      saveDB();
    } catch (e) {
      console.log('[MIO-FILL] guardado final error:', e?.message || e);
    }

    fillState.finished = true;
    fillState.lastIndex = snapshot.length;
    saveDB();

  } catch (e) {
    console.error('[MIO-FILL] ERROR CRÍTICO en el loop:', e?.stack || e);
    st.errors++;
    errorList.push({ name: '(loop)', error: e?.message || String(e) });
    // NO marcar finished para que se pueda reanudar
  } finally {
    clearInterval(heartbeat);

    // Borrar barra
    try {
      if (st.barraMsg && st.barraMsg.key) {
        await sock.sendMessage(jid, { delete: st.barraMsg.key });
      }
    } catch (e) {}

    // Reporte final
    const lines = [
      '\u2606 ' + botLabel + ' FILL V2 \u00B7 ' + (fillState.finished ? 'COMPLETADO' : 'INTERRUMPIDO'),
      '',
      '\u25C8 Total escaneados: ' + st.processed + '/' + st.total,
      '\u2705 Agregados: ' + st.added,
      '\u23ED\uFE0F Ya ten\u00EDan tag (correcto): ' + st.skipped,
      '\u274C No encontrados: ' + st.notFound,
      '\u26A0\uFE0F Errores: ' + st.errors
    ];

    if (!fillState.finished && st.processed < st.total) {
      lines.push('');
      lines.push('\u26A0\uFE0F Proceso interrumpido. Se reanudar\u00E1 desde \u00EDndice ' + st.processed);
      lines.push('> Vuelve a ejecutar el mismo comando para continuar.');
    }

    if (addedList.length) {
      lines.push('');
      lines.push('\u300C TAG AGREGADO (primeros 20) \u300D');
      for (const a of addedList.slice(0, 20)) {
        lines.push('\u00BB ' + a.name + ' \u2192 ' + a.tag);
      }
      if (addedList.length > 20) {
        lines.push('... y ' + (addedList.length - 20) + ' m\u00E1s.');
      }
    }

    if (notFoundList.length) {
      lines.push('');
      lines.push('\u300C SIN TAG (primeros 15) \u300D');
      for (const n of notFoundList.slice(0, 15)) {
        lines.push('\u00BB ' + n);
      }
      if (notFoundList.length > 15) {
        lines.push('... y ' + (notFoundList.length - 15) + ' m\u00E1s.');
      }
    }

    if (errorList.length) {
      lines.push('');
      lines.push('\u300C ERRORES (primeros 10) \u300D');
      for (const e of errorList.slice(0, 10)) {
        lines.push('\u00BB ' + e.name + ': ' + e.error);
      }
      if (errorList.length > 10) {
        lines.push('... y ' + (errorList.length - 10) + ' m\u00E1s.');
      }
    }

    try {
      await sock.sendMessage(jid, { text: lines.join('\n') });
    } catch (e) {
      console.log('[MIO-FILL] reporte final error:', e?.message || e);
    }
  }
}

/* Reset del estado (útil para debug manual) */
function __mioFillReset(mode) {
  db.mioTagFill ??= {};
  db.mioTagFill[mode] = { lastIndex: 0, startedAt: 0, finished: false };
  saveDB();
}

/* ============================================================
 * TAGS_LISTS_V1 — /tagsg y /tagsd
 * ------------------------------------------------------------
 * /tagsg [pagina] → lista personajes SIN gelbooruTag
 * /tagsd [pagina] → lista personajes SIN tag danbooru (o con pendienteTag)
 *
 * 100 personajes por pagina. Solo owners.
 * ============================================================ */

const TAGS_LIST_PAGE_SIZE = 100;

function __tagsCanUse(sender) {
  // Owner principal: siempre puede
  if (isMainOwnerId(sender)) return true;

  // Secondary owner: solo si su rango es Sr. Novato o Sr. Owner
  if (!isSecondaryOwnerId(sender)) return false;

  try {
    const rank = (typeof __getSecondaryRank === 'function')
      ? __getSecondaryRank(sender)
      : null;

    if (rank === 'Sr. Novato' || rank === 'Sr. Owner') return true;

    // Si no hay sistema de rangos, permitir a cualquier secondary
    if (!rank) return true;

    return false;
  } catch (e) {
    return true; // fail-open para secondary owners
  }
}

async function __tagsListRun(sock, msg, jid, sender, mode, pageArg) {
  if (!__tagsCanUse(sender)) return; // ignorar silenciosamente

  const isGelbooru = mode === 'gelbooru';
  const label = isGelbooru ? 'Gelbooru' : 'Danbooru';
  const cmdName = isGelbooru ? 'tagsg' : 'tagsd';

  // Recopilar personajes sin tag
  const missing = [];

  for (const c of charactersCache) {
    if (!c || !c.name) continue;

    if (isGelbooru) {
      const hasGel = c.gelbooruTag && String(c.gelbooruTag).trim();
      if (!hasGel) missing.push(c);
    } else {
      const hasDan = c.tag && String(c.tag).trim() && c.pendienteTag !== true;
      if (!hasDan) missing.push(c);
    }
  }

  if (!missing.length) {
    return sock.sendMessage(
      jid,
      { text: '\u25C7 Todos los personajes ya tienen tag de ' + label + '.' },
      { quoted: msg }
    );
  }

  // Ordenar por ID ascendente para que sea estable
  missing.sort((a, b) => (Number(a.id) || 0) - (Number(b.id) || 0));

  const total = missing.length;
  const totalPages = Math.max(1, Math.ceil(total / TAGS_LIST_PAGE_SIZE));
  let page = parseInt(pageArg, 10);
  if (!Number.isInteger(page) || page < 1) page = 1;
  if (page > totalPages) page = totalPages;

  const start = (page - 1) * TAGS_LIST_PAGE_SIZE;
  const slice = missing.slice(start, start + TAGS_LIST_PAGE_SIZE);

  // Construir lineas
  const lines = [];
  lines.push('\u300E SIN TAG \u00B7 ' + label + ' \u300F');
  lines.push('');
  lines.push('\u25C8 Total sin tag: ' + total);
  lines.push('\u25C8 Pagina: ' + page + '/' + totalPages);
  lines.push('');

  for (const c of slice) {
    const name = String(c.name || '').trim();
    const anime = String(c.anime || '').trim() || 'Sin serie';
    const id = c.id || '?';
    lines.push('\u00BB ' + name + ' (' + anime + ') \u2014 ID ' + id);
  }

  lines.push('');
  if (page < totalPages) {
    lines.push('\u25C8 Siguiente: /' + cmdName + ' ' + (page + 1));
  } else {
    lines.push('\u25C8 \u00DAltima pagina.');
  }
  if (page > 1) {
    lines.push('\u25C8 Anterior: /' + cmdName + ' ' + (page - 1));
  }

  const fullText = lines.join('\n');

  // WhatsApp permite hasta ~65.000 chars por mensaje.
  // Una pagina de 100 personajes nunca supera ~6.000 chars.
  // Enviamos UN SOLO mensaje.
  const HARD_LIMIT = 60000;
  if (fullText.length > HARD_LIMIT) {
    // Caso extremo: personajes con nombres absurdamente largos.
    // Truncamos y avisamos.
    const truncated = fullText.slice(0, HARD_LIMIT - 200) +
      '\n\n\u26A0\uFE0F Mensaje truncado por longitud. Usa paginas mas pequenas.';
    return sock.sendMessage(jid, { text: truncated }, { quoted: msg });
  }

  return sock.sendMessage(jid, { text: fullText }, { quoted: msg });
}

/* ============================================================
 * FIX_RARITY_NORMAL_TO_COMUN_V1
 * ============================================================ */

async function __fixRarityAll(sock, msg, jid, sender) {
  if (!isMainOwnerId(sender)) return;
  const total = charactersCache.length;
  let changed = 0;
  const changedList = [];
  for (const c of charactersCache) {
    if (!c || !c.name) continue;
    const r = String(c.rarity || '').trim();
    if (r.toLowerCase() === 'normal') {
      c.rarity = 'Comun';
      changed++;
      if (changedList.length < 20) changedList.push(c.name + ' (ID ' + (c.id || '?') + ')');
    }
  }
  if (changed > 0) saveCharacters();
  const lines = [
    '\u2606 FIX RARITY \u00B7 NORMAL \u2192 COMUN',
    '',
    '\u25C8 Total revisados: ' + total,
    '\u2705 Cambiados: ' + changed
  ];
  if (changed === 0) {
    lines.push('');
    lines.push('\u25C7 No hab\u00EDa personajes con rareza "Normal".');
  } else {
    lines.push('');
    lines.push('\u300C CAMBIADOS (primeros 20) \u300D');
    for (const n of changedList) lines.push('\u00BB ' + n);
    if (changed > 20) lines.push('... y ' + (changed - 20) + ' m\u00E1s.');
  }
  await sock.sendMessage(jid, { text: lines.join('\n') }, { quoted: msg });
}


/* ============================================================
 * FIX_CREATORS_V1 — /fixcreators
 * ------------------------------------------------------------
 * Asigna al owner principal todos los personajes sin creador.
 * Detecta: creator vacío, null, undefined, 'Desconocido', etc.
 * Solo owner principal.
 * ============================================================ */

function __isInvalidCreator(creator) {
  if (creator === null || creator === undefined) return true;
  const s = String(creator).trim().toLowerCase();
  if (!s) return true;
  if (s === 'null' || s === 'undefined' || s === 'none') return true;
  if (s === 'desconocido' || s === 'unknown' || s === 'desconocida') return true;
  if (s === 'sin creador' || s === 'no creator' || s === 'n/a' || s === 'na') return true;
  return false;
}

function __getOwnerPrincipalJid() {
  try {
    if (typeof getMainOwner === 'function') {
      const v = getMainOwner();
      if (v) return String(v).trim();
    }
  } catch (e) {}
  if (typeof db !== 'undefined' && db) {
    if (db.primaryOwner) return String(db.primaryOwner).trim();
    if (typeof OWNER_NUMBER !== 'undefined' && OWNER_NUMBER) return String(OWNER_NUMBER).trim();
  }
  return null;
}

async function __fixCreatorsAll(sock, msg, jid, sender) {
  if (!isMainOwnerId(sender)) {
    return; // ignorar silenciosamente
  }

  const ownerJid = __getOwnerPrincipalJid();
  if (!ownerJid) {
    return sock.sendMessage(jid, {
      text: '\u274C No pude detectar el JID del owner principal.'
    }, { quoted: msg });
  }

  const total = charactersCache.length;
  let changed = 0;
  let alreadyOk = 0;
  const changedList = [];

  for (const c of charactersCache) {
    if (!c || !c.name) continue;

    if (__isInvalidCreator(c.creator)) {
      c.creator = ownerJid;
      changed++;
      if (changedList.length < 20) {
        changedList.push(c.name + ' (ID ' + (c.id || '?') + ')');
      }
    } else {
      alreadyOk++;
    }
  }

  if (changed > 0) {
    saveCharacters();
  }

  const lines = [
    '\u2606 FIX CREATORS',
    '',
    '\u25C8 Owner principal: ' + ownerJid,
    '\u25C8 Total revisados: ' + total,
    '\u2705 Asignados al owner: ' + changed,
    '\u23ED\uFE0F Ya ten\u00EDan creador: ' + alreadyOk
  ];

  if (changed > 0) {
    lines.push('');
    lines.push('\u300C CAMBIADOS (primeros 20) \u300D');
    for (const n of changedList) lines.push('\u00BB ' + n);
    if (changed > 20) lines.push('... y ' + (changed - 20) + ' m\u00E1s.');
  } else {
    lines.push('');
    lines.push('\u25C7 Todos los personajes ya ten\u00EDan creador v\u00E1lido.');
  }

  await sock.sendMessage(jid, { text: lines.join('\n') }, { quoted: msg });
}


/* ============================================================
 * SETTAG_D/G_V1 — /settagd y /settagg
 * ------------------------------------------------------------
 * /settagd nombre / tag  -> cambia tag de Danbooru
 * /settagd nombre /      -> deja vacío (quita tag)
 * /settagg nombre / tag  -> cambia tag de Gelbooru
 * /settagg nombre /      -> deja vacío (quita tag)
 *
 * Permisos: owner principal, o secondary rango Sr. Owner.
 * ============================================================ */

function __setTagCanUse(sender) {
  if (isMainOwnerId(sender)) return true;
  if (!isSecondaryOwnerId(sender)) return false;
  try {
    const rank = (typeof __getSecondaryRank === "function")
      ? __getSecondaryRank(sender)
      : null;
    if (rank === "Sr. Owner") return true;
    if (!rank) return true;
    return false;
  } catch {
    return true;
  }
}

async function __setTagByType(sock, msg, args, sender, body, prefix, type) {
  const jid = msg.key.remoteJid;
  const isDan = type === "dan";

  if (!__setTagCanUse(sender)) {
    return;
  }

  const raw = String(body || "").replace(/^\S+\s+/, "").trim();
  if (!raw) {
    return sock.sendMessage(jid, {
      text:
        "Uso:\n" +
        prefix + "settag" + (isDan ? "d" : "g") + " Nombre / tag\n" +
        prefix + "settag" + (isDan ? "d" : "g") + " Nombre /    (deja vacío)"
    }, { quoted: msg });
  }

  const slashIdx = raw.indexOf("/");
  if (slashIdx === -1) {
    return sock.sendMessage(jid, {
      text: "Falta el separador /. Formato: nombre / tag"
    }, { quoted: msg });
  }

  const name = raw.slice(0, slashIdx).trim();
  const tagInput = raw.slice(slashIdx + 1).trim();
  const newTag = tagInput;

  if (!name) {
    return sock.sendMessage(jid, {
      text: "Falta el nombre del personaje."
    }, { quoted: msg });
  }

  const char = findCharacter(name);
  if (!char) {
    return sock.sendMessage(jid, {
      text: "Personaje no encontrado: " + name
    }, { quoted: msg });
  }

  const wasInvalid =
    getCharacterImages(char.key).length === 0 &&
    !(await getCharacterMedia(char));

  if (isDan) {
    char.tag = newTag || "";
    if (!newTag) {
      char.pendienteTag = true;
    } else {
      delete char.pendienteTag;
    }
  } else {
    char.gelbooruTag = newTag || "";
  }

  saveCharacters();

  let statusAfter = null;
  if (newTag) {
    const nowReturnsImage = wasInvalid && !!(await getCharacterMedia(char));
    if (nowReturnsImage) {
      statusAfter = rewardInvalidMediaRepair(char, sender);
      if (statusAfter !== null) {
        await notifyEvents(
          sock,
          getStaffDisplayName(sender) +
            " ha arreglado el personaje " + char.name + " y obtuvo 5.000 de status.",
          [sender]
        );
      }
    }
  }

  const fieldLabel = isDan ? "Danbooru" : "Gelbooru";
  const actionLabel = newTag ? "actualizado" : "vaciado";

  const lines = [
    "Tag de " + fieldLabel + " " + actionLabel,
    "",
    "Personaje: " + char.name,
    "Tag: " + (newTag || "(vacío)")
  ];

  if (statusAfter !== null) {
    lines.push("");
    lines.push("RECOMPENSA POR ARREGLO");
    lines.push("+5.000 Status");
    lines.push("Status actual: " + statusAfter);
  }

  return sock.sendMessage(jid, { text: lines.join("\n") }, { quoted: msg });
}

