const GEMINI_CONFIG_FILE = './gemini-config.json';
const GEMINI_DEFAULT_KEY = 'owner_80a9012df01c86f611910967a547f74c185cf39848f10e09';
const GEMINI_DEFAULT_LANG = 'es-ES';

function geminiLoadConfig() {
  try {
    if (fs.existsSync(GEMINI_CONFIG_FILE)) {
      const raw = fs.readFileSync(GEMINI_CONFIG_FILE, 'utf8').trim();
      if (raw) return JSON.parse(raw);
    }
  } catch {}
  return {};
}

function geminiSaveConfig(cfg) {
  try {
    fs.writeFileSync(GEMINI_CONFIG_FILE, JSON.stringify(cfg, null, 2), 'utf8');
    return true;
  } catch { return false; }
}

async function geminiAsk({ prompt, chatId, images, language }) {
  const cfg = geminiLoadConfig();
  const apiKey = String(cfg.apiKey || GEMINI_DEFAULT_KEY).trim();
  const lang = String(language || cfg.language || GEMINI_DEFAULT_LANG).trim();

  const body = {
    prompt: String(prompt || '').trim(),
    model: 'flash-lite',
    language: lang,
    uploadImages: Array.isArray(images) && images.length > 0
  };

  if (chatId) body.chatId = String(chatId);
  if (Array.isArray(images) && images.length > 0) body.images = images;

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 60000);

  try {
    const res = await fetch('https://apiowo.vercel.app/api/gemini', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey
      },
      body: JSON.stringify(body),
      signal: controller.signal
    });

    if (!res.ok) {
      let errText = '';
      try { errText = await res.text(); } catch {}
      throw new Error('HTTP ' + res.status + (errText ? ': ' + errText.slice(0, 200) : ''));
    }

    const data = await res.json();
    if (!data || data.success !== true || !data.text) {
      throw new Error('Respuesta invalida: ' + JSON.stringify(data).slice(0, 200));
    }

    return {
      text: String(data.text),
      chatId: data.chatId || null,
      model: data.model || 'Gemini'
    };
  } finally {
    clearTimeout(timer);
  }
}

async function geminiExtractImagesFromQuoted(msg) {
  const ctx = msg.message?.extendedTextMessage?.contextInfo ||
              msg.message?.imageMessage?.contextInfo ||
              msg.message?.videoMessage?.contextInfo;
  if (!ctx || !ctx.quotedMessage) return [];

  const unwrap = (m) => {
    let c = m;
    while (c) {
      if (c.imageMessage) return c.imageMessage;
      c = c.ephemeralMessage?.message ||
          c.viewOnceMessage?.message ||
          c.viewOnceMessageV2?.message ||
          c.documentWithCaptionMessage?.message;
    }
    return null;
  };

  const img = unwrap(ctx.quotedMessage);
  if (!img) return [];

  try {
    const buffer = await downloadMediaMessage(
      { key: { remoteJid: msg.key.remoteJid, id: ctx.stanzaId, participant: ctx.participant }, message: ctx.quotedMessage },
      'buffer',
      {}
    );
    if (!buffer || !Buffer.isBuffer(buffer)) return [];
    const mime = img.mimetype || 'image/jpeg';
    const b64 = 'data:' + mime + ';base64,' + buffer.toString('base64');
    return [b64];
  } catch (e) {
    console.log('[GEMINI] Error descargando imagen citada:', e?.message || e);
    return [];
  }
}


async function mioRun(sock) {
  const st = global.__mio;

  // MIO_DANBOORU_AUTH_DIRECT_V3
  try { await mioEnsureDanbooruCreds(); } catch (_e) { console.log('[MIO AUTH] warn:', _e?.message || _e); }

  if (!db.creatingLogs || typeof db.creatingLogs !== 'string' || !db.creatingLogs.endsWith('@g.us')) {
    st.active = false;
    try {
      await sock.sendMessage(st.gid, { text: '❌ Debes activar /creatinglogs on en un grupo antes de usar /mio haimiya.' });
    } catch (e) {}
    return;
  }

  st.logJid = db.creatingLogs;

  try {
    st.barraMsg = await sock.sendMessage(st.gid, {
      text: mioBarra(0) + ' ' + mioEstiloNumero(0) + '%\n\n\u00BB Escaneando series...'
    });
  } catch (e) {
    console.error('[MIO] no se pudo crear barra:', e && e.message);
  }

  const barraTimer = null;

  try {
    const report = await mioRunCycle(sock);
    st.active = false;
    if (st.stats) {
      try {
        await mioActualizarBarra(sock, st, st.stats.total, st.stats.total);
      } catch (e) {}
    }

    await mioSleep(800);

    if (Array.isArray(report) && report.length) {
      const serieNames = report.map(r => '`' + r.serie + '`').join(' > ');
      let texto = 'tᴇrmιᴛᴇ ʟɴ sᴇrιᴇs ' + serieNames + ' ᴘorrᴇᴘtɴmᴇᴛtᴇ.\nRᴇsᴠʟtɴdos:\n\n';

      for (const r of report) {
        texto += '`' + r.serie + '` ρjs ᴘrᴇɴdos » `' + r.creados + '` fɴʟʟos `' + r.fallos + '`\n';
      }

      texto += '\n> ρᴠᴇdᴇs vᴇr ʟos fɴʟʟos ᴘoᴛ /ᴇrror. `ɴᴠᴛ ᴛo dιsρoᴛιbʟᴇ`.';

      try {
        await sock.sendMessage(st.gid, {
          text: '@' + String(st.owner).split('@')[0] + ' ' + texto,
          mentions: [st.owner]
        });
      } catch (e) {}
    }
  } catch (error) {
    if (error?.message === 'cancelado') {
      clearTimeout(barraTimer);
      return;
    }
    console.error('[MIO] ciclo interrumpido:', error?.stack || error);
    if (st) {
      st.active = false;
      if (st.pending) st.pending.resolve(null);
      const detail = String(error?.message || error).split('\n')[0];
      try {
        await sock.sendMessage(st.gid, { text: 'Mio Haimiya se detuvo por un error: ' + detail });
      } catch (sendError) {}
      console.log('[MIO] ciclo detenido (DM off):', detail);
    }
  } finally {
    clearTimeout(barraTimer);
    if (st && st.barraMsg && st.barraMsg.key) {
      try {
        await sock.sendMessage(st.gid, { delete: st.barraMsg.key });
      } catch (e) {}
    }
  }
}
/* ============================================================
 * GUARDS_SYSTEM_V1_MARKER
 * /bodyguard - /guards - /robwaifu
 * ============================================================ */

const GUARD_PRICE = 10000000;
const GUARD_MAX_DEFAULT = 5;
const GUARD_MAX_XPREMIUM = 10;
const ROBWAIFU_COOLDOWN_MS = 60 * 60 * 1000;

function formatGemsCompact(value) {
  const v = Number(value) || 0;
  if (v >= 1e9) return (v / 1e9).toLocaleString('en-US', { maximumFractionDigits: 3 }) + ' M';
  if (v >= 1e6) return (v / 1e6).toLocaleString('en-US', { maximumFractionDigits: 3 }) + ' M';
  if (v >= 1e3) return (v / 1e3).toLocaleString('en-US', { maximumFractionDigits: 3 }) + ' K';
  return v.toLocaleString('en-US');
}

function ensureGuardData(user) {
  if (!user || typeof user !== 'object') return;
  if (typeof user.guards !== 'number') user.guards = 0;

  if (typeof user.guardsStock !== 'number') {
    if (user.guards > 5) {
      user.guardsStock = user.guards - 5;
      user.guards = 5;
    } else {
      user.guardsStock = 0;
    }
  }

  if (user.guards > 5) {
    user.guardsStock = (Number(user.guardsStock) || 0) + (user.guards - 5);
    user.guards = 5;
  }

  if (!user.guardStats || typeof user.guardStats !== 'object') {
    user.guardStats = { stolen: 0, protected: 0, robbed: 0, failed: 0 };
  }
  if (typeof user.guardStats.stolen !== 'number') user.guardStats.stolen = 0;
  if (typeof user.guardStats.protected !== 'number') user.guardStats.protected = 0;
  if (typeof user.guardStats.robbed !== 'number') user.guardStats.robbed = 0;
  if (typeof user.guardStats.failed !== 'number') user.guardStats.failed = 0;
  if (typeof user.lastRobWaifu !== 'number') user.lastRobWaifu = 0;
}

async function handleBodyguard(sock, msg, sender) {
  const jid = msg.key.remoteJid;
  const user = initUser(sender, msg.pushName);
  if (!user) return;
  ensureGuardData(user);

  const gems = Number(user.gems) || 0;
  if (gems < GUARD_PRICE) {
    return sock.sendMessage(jid, {
      text:
        'No tienes suficientes gemas, el precio es de `10 millones de gemas`.\n' +
        '> Gemas actuales \u00BB `' + formatGemsCompact(gems) + '`'
    }, { quoted: msg });
  }

  user.gems = gems - GUARD_PRICE;
  user.guardsStock = (Number(user.guardsStock) || 0) + 1;
  saveDB();

  return sock.sendMessage(jid, {
    text:
      '\u2605 Compraste `1` guardi\u00E1n para tu `harem`.\n' +
      '> Activos \u00BB `' + (Number(user.guards) || 0) + '/5`\n' +
      '> En reserva \u00BB `' + user.guardsStock + '`\n\n' +
      '> Usa `/restguards` cuando se te acaben TODOS los activos para desplegar 5 mas.'
  }, { quoted: msg });
}

async function handleRestguards(sock, msg, sender) {
  const jid = msg.key.remoteJid;
  const user = initUser(sender, msg.pushName);
  if (!user) return;
  ensureGuardData(user);

  const active = Number(user.guards) || 0;
  const stock = Number(user.guardsStock) || 0;

  if (active > 0) {
    return sock.sendMessage(jid, {
      text:
        '\u25C7 A\u00FAn tienes `' + active + '` guardi\u00E1n(es) activo(s).\n' +
        '> Solo puedes usar `/restguards` cuando se te acaben TODOS los activos.'
    }, { quoted: msg });
  }

  if (stock <= 0) {
    return sock.sendMessage(jid, {
      text:
        '\u25C7 No tienes guardianes en reserva.\n' +
        '> Compra m\u00E1s con `/bodyguard`.'
    }, { quoted: msg });
  }

  const toActivate = Math.min(5, stock);
  user.guards = toActivate;
  user.guardsStock = stock - toActivate;
  saveDB();

  return sock.sendMessage(jid, {
    text:
      '\u2605 Desplegaste `' + toActivate + '` guardi\u00E1n(es).\n' +
      '> Activos \u00BB `' + user.guards + '/5`\n' +
      '> En reserva \u00BB `' + user.guardsStock + '`'
  }, { quoted: msg });
}

async function handleGuards(sock, msg, sender, mentioned, quotedJid) {
  const jid = msg.key.remoteJid;

  let target = sender;
  if (mentioned && mentioned.length) target = mentioned[0];
  else if (quotedJid) target = quotedJid;

  const selfUser = initUser(sender, msg.pushName);
  if (selfUser) ensureGuardData(selfUser);

  const user = db.users?.[target];
  if (user) ensureGuardData(user);

  const guards = Number(user?.guards) || 0;
  const stats = user?.guardStats || { stolen: 0, protected: 0, robbed: 0, failed: 0 };
  const name = user?.name || String(target).split('@')[0] || 'usuario';

  const stock = Number(user?.guardsStock) || 0;
  const text =
    '`Guardianes ' + name + '`\n' +
    'Activos \u00BB `' + guards + '/5`\n' +
    'En reserva \u00BB `' + stock + '`\n' +
    'Te han robado \u00BB `' + (stats.stolen || 0) + '`\n' +
    'Te han protegido \u00BB `' + (stats.protected || 0) + '`\n' +
    'Has robado \u00BB `' + (stats.robbed || 0) + '`';

  return sock.sendMessage(jid, { text }, { quoted: msg });
}

async function handleRobWaifu(sock, msg, args, groupId, sender) {
  const jid = msg.key.remoteJid;
  const user = initUser(sender, msg.pushName);
  if (!user) return;
  ensureGuardData(user);

  const nameQuery = args.join(' ').trim();

  if (!nameQuery) {
    return sock.sendMessage(jid, {
      text:
        '\u2730 Para robar una waifu haz `/robwaifu name`. \u2730\n' +
        '> Ejemplo 1 \u00BB `/robwaifu Mio Haimiya`\n' +
        '> Ejemplo 2 \u00BB `/robwaifu Nazuna Nanakusa`'
    }, { quoted: msg });
  }

  if (!hasXPremium(user)) {
    return sock.sendMessage(jid, {
      text: '\uD83D\uDED2 Para poder robar a una `waifu` necesitas el pase `xpremium`.'
    }, { quoted: msg });
  }

  const now = Date.now();
  const elapsed = now - (Number(user.lastRobWaifu) || 0);
  if (elapsed < ROBWAIFU_COOLDOWN_MS) {
    const remaining = ROBWAIFU_COOLDOWN_MS - elapsed;
    const mins = Math.floor(remaining / 60000);
    const secs = Math.floor((remaining % 60000) / 1000);
    return sock.sendMessage(jid, {
      text: '\u23F3 Debes esperar `' + mins + 'm ' + secs + 's` para volver a robar.'
    }, { quoted: msg });
  }

  const group = db.groups?.[groupId];
  if (!group || !group.harems) {
    return sock.sendMessage(jid, { text: '\u25C7 No hay datos en este grupo.' }, { quoted: msg });
  }

  const normalizedQuery = nameQuery.toLowerCase().trim();
  let targetOwner = null;
  let targetChar = null;
  let targetHarem = null;

  for (const [uid, harem] of Object.entries(group.harems)) {
    if (!Array.isArray(harem)) continue;
    const found =
      harem.find(c => String(c?.name || '').toLowerCase().trim() === normalizedQuery) ||
      harem.find(c => String(c?.name || '').toLowerCase().includes(normalizedQuery));
    if (found) {
      if (uid === sender) {
        return sock.sendMessage(jid, {
          text: '\u25C7 No puedes robarte tu propio personaje.'
        }, { quoted: msg });
      }
      targetOwner = uid;
      targetChar = found;
      targetHarem = harem;
      break;
    }
  }

  if (!targetChar) {
    return sock.sendMessage(jid, {
      text: '\u25C7 No se encontr\u00F3 el personaje `' + nameQuery + '` en este grupo.'
    }, { quoted: msg });
  }

  const targetUser = db.users?.[targetOwner];
  if (targetUser) ensureGuardData(targetUser);

  const targetGuards = Number(targetUser?.guards) || 0;

  if (targetGuards > 0) {
    targetUser.guards = targetGuards - 1;
    targetUser.guardStats.protected = (targetUser.guardStats.protected || 0) + 1;
    user.guardStats.failed = (user.guardStats.failed || 0) + 1;
    user.lastRobWaifu = now;
    saveDB();

    const mention = db.users?.[targetOwner]?.name || String(targetOwner).split('@')[0];
    return sock.sendMessage(jid, {
      text:
        'El robo fallo, los guardianes de `' + mention + '` te atraparon.\n' +
        '> Intentalo en 1 hora.',
      mentions: [targetOwner]
    }, { quoted: msg });
  }

  const idx = targetHarem.indexOf(targetChar);
  if (idx >= 0) targetHarem.splice(idx, 1);

  group.harems[sender] ??= [];
  if (!group.harems[sender].some(c => c.key === targetChar.key)) {
    group.harems[sender].push(targetChar);
  }

  const char = characterKeyMap.get(targetChar.key);
  // FIX_HAREM_SYNC_V1: rechazar si claimedBy no coincide con targetOwner
  if (!char || !char.claimedBy || !char.claimedBy[groupId] || char.claimedBy[groupId].user !== targetOwner) {
    const newlyAddedIdx = group.harems[sender].indexOf(targetChar);
    if (newlyAddedIdx >= 0) group.harems[sender].splice(newlyAddedIdx, 1);
    if (!targetHarem.some(c => c.key === targetChar.key)) {
      targetHarem.push(targetChar);
    }
    return sock.sendMessage(jid, {
      text: "\u25C7 Este personaje no esta sincronizado con el owner actual. Pide a un owner que ejecute /fixharems."
    }, { quoted: msg });
  }
  char.claimedBy ??= {};
  char.claimedBy[groupId] = { user: sender, time: Date.now() };

  global.ownerIndex ??= {};
  global.ownerIndex[groupId] ??= {};
  if (global.ownerIndex[groupId][targetOwner]) {
    global.ownerIndex[groupId][targetOwner].delete(targetChar.key);
  }
  global.ownerIndex[groupId][sender] ??= new Set();
  global.ownerIndex[groupId][sender].add(targetChar.key);

  user.guardStats.robbed = (user.guardStats.robbed || 0) + 1;
  user.lastRobWaifu = now;
  if (targetUser) {
    targetUser.guardStats.stolen = (targetUser.guardStats.stolen || 0) + 1;
    if (Array.isArray(targetUser.harem)) {
      targetUser.harem = targetUser.harem.filter(k => k !== targetChar.key);
    }
  }
  user.harem ??= [];
  if (!user.harem.includes(targetChar.key)) {
    user.harem.push(targetChar.key);
  }

  saveCharacters();
  saveDB();

  return sock.sendMessage(jid, {
    text:
      '\u00A1 Le robaste a `' + (db.users?.[targetOwner]?.name || String(targetOwner).split('@')[0]) + '` la waifu `' + targetChar.name + '` exitosamente. !\n' +
      '> Cooldown 1 hora.'
  }, { quoted: msg });
}
// REPORT_SYSTEM_V1
const REPORT_COOLDOWN_MS = 2 * 60 * 1000;

function formatReportDate(date) {
  try {
    const fmt = new Intl.DateTimeFormat('en-CA', {
      timeZone: 'America/Santiago',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    });
    const parts = fmt.format(date).split('-');
    return Number(parts[2]) + '/' + Number(parts[1]) + '/' + parts[0];
  } catch {
    return date.getDate() + '/' + (date.getMonth() + 1) + '/' + date.getFullYear();
  }
}

function formatElapsed(ms) {
  ms = Math.max(0, Number(ms) || 0);
  const totalSeconds = Math.floor(ms / 1000);
  if (totalSeconds < 60) return totalSeconds + 's';
  const totalMinutes = Math.floor(totalSeconds / 60);
  if (totalMinutes < 60) return totalMinutes + 'm ' + (totalSeconds % 60) + 's';
  const totalHours = Math.floor(totalMinutes / 60);
  if (totalHours < 24) return totalHours + 'h ' + (totalMinutes % 60) + 'm';
  const totalDays = Math.floor(totalHours / 24);
  return totalDays + 'd ' + (totalHours % 24) + 'h';
}

async function deliverReportToOwner(sock, payload) {
  const candidates = [];
  const seen = new Set();

  const normalizeJid = (value) => {
    if (!value) return '';
    return String(value).trim()
      .replace(/:.*(?=@)/, '')
      .replace(/@c\.us$/i, '@s.whatsapp.net');
  };

  const normalizeNumber = (value) => {
    return normalizeJid(value).split('@')[0].replace(/\D/g, '');
  };

  const addCandidate = (value, source) => {
    const raw = String(value || '').trim();
    if (!raw) return;

    const processOne = (v) => {
      const norm = normalizeJid(v);
      if (!norm) return;
      if (seen.has(norm)) return;
      const num = normalizeNumber(norm);
      if (!num || num.length < 7 || num.length > 20) return;
      seen.add(norm);
      candidates.push({ jid: norm, source });
    };

    if (raw.toLowerCase().endsWith('@lid')) {
      processOne(raw);
      try {
        const mapped = db.missionLidToJid?.[raw] ||
          (typeof missionLidToJid !== 'undefined' ? missionLidToJid.get(raw) : null);
        if (mapped) processOne(mapped);
      } catch (e) {}
      const numFromLid = raw.split('@')[0].replace(/\D/g, '');
      if (numFromLid.length >= 7 && numFromLid.length <= 15) {
        processOne(numFromLid + '@s.whatsapp.net');
      }
    } else if (/^\d+$/.test(raw)) {
      processOne(raw + '@s.whatsapp.net');
    } else {
      processOne(raw);
    }
  };

  addCandidate(db.reportOwnerRealJid, 'reportOwnerRealJid');
  addCandidate(db.primaryOwner, 'primaryOwner');
  addCandidate(OWNER_NUMBER, 'OWNER_NUMBER');
  addCandidate(OWNER_CONTACT_NUMBER, 'OWNER_CONTACT_NUMBER');

  console.log('[REPORT] Candidatos:', JSON.stringify(candidates, null, 2));

  if (!candidates.length) {
    throw new Error('No hay candidatos para enviar');
  }

  const socketsToTry = [];
  const mainSock = globalThis.MAIN_BOT_SOCK;
  if (mainSock && mainSock.user && mainSock.user.id) {
    socketsToTry.push({ sock: mainSock, label: 'MAIN_BOT_SOCK' });
  }
  if (sock && sock !== mainSock && sock.user && sock.user.id) {
    socketsToTry.push({ sock, label: 'current_sock' });
  }
  const subSockets = globalThis.SUBBOT_SOCKETS;
  if (subSockets instanceof Map) {
    for (const [phone, subSock] of subSockets.entries()) {
      if (subSock && subSock.user && subSock.user.id) {
        socketsToTry.push({ sock: subSock, label: 'subbot:' + phone });
      }
    }
  } else if (subSockets && typeof subSockets === 'object') {
    for (const [phone, subSock] of Object.entries(subSockets)) {
      if (subSock && subSock.user && subSock.user.id) {
        socketsToTry.push({ sock: subSock, label: 'subbot:' + phone });
      }
    }
  }

  console.log('[REPORT] Sockets disponibles:', socketsToTry.map(s => s.label));

  if (!socketsToTry.length) {
    throw new Error('No hay sockets disponibles');
  }

  const errors = [];

  for (const socketEntry of socketsToTry) {
    const { sock: trySock, label } = socketEntry;
    const botNum = normalizeNumber(trySock.user?.id);

    for (const cand of candidates) {
      const targetNum = normalizeNumber(cand.jid);

      if (botNum && targetNum && botNum === targetNum) {
        console.log('[REPORT] Skip auto-envio:', label, '->', cand.jid);
        continue;
      }

      try {
        const sent = await trySock.sendMessage(cand.jid, payload);
        console.log('[REPORT] OK Enviado via', label, '->', cand.jid, '(' + cand.source + ')');
        return { ok: true, jid: cand.jid, via: label, source: cand.source, sentMessage: sent };
      } catch (e) {
        const em = e?.message || String(e);
        console.error('[REPORT] FAIL', label, '->', cand.jid, ':', em);
        errors.push(label + ' -> ' + cand.jid + ' : ' + em);
      }
    }
  }

  throw new Error('No se pudo entregar. Intentos: ' + errors.join(' | '));
}

export async function handleReport(sock, msg, args, jid, sender) {
  if (typeof db.reportsEnabled !== 'boolean') db.reportsEnabled = true;
  db.reportCooldowns = db.reportCooldowns || {};

  if (!db.reportsEnabled) {
    return sock.sendMessage(jid, {
      text: 'A\u1974t\u1959\u1972\u1963m\u1971\u1952t\u1971 \u1963os r\u1971\u03C1ort\u1971s \u1971st\u1972\u1952 d\u1971s\u1972\u1974t\u03B9v\u1972dos.\n> \u0060R\u1971gr\u1971s\u1972 d\u1971s\u03C1\u1959\u1971s \u03C1\u1972r\u1972 r\u1971v\u03B9s\u1972r.\u0060'
    }, { quoted: msg });
  }

  const now = Date.now();
  const last = Number(db.reportCooldowns[sender] || 0);
  if (now - last < REPORT_COOLDOWN_MS) {
    const remaining = REPORT_COOLDOWN_MS - (now - last);
    const m = Math.floor(remaining / 60000);
    const s = Math.floor((remaining % 60000) / 1000);
    const label = m > 0 ? (m + 'm' + (s > 0 ? ' ' + s + 's' : '')) : (s + 's');
    return sock.sendMessage(jid, {
      text: 'D\u1971b\u1971s \u1971s\u03C1\u1971r\u1972r \u0060' + label + '\u0060 \u03C1\u1972r\u1972 r\u1971\u03C1ort\u1972r otr\u1972 v\u1971z.\n> M\u1959\u1974hos r\u1971\u03C1ort\u1971s \u1971\u1952v\u03B9\u1972dos d\u1971s\u03C1\u1959\u1971s d\u1971 2 m\u03B9\u1952\u1959tos s\u1971g\u1959\u03B9dos o r\u1971\u03C1ort\u1971s f\u1972\u1963sos, \u03C1\u1959\u1971d\u1971s s\u1971r b\u1972\u1952\u1971\u1972do.'
    }, { quoted: msg });
  }

  const textContent = String(args.join(' ') || '').trim();
  const contextInfo =
    (msg.message && msg.message.extendedTextMessage && msg.message.extendedTextMessage.contextInfo) ||
    (msg.message && msg.message.imageMessage && msg.message.imageMessage.contextInfo) ||
    (msg.message && msg.message.videoMessage && msg.message.videoMessage.contextInfo) ||
    {};
  const quotedMessage = contextInfo.quotedMessage;

  if (!textContent && !quotedMessage) {
    return sock.sendMessage(jid, {
      text: 'N\u1971\u1974\u1971s\u03B9t\u1972s \u1974\u03B9t\u1972r \u1959\u1952 m\u1971\u1952s\u1972j\u1971 o \u03C1o\u1952\u1971r t\u1971xto \u03C1\u1972r\u1972 r\u1971\u03C1ort\u1972r\u1963o.\n> \u0060/r\u1971\u03C1ort t\u1971xto\u0060 o \u0060/r\u1971\u03C1ort \u1974\u03B9t\u1972\u1952do \u1959\u1952 m\u1971\u1952s\u1972j\u1971\u0060. T\u1972mb\u03B9\u1971\u1952 \u03C1\u1959\u1971d\u1971s \u1971\u1952v\u03B9\u1972r \u1959\u1952\u1972 \u03B9m\u1972g\u1971\u1952 \u1974omo \u1971v\u03B9d\u1971\u1952\u1974\u03B9\u1972: \u0060\u03C1r\u03B9m\u1971ro \u1971\u1952v\u03B9\u1972 \u1963\u1972 \u03B9m\u1972g\u1971\u1952 j\u1959\u1952to \u1972\u1963 t\u1971xto \u10E7 d\u1971s\u03C1\u1959\u1971s \u1974\u03B9t\u1972\u1963o \u1974o\u1952 /r\u1971\u03C1ort\u0060.'
    }, { quoted: msg });
  }

  let reportBody = '';
  let reportImage = null;
  let hasQuote = false;

  if (quotedMessage) {
    hasQuote = true;
    const quotedText =
      quotedMessage.conversation ||
      (quotedMessage.extendedTextMessage && quotedMessage.extendedTextMessage.text) ||
      (quotedMessage.imageMessage && quotedMessage.imageMessage.caption) ||
      (quotedMessage.videoMessage && quotedMessage.videoMessage.caption) ||
      '';

    if (quotedText) reportBody = '\u0060' + String(quotedText).trim() + '\u0060';

    const quotedImageMessage =
      quotedMessage.imageMessage ||
      (quotedMessage.ephemeralMessage && quotedMessage.ephemeralMessage.message && quotedMessage.ephemeralMessage.message.imageMessage) ||
      (quotedMessage.viewOnceMessage && quotedMessage.viewOnceMessage.message && quotedMessage.viewOnceMessage.message.imageMessage) ||
      (quotedMessage.viewOnceMessageV2 && quotedMessage.viewOnceMessageV2.message && quotedMessage.viewOnceMessageV2.message.imageMessage);

    if (quotedImageMessage) {
      try {
        const quotedMsgForDownload = {
          key: {
            remoteJid: jid,
            id: contextInfo.stanzaId,
            participant: contextInfo.participant
          },
          message: quotedMessage
        };
        const buf = await downloadMediaMessage(quotedMsgForDownload, 'buffer', {});
        if (Buffer.isBuffer(buf) && buf.length > 0) reportImage = buf;
      } catch (e) {
        console.error('[REPORT] Error descargando imagen:', e && e.message ? e.message : e);
      }
    }

    if (!reportBody && !reportImage) {
      reportBody = '\u0060[Mensaje citado sin contenido de texto disponible]\u0060';
    }
  }

  if (!hasQuote && textContent) {
    reportBody = '\u0060' + textContent + '\u0060';
  }

  if (hasQuote && textContent && reportBody) {
    reportBody = reportBody + '\n\n> Comentario: \u0060' + textContent + '\u0060';
  }

  const userName =
    (db.users && db.users[sender] && db.users[sender].name) ||
    msg.pushName ||
    String(sender).split('@')[0] ||
    'Usuario';

  let groupLink = 'Chat privado';
  if (jid && jid.endsWith('@g.us')) {
    try {
      const code = await sock.groupInviteCode(jid);
      if (code) groupLink = 'https://chat.whatsapp.com/' + code;
    } catch (e) {
      try {
        const meta = await sock.groupMetadata(jid);
        if (meta && meta.subject) groupLink = meta.subject;
        else groupLink = jid;
      } catch {
        groupLink = jid;
      }
    }
  }

  const nowDate = new Date();
  const dateStr = formatReportDate(nowDate);

  const baseText =
    '\u272F R\u1971\u03C1ort\u1971 d\u1971\u1963 \u1959s\u1959\u1972r\u03B9o \u0060' + userName + '\u0060\n\n' +
    reportBody + '\n\n' +
    '\u2698 Est\u1971 r\u1971\u03C1ort\u1971 f\u1959\u1971 \u1971\u1952v\u03B9\u1972do d\u1971sd\u1971 \u0060' + groupLink + '\u0060.\n' +
    '\u2698 F\u1971\u1974h\u1972 \u0060' + dateStr + '\u0060\n' +
    '\u2698 R\u1971\u1974\u03B9b\u03B9do h\u1972\u1974\u1971 \u0060{HACE}\u0060';

  const initialText = baseText.replace('{HACE}', formatElapsed(0));

  const prevCooldown = Number(db.reportCooldowns[sender] || 0);
  db.reportCooldowns[sender] = now;

  let deliverResult;
  try {
    deliverResult = await deliverReportToOwner(
      sock,
      reportImage
        ? { image: reportImage, caption: initialText }
        : { text: initialText }
    );
  } catch (e) {
    db.reportCooldowns[sender] = prevCooldown;
    console.error('[REPORT] Error entregando:', e && e.message ? e.message : e);
    return sock.sendMessage(jid, {
      text: '\u25C7 No se pudo enviar el reporte al owner. Intenta de nuevo m\u1972s t\u1972rd\u1971.'
    }, { quoted: msg });
  }

  if (deliverResult && deliverResult.sentMessage && deliverResult.sentMessage.key && deliverResult.sentMessage.key.id) {
    db.reports ??= {};
    const reportId = deliverResult.sentMessage.key.id;
    db.reports[reportId] = {
      messageId: reportId,
      chatJid: deliverResult.jid,
      messageKey: {
        remoteJid: deliverResult.jid,
        fromMe: true,
        id: reportId
      },
      baseText: baseText,
      createdAt: now,
      lastEditedAt: now,
      status: 'pending',
      reportBy: sender,
      reportFrom: groupLink,
      hasImage: Boolean(reportImage)
    };
    console.log('[REPORT] Guardado en db.reports:', reportId);
  }

  saveDB();

  const confirmText = hasQuote
    ? '(\u02F6\u1D54 \u1D55 \u1D54\u02F6) T\u1959 r\u1971\u03C1ort\u1971 \u1974o\u1952 \u1971\u1963 m\u1971\u1952s\u1972j\u1971 \u1974\u03B9t\u1972do f\u1959\u1971 \u1971\u1952v\u03B9\u1972do \u1972\u1963 o\u1955\u1952\u1971r d\u1971\u1963 bot, gr\u1972\u1974\u03B9\u1972s \u03C1or \u1972\u10E7\u1959d\u1972r\u1952os \u1972 m\u1971jor\u1972r.'
    : '(\u02F6\u1D54 \u1D55 \u1D54\u02F6) T\u1959 r\u1971\u03C1ort\u1971 f\u1959\u1971 \u1971\u1952v\u03B9\u1972do \u1972\u1963 o\u1955\u1952\u1971r d\u1971\u1963 bot, gr\u1972\u1974\u03B9\u1972s \u03C1or \u1972\u10E7\u1959d\u1972r\u1952os \u1972 m\u1971jor\u1972r.';

  return sock.sendMessage(jid, { text: confirmText }, { quoted: msg });
}

export async function handleReportsToggle(sock, msg, args, sender) {
  if (!isMainOwnerId(sender)) {
    return sock.sendMessage(msg.key.remoteJid, {
      text: '\u25C7 Solo el owner principal puede usar este comando.'
    }, { quoted: msg });
  }

  const action = String(args[0] || '').toLowerCase().trim();

  if (action === 'on') {
    db.reportsEnabled = true;
    saveDB();
    return sock.sendMessage(msg.key.remoteJid, {
      text: '\u221A Los r\u1971\u03C1ort\u1971s f\u1959\u1971ro\u1952 \u0060A\u1974t\u03B9v\u1972dos\u0060.'
    }, { quoted: msg });
  }

  if (action === 'off') {
    db.reportsEnabled = false;
    saveDB();
    return sock.sendMessage(msg.key.remoteJid, {
      text: '\u221A Los r\u1971\u03C1ort\u1971s f\u1959\u1971ro\u1952 \u0060D\u1971s\u1972\u1974t\u03B9v\u1972dos\u0060.'
    }, { quoted: msg });
  }

  if (action === 'status') {
    return sock.sendMessage(msg.key.remoteJid, {
      text:
        '\u25C7 Estado de reportes:\n\n' +
        '\u2022 reportsEnabled: ' + String(db.reportsEnabled) + '\n' +
        '\u2022 reportOwnerRealJid: ' + String(db.reportOwnerRealJid || '(no capturado)') + '\n' +
        '\u2022 primaryOwner: ' + String(db.primaryOwner || '(null)') + '\n' +
        '\u2022 OWNER_NUMBER: ' + String(OWNER_NUMBER) + '\n' +
        '\u2022 OWNER_CONTACT_NUMBER: ' + String(OWNER_CONTACT_NUMBER) + '\n' +
        '\u2022 Reportes guardados: ' + String(Object.keys(db.reports || {}).length) + '\n\n' +
        '> Escribe al bot en privado una vez para capturar el JID correcto.\n' +
        '> O usa /reports setowner @tu_usuario'
    }, { quoted: msg });
  }

  if (action === 'setowner') {
    const ctx = msg.message?.extendedTextMessage?.contextInfo || {};
    const mentioned = Array.isArray(ctx.mentionedJid) ? ctx.mentionedJid : [];
    const quotedParticipant = ctx.participant;
    const argNumber = String(args[1] || '').trim().replace(/\D/g, '');

    let targetJid = null;
    if (mentioned[0]) targetJid = mentioned[0];
    else if (quotedParticipant) targetJid = quotedParticipant;
    else if (argNumber && argNumber.length >= 7) targetJid = argNumber + '@s.whatsapp.net';

    if (!targetJid) {
      return sock.sendMessage(msg.key.remoteJid, {
        text: '\u25C7 Uso: /reports setowner @usuario  o  /reports setowner 56956461451'
      }, { quoted: msg });
    }

    db.reportOwnerRealJid = targetJid;
    saveDB();

    return sock.sendMessage(msg.key.remoteJid, {
      text: '\u221A Owner JID actualizado: ' + targetJid
    }, { quoted: msg });
  }

  if (action === 'test') {
    try {
      const result = await deliverReportToOwner(sock, {
        text: '\u2606 Mensaje de prueba del sistema de reportes.\nSi ves esto, el sistema funciona.'
      });
      return sock.sendMessage(msg.key.remoteJid, {
        text: '\u221A Test enviado via ' + result.via + ' -> ' + result.jid
      }, { quoted: msg });
    } catch (e) {
      return sock.sendMessage(msg.key.remoteJid, {
        text: '\u2717 Error en test: ' + (e?.message || e)
      }, { quoted: msg });
    }
  }

  return sock.sendMessage(msg.key.remoteJid, {
    text:
      '\u25C7 Uso:\n' +
      '/reports on\n' +
      '/reports off\n' +
      '/reports status\n' +
      '/reports setowner @usuario\n' +
      '/reports test'
  }, { quoted: msg });
}

// ============================================================
// REPORT_MARK_FIXED / REPORT_MARK_CANCELLED
// ============================================================

function __reportIsOwner(sender) {
  if (isMainOwnerId(sender)) return true;
  const normNum = v => String(v || '').split('@')[0].replace(/\D/g, '');
  const senderNum = normNum(sender);
  if (!senderNum) return false;
  const candidates = [
    db.reportOwnerRealJid,
    OWNER_NUMBER,
    OWNER_CONTACT_NUMBER,
    db.primaryOwner
  ].filter(Boolean);
  return candidates.some(x => normNum(x) === senderNum);
}

async function __markReport(sock, msg, jid, sender, newStatus) {
  if (!__reportIsOwner(sender)) {
    return sock.sendMessage(jid, {
      text: '\u25C7 Solo el owner principal puede usar este comando.'
    }, { quoted: msg });
  }

  const ctx = msg.message?.extendedTextMessage?.contextInfo ||
    msg.message?.imageMessage?.contextInfo ||
    msg.message?.videoMessage?.contextInfo ||
    {};
  const quotedId = ctx.stanzaId;

  if (!quotedId) {
    return sock.sendMessage(jid, {
      text: '\u25C7 Debes citar (responder) al mensaje del reporte.'
    }, { quoted: msg });
  }

  db.reports ??= {};
  const report = db.reports[quotedId];

  if (!report) {
    return sock.sendMessage(jid, {
      text: '\u25C7 No encontr\u00E9 un reporte con ese ID. Aseg\u00FArate de citar el mensaje correcto.'
    }, { quoted: msg });
  }

  if (report.status !== 'pending') {
    return sock.sendMessage(jid, {
      text: '\u25C7 Ese reporte ya fue marcado como "' + report.status + '".'
    }, { quoted: msg });
  }

  report.status = newStatus;
  report.resolvedAt = Date.now();
  report.resolvedBy = sender;
  saveDB();

  const elapsed = formatElapsed(Date.now() - report.createdAt);
  const resolvedDate = formatReportDate(new Date());

  let footer = '';
  if (newStatus === 'fixed') {
    footer = '\n\n\u2713 A\u1963\u1971g\u1971r\u1972do \u2014 \u0060' + resolvedDate + '\u0060';
  } else if (newStatus === 'cancelled') {
    footer = '\n\n\u2717 A\u1952\u1959\u1963\u1972do \u2014 \u0060' + resolvedDate + '\u0060';
  }

  const finalText = String(report.baseText || '').replace('{HACE}', elapsed) + footer;

  const activeSock = globalThis.MAIN_BOT_SOCK;
  let edited = false;
  if (activeSock && activeSock.user && activeSock.user.id) {
    try {
      await activeSock.sendMessage(report.messageKey.remoteJid || report.chatJid, {
        text: finalText,
        edit: report.messageKey
      });
      edited = true;
    } catch (e) {
      console.error('[REPORT-EDIT]', e?.message || e);
    }
  }

  const confirmIcon = newStatus === 'fixed' ? '\u2713' : '\u2717';
  const confirmLabel = newStatus === 'fixed' ? 'arreglado' : 'anulado';

  return sock.sendMessage(jid, {
    text: confirmIcon + ' Reporte marcado como ' + confirmLabel + '.' + (edited ? '' : ' (No se pudo editar el mensaje original)')
  }, { quoted: msg });
}

export async function handleReportMarkFixed(sock, msg, jid, sender) {
  return __markReport(sock, msg, jid, sender, 'fixed');
}

export async function handleReportMarkCancelled(sock, msg, jid, sender) {
  return __markReport(sock, msg, jid, sender, 'cancelled');
}

// ============================================================
// REPORT_UPDATE_TIMER
// ============================================================
const REPORT_UPDATE_INTERVAL_MS = 10 * 60 * 1000;
const REPORT_MAX_PENDING_AGE_MS = 30 * 24 * 60 * 60 * 1000;

if (!global.__reportUpdateTimer) {
  global.__reportUpdateTimer = setInterval(async () => {
    try {
      const reports = db.reports || {};
      const pending = Object.entries(reports).filter(
        ([id, r]) => r && r.status === 'pending'
      );
      if (!pending.length) return;

      let activeSock = globalThis.MAIN_BOT_SOCK;
      if (!activeSock || !activeSock.user || !activeSock.user.id) {
        const subs = globalThis.SUBBOT_SOCKETS;
        if (subs instanceof Map) {
          for (const [, s] of subs.entries()) {
            if (s?.user?.id) { activeSock = s; break; }
          }
        } else if (subs && typeof subs === 'object') {
          for (const s of Object.values(subs)) {
            if (s?.user?.id) { activeSock = s; break; }
          }
        }
      }
      if (!activeSock || !activeSock.user || !activeSock.user.id) return;

      const now = Date.now();
      let updated = 0;
      let expired = 0;

      for (const [id, r] of pending) {
        if (r.hasImage) continue;
        if (now - r.createdAt > REPORT_MAX_PENDING_AGE_MS) {
          r.status = 'expired';
          expired++;
          continue;
        }
        if (!r.baseText) continue;

        const elapsed = formatElapsed(now - r.createdAt);
        const newText = String(r.baseText).replace('{HACE}', elapsed);

        try {
          await activeSock.sendMessage(r.messageKey.remoteJid || r.chatJid, {
            text: newText,
            edit: r.messageKey
          });
          r.lastEditedAt = now;
          updated++;
        } catch (e) {
          console.error('[REPORT-TIMER] error editando', id, ':', e?.message || e);
        }
      }

      if (updated > 0 || expired > 0) {
        saveDB();
        console.log('[REPORT-TIMER] actualizados:', updated, '| expirados:', expired);
      }
    } catch (e) {
      console.error('[REPORT-TIMER] error general:', e?.message || e);
    }
  }, REPORT_UPDATE_INTERVAL_MS);
  console.log('[REPORT-TIMER] iniciado (cada ' + (REPORT_UPDATE_INTERVAL_MS / 60000) + ' min)');
}

