/* ============================================================
 * GIFPASE_SYSTEM_V1
 * /gifpase  /regalopase  /activepass  /infoxp
 * ============================================================ */

function __gifpaseFancy(str) {
  const map = {
    'a': '\u1972', 'e': '\u1971', 'i': '\u03B9', 'l': '\u1963',
    'n': '\u1952', 'u': '\u1959', 'c': '\u1974', 'p': '\u03C1',
    'w': '\u1955', 'y': '\u10E7'
  };
  return String(str || '').split('').map(function (ch) {
    return map[ch] || ch;
  }).join('');
}

function __gifpaseNormalizeJid(value) {
  if (!value) return "";
  return String(value)
    .trim()
    .replace(/:.*(?=@)/, "")
    .replace(/@c\.us$/i, "@s.whatsapp.net")
    .toLowerCase();
}

function __gifpaseFindUserRecord(jidToFind) {
  const norm = __gifpaseNormalizeJid(jidToFind);
  if (db.users && db.users[norm]) return { key: norm, user: db.users[norm] };
  const mapping = db.missionLidToJid || {};
  for (const entry of Object.entries(mapping)) {
    const lid = entry[0];
    const phoneJid = entry[1];
    if (__gifpaseNormalizeJid(lid) === norm) {
      const mapped = db.users && db.users[__gifpaseNormalizeJid(phoneJid)];
      if (mapped) return { key: __gifpaseNormalizeJid(phoneJid), user: mapped };
    }
    if (__gifpaseNormalizeJid(phoneJid) === norm) {
      const mapped = db.users && db.users[__gifpaseNormalizeJid(lid)];
      if (mapped) return { key: __gifpaseNormalizeJid(lid), user: mapped };
    }
  }
  return { key: norm, user: null };
}

function __gifpaseUserHasXPremium(userRecord) {
  if (!userRecord) return false;
  try {
    if (typeof hasXPremium === "function") return Boolean(hasXPremium(userRecord));
  } catch (e) {}
  return userRecord.xpremium === true;
}

async function __gifpaseResolveTarget(sock, mentioned, quotedJid, args) {
  if (Array.isArray(mentioned) && mentioned.length) return mentioned[0];
  if (quotedJid) return quotedJid;
  const raw = Array.isArray(args) && args[0] ? String(args[0]) : "";
  const phone = raw.replace(/\D/g, "");
  if (phone.length >= 7 && phone.length <= 15) {
    try {
      const results = await sock.onWhatsApp(phone + "@s.whatsapp.net");
      const found = Array.isArray(results) ? results.find(function (x) { return x && x.exists; }) : null;
      if (found && found.lid) return found.lid;
      if (found && found.jid) return found.jid;
      return phone + "@s.whatsapp.net";
    } catch (e) {
      console.log("[GIFPASE] onWhatsApp error:", e && e.message ? e.message : e);
      return phone + "@s.whatsapp.net";
    }
  }
  return null;
}

export async function handleGifPase(sock, msg, args, jid, sender, mentioned, quotedJid) {

  const COST = 100000000;

  const target = await __gifpaseResolveTarget(sock, mentioned, quotedJid, args);

  if (!target) {
    return sock.sendMessage(jid, {
      text:
        "\u25C7 Debes mencionar, responder o escribir el n\u00FAmero de la persona a la que le regalar\u00E1s el pase `xpremium`.\n\n" +
        "> Ejemplo: /gifpase @usuario\n" +
        "> Ejemplo: /gifpase 56912345678"
    }, { quoted: msg });
  }

  const targetNorm = __gifpaseNormalizeJid(target);
  const senderNorm = __gifpaseNormalizeJid(sender);

  if (targetNorm === senderNorm) {
    return sock.sendMessage(jid, {
      text: "\u25C7 No puedes regalarte el pase a ti mismo."
    }, { quoted: msg });
  }

  const gifter = initUser(sender, msg.pushName);
  if (!gifter) {
    return sock.sendMessage(jid, {
      text: "\u274C No se pudo cargar tu cuenta."
    }, { quoted: msg });
  }

  const targetRecord = __gifpaseFindUserRecord(target);
  const targetUser = targetRecord.user;
  const rawName = (targetUser && targetUser.name)
    ? targetUser.name
    : (String(target).split("@")[0].split(":")[0] || "usuario");
  const targetName = String(rawName);
  const targetFancy = __gifpaseFancy(targetName);

  if (__gifpaseUserHasXPremium(targetUser)) {
    return sock.sendMessage(jid, {
      text:
        __gifpaseFancy("No puedes regalarle el pase") +
        " `x" + __gifpaseFancy("premium") + "` " +
        __gifpaseFancy("a") + " `" + targetFancy + "`\n" +
        "> " + __gifpaseFancy("ya tiene") + " `x" + __gifpaseFancy("premium") + "`.",
      mentions: [target]
    }, { quoted: msg });
  }

  const currentGems = Number(gifter.gems) || 0;
  if (currentGems < COST) {
    const missing = COST - currentGems;
    const missingStr = missing.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    return sock.sendMessage(jid, {
      text:
        __gifpaseFancy("No puedes regalarle el pase") +
        " `x" + __gifpaseFancy("premium") + "` " +
        __gifpaseFancy("a") + " `" + targetFancy + "`, " +
        __gifpaseFancy("te falta") + " `" + missingStr + "`.",
      mentions: [target]
    }, { quoted: msg });
  }

  db.pendingPasses = db.pendingPasses || {};
  let code = "";
  let attempts = 0;
  do {
    code = String(Math.floor(100000 + Math.random() * 900000));
    attempts++;
  } while (db.pendingPasses[code] && attempts < 50);

  if (db.pendingPasses[code]) {
    return sock.sendMessage(jid, {
      text: "\u274C No se pudo generar un c\u00F3digo \u00FAnico. Intenta de nuevo."
    }, { quoted: msg });
  }

  gifter.gems = currentGems - COST;

  db.pendingPasses[code] = {
    code: code,
    gifterJid: sender,
    gifterName: gifter.name || String(sender).split("@")[0],
    receiverJid: target,
    receiverName: targetName,
    createdAt: Date.now(),
    expiresAt: Date.now() + 30 * 24 * 60 * 60 * 1000,
    activatedAt: null,
    activatedBy: null
  };

  db.stats = db.stats || {};
  db.stats.pasesRegalados = (Number(db.stats.pasesRegalados) || 0) + 1;

  saveDB();

  await sock.sendMessage(jid, {
    text:
      "(\u02F6\u02C3\u2919\u02C2\u02F6) \u00A1 " +
      __gifpaseFancy("Le regalaste el pase") + " `x" + __gifpaseFancy("premium") + "` " +
      __gifpaseFancy("a") + " `" + targetFancy + "` ! \n" +
      "> " + __gifpaseFancy("El lo tiene que activar desde el chat privado del bot."),
    mentions: [sender, target]
  }, { quoted: msg });

  try {
    await sock.sendMessage(target, {
      text:
        "(\u02F6\u1D54 \u1D55 \u1D54\u02F6) " + __gifpaseFancy("Hola") + ", `" + targetFancy + "` " +
        __gifpaseFancy("te regalo el pase") + " `x" + __gifpaseFancy("premium") + "` " +
        __gifpaseFancy("para activarlo solo escribe aqui") + " `/activepass " + code + "`."
    });
  } catch (e) {
    console.log("[GIFPASE] No se pudo enviar DM al receptor:", e && e.message ? e.message : e);
  }
}

export async function handleActivePass(sock, msg, args, jid, sender) {

  const code = String((Array.isArray(args) && args[0]) || "").trim();

  if (!code) {
    return sock.sendMessage(jid, {
      text: "\u25C7 Uso: /activepass CODIGO\n\n> Ejemplo: /activepass 729638"
    }, { quoted: msg });
  }

  db.pendingPasses = db.pendingPasses || {};
  const pending = db.pendingPasses[code];

  if (!pending) {
    return sock.sendMessage(jid, {
      text: "\u25C7 El c\u00F3digo `" + code + "` no es v\u00E1lido o ya fue usado."
    }, { quoted: msg });
  }

  if (pending.expiresAt && Date.now() > Number(pending.expiresAt)) {
    delete db.pendingPasses[code];
    saveDB();
    return sock.sendMessage(jid, {
      text: "\u25C7 El c\u00F3digo `" + code + "` ya expir\u00F3."
    }, { quoted: msg });
  }

  if (pending.activatedAt) {
    return sock.sendMessage(jid, {
      text: "\u25C7 El c\u00F3digo `" + code + "` ya fue usado."
    }, { quoted: msg });
  }

  const user = initUser(sender, msg.pushName);
  if (!user) {
    return sock.sendMessage(jid, {
      text: "\u274C No se pudo cargar tu cuenta."
    }, { quoted: msg });
  }

  if (__gifpaseUserHasXPremium(user)) {
    return sock.sendMessage(jid, {
      text: "\u25C7 Ya tienes `xpremium` activado. El c\u00F3digo no fue consumido."
    }, { quoted: msg });
  }

  user.xpremium = true;
  user.xpremiumGiftedBy = pending.gifterJid || null;
  user.xpremiumGiftedAt = Date.now();

  // SYNC LID<->JID: tambien aplicar xpremium en el registro alterno
  // para que el pase funcione tanto en grupos (LID) como en privado (JID).
  try {
    const __apSender = String(sender || "").trim().toLowerCase();
    const __apMapping = db.missionLidToJid || {};
    for (const [__apLid, __apPhone] of Object.entries(__apMapping)) {
      const __apLidNorm = String(__apLid || "").trim().toLowerCase();
      const __apPhoneNorm = String(__apPhone || "").trim().toLowerCase();
      let __apAlt = null;
      if (__apLidNorm === __apSender) __apAlt = __apPhoneNorm;
      else if (__apPhoneNorm === __apSender) __apAlt = __apLidNorm;
      if (__apAlt && __apAlt !== __apSender) {
        const __apAltUser = initUser(__apAlt);
        if (__apAltUser && !__gifpaseUserHasXPremium(__apAltUser)) {
          __apAltUser.xpremium = true;
          __apAltUser.xpremiumGiftedBy = pending.gifterJid || null;
          __apAltUser.xpremiumGiftedAt = Date.now();
          console.log("[GIFPASE] xpremium sincronizado en registro alterno:", __apAlt);
        }
      }
    }
  } catch (__apErr) {
    console.error("[GIFPASE] Error sincronizando xpremium:", __apErr && __apErr.message || __apErr);
  }

  pending.activatedAt = Date.now();
  pending.activatedBy = sender;

  ensureXpremiumData(user);
  user.lastXpremiumChargeDay = getChileDayKey();

  saveDB();

  return sock.sendMessage(jid, {
    text:
      "\u00A1 " + __gifpaseFancy("Ahora ya tienes") + " `x" + __gifpaseFancy("premium") + "` " +
      __gifpaseFancy("activado permanentemente") + ". !\n" +
      "> " + __gifpaseFancy("Mira los beneficios de este pase con") + " `/infoxp`"
  }, { quoted: msg });
}


/* ============================================================
 * XPREMIUM_DAILY_CHARGE_V1
 * ============================================================ */

function ensureXpremiumData(user) {
  if (!user || typeof user !== 'object') return;
  if (typeof user.xpremium !== 'boolean') user.xpremium = false;
  if (typeof user.xpremiumSuspended !== 'boolean') user.xpremiumSuspended = false;
  if (typeof user.xpremiumDebt !== 'number') user.xpremiumDebt = 0;
  if (typeof user.lastXpremiumChargeDay !== 'string') user.lastXpremiumChargeDay = '';
}

export async function handleRetXPremium(sock, msg, sender) {
  const jid = msg.key.remoteJid;
  const user = initUser(sender, msg.pushName);
  if (!user) {
    return sock.sendMessage(jid, {
      text: '\u274C No se pudo cargar tu cuenta.'
    }, { quoted: msg });
  }
  ensureXpremiumData(user);
  if (user.xpremium === true) {
    return sock.sendMessage(jid, {
      text: '\u25C7 Ya tienes XPremium activo.\n> No hay nada que reactivar.'
    }, { quoted: msg });
  }
  const debt = Number(user.xpremiumDebt) || 0;
  if (!user.xpremiumSuspended && debt <= 0) {
    return sock.sendMessage(jid, {
      text: '\u25C7 No tienes deuda pendiente.\n> Compra XPremium con /xpremium.'
    }, { quoted: msg });
  }
  const diamonds = Number(user.diamonds) || 0;
  const debtToCharge = debt > 0 ? debt : 100000000;
  if (diamonds < debtToCharge) {
    return sock.sendMessage(jid, {
      text:
        '\u274C No tienes suficientes diamantes para reactivar XPremium.\n\n' +
        '> Deuda \u00BB \u0060' + debtToCharge.toLocaleString() + '\u0060\n' +
        '> Saldo \u00BB \u0060' + diamonds.toLocaleString() + '\u0060\n' +
        '> Te falta \u00BB \u0060' + (debtToCharge - diamonds).toLocaleString() + '\u0060'
    }, { quoted: msg });
  }
  user.diamonds = diamonds - debtToCharge;
  user.xpremiumDebt = 0;
  user.xpremiumSuspended = false;
  user.xpremium = true;
  user.lastXpremiumChargeDay = getChileDayKey();
  saveDB();
  return sock.sendMessage(jid, {
    text:
      '\u2713 XPremium reactivado.\n\n' +
      '> Pagaste \u0060' + debtToCharge.toLocaleString() + '\u0060 diamantes\n' +
      '> Saldo \u0060' + user.diamonds.toLocaleString() + '\u0060 diamantes'
  }, { quoted: msg });
}

export async function handleInfoXp(sock, msg, jid) {
  const text =
    "\u02DA\u208A\u2027\uA4F0\u10D0 \u208D\u1422.  \u032B.\u1422\u208E \u0ED2\uA4F1 \u2027\u208A\u02DA " +
    __gifpaseFancy("pase") + " `XPREMIUM`\n" +
    "\u2730 " + __gifpaseFancy("comandos") + " Ex" + __gifpaseFancy("clusivos") + " \u2730\n\n" +
    "\u27A3 `/" + __gifpaseFancy("song") + "` " + __gifpaseFancy("Te permite jugar y ganar gemas") + "\n" +
    "\u27A3 `x2 de suerte` " + __gifpaseFancy("tendras un x2 de suerte en") + " /" + __gifpaseFancy("rw") + ".\n" +
    "\u27A3 `" + __gifpaseFancy("rwp") + "` " + __gifpaseFancy("Te permite invocar a tu personaje favorito") + ".\n" +
    "\u27A3 `" + __gifpaseFancy("lang") + "` " + __gifpaseFancy("Te permite cambiar el idioma del bot") + ".\n" +
    "\u27A3 `" + __gifpaseFancy("robwaifu") + "` " + __gifpaseFancy("Podras robar waifus de otros") + ".\n" +
    "\u27A3 `" + __gifpaseFancy("Apostador") + "` " + __gifpaseFancy("Tienes un x2 de suerte") + ".\n" +
    "\u27A3 `" + __gifpaseFancy("luck") + "` " + __gifpaseFancy("Podras mejorar y comprar suerte para") + " /" + __gifpaseFancy("rw") + ".";

  return sock.sendMessage(jid, { text: text }, { quoted: msg });
}


/* ============================================================
 * FIX_HAREMS_V1
 * Rebuilds all harems from char.claimedBy (single source of truth).
 * Repairs duplicate claims where char.claimedBy[groupId] points to one user
 * but multiple users have the character in db.groups[gid].harems[user].
 * ============================================================ */
export async function handleFixHarems(sock, msg, jid, sender) {
  if (!isMainOwnerId(sender) && !isSecondaryOwnerId(sender)) {
    return sock.sendMessage(jid, {
      text: "\u25C7 Solo los owners pueden usar /fixharems."
    }, { quoted: msg });
  }

  const stats = {
    groupsCleared: 0,
    usersCleared: 0,
    charsRebuilt: 0,
    orphansRemoved: 0,
    groupsCreated: 0,
    usersUpdated: 0,
    dupsPrevented: 0
  };

  // STEP 1: Clear all harems
  for (const gid of Object.keys(db.groups || {})) {
    if (db.groups[gid] && db.groups[gid].harems) {
      const had = Object.keys(db.groups[gid].harems).length;
      if (had > 0) stats.groupsCleared++;
      db.groups[gid].harems = {};
    }
  }

  // STEP 2: Clear all user.harem arrays
  for (const uid of Object.keys(db.users || {})) {
    const u = db.users[uid];
    if (u && Array.isArray(u.harem) && u.harem.length > 0) {
      stats.usersCleared++;
    }
    if (u) u.harem = [];
  }

  // STEP 3: Rebuild from char.claimedBy (source of truth)
  for (const char of charactersCache) {
    if (!char || !char.claimedBy || typeof char.claimedBy !== 'object') continue;

    for (const [gid, claim] of Object.entries(char.claimedBy)) {
      if (!claim || !claim.user) {
        stats.orphansRemoved++;
        delete char.claimedBy[gid];
        continue;
      }

      if (!db.groups[gid]) {
        stats.orphansRemoved++;
        delete char.claimedBy[gid];
        continue;
      }

      db.groups[gid].harems ??= {};
      const existedBefore = Boolean(db.groups[gid].harems[claim.user]);
      db.groups[gid].harems[claim.user] ??= [];
      if (!existedBefore) stats.groupsCreated++;

      if (!db.groups[gid].harems[claim.user].some(c => c.key === char.key)) {
        db.groups[gid].harems[claim.user].push({
          id: char.id,
          key: char.key,
          name: char.name,
          anime: char.anime,
          gender: char.gender,
          value: char.value,
          rarity: char.rarity,
          image: char.image || null,
          claimed: false,
          claimedBy: null,
          timestamp: claim.time || Date.now(),
          invoker: claim.user
        });
        stats.charsRebuilt++;
      } else {
        stats.dupsPrevented++;
      }

      const u = initUser(claim.user);
      if (u) {
        u.harem ??= [];
        if (!u.harem.includes(char.key)) {
          u.harem.push(char.key);
          stats.usersUpdated++;
        }
      }
    }
  }

  saveCharacters();
  saveDB();

  // Rebuild ownerIndex
  try { buildOwnerIndex(); } catch (e) { console.error('[FIXHAREMS] ownerIndex:', e?.message || e); }

  const lines = [
    "\u2713 HAREMS REPARADOS",
    "",
    "\u25A1 Grupos limpiados \u00BB " + stats.groupsCleared,
    "\u25A1 Usuarios limpiados \u00BB " + stats.usersCleared,
    "\u25C7 Personajes re-asignados \u00BB " + stats.charsRebuilt,
    "\u25C7 Claims huerfanos eliminados \u00BB " + stats.orphansRemoved,
    "\u25C7 Usuarios actualizados \u00BB " + stats.usersUpdated,
    "\u25C7 Duplicados prevenidos \u00BB " + stats.dupsPrevented,
    "",
    "> Ahora todos los harems coinciden con char.claimedBy."
  ];

  console.log("[FIXHAREMS]", JSON.stringify(stats));

  return sock.sendMessage(jid, {
    text: lines.join("\n")
  }, { quoted: msg });
}


/* ============================================================
 * IMPOSTOR_SYSTEM_V1
 * Mini-juego: 1 impostor entre 2-5 civiles
 * ============================================================ */

const IMPOSTOR_MIN_PLAYERS = 2;
const IMPOSTOR_MAX_PLAYERS = 5;
const IMPOSTOR_TURN_MS = 60 * 1000;
const IMPOSTOR_GAME_MS = 10 * 60 * 1000;
const IMPOSTOR_VOTE_MS = 2 * 60 * 1000;
const IMPOSTOR_REWARD_CIVIL = 100000000;
const IMPOSTOR_REWARD_IMPOSTOR = 500000000;
const IMPOSTOR_STREAK_REWARD = 1;

// IMPOSTOR_SYSTEM_V2_MARKER

function __poxInit() {
  db.impostorWords ??= [];
  db.impostorGames ??= {};
  db.poxStreaks ??= {};
}

function __poxGenerateId() {
  return 'pox_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
}

function __poxClearTurnTimer(game) {
  if (!game || !game.timers) return;
  if (game.timers.turn) {
    try { clearTimeout(game.timers.turn); } catch {}
    game.timers.turn = null;
  }
}

function __poxClearTimers(game) {
  if (!game || !game.timers) return;
  for (const k of Object.keys(game.timers)) {
    try { clearTimeout(game.timers[k]); } catch {}
    try { clearInterval(game.timers[k]); } catch {}
    game.timers[k] = null;
  }
}

function __poxCleanupStale() {
  __poxInit();
  const now = Date.now();
  for (const gid of Object.keys(db.impostorGames)) {
    const g = db.impostorGames[gid];
    if (!g) { delete db.impostorGames[gid]; continue; }
    if (g.expiresAt && now > g.expiresAt + 5 * 60 * 1000) {
      __poxClearTimers(g);
      delete db.impostorGames[gid];
      console.log('[IMPOSTOR] Juego expirado limpiado:', gid);
    }
  }
}

function __poxGetName(jid) {
  return db.users?.[jid]?.name || String(jid).split('@')[0] || 'usuario';
}

function __poxGetPhone(jid) {
  return String(jid).split('@')[0];
}

function __poxGetStreak(jid) {
  return Number(db.poxStreaks?.[jid] || 0);
}

function __poxSetStreak(jid, val) {
  db.poxStreaks ??= {};
  db.poxStreaks[jid] = Math.max(0, Number(val) || 0);
}

async function __poxSendSecret(sock, playerJid, game, isImpostor) {
  try {
    const header = isImpostor
      ? '\uD83D\uDD75\uFE0F *ERES EL IMPOSTOR*'
      : '\uD83D\uDC64 *ERES CIVIL*';
    const body = isImpostor
      ? 'Tu PISTA es:\n*' + game.hint + '*\n\n> No conoces la palabra. Escucha a los demas y describe algo coherente para no ser descubierto.'
      : 'Tu PALABRA es:\n*' + game.word + '*\n\n> Describela SIN decirla. Ejemplo: si es "zapato", di "algo para los pies".';
    const footer = '\n\n_Juego: ' + game.id + '_\n> No compartas este mensaje.';
    await sock.sendMessage(playerJid, { text: header + '\n\n' + body + footer });
    return true;
  } catch (e) {
    console.log('[IMPOSTOR] DM fail:', playerJid, e?.message || e);
    return false;
  }
}

async function __poxAnnounceTurn(sock, game) {
  const player = game.turnOrder[game.currentTurnIdx];
  const playerName = __poxGetName(player);
  const playerPhone = __poxGetPhone(player);
  const gid = game.groupId;

  __poxClearTurnTimer(game);

  try {
    await sock.sendMessage(gid, {
      text: '> T\u1959r\u1952o d\u1971 \u0060' + playerName + '\u0060\n@' + playerPhone + ' d\u03B9s\u1974r\u03B9b\u1971 \u1963\u1972 \u03C1\u1972\u1963\u1972br\u1972 \u1974o\u1952 \u0060/r\u03C1\u0060',
      mentions: [player]
    });
  } catch (e) { console.log('[IMPOSTOR] error anuncio turno:', e?.message || e); }

  game.timers.turn = setTimeout(async () => {
    await __poxAdvanceTurn(sock, game);
  }, IMPOSTOR_TURN_MS);
  saveDB();
}

async function __poxAdvanceTurn(sock, game) {
  if (!game || game.phase !== 'playing') return;
  game.currentTurnIdx++;
  if (game.currentTurnIdx >= game.turnOrder.length) {
    await __poxStartVoting(sock, game);
    return;
  }
  saveDB();
  await __poxAnnounceTurn(sock, game);
}

async function __poxStartVoting(sock, game) {
  if (!game || game.phase !== 'playing') return;
  __poxClearTimers(game);
  game.phase = 'voting';
  game.voteStartedAt = Date.now();
  game.votes = {};
  saveDB();

  const playersList = game.players.map(p => '@' + __poxGetPhone(p)).join(', ');
  try {
    await sock.sendMessage(game.groupId, {
      text: '\uD83D\uDDD3\uFE0F *VOTACION ABIERTA* (' + Math.round(IMPOSTOR_VOTE_MS / 60000) + ' min)\n\nJugadores: ' + playersList + '\n\nUsa `/voto @usuario` para votar quien es el impostor.',
      mentions: game.players
    });
  } catch (e) { console.log('[IMPOSTOR] error anuncio votacion:', e?.message || e); }

  game.timers.vote = setTimeout(async () => {
    await __poxFinishGame(sock, game);
  }, IMPOSTOR_VOTE_MS);
  saveDB();
}

async function __poxFinishGame(sock, game) {
  if (!game) return;
  __poxClearTimers(game);
  game.phase = 'finished';
  game.finishedAt = Date.now();

  const counts = {};
  for (const p of game.players) counts[p] = 0;
  for (const [voter, target] of Object.entries(game.votes || {})) {
    if (counts[target] !== undefined) counts[target]++;
  }

  let maxVotes = 0;
  let topPlayers = [];
  for (const [p, c] of Object.entries(counts)) {
    if (c > maxVotes) { maxVotes = c; topPlayers = [p]; }
    else if (c === maxVotes) topPlayers.push(p);
  }

  const votersCount = Object.keys(game.votes || {}).length;
  const impostorWon = votersCount === 0 || topPlayers.length !== 1 || topPlayers[0] !== game.impostor;

  const impostorPhone = __poxGetPhone(game.impostor);
  const impostorName = __poxGetName(game.impostor);

  let finalText;

  if (impostorWon) {
    const impUser = db.users?.[game.impostor];
    if (impUser) {
      impUser.gems = (Number(impUser.gems) || 0) + IMPOSTOR_REWARD_IMPOSTOR;
    }
    const oldStreak = __poxGetStreak(game.impostor);
    __poxSetStreak(game.impostor, oldStreak + IMPOSTOR_STREAK_REWARD);
    const newStreak = __poxGetStreak(game.impostor);
    const rewardM = Math.round(IMPOSTOR_REWARD_IMPOSTOR / 1000000);

    finalText =
      '\u00A1 E\u1963 \u03B9m\u03C1ostor \u1971r\u1972 @' + impostorPhone + ' !\n' +
      'G\u1972\u1952\u1972\u1952 ' + rewardM + ' M d\u1971 g\u1971m\u1972s \u10E7 \u1963os \u1974\u03B9v\u03B9\u1963\u1971s \u03C1\u03B9\u1971rd\u1971\u1952.\n' +
      '\u00A1 \u0060' + impostorName + '\u0060 \u1963\u1963\u1971v\u1972 ' + newStreak + ' r\u1972\u1974h\u1972' + (newStreak !== 1 ? 's' : '') + ' \uD83D\uDD25 g\u1972\u1952\u1972\u1952do !\n' +
      '> \u1963\u1972 \u03C1\u1972\u1963\u1972br\u1972 \u1971r\u1972 \u0060' + game.word + '\u0060.';
  } else {
    for (const p of game.players) {
      if (p === game.impostor) continue;
      const u = db.users?.[p];
      if (u) u.gems = (Number(u.gems) || 0) + IMPOSTOR_REWARD_CIVIL;
    }
    const oldStreak = __poxGetStreak(game.impostor);
    __poxSetStreak(game.impostor, Math.max(0, oldStreak - IMPOSTOR_STREAK_REWARD));
    const rewardM = Math.round(IMPOSTOR_REWARD_CIVIL / 1000000);

    finalText =
      '\u00A1 E\u1963 \u03B9m\u03C1ostor \u1971r\u1972 @' + impostorPhone + ' !\n' +
      'G\u1972\u1952\u1972\u1952n ' + rewardM + ' M d\u1971 g\u1971m\u1972s \u10E7 \u1971\u1963 \u03B9m\u03C1ostor \u03C1\u03B9\u1971rd\u1971.\n' +
      '\u00A1 \u0060' + impostorName + '\u0060 P\u1971rd\u03B9o s\u1959s ' + IMPOSTOR_STREAK_REWARD + ' r\u1972\u1974h\u1972' + (IMPOSTOR_STREAK_REWARD !== 1 ? 's' : '') + ' d\u1971 \u03C1ox !\n' +
      '> \u1963\u1972 \u03C1\u1972\u1963\u1972br\u1972 \u1971r\u1972 \u0060' + game.word + '\u0060.';
  }

  const gid = game.groupId;
  const mentions = [...new Set([game.impostor, ...game.players])];

  delete db.impostorGames[gid];
  saveDB();

  try {
    const revealMsg = await sock.sendMessage(gid, { text: 'R\u1971v\u1971\u1963\u1972\u1952do....' });
    await new Promise(r => setTimeout(r, 5000));
    await sock.sendMessage(gid, {
      text: finalText,
      edit: revealMsg.key,
      mentions
    });
  } catch (e) { console.log('[IMPOSTOR] error resultado final:', e?.message || e); }
}

async function __poxBeginGame(sock, game) {
  __poxInit();
  const words = db.impostorWords || [];
  if (!words.length) {
    return sock.sendMessage(game.groupId, {
      text: '\u25C7 No hay palabras. Un owner debe agregar con /addpox palabra / pista.'
    });
  }
  const pick = words[Math.floor(Math.random() * words.length)];
  game.word = String(pick.word);
  game.hint = String(pick.hint);
  const shuffled = [...game.players].sort(() => Math.random() - 0.5);
  game.impostor = shuffled[0];
  game.turnOrder = [...game.players].sort(() => Math.random() - 0.5);
  game.currentTurnIdx = 0;
  game.phase = 'playing';
  game.descriptions = {};
  game.gameStartedAt = Date.now();
  game.expiresAt = Date.now() + IMPOSTOR_GAME_MS + IMPOSTOR_VOTE_MS + 60000;
  game.votes = {};
  game.timers = {};

  let dmFailures = [];
  for (const p of game.players) {
    const isImp = p === game.impostor;
    const ok = await __poxSendSecret(sock, p, game, isImp);
    if (!ok) dmFailures.push(p);
  }

  saveDB();

  const playerMentions = game.players.map(p => '@' + __poxGetPhone(p)).join(', ');
  const firstPlayer = game.turnOrder[0];
  const firstPhone = __poxGetPhone(firstPlayer);
  const firstName = __poxGetName(firstPlayer);

  await sock.sendMessage(game.groupId, {
    text:
      '\uD83C\uDFAD *JUEGO INICIADO*\n\n' +
      '\uD83D\uDC65 Jugadores (' + game.players.length + '): ' + playerMentions + '\n\n' +
      '\uD83D\uDCE9 Cada jugador recibio su rol por privado.\n' +
      '> Si NO te llego, avisa al host.\n\n' +
      '\u23F1\uFE0F Comiencen a describir por turnos.\n' +
      '> T\u1959r\u1952o d\u1971 \u0060' + firstName + '\u0060\n' +
      '@' + firstPhone + ' d\u03B9s\u1974r\u03B9b\u1971 \u1963\u1972 \u03C1\u1972\u1963\u1972br\u1972 \u1974o\u1952 \u0060/r\u03C1\u0060',
    mentions: [...new Set([game.impostor, ...game.players, firstPlayer])]
  });

  if (dmFailures.length) {
    await sock.sendMessage(game.groupId, {
      text: '\u26A0\uFE0F No pude enviar rol privado a: ' + dmFailures.map(p => '@' + __poxGetPhone(p)).join(', ') + '. Verifiquen privacidad / DMs.',
      mentions: dmFailures
    });
  }

  game.timers.turn = setTimeout(async () => {
    await __poxAdvanceTurn(sock, game);
  }, IMPOSTOR_TURN_MS);

  game.timers.game = setTimeout(async () => {
    if (game && game.phase === 'playing') {
      await __poxStartVoting(sock, game);
    }
  }, IMPOSTOR_GAME_MS);

  saveDB();
}

// /impostor - solo explicacion
export async function handleImpostor(sock, msg, jid, sender) {
  const text =
    '\u02DA\u208A\u2027\uA4F0\u10D0 \u208D\u1422.  .\u1422\u208E \u0ED2\uA4F1 \u2027\u208A\u02DA \u0060E\u1963 j\u1959\u1971go d\u1971\u1963 \u03B9m\u03C1ostor\u0060 \u2730\n\n' +
    '> \u1974\u1972d\u1972 \u1974\u03B9v\u03B9\u1963 r\u1971\u1974\u03B9b\u1971 \u1959\u1952\u1972 \u03C1\u1972\u1963\u1972br\u1972, todos \u1963os \u1974\u03B9v\u03B9\u1963\u1971s t\u03B9\u1971n\u1971n \u1963\u1972 m\u03B9sm\u1972 \u03C1\u1972\u1963\u1972br\u1972 m\u1971nos \u1971\u1963 \u03B9m\u03C1ostor, \u1971\u1963 \u03B9m\u03C1ostor so\u1963o t\u03B9\u1971n\u1971 \u1959\u1952\u1972 \u03C1\u03B9st\u1972 d\u1971 \u1971d\u1972 \u03C1\u1972\u1963\u1972br\u1972, t\u03B9\u1971n\u1971 q\u1959\u1971 d\u1971s\u1974r\u03B9b\u03B9r \u1971s\u1972 \u03C1\u1972\u1963\u1972br\u1972, s\u03B9 \u1971s \u0060z\u1972\u03C1\u1972to\u0060 d\u1971b\u1971s d\u1971\u1974\u03B9r q\u1959\u1971 \u1971s \u1972\u1963go \u03C1\u1972r\u1972 \u1963o \u03C1\u03B9\u1971s. s\u03B9 d\u03B9\u1974\u1971s z\u1972\u03C1\u1972to \u1971\u1963 \u03B9m\u03C1ostor s\u1972br\u1972 q\u1959\u1971 \u1963\u1972 \u03C1\u1972\u1963\u1972br\u1972 s\u1971\u1974r\u1971t\u1972 \u1971s z\u1972\u03C1\u1972to \u10E7 \u03C1\u1971rd\u1971r\u1972n \u1963\u1963\u1971v\u1972ndos\u1971 500M d\u1971 g\u1972m\u1972s \u10E7 \u1963os \u1974\u03B9v\u03B9\u1963\u1971s n\u1972d\u1972, \u1971\u1963 j\u1959\u1971go d\u1959r\u1972 10 m\u03B9n\u1959tos \u10E7 \u1974\u1972d\u1972 t\u1959rno \u1971s d\u1971 1 m\u03B9n\u1959to \u03C1or j\u1959g\u1972dor, s\u03B9 \u1963os \u1974\u03B9v\u03B9\u1963\u1971s g\u1972n\u1972n, \u1974\u1972d\u1972 \u1959no s\u1971 \u1963\u1963\u1971v\u1972 100M d\u1971 g\u1971m\u1972s.\n\n' +
    '> P\u1972r\u1972 \u1974r\u1971\u1972r \u1959n\u1972 \u03C1\u1972rt\u03B9d\u1972 \u1959s\u1972 \u0060/\u1974r\u1971\u1972t\u1971 \u03B9m\u03C1ostor\u0060';

  return sock.sendMessage(jid, { text }, { quoted: msg });
}

// /create impostor
export async function handleCreateImpostor(sock, msg, jid, sender) {
  __poxInit();
  if (!jid.endsWith('@g.us')) {
    return sock.sendMessage(jid, { text: '\u25C7 Solo funciona en grupos.' }, { quoted: msg });
  }
  if (db.impostorGames[jid]) {
    const g = db.impostorGames[jid];
    if (g.phase === 'lobby') {
      return sock.sendMessage(jid, { text: '\u25C7 Ya hay un lobby abierto. Usa /unir para unirte.' }, { quoted: msg });
    }
    return sock.sendMessage(jid, { text: '\u25C7 Ya hay un juego en curso.' }, { quoted: msg });
  }
  if (!db.impostorWords.length) {
    return sock.sendMessage(jid, { text: '\u25C7 No hay palabras. Un owner debe agregar con /addpox.' }, { quoted: msg });
  }
  const game = {
    id: __poxGenerateId(),
    groupId: jid,
    host: sender,
    players: [sender],
    phase: 'lobby',
    createdAt: Date.now(),
    timers: {}
  };
  db.impostorGames[jid] = game;
  saveDB();

  game.timers.lobby = setTimeout(async () => {
    const g = db.impostorGames?.[jid];
    if (g && g.phase === 'lobby') {
      try {
        await sock.sendMessage(jid, { text: '\u23F0 El lobby expir\u00F3. Usa /create impostor para crear uno nuevo.' });
      } catch {}
      __poxClearTimers(g);
      delete db.impostorGames[jid];
      saveDB();
    }
  }, 5 * 60 * 1000);

  await sock.sendMessage(jid, {
    text:
      '\uD83C\uDFAD *LOBBY IMPOSTOR ABIERTO*\n\n' +
      'Host: @' + __poxGetPhone(sender) + '\n' +
      'Jugadores: 1/' + IMPOSTOR_MAX_PLAYERS + '\n\n' +
      '> /unir \u2014 unirse (min ' + IMPOSTOR_MIN_PLAYERS + ', max ' + IMPOSTOR_MAX_PLAYERS + ')\n' +
      '> /startimp \u2014 empezar (solo host)\n' +
      '> /cancelimp \u2014 cancelar\n\n' +
      '\u23F1\uFE0F Expira en 5 min.',
    mentions: [sender]
  }, { quoted: msg });
}

// /rp
export async function handleRp(sock, msg, jid, sender, text) {
  __poxInit();
  const game = db.impostorGames?.[jid];
  if (!game || game.phase !== 'playing') {
    return sock.sendMessage(jid, { text: '\u25C7 No hay juego activo en fase de descripci\u00F3n.' }, { quoted: msg });
  }
  if (!game.players.includes(sender)) {
    return sock.sendMessage(jid, { text: '\u25C7 No est\u00E1s en el juego.' }, { quoted: msg });
  }

  const currentPlayer = game.turnOrder[game.currentTurnIdx];

  if (currentPlayer !== sender) {
    const currentName = __poxGetName(currentPlayer);
    return sock.sendMessage(jid, {
      text: 'Y\u1972 r\u1971s\u03C1o\u1952d\u03B9st\u1971, \u1971\u1963 t\u1959r\u1952o \u1971s d\u1971 \u0060' + currentName + '\u0060.',
      mentions: [currentPlayer]
    }, { quoted: msg });
  }

  if (!text) {
    return sock.sendMessage(jid, { text: 'Uso: /rp <tu descripci\u00F3n>' }, { quoted: msg });
  }
  if (text.length > 250) {
    return sock.sendMessage(jid, { text: '\u25C7 M\u00E1ximo 250 caracteres.' }, { quoted: msg });
  }

  game.descriptions ??= {};
  if (game.descriptions[sender]) {
    return sock.sendMessage(jid, { text: '\u25C7 Ya respondiste en este juego.' }, { quoted: msg });
  }
  // RP_NO_REPEAT_WORDS_V1
  const __rpNorm = s => String(s || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, '')
    .replace(/\s+/g, ' ')
    .trim();

  const __rpTextNorm = __rpNorm(text);
  if (!__rpTextNorm) {
    return sock.sendMessage(jid, {
      text: '\u25C7 Tu descripci\u00F3n no contiene palabras validas.'
    }, { quoted: msg });
  }

  for (const [__rpOtherPid, __rpOtherText] of Object.entries(game.descriptions)) {
    if (__rpOtherPid === sender) continue;
    if (__rpNorm(__rpOtherText) === __rpTextNorm) {
      const __rpOtherName = __poxGetName(__rpOtherPid);
      return sock.sendMessage(jid, {
        text: '\u25C7 Esa palabra ya fue usada por *' + __rpOtherName + '*.\n> Di otra cosa distinta, no puedes repetir.',
        mentions: [__rpOtherPid]
      }, { quoted: msg });
    }
  }

  game.descriptions[sender] = text;

  game.currentTurnIdx++;
  if (game.currentTurnIdx >= game.turnOrder.length) {
    saveDB();
    await __poxStartVoting(sock, game);
    return;
  }

  const nextPlayer = game.turnOrder[game.currentTurnIdx];
  const nextName = __poxGetName(nextPlayer);
  const nextPhone = __poxGetPhone(nextPlayer);
  const senderName = __poxGetName(sender);

  __poxClearTurnTimer(game);
  saveDB();

  await sock.sendMessage(jid, {
    text: '\u0060' + senderName + '\u0060 R\u1971s\u03C1o\u1952d\u03B9o.\n@' + nextPhone + ' d\u03B9s\u1974r\u03B9b\u1971 \u1963\u1972 \u03C1\u1972\u1963\u1972br\u1972.\n> T\u1959r\u1952o d\u1971 \u0060' + nextName + '\u0060 r\u1971s\u03C1o\u1952d\u1971 \u1974o\u1952 \u0060/r\u03C1\u0060',
    mentions: [nextPlayer]
  });

  game.timers.turn = setTimeout(async () => {
    await __poxAdvanceTurn(sock, game);
  }, IMPOSTOR_TURN_MS);
  saveDB();
}

export async function handleAddPox(sock, msg, args, sender) {
  const jid = msg.key.remoteJid;
  if (!isMainOwnerId(sender) && !isSecondaryOwnerId(sender)) {
    return sock.sendMessage(jid, { text: '\u25C7 Solo owners pueden usar /addpox.' }, { quoted: msg });
  }
  const raw = args.join(' ').trim();
  if (!raw) {
    return sock.sendMessage(jid, { text: '\u25C7 Uso: /addpox palabra / pista' }, { quoted: msg });
  }
  const parts = raw.split('/').map(x => x.trim()).filter(Boolean);
  if (parts.length < 2) {
    return sock.sendMessage(jid, { text: '\u25C7 Uso: /addpox palabra / pista' }, { quoted: msg });
  }
  const word = parts[0];
  const hint = parts.slice(1).join(' / ');
  __poxInit();
  if (db.impostorWords.some(w => String(w.word).toLowerCase() === word.toLowerCase())) {
    return sock.sendMessage(jid, { text: '\u25C7 Ya existe la palabra "' + word + '".' }, { quoted: msg });
  }
  db.impostorWords.push({ word, hint });
  saveDB();
  return sock.sendMessage(jid, {
    text: '\u2713 Agregada\n\n\u25C7 Palabra \u00BB *' + word + '*\n\u25C7 Pista \u00BB *' + hint + '*\n\n> Total: ' + db.impostorWords.length
  }, { quoted: msg });
}

export async function handleDelPox(sock, msg, args, sender) {
  const jid = msg.key.remoteJid;
  if (!isMainOwnerId(sender) && !isSecondaryOwnerId(sender)) {
    return sock.sendMessage(jid, { text: '\u25C7 Solo owners pueden usar /delpox.' }, { quoted: msg });
  }
  const word = args.join(' ').trim().toLowerCase();
  if (!word) {
    return sock.sendMessage(jid, { text: '\u25C7 Uso: /delpox palabra' }, { quoted: msg });
  }
  __poxInit();
  const before = db.impostorWords.length;
  db.impostorWords = db.impostorWords.filter(w => String(w.word).toLowerCase() !== word);
  if (db.impostorWords.length === before) {
    return sock.sendMessage(jid, { text: '\u25C7 No existe "' + word + '".' }, { quoted: msg });
  }
  saveDB();
  return sock.sendMessage(jid, { text: '\u2713 Eliminada "' + word + '".' }, { quoted: msg });
}

export async function handleListPox(sock, msg, sender) {
  const jid = msg.key.remoteJid;
  if (!isMainOwnerId(sender) && !isSecondaryOwnerId(sender)) {
    return sock.sendMessage(jid, { text: '\u25C7 Solo owners pueden usar /listpox.' }, { quoted: msg });
  }
  __poxInit();
  if (!db.impostorWords.length) {
    return sock.sendMessage(jid, { text: '\u25C7 No hay palabras registradas.' }, { quoted: msg });
  }
  const lines = db.impostorWords.map((w, i) => (i+1) + '. *' + w.word + '* \u2192 _' + w.hint + '_');
  return sock.sendMessage(jid, {
    text: '\uD83C\uDFAD *PALABRAS (' + db.impostorWords.length + ')*\n\n' + lines.join('\n')
  }, { quoted: msg });
}

export async function handleJoinPox(sock, msg, jid, sender) {
  __poxInit();
  const game = db.impostorGames[jid];
  if (!game || game.phase !== 'lobby') {
    return sock.sendMessage(jid, { text: '\u25C7 No hay lobby activo. Usa /create impostor.' }, { quoted: msg });
  }
  if (game.players.includes(sender)) {
    return sock.sendMessage(jid, { text: '\u25C7 Ya est\u00E1s dentro.' }, { quoted: msg });
  }
  if (game.players.length >= IMPOSTOR_MAX_PLAYERS) {
    return sock.sendMessage(jid, { text: '\u25C7 Lobby lleno (' + IMPOSTOR_MAX_PLAYERS + ' max).' }, { quoted: msg });
  }
  game.players.push(sender);
  saveDB();
  const mentions = game.players;
  await sock.sendMessage(jid, {
    text: '\u2713 @' + __poxGetPhone(sender) + ' se uni\u00F3.\n\n\uD83D\uDC65 Jugadores (' + game.players.length + '/' + IMPOSTOR_MAX_PLAYERS + '):\n' + game.players.map(p => '@' + __poxGetPhone(p)).join(', '),
    mentions
  }, { quoted: msg });
  if (game.players.length === IMPOSTOR_MAX_PLAYERS) {
    game.phase = 'starting';
    __poxClearTimers(game);
    await __poxBeginGame(sock, game);
  }
}

export async function handleStartPox(sock, msg, jid, sender) {
  __poxInit();
  const game = db.impostorGames[jid];
  if (!game || game.phase !== 'lobby') {
    return sock.sendMessage(jid, { text: '\u25C7 No hay lobby activo.' }, { quoted: msg });
  }
  if (game.host !== sender) {
    return sock.sendMessage(jid, { text: '\u25C7 Solo el host puede iniciar.' }, { quoted: msg });
  }
  if (game.players.length < IMPOSTOR_MIN_PLAYERS) {
    return sock.sendMessage(jid, { text: '\u25C7 Necesitas al menos ' + IMPOSTOR_MIN_PLAYERS + ' jugadores.' }, { quoted: msg });
  }
  __poxClearTimers(game);
  game.phase = 'starting';
  await __poxBeginGame(sock, game);
}

export async function handleCancelPox(sock, msg, jid, sender) {
  __poxInit();
  const game = db.impostorGames[jid];
  if (!game) {
    return sock.sendMessage(jid, { text: '\u25C7 No hay juego activo.' }, { quoted: msg });
  }
  if (game.host !== sender && !isMainOwnerId(sender) && !isSecondaryOwnerId(sender)) {
    return sock.sendMessage(jid, { text: '\u25C7 Solo el host o un owner puede cancelar.' }, { quoted: msg });
  }
  __poxClearTimers(game);
  delete db.impostorGames[jid];
  saveDB();
  await sock.sendMessage(jid, { text: '\u2713 Juego cancelado.' }, { quoted: msg });
}

export async function handleVotePox(sock, msg, jid, sender, mentioned, quotedJid) {
  __poxInit();
  const game = db.impostorGames[jid];
  if (!game) {
    return sock.sendMessage(jid, { text: '\u25C7 No hay juego activo.' }, { quoted: msg });
  }
  if (game.phase !== 'voting') {
    return sock.sendMessage(jid, { text: '\u25C7 La votaci\u00F3n a\u00FAn no est\u00E1 abierta.' }, { quoted: msg });
  }
  if (!game.players.includes(sender)) {
    return sock.sendMessage(jid, { text: '\u25C7 Solo jugadores pueden votar.' }, { quoted: msg });
  }
  if (game.votes[sender]) {
    return sock.sendMessage(jid, { text: '\u25C7 Ya votaste por @' + __poxGetPhone(game.votes[sender]) + '.' }, { quoted: msg });
  }
  const target = (Array.isArray(mentioned) && mentioned[0]) || quotedJid;
  if (!target) {
    return sock.sendMessage(jid, {
      text: 'Pueden mencionarlo con /voto @menci\u00F3n o respondiendo su mensaje.'
    }, { quoted: msg });
  }
  if (!game.players.includes(target)) {
    return sock.sendMessage(jid, { text: '\u25C7 Ese usuario no est\u00E1 en la partida.' }, { quoted: msg });
  }
  if (target === sender) {
    return sock.sendMessage(jid, { text: '\u25C7 No puedes votar por ti mismo.' }, { quoted: msg });
  }
  game.votes[sender] = target;
  saveDB();

  const voters = Object.keys(game.votes).length;
  const need = game.players.length;
  const remaining = need - voters;

  const targetName = __poxGetName(target);
  const missingVoters = game.players.filter(p => !game.votes[p]);
  const missingMentions = missingVoters.map(p => '@' + __poxGetPhone(p)).join(', ');

  let responseText;
  if (remaining <= 0) {
    responseText = 'vot\u1972st\u1971 \u03C1or \u0060' + targetName + '\u0060.\n> Todos han votado.';
  } else {
    responseText = 'vot\u1972st\u1971 \u03C1or \u0060' + targetName + '\u0060.\n> F\u1972\u1963t\u1972\u1952 ' + remaining + ' voto' + (remaining !== 1 ? 's' : '') + ' ' + missingMentions + '\n\nPueden mencionarlo con /voto @menci\u00F3n o respondiendo su mensaje.';
  }

  await sock.sendMessage(jid, {
    text: responseText,
    mentions: [sender, target, ...missingVoters]
  }, { quoted: msg });

  if (voters >= need) {
    await __poxFinishGame(sock, game);
  }
}

setTimeout(() => {
  try {
    __poxInit();
    for (const gid of Object.keys(db.impostorGames)) {
      const g = db.impostorGames[gid];
      if (g) {
        __poxClearTimers(g);
        console.log('[IMPOSTOR] Juego cancelado por reinicio:', gid);
      }
      delete db.impostorGames[gid];
    }
    saveDB();
  } catch (e) { console.log('[IMPOSTOR] cleanup error:', e?.message || e); }
}, 5000);

setInterval(__poxCleanupStale, 5 * 60 * 1000);


