let __impostorPlaceholder = null;
async function getImpostorPlaceholder() {
  if (__impostorPlaceholder) return __impostorPlaceholder;
  try {
    const { default: sharpLib } = await import('sharp');
    __impostorPlaceholder = await sharpLib({
      create: { width: 200, height: 200, channels: 3, background: { r: 25, g: 25, b: 35 } }
    }).jpeg({ quality: 70 }).toBuffer();
    return __impostorPlaceholder;
  } catch (e) {
    return null;
  }
}

async function sendImpostorSecretDM(sock, playerJid, content) {
  try {
    const placeholder = await getImpostorPlaceholder();
    if (placeholder) {
      try {
        await sock.sendMessage(playerJid, {
          image: placeholder,
          viewOnce: true,
          caption: content
        });
        return true;
      } catch (e) {
        console.log('[IMPOSTOR] viewOnce fallo:', e?.message);
      }
    }
    try {
      await sock.sendMessage(playerJid, { text: content, viewOnce: true });
      return true;
    } catch (e) {
      console.log('[IMPOSTOR] text viewOnce fallo:', e?.message);
    }
    await sock.sendMessage(playerJid, { text: content });
    return true;
  } catch (e) {
    console.log('[IMPOSTOR] DM fail total:', e?.message);
    return false;
  }
}

async function transitionToVoting(sock, gid) {
  const game = db.impostorGames?.[gid];
  if (!game || game.status !== 'playing') return;
  game.status = 'voting';
  game.votingStartedAt = Date.now();
  saveDB();

  const oldTimer = globalThis.__impostorTimers.get(gid);
  if (oldTimer) { clearTimeout(oldTimer); globalThis.__impostorTimers.delete(gid); }

  try {
    await sock.sendMessage(gid, {
      text:
        '⏰ ¡TIEMPO DE DESCRIPCIÓN TERMINADO!\n\n' +
        'Ahora empieza la votación.\n\n' +
        'Jugadores: ' + game.players.map(p => '@' + p.split('@')[0]).join(', ') + '\n\n' +
        'Usa /voto @usuario para votar por el impostor.\n\n' +
        'Tienen 2 minutos.',
      mentions: game.players
    });
  } catch (e) {
    console.log('[IMPOSTOR] transitionToVoting send fail:', e?.message);
  }

  const t = setTimeout(() => { void endImpostorGame(sock, gid); }, 2 * 60 * 1000);
  globalThis.__impostorTimers.set(gid, t);
}

async function endImpostorGame(sock, gid) {
  const game = db.impostorGames?.[gid];
  if (!game) return;

  const timer = globalThis.__impostorTimers.get(gid);
  if (timer) { clearTimeout(timer); globalThis.__impostorTimers.delete(gid); }

  game.status = 'ended';

  const tally = {};
  for (const target of Object.values(game.votes || {})) {
    tally[target] = (tally[target] || 0) + 1;
  }

  let maxVotes = 0;
  let topPlayers = [];
  for (const [player, count] of Object.entries(tally)) {
    if (count > maxVotes) { maxVotes = count; topPlayers = [player]; }
    else if (count === maxVotes) { topPlayers.push(player); }
  }

  const impostorWins = topPlayers.length !== 1 || topPlayers[0] !== game.impostor;

  let descriptionsText = '';
  for (const [pid, text] of Object.entries(game.descriptions || {})) {
    const name = db.users?.[pid]?.name || pid.split('@')[0];
    const tag = pid === game.impostor ? ' (IMPOSTOR)' : '';
    descriptionsText += '\u2022 ' + name + tag + ': "' + text + '"\n';
  }

  let resultText = '\uD83C\uDFAD FIN DEL JUEGO \uD83C\uDFAD\n\n';
  resultText += '\uD83D\uDCD6 Palabra: "' + game.word + '"\n';
  resultText += '\uD83D\uDCA1 Pista: "' + game.hint + '"\n';
  resultText += '\uD83C\uDFAF El impostor era: @' + game.impostor.split('@')[0] + '\n\n';

  const votesCount = Object.keys(game.votes || {}).length;
  if (votesCount === 0) {
    resultText += '\u26A0\uFE0F Nadie vot\u00F3 \u2192 el impostor gana.\n\n';
  } else if (topPlayers.length > 1) {
    resultText += '\u26A0\uFE0F Empate entre ' + topPlayers.map(p => '@' + p.split('@')[0]).join(', ') + ' \u2192 el impostor gana.\n\n';
  }

  if (impostorWins) {
    resultText += '\uD83C\uDFC6 \u00A1EL IMPOSTOR GANA! \uD83C\uDFC6\n\n';
    resultText += '+500.000.000 gemas para @' + game.impostor.split('@')[0];
    const user = db.users?.[game.impostor];
    if (user) user.gems = (Number(user.gems) || 0) + 500000000;
  } else {
    const civilians = game.players.filter(p => p !== game.impostor);
    resultText += '\uD83C\uDFC6 \u00A1LOS CIVILES GANAN! \uD83C\uDFC6\n\n';
    resultText += civilians.map(p => '+100.000.000 gemas para @' + p.split('@')[0]).join('\n');
    for (const player of civilians) {
      const user = db.users?.[player];
      if (user) user.gems = (Number(user.gems) || 0) + 100000000;
    }
  }

  if (descriptionsText) {
    resultText += '\n\n\uD83D\uDCDD Descripciones:\n' + descriptionsText;
  }

  delete db.impostorGames[gid];
  saveDB();

  try {
    await sock.sendMessage(gid, {
      text: resultText,
      mentions: game.players
    });
  } catch (e) {
    console.log('[IMPOSTOR] end send fail:', e?.message);
  }
}

if (!global.__impostorHeartbeat) {
  global.__impostorHeartbeat = setInterval(async () => {
    const now = Date.now();
    const sock = globalThis.MAIN_BOT_SOCK;
    if (!sock) return;
    for (const [gid, game] of Object.entries(db.impostorGames || {})) {
      if (!game) continue;
      if (globalThis.__impostorTimers.has(gid)) continue;
      if (game.status === 'playing' && game.startedAt && now - game.startedAt >= 10 * 60 * 1000) {
        await transitionToVoting(sock, gid);
      } else if (game.status === 'voting' && game.votingStartedAt && now - game.votingStartedAt >= 2 * 60 * 1000) {
        await endImpostorGame(sock, gid);
      }
    }
  }, 30 * 1000);
}

/* ============================================================
 * MODLVLTRANSF - HELPERS
 * ============================================================ */

async function handleModlvltransfReply(sock, msg, sender) {
  const __quotedId =
    msg.message?.extendedTextMessage?.contextInfo?.stanzaId;
  if (!__quotedId) return false;

  db.pendingTransfers ??= {};
  const __pending = db.pendingTransfers[__quotedId];
  if (!__pending) return false;

  if (__pending.sender !== sender) return true;

  const __text = (
    msg.message?.conversation ||
    msg.message?.extendedTextMessage?.text ||
    ""
  ).trim().toLowerCase();

  if (__text !== "si" && __text !== "s\u00ED" && __text !== "no") return true;

  delete db.pendingTransfers[__quotedId];

  if (__text === "no") {
    saveDB();
    await sock.sendMessage(
      msg.key.remoteJid,
      { text: "\u25C7 Transferencia cancelada." },
      { quoted: msg }
    );
    return true;
  }

  if (Date.now() - __pending.createdAt > 5 * 60 * 1000) {
    saveDB();
    await sock.sendMessage(
      msg.key.remoteJid,
      { text: "\u25C7 La solicitud de transferencia expir\u00F3." },
      { quoted: msg }
    );
    return true;
  }

  saveDB();
  await executeModlvlTransfer(sock, msg, __pending.oldId, __pending.newId);
  return true;
}

async function executeModlvlTransfer(sock, msg, oldId, newId) {
  const jid = msg.key.remoteJid;

  try {
    const ts = Date.now();
    const backupDir = "./backups";
    if (!fs.existsSync(backupDir)) fs.mkdirSync(backupDir, { recursive: true });
    if (fs.existsSync(DB_FILE)) {
      fs.copyFileSync(DB_FILE, `${backupDir}/database.pre-transfer-${ts}.json`);
    }
    if (fs.existsSync(CHARACTERS_FILE)) {
      fs.copyFileSync(CHARACTERS_FILE, `${backupDir}/characters.pre-transfer-${ts}.json`);
    }

    const stats = {
      profile: false, economy: 0, cooldowns: 0,
      haremGroups: 0, haremChars: 0, claims: 0,
      staffProfile: false, staffName: false, staffPrefix: false,
      staffStats: false, staffClaims: 0,
      banned: false, modWarns: false, reports: 0,
      reportCooldowns: false, poxStreaks: false, pendingPasses: 0,
      suggestStats: false, globalVote: false, donationsOff: 0,
      secondaryOwners: 0, reportOwner: false, primaryOwner: false, primaryBots: 0
    };

    if (db.users?.[oldId]) {
      db.users[newId] = JSON.parse(JSON.stringify(db.users[oldId]));
      delete db.users[oldId];
      stats.profile = true;
    }

    for (const gid of Object.keys(db.groups || {})) {
      const group = db.groups[gid];
      if (!group) continue;

      if (group.economy?.[oldId]) {
        group.economy[newId] = JSON.parse(JSON.stringify(group.economy[oldId]));
        delete group.economy[oldId];
        stats.economy++;
      }

      if (group.cooldowns?.[oldId]) {
        group.cooldowns[newId] = JSON.parse(JSON.stringify(group.cooldowns[oldId]));
        delete group.cooldowns[oldId];
        stats.cooldowns++;
      }

      if (Array.isArray(group.harems?.[oldId])) {
        const oldHarem = group.harems[oldId];
        stats.haremChars += oldHarem.length;
        const existing = Array.isArray(group.harems[newId]) ? group.harems[newId] : [];
        const existingKeys = new Set(
          existing.map(h => (typeof h === "string" ? h : h?.key)).filter(Boolean)
        );
        const merged = [...existing];
        for (const entry of oldHarem) {
          const key = typeof entry === "string" ? entry : entry?.key;
          if (!key || !existingKeys.has(key)) {
            merged.push(JSON.parse(JSON.stringify(entry)));
            if (key) existingKeys.add(key);
          }
        }
        group.harems[newId] = merged;
        delete group.harems[oldId];
        stats.haremGroups++;
      }

      if (Array.isArray(group.donationsOff)) {
        let changed = false;
        for (let i = 0; i < group.donationsOff.length; i++) {
          if (group.donationsOff[i] === oldId) {
            group.donationsOff[i] = newId;
            stats.donationsOff++;
            changed = true;
          }
        }
        if (changed) group.donationsOff = [...new Set(group.donationsOff)];
      }
    }

    for (const char of charactersCache) {
      if (!char?.claimedBy) continue;
      for (const gid of Object.keys(char.claimedBy)) {
        if (char.claimedBy[gid]?.user === oldId) {
          char.claimedBy[gid].user = newId;
          stats.claims++;
        }
      }
    }

    if (db.staffProfiles?.[oldId]) {
      db.staffProfiles[newId] = JSON.parse(JSON.stringify(db.staffProfiles[oldId]));
      delete db.staffProfiles[oldId];
      stats.staffProfile = true;
    }
    if (db.staffNames?.[oldId]) {
      db.staffNames[newId] = db.staffNames[oldId];
      delete db.staffNames[oldId];
      stats.staffName = true;
    }
    if (db.staffPrefixes?.[oldId]) {
      db.staffPrefixes[newId] = db.staffPrefixes[oldId];
      delete db.staffPrefixes[oldId];
      stats.staffPrefix = true;
    }
    if (db.staffStats?.[oldId]) {
      db.staffStats[newId] = JSON.parse(JSON.stringify(db.staffStats[oldId]));
      delete db.staffStats[oldId];
      stats.staffStats = true;
    }

    for (const creatorId of Object.keys(db.staffStats || {})) {
      const statData = db.staffStats[creatorId];
      if (!statData?.claimed) continue;
      for (const charId of Object.keys(statData.claimed)) {
        const list = statData.claimed[charId];
        if (!Array.isArray(list)) continue;
        let changed = false;
        for (let i = 0; i < list.length; i++) {
          if (list[i] === oldId) { list[i] = newId; stats.staffClaims++; changed = true; }
        }
        if (changed) statData.claimed[charId] = [...new Set(list)];
      }
    }

    if (db.bannedUsers?.[oldId]) {
      db.bannedUsers[newId] = db.bannedUsers[oldId];
      delete db.bannedUsers[oldId];
      stats.banned = true;
    }
    if (db.modWarns?.[oldId]) {
      db.modWarns[newId] = db.modWarns[oldId];
      delete db.modWarns[oldId];
      stats.modWarns = true;
    }
    for (const reportId of Object.keys(db.reports || {})) {
      const rep = db.reports[reportId];
      if (!rep) continue;
      if (rep.reportBy === oldId) { rep.reportBy = newId; stats.reports++; }
      if (rep.resolvedBy === oldId) rep.resolvedBy = newId;
    }
    if (db.reportCooldowns?.[oldId] !== undefined) {
      db.reportCooldowns[newId] = db.reportCooldowns[oldId];
      delete db.reportCooldowns[oldId];
      stats.reportCooldowns = true;
    }
    if (db.poxStreaks?.[oldId] !== undefined) {
      db.poxStreaks[newId] = db.poxStreaks[oldId];
      delete db.poxStreaks[oldId];
      stats.poxStreaks = true;
    }
    for (const code of Object.keys(db.pendingPasses || {})) {
      const pass = db.pendingPasses[code];
      if (!pass) continue;
      if (pass.gifterJid === oldId) { pass.gifterJid = newId; stats.pendingPasses++; }
      if (pass.receiverJid === oldId) { pass.receiverJid = newId; stats.pendingPasses++; }
    }
    if (db.suggestStats?.[oldId]) {
      db.suggestStats[newId] = db.suggestStats[oldId];
      delete db.suggestStats[oldId];
      stats.suggestStats = true;
    }
    if (db.globalCooldowns?.vote?.[oldId] !== undefined) {
      db.globalCooldowns.vote[newId] = db.globalCooldowns.vote[oldId];
      delete db.globalCooldowns.vote[oldId];
      stats.globalVote = true;
    }
    if (Array.isArray(db.secondaryOwners)) {
      let changed = false;
      for (let i = 0; i < db.secondaryOwners.length; i++) {
        if (db.secondaryOwners[i] === oldId) {
          db.secondaryOwners[i] = newId; stats.secondaryOwners++; changed = true;
        }
      }
      if (changed) db.secondaryOwners = [...new Set(db.secondaryOwners)];
    }
    if (db.reportOwnerRealJid === oldId) {
      db.reportOwnerRealJid = newId;
      stats.reportOwner = true;
    }
    if (db.primaryOwner === oldId) {
      db.primaryOwner = newId;
      stats.primaryOwner = true;
    }
    for (const gid of Object.keys(db.primaryBots || {})) {
      if (db.primaryBots[gid] === oldId) { db.primaryBots[gid] = newId; stats.primaryBots++; }
    }

    saveCharacters();
    saveDB();

    try {
      if (typeof buildOwnerIndex === "function") buildOwnerIndex();
    } catch (err) {
      console.error("[MODLVLTRANSF] buildOwnerIndex error:", err?.message || err);
    }

    console.log("[MODLVLTRANSF]", oldId, "->", newId, JSON.stringify(stats));

    const __mentions = [];
    if (newId.includes("@s.whatsapp.net")) __mentions.push(newId);
    if (oldId.includes("@s.whatsapp.net")) __mentions.push(oldId);

    await sock.sendMessage(
      jid,
      {
        text:
          `\u2705 TRANSFERENCIA COMPLETADA\n\n` +
          `\u25C7 Viejo \u00BB \`${oldId}\`\n` +
          `\u25C7 Nuevo \u00BB \`${newId}\`\n\n` +
          `\u25C6 Perfil \u00BB ${stats.profile ? "S\u00ED" : "No"}\n` +
          `\u25C6 Econom\u00EDa \u00BB ${stats.economy}\n` +
          `\u25C6 Cooldowns \u00BB ${stats.cooldowns}\n` +
          `\u25C6 Harems \u00BB ${stats.haremGroups} grupo(s) / ${stats.haremChars} personaje(s)\n` +
          `\u25C6 Claims \u00BB ${stats.claims}\n` +
          `\u25C6 Staff Profile \u00BB ${stats.staffProfile ? "S\u00ED" : "No"}\n` +
          `\u25C6 Staff Stats \u00BB ${stats.staffStats ? "S\u00ED" : "No"}\n` +
          `\u25C6 Staff Claims \u00BB ${stats.staffClaims}\n` +
          `\u25C6 Report Cooldowns \u00BB ${stats.reportCooldowns ? "S\u00ED" : "No"}\n` +
          `\u25C6 Pox Streaks \u00BB ${stats.poxStreaks ? "S\u00ED" : "No"}\n` +
          `\u25C6 Suggest Stats \u00BB ${stats.suggestStats ? "S\u00ED" : "No"}\n` +
          `\u25C6 Ban \u00BB ${stats.banned ? "S\u00ED" : "No"}\n` +
          `\u25C6 Secondary Owners \u00BB ${stats.secondaryOwners}\n` +
          `\u25C6 Primary Owner \u00BB ${stats.primaryOwner ? "S\u00ED" : "No"}\n` +
          `\u25C6 DonationsOff \u00BB ${stats.donationsOff}\n\n` +
          `\u25C7 Backup \u00BB \`backups/database.pre-transfer-${ts}.json\`\n` +
          `\u25C7 Backup \u00BB \`backups/characters.pre-transfer-${ts}.json\``,
        mentions: __mentions
      },
      { quoted: msg }
    );
  } catch (error) {
    console.error("[MODLVLTRANSF] Error:", error);
    await sock.sendMessage(
      jid,
      {
        text:
          `\u274C Error durante la transferencia.\n\n` +
          `> ${error?.message || error}\n\n` +
          `> Los backups est\u00E1n en \`backups/\``
      },
      { quoted: msg }
    );
  }
}

/* ============================================================
 * RELOADW_SYSTEM_V1
 * /reloadw — solo owner principal
 *
 * 1. Borra backups .mio_* viejos (7 días)
 * 2. Borra archivos viejos dentro de ./backups/
 * 3. Borra carpetas backup_* viejas
 * 4. Borra usuarios sin comandos en 7 días (Chile)
 * 5. Reporta lo liberado
 * ============================================================ */

async function handleReloadW(sock, msg, jid, sender) {
  if (!isMainOwnerId(sender)) {
    return sock.sendMessage(
      jid,
      { text: '❌ Solo el owner principal puede usar /reloadw.' },
      { quoted: msg }
    );
  }

  const CUTOFF_DAYS = 7;
  const CUTOFF_MS = CUTOFF_DAYS * 24 * 60 * 60 * 1000;
  const now = Date.now();
  const todayKey = getChileDayKey(now);

  const stats = {
    mioFiles: 0,
    backupsFiles: 0,
    backupDirs: 0,
    usersDeleted: 0,
    bytesFreed: 0
  };

  const diffChileDays = (fromKey, toKey) => {
    try {
      const [fy, fm, fd] = String(fromKey).split('-').map(Number);
      const [ty, tm, td] = String(toKey).split('-').map(Number);
      const fromUTC = Date.UTC(fy, fm - 1, fd);
      const toUTC = Date.UTC(ty, tm - 1, td);
      return Math.floor((toUTC - fromUTC) / (24 * 60 * 60 * 1000));
    } catch {
      return 0;
    }
  };

  const safeGetSize = (p) => {
    let total = 0;
    try {
      const items = fs.readdirSync(p);
      for (const item of items) {
        const ip = path.join(p, item);
        try {
          const s = fs.lstatSync(ip);
          if (s.isSymbolicLink()) continue;
          if (s.isDirectory()) total += safeGetSize(ip);
          else total += s.size;
        } catch (e) {}
      }
    } catch (e) {}
    return total;
  };

  await sock.sendMessage(
    jid,
    { text: '🧹 Ejecutando /reloadw...\n> Puede tardar unos segundos.' },
    { quoted: msg }
  );

  /* 1. Archivos .mio_* viejos */
  try {
    const cwd = process.cwd();
    for (const file of fs.readdirSync(cwd)) {
      if (!file.includes('.mio_')) continue;
      const fullPath = path.join(cwd, file);
      try {
        const s = fs.lstatSync(fullPath);
        if (!s.isFile()) continue;
        if (now - s.mtimeMs > CUTOFF_MS) {
          stats.bytesFreed += s.size;
          fs.unlinkSync(fullPath);
          stats.mioFiles++;
        }
      } catch (e) {}
    }
  } catch (e) {
    console.error('[RELOADW] mio files:', e?.message || e);
  }

  /* 2. Archivos viejos dentro de ./backups/ */
  try {
    const backupsDir = path.join(process.cwd(), 'backups');
    if (fs.existsSync(backupsDir)) {
      for (const file of fs.readdirSync(backupsDir)) {
        const fullPath = path.join(backupsDir, file);
        try {
          const s = fs.lstatSync(fullPath);
          if (!s.isFile()) continue;
          if (now - s.mtimeMs > CUTOFF_MS) {
            stats.bytesFreed += s.size;
            fs.unlinkSync(fullPath);
            stats.backupsFiles++;
          }
        } catch (e) {}
      }
    }
  } catch (e) {
    console.error('[RELOADW] backups/:', e?.message || e);
  }

  /* 3. Carpetas backup_* viejas */
  try {
    const cwd = process.cwd();
    for (const dir of fs.readdirSync(cwd)) {
      if (!dir.startsWith('backup_')) continue;
      const fullPath = path.join(cwd, dir);
      try {
        const s = fs.lstatSync(fullPath);
        if (!s.isDirectory()) continue;
        if (now - s.mtimeMs > CUTOFF_MS) {
          const size = safeGetSize(fullPath);
          fs.rmSync(fullPath, { recursive: true, force: true });
          stats.bytesFreed += size;
          stats.backupDirs++;
        }
      } catch (e) {}
    }
  } catch (e) {
    console.error('[RELOADW] backup_*:', e?.message || e);
  }

  /* 4. Usuarios inactivos 7 días (reloj real de Chile) */
  const protectedIds = new Set(
    [
      OWNER_NUMBER,
      ...(Array.isArray(db.secondaryOwners) ? db.secondaryOwners : [])
    ].filter(Boolean)
  );

  const __dbAntes = contarDatosDatabase(db);

  for (const uid of Object.keys(db.users || {})) {
    if (protectedIds.has(uid)) continue;
    if (db.bannedUsers?.[uid]) continue;

    const user = db.users[uid];
    if (!user || typeof user !== 'object') {
      delete db.users[uid];
      stats.usersDeleted++;
      continue;
    }

    const lastTs =
      Number(user.lastCommandAt) ||
      Number(user.lastMessageAt) ||
      Number(user.lastXpGain) ||
      0;

    if (!lastTs) {
      if (!user.createdAt) user.createdAt = now;
      const createdKey = getChileDayKey(Number(user.createdAt));
      if (diffChileDays(createdKey, todayKey) >= CUTOFF_DAYS) {
        delete db.users[uid];
        stats.usersDeleted++;
      }
      continue;
    }

    const lastKey = getChileDayKey(lastTs);
    if (diffChileDays(lastKey, todayKey) >= CUTOFF_DAYS) {
      delete db.users[uid];
      stats.usersDeleted++;
    }
  }

  if (stats.usersDeleted > 0) {
    registrarReduccionIntencional(
      __dbAntes - contarDatosDatabase(db),
      'reloadw'
    );
    saveDB();
  }

  /* 5. Reporte */
  const fmtBytes = (b) => {
    if (!Number.isFinite(b) || b <= 0) return '0 B';
    if (b < 1024) return b + ' B';
    if (b < 1024 * 1024) return (b / 1024).toFixed(2) + ' KB';
    if (b < 1024 * 1024 * 1024) return (b / (1024 * 1024)).toFixed(2) + ' MB';
    return (b / (1024 * 1024 * 1024)).toFixed(3) + ' GB';
  };

  const reporte = [
    '🧹 *RELOADW COMPLETADO*',
    '',
    '◈ Backups `.mio_*` eliminados » `' + stats.mioFiles + '`',
    '◈ Archivos de `./backups/` eliminados » `' + stats.backupsFiles + '`',
    '◈ Carpetas `backup_*` eliminadas » `' + stats.backupDirs + '`',
    '◈ Usuarios inactivos (7d Chile) eliminados » `' + stats.usersDeleted + '`',
    '',
    '◈ Espacio liberado » `' + fmtBytes(stats.bytesFreed) + '`',
    '',
    '> Fecha Chile actual » `' + todayKey + '`',
    '> Criterio » inactividad ≥ 7 días calendario (America/Santiago).'
  ].join('\n');

  return sock.sendMessage(jid, { text: reporte }, { quoted: msg });
}

/* ============================================================
 * PESO_SYSTEM_V1 — /peso y /weight
 * Muestra el peso total del bot, top carpetas y archivos raíz.
 * ============================================================ */

async function handlePeso(sock, msg, jid) {
  const root = process.cwd();

  const fmt = (b) => {
    if (!Number.isFinite(b) || b <= 0) return '0 B';
    if (b < 1024) return b + ' B';
    if (b < 1024 * 1024) return (b / 1024).toFixed(2) + ' KB';
    if (b < 1024 * 1024 * 1024) return (b / (1024 * 1024)).toFixed(2) + ' MB';
    return (b / (1024 * 1024 * 1024)).toFixed(3) + ' GB';
  };

  const walk = (p) => {
    let size = 0;
    let count = 0;
    try {
      for (const item of fs.readdirSync(p)) {
        const ip = path.join(p, item);
        try {
          const s = fs.lstatSync(ip);
          if (s.isSymbolicLink()) continue;
          if (s.isDirectory()) {
            const r = walk(ip);
            size += r.size;
            count += r.count;
          } else {
            size += s.size;
            count++;
          }
        } catch (e) {}
      }
    } catch (e) {}
    return { size, count };
  };

  await sock.sendMessage(
    jid,
    { text: '📦 Calculando peso del bot...' },
    { quoted: msg }
  );

  const total = walk(root);

  /* Carpetas de primer nivel */
  const folders = [];
  try {
    for (const item of fs.readdirSync(root)) {
      const ip = path.join(root, item);
      try {
        const s = fs.lstatSync(ip);
        if (!s.isDirectory()) continue;
        if (item === '.git') continue;
        const r = walk(ip);
        folders.push({ name: item, size: r.size, count: r.count });
      } catch (e) {}
    }
  } catch (e) {}

  folders.sort((a, b) => b.size - a.size);
  const topFolders = folders.slice(0, 10);

  /* Archivos sueltos grandes en la raíz */
  const rootFiles = [];
  try {
    for (const item of fs.readdirSync(root)) {
      const ip = path.join(root, item);
      try {
        const s = fs.lstatSync(ip);
        if (s.isFile() && s.size > 1024 * 1024) {
          rootFiles.push({ name: item, size: s.size });
        }
      } catch (e) {}
    }
  } catch (e) {}
  rootFiles.sort((a, b) => b.size - a.size);

  const lines = [
    '✦ *PESO DEL BOT* ✦',
    '',
    '◈ Total » `' + fmt(total.size) + '`',
    '◈ Archivos » `' + total.count.toLocaleString('en-US') + '`',
    '',
    '「 TOP 10 CARPETAS 」'
  ];

  for (const f of topFolders) {
    lines.push(
      '➢ `' + f.name + '` » `' +
        fmt(f.size) +
        '` · ' + f.count.toLocaleString('en-US') + ' archivos'
    );
  }

  if (rootFiles.length) {
    lines.push('', '「 ARCHIVOS RAÍZ > 1 MB 」');
    for (const f of rootFiles.slice(0, 5)) {
      lines.push('➢ `' + f.name + '` » `' + fmt(f.size) + '`');
    }
  }

  lines.push('', '> Calculado en ' + new Date().toLocaleString('es-CL'));

  await sock.sendMessage(jid, { text: lines.join('\n') }, { quoted: msg });
}

// ============================================================
// MANHWA_SYSTEM_V1
// ============================================================
const MANHWA_DIR = path.join(process.cwd(), 'manhwa');
const MANHWA_DATA_FILE = path.join(MANHWA_DIR, 'data.json');
const MANHWA_IMAGES_DIR = path.join(MANHWA_DIR, 'images');
const MANHWA_MAX_ALBUM = 30;
const MANHWA_MAX_CAP_IMAGES = 500;
const MANHWA_MAX_CAPITULOS = 500;
const MANHWA_MAX_IMAGE_BYTES = 5 * 1024 * 1024;

let __manhwaCache = null;

function __manhwaEnsureDirs() {
  if (!fs.existsSync(MANHWA_DIR)) fs.mkdirSync(MANHWA_DIR, { recursive: true });
  if (!fs.existsSync(MANHWA_IMAGES_DIR)) fs.mkdirSync(MANHWA_IMAGES_DIR, { recursive: true });
}

function __manhwaLoad() {
  if (__manhwaCache) return __manhwaCache;
  __manhwaEnsureDirs();
  try {
    if (fs.existsSync(MANHWA_DATA_FILE)) {
      const raw = fs.readFileSync(MANHWA_DATA_FILE, 'utf8');
      __manhwaCache = raw.trim() ? JSON.parse(raw) : {};
      if (!__manhwaCache || typeof __manhwaCache !== 'object') __manhwaCache = {};
    } else {
      __manhwaCache = {};
    }
  } catch (e) {
    console.error('[MANHWA] load error:', e?.message || e);
    __manhwaCache = {};
  }
  return __manhwaCache;
}

function __manhwaSave() {
  __manhwaEnsureDirs();
  const data = __manhwaCache || {};
  const tmp = MANHWA_DATA_FILE + '.tmp';
  fs.writeFileSync(tmp, JSON.stringify(data, null, 2), 'utf8');
  fs.renameSync(tmp, MANHWA_DATA_FILE);
}

function __manhwaSlug(name) {
  return String(name || '')
    .normalize('NFD')
    .replace(/[\\u0300-\\u036f]/g, '')
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function __manhwaCapKey(cap) {
  const num = String(cap || '').trim();
  const digits = num.replace(/[^0-9.]/g, '');
  if (digits) return 'cap_' + digits.replace(/\\./g, '_');
  return 'cap_' + __manhwaSlug(num);
}

function __manhwaHash(buffer) {
  return crypto.createHash('sha256').update(buffer).digest('hex');
}

function __manhwaFindDuplicateHash(hash) {
  const data = __manhwaLoad();
  for (const mKey of Object.keys(data)) {
    const m = data[mKey];
    if (!m || !m.capitulos) continue;
    for (const cKey of Object.keys(m.capitulos)) {
      const cap = m.capitulos[cKey];
      if (!cap || !Array.isArray(cap.images)) continue;
      for (const img of cap.images) {
        if (img && img.hash === hash) {
          return { manhwaKey: mKey, manhwaName: m.nombre, capKey: cKey, capNumero: cap.numero };
        }
      }
    }
  }
  return null;
}

function __manhwaAddImagenesBatch(manhwaNombre, capitulo, buffers) {
  const data = __manhwaLoad();
  const mKey = __manhwaSlug(manhwaNombre);
  if (!mKey) return { ok: false, error: 'Nombre de manhwa invalido' };
  const cKey = __manhwaCapKey(capitulo);

  if (!data[mKey]) {
    data[mKey] = { nombre: String(manhwaNombre).trim(), capitulos: {}, createdAt: Date.now() };
  }
  const manhwa = data[mKey];
  if (!manhwa.capitulos) manhwa.capitulos = {};

  const existingCaps = Object.keys(manhwa.capitulos).length;
  if (existingCaps >= MANHWA_MAX_CAPITULOS && !manhwa.capitulos[cKey]) {
    return { ok: false, error: 'Limite de capitulos alcanzado: ' + MANHWA_MAX_CAPITULOS };
  }

  if (!manhwa.capitulos[cKey]) {
    manhwa.capitulos[cKey] = {
      numero: String(capitulo).trim(),
      images: [],
      createdAt: Date.now()
    };
  }
  const cap = manhwa.capitulos[cKey];
  if (!Array.isArray(cap.images)) cap.images = [];

  const capImagesDir = path.join(MANHWA_IMAGES_DIR, mKey, cKey);
  if (!fs.existsSync(capImagesDir)) fs.mkdirSync(capImagesDir, { recursive: true });

  const results = {
    added: 0,
    duplicates: [],
    tooLarge: [],
    invalid: [],
    capReached: false,
    capTotal: cap.images.length
  };

  for (const buf of buffers) {
    if (cap.images.length >= MANHWA_MAX_CAP_IMAGES) {
      results.capReached = true;
      break;
    }
    if (!Buffer.isBuffer(buf) || !buf.length) {
      results.invalid.push({ motivo: 'buffer vacio' });
      continue;
    }
    if (buf.length > MANHWA_MAX_IMAGE_BYTES) {
      results.tooLarge.push({ bytes: buf.length });
      continue;
    }
    const hash = __manhwaHash(buf);
    const dup = __manhwaFindDuplicateHash(hash);
    if (dup) {
      results.duplicates.push({ hash: hash.slice(0, 8), dupEn: dup });
      continue;
    }
    if (results.duplicates.some(d => d.hash === hash.slice(0, 8))) {
      results.duplicates.push({ hash: hash.slice(0, 8), dupEn: { mismoBatch: true } });
      continue;
    }
    let ext = 'jpg';
    if (buf.length >= 8 && buf.subarray(0, 8).equals(Buffer.from([0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a]))) ext = 'png';
    else if (buf.length >= 4 && buf.subarray(0, 4).toString() === 'RIFF') ext = 'webp';
    else if (buf.length >= 4 && buf.subarray(0, 4).toString() === 'GIF8') ext = 'gif';
    const fileName = 'img_' + hash.slice(0, 12) + '.' + ext;
    const fullPath = path.join(capImagesDir, fileName);
    try {
      fs.writeFileSync(fullPath, buf);
      cap.images.push({ file: fileName, hash: hash, ext: ext, addedAt: Date.now() });
      results.added++;
    } catch (e) {
      console.error('[MANHWA] write error:', e?.message || e);
      results.invalid.push({ motivo: 'write error' });
    }
  }

  results.capTotal = cap.images.length;
  __manhwaSave();
  return { ok: true, results: results, manhwaKey: mKey, capKey: cKey };
}

async function handleAddManhwa(sock, msg, args, sender, isMainOwner) {
  const jid = msg.key.remoteJid;
  if (!isMainOwner) {
    return sock.sendMessage(jid, { text: '\\u25C7 Solo el owner principal puede usar /addmanhwa.' }, { quoted: msg });
  }
  const raw = String(args.join(' ')).trim();
  const parts = raw.split('/').map(x => x.trim()).filter(Boolean);
  if (parts.length < 2) {
    return sock.sendMessage(jid, {
      text: '\\u25C7 Uso: /addmanhwa Nombre del Manhwa / Capitulo\\n> Responde (cita) a una imagen o album.'
    }, { quoted: msg });
  }
  const manhwaNombre = parts[0];
  const capitulo = parts[1];
  const ctx =
    msg.message?.extendedTextMessage?.contextInfo ||
    msg.message?.imageMessage?.contextInfo ||
    msg.message?.videoMessage?.contextInfo ||
    null;
  if (!ctx || !ctx.stanzaId || !ctx.quotedMessage) {
    return sock.sendMessage(jid, {
      text: '\\u25C7 Debes responder (citar) a una imagen o a un album.'
    }, { quoted: msg });
  }
  const unwrap = (content) => {
    let c = content;
    while (c) {
      if (c.imageMessage) return c;
      c =
        c.ephemeralMessage?.message ||
        c.viewOnceMessage?.message ||
        c.viewOnceMessageV2?.message ||
        c.documentWithCaptionMessage?.message ||
        null;
    }
    return null;
  };
  const quoted = ctx.quotedMessage;
  const images = [];
  const seenIds = new Set();
  const direct = unwrap(quoted);
  if (direct?.imageMessage) {
    images.push({
      key: { remoteJid: jid, id: ctx.stanzaId, participant: ctx.participant },
      message: direct
    });
    seenIds.add(String(ctx.stanzaId));
  }
  if (!images.length) {
    const albumTimestamp = String(ctx.messageTimestamp || '');
    const albumParticipant = String(ctx.participant || '');
    let albumContainerTimestamp = albumTimestamp;
    let albumContainerParticipant = albumParticipant;
    for (const [uid, list] of Object.entries(pendingAlbums || {})) {
      if (uid === '__byAlbum') continue;
      if (!Array.isArray(list)) continue;
      for (const entry of list) {
        if (!entry?.msg?.key?.id) continue;
        if (String(entry.msg.key.id) === String(ctx.stanzaId)) {
          albumContainerTimestamp = String(entry.msg.messageTimestamp || albumTimestamp);
          albumContainerParticipant = String(entry.msg.key.participant || entry.msg.participant || albumParticipant);
          break;
        }
      }
    }
    for (const [uid, list] of Object.entries(pendingAlbums || {})) {
      if (uid === '__byAlbum') continue;
      if (!Array.isArray(list)) continue;
      for (const entry of list) {
        if (!entry?.msg) continue;
        const inner = unwrap(entry.msg.message);
        if (!inner?.imageMessage) continue;
        const entryParticipant = String(entry.msg.key?.participant || entry.msg.participant || uid);
        const entryTimestamp = String(entry.msg.messageTimestamp || '');
        const sameParticipant = albumContainerParticipant && entryParticipant === albumContainerParticipant;
        const sameTimestamp = albumContainerTimestamp && entryTimestamp === albumContainerTimestamp;
        if (!sameParticipant || !sameTimestamp) continue;
        const id = entry.msg.key.id;
        if (!id || seenIds.has(String(id))) continue;
        images.push(entry.msg);
        seenIds.add(String(id));
      }
    }
    if (!images.length && albumContainerParticipant) {
      const now = Date.now();
      const list = pendingAlbums[albumContainerParticipant];
      if (Array.isArray(list)) {
        const recent = list
          .filter(entry => {
            if (!entry?.msg) return false;
            const inner = unwrap(entry.msg.message);
            if (!inner?.imageMessage) return false;
            const t = Number(entry.msg.messageTimestamp || 0) * 1000;
            return now - t < 60000;
          })
          .slice(-30);
        for (const entry of recent) {
          const id = entry.msg.key.id;
          if (!id || seenIds.has(String(id))) continue;
          images.push(entry.msg);
          seenIds.add(String(id));
        }
      }
    }
  }
  if (!images.length) {
    return sock.sendMessage(jid, {
      text: '\\u25C7 El mensaje citado no contiene imagenes.'
    }, { quoted: msg });
  }
  await sock.sendMessage(jid, {
    text: '\\u23F3 Procesando ' + images.length + ' imagen(es)...'
  }, { quoted: msg });
  const buffers = [];
  const failed = [];
  for (let i = 0; i < images.length; i++) {
    try {
      const buf = await downloadMediaMessage(images[i], 'buffer', {});
      if (Buffer.isBuffer(buf) && buf.length) {
        buffers.push(buf);
      } else {
        failed.push({ index: i + 1, motivo: 'buffer vacio' });
      }
    } catch (e) {
      failed.push({ index: i + 1, motivo: e?.message || 'download error' });
    }
  }
  if (!buffers.length) {
    return sock.sendMessage(jid, {
      text: '\\u274C Ninguna imagen pudo descargarse.'
    }, { quoted: msg });
  }
  const result = __manhwaAddImagenesBatch(manhwaNombre, capitulo, buffers);
  if (!result.ok) {
    return sock.sendMessage(jid, { text: '\\u274C ' + (result.error || 'Error') }, { quoted: msg });
  }
  const r = result.results;
  let texto = '\\u2705 Manhwa actualizado\\n\\n';
  texto += '\\u25C7 Manhwa: `' + manhwaNombre + '`\\n';
  texto += '\\u25C7 Capitulo: `' + capitulo + '`\\n\\n';
  texto += '\\u2713 Agregadas: `' + r.added + '`\\n';
  texto += '\\u25C7 Total en capitulo: `' + r.capTotal + '`\\n';
  if (r.duplicates.length) texto += '\\n\\u26A0\\uFE0F Duplicadas: `' + r.duplicates.length + '`\\n';
  if (r.tooLarge.length) texto += '\\u26A0\\uFE0F Muy pesadas (>5MB): `' + r.tooLarge.length + '`\\n';
  if (r.invalid.length) texto += '\\u26A0\\uFE0F Invalidas: `' + r.invalid.length + '`\\n';
  if (failed.length) texto += '\\u26A0\\uFE0F Fallos de descarga: `' + failed.length + '`\\n';
  if (r.capReached) texto += '\\n\\u26A0\\uFE0F Limite de ' + MANHWA_MAX_CAP_IMAGES + ' alcanzado.';
  await sock.sendMessage(jid, { text: texto }, { quoted: msg });
}

async function handleManhwa(sock, msg, args) {
  const jid = msg.key.remoteJid;
  const raw = String(args.join(' ')).trim();
  const parts = raw.split('/').map(x => x.trim()).filter(Boolean);
  if (parts.length < 2) {
    return sock.sendMessage(jid, {
      text: '\\u25C7 Uso: /manhwa Nombre del Manhwa / Capitulo'
    }, { quoted: msg });
  }
  const manhwaNombre = parts[0];
  const capitulo = parts[1];
  const data = __manhwaLoad();
  const mKey = __manhwaSlug(manhwaNombre);
  const cKey = __manhwaCapKey(capitulo);
  const manhwa = data[mKey];
  if (!manhwa) {
    return sock.sendMessage(jid, { text: '\\u25C7 Manhwa no encontrado: `' + manhwaNombre + '`' }, { quoted: msg });
  }
  const cap = manhwa.capitulos?.[cKey];
  if (!cap || !Array.isArray(cap.images) || !cap.images.length) {
    return sock.sendMessage(jid, { text: '\\u25C7 Capitulo no encontrado o vacio.' }, { quoted: msg });
  }
  const capImagesDir = path.join(MANHWA_IMAGES_DIR, mKey, cKey);
  const total = cap.images.length;
  const bloques = [];
  for (let i = 0; i < total; i += MANHWA_MAX_ALBUM) {
    bloques.push(cap.images.slice(i, i + MANHWA_MAX_ALBUM));
  }
  await sock.sendMessage(jid, {
    text: '\\uD83D\\uDCD6 *' + manhwa.nombre + '* \\u2014 Capitulo `' + cap.numero + '`\\n> ' + total + ' pagina(s)'
  }, { quoted: msg });
  for (let bIdx = 0; bIdx < bloques.length; bIdx++) {
    const bloque = bloques[bIdx];
    const startNum = bIdx * MANHWA_MAX_ALBUM + 1;
    const endNum = startNum + bloque.length - 1;
    const albumPayload = [];
    for (let i = 0; i < bloque.length; i++) {
      const img = bloque[i];
      const fullPath = path.join(capImagesDir, img.file);
      if (!fs.existsSync(fullPath)) continue;
      try {
        const buf = fs.readFileSync(fullPath);
        const item = {
          image: buf,
          mimetype: 'image/' + (img.ext === 'jpg' ? 'jpeg' : img.ext)
        };
        if (bIdx === 0 && i === 0) {
          item.caption = '\\uD83D\\uDCD6 ' + manhwa.nombre + ' \\u2014 Cap ' + cap.numero + ' (Paginas ' + startNum + '-' + endNum + ' de ' + total + ')';
        }
        albumPayload.push(item);
      } catch (e) {
        console.log('[MANHWA] read error:', img.file, e?.message || e);
      }
    }
    if (!albumPayload.length) continue;
    try {
      await sock.sendMessage(jid, { album: albumPayload });
    } catch (albumErr) {
      console.log('[MANHWA] album error, fallback individual:', albumErr?.message || albumErr);
      for (const item of albumPayload) {
        try {
          await sock.sendMessage(jid, {
            image: item.image,
            mimetype: item.mimetype,
            caption: item.caption
          });
          await new Promise(r => setTimeout(r, 200));
        } catch (e) {}
      }
    }
    if (bIdx < bloques.length - 1) {
      await new Promise(r => setTimeout(r, 1000));
    }
  }
}

async function handleDelManhwa(sock, msg, args, sender, isMainOwner) {
  const jid = msg.key.remoteJid;
  if (!isMainOwner) {
    return sock.sendMessage(jid, { text: '\\u25C7 Solo el owner principal puede usar /delmanhwa.' }, { quoted: msg });
  }
  const raw = String(args.join(' ')).trim();
  const parts = raw.split('/').map(x => x.trim()).filter(Boolean);
  if (parts.length < 2) {
    return sock.sendMessage(jid, { text: '\\u25C7 Uso: /delmanhwa Nombre / Capitulo' }, { quoted: msg });
  }
  const manhwaNombre = parts[0];
  const capitulo = parts[1];
  const data = __manhwaLoad();
  const mKey = __manhwaSlug(manhwaNombre);
  const cKey = __manhwaCapKey(capitulo);
  const manhwa = data[mKey];
  if (!manhwa) return sock.sendMessage(jid, { text: '\\u25C7 Manhwa no encontrado.' }, { quoted: msg });
  const cap = manhwa.capitulos?.[cKey];
  if (!cap) return sock.sendMessage(jid, { text: '\\u25C7 Capitulo no encontrado.' }, { quoted: msg });
  const capImagesDir = path.join(MANHWA_IMAGES_DIR, mKey, cKey);
  let deletedFiles = 0;
  if (fs.existsSync(capImagesDir)) {
    try {
      const files = fs.readdirSync(capImagesDir);
      for (const f of files) {
        try { fs.unlinkSync(path.join(capImagesDir, f)); deletedFiles++; } catch (e) {}
      }
      try { fs.rmdirSync(capImagesDir); } catch (e) {}
    } catch (e) {}
  }
  const imagesCount = Array.isArray(cap.images) ? cap.images.length : 0;
  delete manhwa.capitulos[cKey];
  const restantes = Object.keys(manhwa.capitulos || {}).length;
  let manhwaEliminado = false;
  if (restantes === 0) {
    delete data[mKey];
    const manhwaDir = path.join(MANHWA_IMAGES_DIR, mKey);
    try { if (fs.existsSync(manhwaDir)) fs.rmdirSync(manhwaDir); } catch (e) {}
    manhwaEliminado = true;
  }
  __manhwaSave();
  let texto = '\\uD83D\\uDDD1\\uFE0F Capitulo eliminado\\n\\n';
  texto += '\\u25C7 Manhwa: `' + manhwa.nombre + '`\\n';
  texto += '\\u25C7 Capitulo: `' + cap.numero + '`\\n';
  texto += '\\u2713 Imagenes eliminadas: `' + deletedFiles + '` (registradas: ' + imagesCount + ')\\n';
  texto += '\\u25C7 Capitulos restantes en el manhwa: `' + restantes + '`\\n';
  if (manhwaEliminado) texto += '\\n\\u26A0\\uFE0F El manhwa quedo sin capitulos y fue eliminado.';
  await sock.sendMessage(jid, { text: texto }, { quoted: msg });
}

async function handleDelCap(sock, msg, args, sender, isMainOwner) {
  const jid = msg.key.remoteJid;
  if (!isMainOwner) {
    return sock.sendMessage(jid, { text: '\\u25C7 Solo el owner principal puede usar /delcap.' }, { quoted: msg });
  }
  const raw = String(args.join(' ')).trim();
  const parts = raw.split('/').map(x => x.trim()).filter(Boolean);
  if (parts.length < 3) {
    return sock.sendMessage(jid, {
      text: '\\u25C7 Uso: /delcap Nombre del Manhwa / Capitulo / Numero de imagen\\n> Ejemplo: /delcap Solo Leveling / 2 / 12'
    }, { quoted: msg });
  }
  const manhwaNombre = parts[0];
  const capitulo = parts[1];
  const idx = Number(parts[2]);
  if (!Number.isInteger(idx) || idx < 1) {
    return sock.sendMessage(jid, { text: '\\u25C7 El numero debe ser entero >= 1.' }, { quoted: msg });
  }
  const data = __manhwaLoad();
  const mKey = __manhwaSlug(manhwaNombre);
  const cKey = __manhwaCapKey(capitulo);
  const manhwa = data[mKey];
  if (!manhwa) return sock.sendMessage(jid, { text: '\\u25C7 Manhwa no encontrado.' }, { quoted: msg });
  const cap = manhwa.capitulos?.[cKey];
  if (!cap || !Array.isArray(cap.images)) return sock.sendMessage(jid, { text: '\\u25C7 Capitulo no encontrado.' }, { quoted: msg });
  if (idx > cap.images.length) {
    return sock.sendMessage(jid, {
      text: '\\u25C7 El capitulo solo tiene ' + cap.images.length + ' imagen(es). Pediste la ' + idx + '.'
    }, { quoted: msg });
  }
  const target = cap.images[idx - 1];
  const capImagesDir = path.join(MANHWA_IMAGES_DIR, mKey, cKey);
  const fullPath = path.join(capImagesDir, target.file);
  let deleted = false;
  try {
    if (fs.existsSync(fullPath)) { fs.unlinkSync(fullPath); deleted = true; }
  } catch (e) {}
  cap.images.splice(idx - 1, 1);
  __manhwaSave();
  let texto = '\\uD83D\\uDDD1\\uFE0F Imagen eliminada\\n\\n';
  texto += '\\u25C7 Manhwa: `' + manhwa.nombre + '`\\n';
  texto += '\\u25C7 Capitulo: `' + cap.numero + '`\\n';
  texto += '\\u25C7 Posicion eliminada: `' + idx + '`\\n';
  texto += '\\u2713 Archivo: `' + target.file + '` ' + (deleted ? 'eliminado' : 'no encontrado en disco') + '\\n';
  texto += '\\u25C7 Imagenes restantes en el capitulo: `' + cap.images.length + '`';
  await sock.sendMessage(jid, { text: texto }, { quoted: msg });
}

