function __normalizeRankKey(s) {
  return String(s || '')
    .trim()
    .toLowerCase()
    .replace(/[\s._\-]+/g, '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function __resolveRankName(input) {
  const key = __normalizeRankKey(input);
  if (!key) return null;
  for (const rankName of Object.keys(RANGOS_SECUNDARIOS)) {
    if (__normalizeRankKey(rankName) === key) return rankName;
  }
  return null;
}

function __getSecondaryRank(sender) {
  if (!sender) return 'Sr. Novato';
  db.secondaryRanks ??= {};
  const key = String(sender).trim().toLowerCase();
  const rank = db.secondaryRanks[key];
  if (rank && RANGOS_SECUNDARIOS[rank]) return rank;
  return 'Sr. Novato';
}

function __setSecondaryRank(sender, rank) {
  if (!sender || !rank) return false;
  if (!RANGOS_SECUNDARIOS[rank]) return false;
  db.secondaryRanks ??= {};
  db.secondaryRanks[String(sender).trim().toLowerCase()] = rank;
  return true;
}

function __isCommandAllowedForRank(sender, command) {
  // ROLE_FILTER_DEFENSIVE_V29
  if (isMainOwnerId(sender)) return true;
  if (!isSecondaryOwnerId(sender)) return true;

  const rank = __getSecondaryRank(sender);
  const rankCfg = RANGOS_SECUNDARIOS[rank];

  if (!rankCfg) return true;

  const cmd = String(command || '').toLowerCase().trim();
  if (!cmd) return true;

  if (rankCfg.forbidden && typeof rankCfg.forbidden.has === 'function') {
    return !rankCfg.forbidden.has(cmd);
  }

  if (rankCfg.allowed && typeof rankCfg.allowed.has === 'function') {
    return rankCfg.allowed.has(cmd);
  }

  return true;
}



