 /*
  * ============================================================
  * BUSCADOR INTERNO ADDP
  * ============================================================
  *
  * Misma lógica base utilizada por /searchg.
  *
  * Devuelve solamente el nombre del tag.
  */

 async function buscarTagAutomaticoAddP(
  nombre,
  anime
 ) {

  const normalizar =
   text =>
    String(text || "")
     .toLowerCase()
     .replace(/_/g, " ")
     .replace(/[^a-z0-9 ]/g, "")
     .trim();

  const target =
   normalizar(nombre);

  if (!target) {
   return null;
  }

  let tags = [];

  try {

   const axios =
    (await import("axios")).default;

   /*
    * Primero buscamos por el nombre.
    * Después por el anime, igual que searchg.
    */
   const queries = [
    nombre.replace(/\s+/g, "_"),
    nombre,
    anime
   ];

   for (
    const q of queries
   ) {

    if (!q) continue;

    const url =
     "https://danbooru.donmai.us/tags.json" +
     "?search[category]=4" +
     "&search[name_matches]=*" +
     encodeURIComponent(q) +
     "*" +
     "&limit=100";

    try {

     const res =
      await axios.get(
       url,
       {
        timeout: 15000
       }
      );

     if (
      Array.isArray(
       res.data
      )
     ) {

      tags.push(
       ...res.data
      );

     }

    } catch (error) {

     console.error(
      "⚠️ ADDP SEARCH:",
      q,
      error?.message || error
     );

    }

   }

   /*
    * Eliminar duplicados.
    */
   tags =
    [
     ...new Map(
      tags.map(
       t => [
        t.name,
        t
       ]
      )
     ).values()
    ];

  } catch (error) {

   console.error(
    "❌ ADDP SEARCHG INTERNO:",
    error
   );

   return null;
  }

  if (!tags.length) {

   console.log(
    "❌ ADDP AUTOTAG: sin coincidencias:",
    nombre,
    "| serie:",
    anime
   );

   return null;
  }

  /*
   * ============================================================
   * SCORE
   * ============================================================
   *
   * Mantiene el algoritmo de /searchg:
   *
   * exacto       +20000
   * contiene      +8000
   * comienza      +5000
   * variantes    -10000
   */

  function similarity(
   value
  ) {

   const originalTag =
    String(
     value || ""
    ).toLowerCase();

   const valueNormalized =
    normalizar(
     value
    );

   let score = 0;

   /*
    * Coincidencia exacta.
    */
   if (
    valueNormalized ===
    target
   ) {

    score += 20000;

   }

   /*
    * Nombre contenido.
    */
   if (
    valueNormalized.includes(
     target
    )
   ) {

    score += 8000;

   }

   /*
    * Tag comienza por el nombre.
    */
   if (
    valueNormalized.startsWith(
     target
    )
   ) {

    score += 5000;

   }

   /*
    * Penalizar variantes.
    */
   if (
    /(costume|outfit|alternate|swimsuit|cosplay|3rd|2nd)/i
     .test(
      originalTag
     )
   ) {

    score -= 10000;

   }

   /*
    * Si el nombre del anime aparece en el tag,
    * dar una pequeña prioridad adicional.
    *
    * No se usa como requisito porque muchos tags
    * de personajes de Danbooru no contienen el anime.
    */
   const animeNormalized =
    normalizar(
     anime
    );

   if (
    animeNormalized &&
    valueNormalized.includes(
     animeNormalized
    )
   ) {

    score += 1000;

   }

   return score;
  }

  tags.sort(
   (a, b) =>
    similarity(b.name) -
    similarity(a.name)
  );

  const best =
   tags[0];

  if (!best) {
   return null;
  }

  /*
   * ============================================================
   * SEGURIDAD
   * ============================================================
   *
   * No aceptar resultados que no tengan ninguna relación
   * con el nombre solicitado.
   */
  const bestNormalized =
   normalizar(
    best.name
   );

  const tieneRelacion =
   bestNormalized === target ||
   bestNormalized.includes(target) ||
   bestNormalized.startsWith(target);

  if (!tieneRelacion) {

   console.log(
    "⚠️ ADDP AUTOTAG: resultado rechazado:",
    best.name,
    "| solicitado:",
    nombre
   );

   return null;
  }

  console.log(
   "🔎 ADDP AUTOTAG:",
   nombre,
   "->",
   best.name,
   "| serie:",
   anime
  );

  return best.name;
 }


