 for (
  const linea of lineas
 ) {

  let separador = "";

  /*
   * PRIMERO: modo manual.
   */
  if (
   linea.includes(">")
  ) {

   separador = ">";

  } else if (
   linea.includes("=")
  ) {

   separador = "=";

  }

  /*
   * ============================================================
   * MODO MANUAL
   * ============================================================
   */

  if (separador) {

   const posicion =
    linea.indexOf(
     separador
    );

   const nombre =
    linea
     .slice(
      0,
      posicion
     )
     .trim();

   const tag =
    linea
     .slice(
      posicion + 1
     )
     .trim();

   if (
    !nombre ||
    !tag
   ) {

    console.log(
     " ADDP: línea manual inválida:",
     linea
    );

    continue;
   }

   /*
    * ADDP: eliminar ID de serie residual del nombre.
    *
    * Ejemplo:
    *   "124 ¿s N¿dt" -> "¿s N¿dt"
    *
    * Solo elimina números al principio del nombre.
    * No modifica números que formen parte real del nombre.
    */
   const nombreLimpioAddP =
    String(nombre || '')
     .replace(/^\d+\s+/, '')
     .trim();

   if (!nombreLimpioAddP) {
    console.log(
     " ADDP: nombre vacío después de limpiar ID:",
     nombre
    );
    continue;
   }

   personajesIniciales.push({
    nombre: nombreLimpioAddP,
    tag
   });

   console.log(
    "✍️ ADDP MANUAL:",
    nombre,
    "->",
    tag
   );

   continue;
  }


  /*
   * ============================================================
   * MODO AUTOMÁTICO
   * ============================================================
   *
   * No hay > ni =.
   *
   * El texto completo es el nombre del personaje.
   */

  const nombre =
   linea.trim();

  if (!nombre) {
   continue;
  }

  const animeAddP =
   String(
    serie?.name ||
    ""
   ).trim();

  console.log(
   "◆ ADDP AUTOTAG: buscando:",
   nombre,
   "| serie:",
   animeAddP
  );

  const tagAutomatico =
   await buscarTagAutomaticoAddP(
    nombre,
    animeAddP
   );

  if (!tagAutomatico) {

   console.log(
    "❌ ADDP AUTOTAG: no se encontró tag:",
    nombre
   );

   /*
    * No meter un personaje sin tag en la cola.
    */
   continue;
  }

  personajesIniciales.push({
   nombre,
   tag:
    tagAutomatico
  });

  console.log(
   "✓ ADDP AUTOTAG:",
   nombre,
   "->",
   tagAutomatico
  );

 }
