/* ============================================================
 * TRAIN_SYSTEM_V1 - Entrenamiento y batalla de personajes
 * ============================================================ */

const TRAIN_PRICE_BASE = 5000000;
const TRAIN_PRICE_PER_LEVEL = 1000000;
const TRAIN_MIN_GAIN = 50;
const TRAIN_MAX_GAIN = 400;
const TRAIN_COOLDOWN_XPREMIUM_MS = 20 * 60 * 1000;
const TRAIN_COOLDOWN_NORMAL_MS = 40 * 60 * 1000;

function ensureTrainData(character) {
  if (!character || typeof character !== 'object') return;
  if (typeof character.trainLevel !== 'number' || character.trainLevel < 1) {
    character.trainLevel = 1;
  }
  if (typeof character.trainAtk !== 'number') {
    character.trainAtk = Math.floor(Math.random() * 100) + 50;
  }
  if (typeof character.trainHp !== 'number') {
    character.trainHp = Math.floor(Math.random() * 150) + 100;
  }
  if (typeof character.trainDamage !== 'number') {
    character.trainDamage = Math.floor(Math.random() * 80) + 40;
  }
  if (typeof character.trainCooldownUntil !== 'number') {
    character.trainCooldownUntil = 0;
  }
  if (character.trainPending && typeof character.trainPending !== 'object') {
    character.trainPending = null;
  }
}

function getTrainPrice(character) {
  const level = Math.max(1, Number(character?.trainLevel) || 1);
  return TRAIN_PRICE_BASE + (level - 1) * TRAIN_PRICE_PER_LEVEL;
}

function getTrainCooldownMs(user) {
  return hasXPremium(user) ? TRAIN_COOLDOWN_XPREMIUM_MS : TRAIN_COOLDOWN_NORMAL_MS;
}

function getCharacterPower(character) {
  ensureTrainData(character);
  return (
    character.trainAtk * 2 +
    character.trainHp +
    character.trainDamage * 3
  );
}

function formatTrainNumber(n) {
  return Number(n || 0).toLocaleString('en-US').replace(/,/g, '.');
}

function findUserCharacterInGroup(groupId, sender, query) {
  const harem = db.groups?.[groupId]?.harems?.[sender] || [];
  if (!harem.length) return null;
  const q = String(query || '').toLowerCase().trim();
  if (!q) return null;
  let found = harem.find(c => String(c?.name || '').toLowerCase().trim() === q);
  if (!found) {
    found = harem.find(c => String(c?.name || '').toLowerCase().includes(q));
  }
  if (!found) return null;
  const character = characterKeyMap.get(found.key);
  if (!character) return null;
  return { haremEntry: found, character };
}

async function getTrainCharacterImage(character) {
  try {
    const locals = getCharacterImages(character.key);
    if (locals.length) {
      const imgName = locals[Math.floor(Math.random() * locals.length)];
      const imgPath = path.join(GACHA_IMAGES, imgName);
      const buffer = imageCache.get(imgPath) || fs.readFileSync(imgPath);
      imageCache.set(imgPath, buffer);
      const ext = path.extname(imgName).toLowerCase();
      const mimetype = ext === '.png' ? 'image/png' : ext === '.webp' ? 'image/webp' : ext === '.gif' ? 'image/gif' : 'image/jpeg';
      return { image: buffer, mimetype };
    }
  } catch (e) {
    console.log('[TRAIN IMG] local:', e?.message || e);
  }

  if (character.tag) {
    try {
      const du = await getDanbooruImageWithAuth(character.tag);
      if (du) {
        const dd = await downloadImage(du);
        if (dd && dd.buffer && dd.buffer.length) {
          return { image: dd.buffer, mimetype: dd.mimetype };
        }
      }
    } catch (e) {
      console.log('[TRAIN IMG] danbooru:', e?.message || e);
    }

    try {
      const url = await getGelbooruImage(character.tag);
      if (url) {
        const downloaded = await downloadImage(url);
        if (downloaded && downloaded.buffer && downloaded.buffer.length) {
          return { image: downloaded.buffer, mimetype: downloaded.mimetype };
        }
      }
    } catch (e) {
      console.log('[TRAIN IMG] gelbooru:', e?.message || e);
    }
  }

  return null;
}

const STAT_FANCY_TRAIN = {
  atk: 'Aƚαϙυε',
  hp: 'Vιԃα',
  damage: 'Dαñσ'
};
const STAT_KEY_TRAIN = {
  atk: 'trainAtk',
  hp: 'trainHp',
  damage: 'trainDamage'
};

export async function handleTrain(sock, msg, args, jid, sender) {
  const user = initUser(sender, msg.pushName);
  if (!user) {
    return sock.sendMessage(jid, { text: '❌ No se pudo cargar tu cuenta.' }, { quoted: msg });
  }

  const query = args.join(' ').trim();
  if (!query) {
    return sock.sendMessage(jid, {
      text: '◈ Uso: /train NombreDelPersonaje\n\n> Debes tener el personaje en tu /harem de este grupo.'
    }, { quoted: msg });
  }

  const found = findUserCharacterInGroup(jid, sender, query);
  if (!found) {
    return sock.sendMessage(jid, {
      text: '◈ No tienes ningún personaje con ese nombre en tu harem de este grupo.'
    }, { quoted: msg });
  }

  const character = found.character;
  ensureTrainData(character);

  const now = Date.now();

  if (character.trainPending && typeof character.trainPending === 'object') {
    const pending = character.trainPending;
    const appliesAt = Number(pending.appliesAt) || 0;

    if (now < appliesAt) {
      const remaining = appliesAt - now;
      const mins = Math.floor(remaining / 60000);
      const secs = Math.floor((remaining % 60000) / 1000);
      return sock.sendMessage(jid, {
        text:
          'ദ്ദി(˶ᵕ ᵕ˶) ✦ 『 Eηƚɾεηαɱιεηƚσ 』\n\n' +
          '୨୧ Pεɾʂσηαʝε » `' + character.name + '`\n' +
          '⏳ *Eη ƈυɾʂσ* » `' + mins + 'm ' + secs + 's`\n\n' +
          '> ✧¡ Vuelve a usar */train* cuando termine.'
      }, { quoted: msg });
    }

    const stats = pending.stats || {};
    character.trainAtk = Number(stats.trainAtk) || character.trainAtk;
    character.trainHp = Number(stats.trainHp) || character.trainHp;
    character.trainDamage = Number(stats.trainDamage) || character.trainDamage;
    character.trainLevel = (Number(character.trainLevel) || 1) + 1;
    character.trainPending = null;
    saveCharacters();

    const finalText =
      'ദ്ദി(˶ᵕ ᵕ˶) ✦ 『 Eηƚɾεηαɱιεηƚσ 』\n\n' +
      '୨୧ Pεɾʂσηαʝε » `' + character.name + '`\n' +
      '✦ *Nιʋεʅ* » `' + character.trainLevel + '`\n\n' +
      '♡ `Sƚαƚʂ αƈƚυαʅεʂ`\n' +
      '❥ *Aƚαϙυε* » `' + formatTrainNumber(character.trainAtk) + '`\n' +
      '❥ *Vιԃα* » `' + formatTrainNumber(character.trainHp) + '`\n' +
      '❥ *Dαñσ* » `' + formatTrainNumber(character.trainDamage) + '`\n\n' +
      '> ✓ Eηƚɾεηαɱιεηƚσ ƈσɱρʅεƚαԃσ.\n' +
      '> ✧¡ Pυεԃεʂ ʋσʅʋεɾ α εηƚɾεηαɾ ƈση */train*.';

    let media = null;
    try { media = await getTrainCharacterImage(character); } catch (e) {}
    if (media) return sock.sendMessage(jid, { ...media, caption: finalText }, { quoted: msg });
    return sock.sendMessage(jid, { text: finalText }, { quoted: msg });
  }

  if (now < character.trainCooldownUntil) {
    const remaining = character.trainCooldownUntil - now;
    const mins = Math.floor(remaining / 60000);
    const secs = Math.floor((remaining % 60000) / 1000);
    return sock.sendMessage(jid, {
      text: `⏳ Debes esperar ${mins}m ${secs}s para entrenar a *${character.name}* de nuevo.`
    }, { quoted: msg });
  }

  const price = getTrainPrice(character);
  const gems = Number(user.gems) || 0;

  if (gems < price) {
    return sock.sendMessage(jid, {
      text:
        '◈ Gemas insuficientes\n\n' +
        `❖ ${character.name} · Nivel ${character.trainLevel}\n` +
        `✧ Costo » ${formatTrainNumber(price)} gemas\n` +
        `✧ Tú tienes » ${formatTrainNumber(gems)} gemas\n` +
        `✧ Faltan » ${formatTrainNumber(price - gems)} gemas`
    }, { quoted: msg });
  }

  const statOptions = ['atk', 'hp', 'damage'];
  const statChosen = statOptions[Math.floor(Math.random() * statOptions.length)];
  const gain = Math.floor(Math.random() * (TRAIN_MAX_GAIN - TRAIN_MIN_GAIN + 1)) + TRAIN_MIN_GAIN;

  const newStats = {
    trainAtk: character.trainAtk,
    trainHp: character.trainHp,
    trainDamage: character.trainDamage
  };

  if (statChosen === 'atk') newStats.trainAtk += gain;
  else if (statChosen === 'hp') newStats.trainHp += gain;
  else newStats.trainDamage += gain;

  const cooldownMs = getTrainCooldownMs(user);
  const appliesAt = now + cooldownMs;
  const minutes = Math.floor(cooldownMs / 60000);

  user.gems = gems - price;

  character.trainPending = {
    stats: newStats,
    startedAt: now,
    appliesAt
  };
  character.trainCooldownUntil = appliesAt;

  saveCharacters();
  saveDB();

  const statFancy = STAT_FANCY_TRAIN[statChosen];
  const statKey = STAT_KEY_TRAIN[statChosen];
  const beforeVal = character[statKey];
  const afterVal = newStats[statKey];

  const text =
    'ദ്ദി(˶ᵕ ᵕ˶) ✦ 『 Eηƚɾεηαɱιεηƚσ 』\n\n' +
    '୨୧ Pεɾʂσηαʝε » `' + character.name + '`\n' +
    '✦ *Nιʋεʅ»* `' + character.trainLevel + ' ➾ ' + (character.trainLevel + 1) + '`\n' +
    '✧¡ *Dυɾαƈιóη »* `' + minutes + ' ɱιη`\n' +
    '♡ *Mεʝσɾα »* `+' + gain + ' ' + statFancy + '`\n\n' +
    '❥ *' + statFancy + ' »* `' + formatTrainNumber(beforeVal) + ' ➾ ' + formatTrainNumber(afterVal) + '`\n' +
    '✧ *Cσʂƚσ »* `' + formatTrainNumber(price) + ' ɠεɱαʂ 💎`\n\n' +
    '> «💎 Gεɱαʂ ɾεʂƚαηƚεʂ » `' + formatTrainNumber(user.gems) + '`\n' +
    '> ✧¡ Uʂα */train* αʅ ƚεɾɱιηαɾ.';

  let media = null;
  try { media = await getTrainCharacterImage(character); } catch (e) {}
  if (media) return sock.sendMessage(jid, { ...media, caption: text }, { quoted: msg });
  return sock.sendMessage(jid, { text }, { quoted: msg });
}

export async function handleTinf(sock, msg, args, jid, sender) {
  const query = args.join(' ').trim();
  if (!query) {
    return sock.sendMessage(jid, { text: '◈ Uso: /tinf NombreDelPersonaje' }, { quoted: msg });
  }

  const character = findCharacter(query);
  if (!character) {
    return sock.sendMessage(jid, { text: '◈ Personaje no encontrado.' }, { quoted: msg });
  }

  ensureTrainData(character);

  const power = getCharacterPower(character);
  const nextPrice = getTrainPrice(character);

  let text =
    'ദ്ദി(˶ᵕ ᵕ˶) ✦ 『 Iηϝσ 』\n\n' +
    '୨୧ *Pεɾʂσηαʝε* » `' + character.name + '`\n' +
    '✧ *Aηιɱε* » `' + (character.anime || 'Desconocido') + '`\n' +
    '✦ *Nιʋεʅ* » `' + character.trainLevel + '`\n\n' +
    '♡ `Sƚαƚʂ`\n' +
    '❥ *Aƚαϙυε* » `' + formatTrainNumber(character.trainAtk) + '`\n' +
    '❥ *Vιԃα* » `' + formatTrainNumber(character.trainHp) + '`\n' +
    '❥ *Dαñσ* » `' + formatTrainNumber(character.trainDamage) + '`\n\n' +
    '> ✧ *Pσԃεɾ ƚσƚαʅ » ' + formatTrainNumber(power) + '*\n' +
    '> 💎 *Pɾóxιɱσ εηƚɾεηαɱιεηƚσ* » `' + formatTrainNumber(nextPrice) + '`';

  if (character.trainPending && typeof character.trainPending === 'object') {
    const pending = character.trainPending;
    const appliesAt = Number(pending.appliesAt) || 0;
    const now = Date.now();

    if (now < appliesAt) {
      const remaining = appliesAt - now;
      const mins = Math.floor(remaining / 60000);
      const secs = Math.floor((remaining % 60000) / 1000);
      text += '\n>  *Eηƚɾεηαɱιεηƚσ » ' + mins + 'm ' + secs + 's ».*';
    }
  }

  let media = null;
  try { media = await getTrainCharacterImage(character); } catch (e) {}
  if (media) return sock.sendMessage(jid, { ...media, caption: text }, { quoted: msg });
  return sock.sendMessage(jid, { text }, { quoted: msg });
}
export async function handleBatalla(sock, msg, args, jid, sender) {
  const raw = args.join(' ');
  const parts = raw.split('/').map(x => x.trim()).filter(Boolean);

  if (parts.length < 2) {
    return sock.sendMessage(jid, {
      text: '◈ Uso: /batalla NombrePersonajeA / NombrePersonajeB\n\n> Ambos personajes deben estar en este grupo.'
    }, { quoted: msg });
  }

  const nameA = parts[0];
  const nameB = parts.slice(1).join(' / ');

  const group = db.groups?.[jid];
  if (!group || !group.harems) {
    return sock.sendMessage(jid, { text: '◈ No hay datos en este grupo.' }, { quoted: msg });
  }

  const findInGroup = (q) => {
    const norm = String(q).toLowerCase().trim();
    for (const [uid, harem] of Object.entries(group.harems)) {
      if (!Array.isArray(harem)) continue;
      const found =
        harem.find(c => String(c?.name || '').toLowerCase().trim() === norm) ||
        harem.find(c => String(c?.name || '').toLowerCase().includes(norm));
      if (found) return { ownerId: uid, haremEntry: found };
    }
    return null;
  };

  const a = findInGroup(nameA);
  const b = findInGroup(nameB);

  if (!a || !b) {
    return sock.sendMessage(jid, {
      text: '◈ Uno o ambos personajes no están en este grupo.'
    }, { quoted: msg });
  }

  if (a.ownerId === b.ownerId) {
    return sock.sendMessage(jid, {
      text: '◈ Ambos personajes pertenecen al mismo usuario.'
    }, { quoted: msg });
  }

  const charA = characterKeyMap.get(a.haremEntry.key);
  const charB = characterKeyMap.get(b.haremEntry.key);

  if (!charA || !charB) {
    return sock.sendMessage(jid, {
      text: '◈ No se pudieron cargar los personajes.'
    }, { quoted: msg });
  }

  ensureTrainData(charA);
  ensureTrainData(charB);

  const powerA = getCharacterPower(charA);
  const powerB = getCharacterPower(charB);

  const rollA = powerA * (0.8 + Math.random() * 0.4);
  const rollB = powerB * (0.8 + Math.random() * 0.4);

  const winner = rollA >= rollB ? 'A' : 'B';
  const winnerChar = winner === 'A' ? charA : charB;
  const loserChar = winner === 'A' ? charB : charA;
  const winnerOwner = winner === 'A' ? a.ownerId : b.ownerId;
  const loserOwner = winner === 'A' ? b.ownerId : a.ownerId;
  const loserEntry = winner === 'A' ? b.haremEntry : a.haremEntry;

  const loserHarem = group.harems[loserOwner] || [];
  const loserIdx = loserHarem.indexOf(loserEntry);
  if (loserIdx >= 0) loserHarem.splice(loserIdx, 1);

  group.harems[winnerOwner] ??= [];
  if (!group.harems[winnerOwner].some(c => c.key === loserEntry.key)) {
    group.harems[winnerOwner].push(loserEntry);
  }

  loserChar.claimedBy ??= {};
  loserChar.claimedBy[jid] = { user: winnerOwner, time: Date.now() };

  global.ownerIndex ??= {};
  global.ownerIndex[jid] ??= {};
  if (global.ownerIndex[jid][loserOwner]) {
    global.ownerIndex[jid][loserOwner].delete(loserEntry.key);
  }
  global.ownerIndex[jid][winnerOwner] ??= new Set();
  global.ownerIndex[jid][winnerOwner].add(loserEntry.key);

  const winnerUser = initUser(winnerOwner);
  const loserUser = initUser(loserOwner);
  if (winnerUser) {
    winnerUser.harem ??= [];
    if (!winnerUser.harem.includes(loserEntry.key)) winnerUser.harem.push(loserEntry.key);
  }
  if (loserUser && Array.isArray(loserUser.harem)) {
    loserUser.harem = loserUser.harem.filter(k => k !== loserEntry.key);
  }

  saveCharacters();
  saveDB();

  return sock.sendMessage(jid, {
    text:
      'ദ്ദി(˶ᵕ ᵕ˶) ══『 𝐁𝐀𝐓𝐀𝐋𝐋𝐀 』══\n\n' +
      `❖ ${charA.name} (Poder: ${formatTrainNumber(powerA)})\n` +
      '   𝘃𝘀\n' +
      `❖ ${charB.name} (Poder: ${formatTrainNumber(powerB)})\n\n` +
      `🏆 ¡Ganó *${winnerChar.name}*!\n` +
      `> Se lleva a *${loserChar.name}* al harem de @${String(winnerOwner).split('@')[0]}`,
    mentions: [winnerOwner, loserOwner]
  }, { quoted: msg });
}
