export async function handleSetBotOwner(
  sock,
  msg,
  sender,
  args
) {

  const jid =
    msg?.key?.remoteJid || "";

  /*
   * ============================================================
   * /SETBOTOWNER V2
   * ============================================================
   *
   * REGLAS:
   *
   * 1. Solo funciona en grupos.
   * 2. El bot que ejecuta el comando debe ser el PRIMARY.
   * 3. El usuario debe ser owner de ESA SESIÓN.
   * 4. El owner inicial es el ownerUser registrado al crear
   *    la sesión mediante /code.
   * 5. Se actualizan active.json y db.subBots.
   *
   * ============================================================
   */

  if (!jid.endsWith("@g.us")) {

    return sock.sendMessage(
      jid,
      {
        text:
          "❌ Este comando solo puede usarse en grupos."
      },
      {
        quoted: msg
      }
    );

  }

  /*
   * ============================================================
   * NORMALIZADORES
   * ============================================================
   */

  const normalizeJid = value => {

    if (!value) return "";

    return String(value)
      .trim()
      .replace(/:.*(?=@)/, "")
      .replace(/@c\\.us$/i, "@s.whatsapp.net");

  };

  const normalizeNumber = value => {

    return normalizeJid(value)
      .replace(/@.*$/, "")
      .replace(/[^0-9]/g, "");

  };

  const sameUser = (a, b) => {

    if (!a || !b) return false;

    const A = normalizeJid(a);
    const B = normalizeJid(b);

    if (A === B) return true;

    const AN = normalizeNumber(A);
    const BN = normalizeNumber(B);

    return (
      AN &&
      BN &&
      AN === BN
    );

  };

  /*
   * ============================================================
   * SENDER REAL
   * ============================================================
   */

  const realSender =
    normalizeJid(
      sender ||
      msg?.key?.participant ||
      msg?.participant ||
      msg?.key?.remoteJid
    );

  console.log("========================================");
  console.log("SETBOTOWNER V2");
  console.log("========================================");
  console.log("GRUPO:", jid);
console.log(
    "SOCKET ID:",
    sock?.user?.id || "sin ID"
  );

  /*
   * ============================================================
   * PRIMARY DEL GRUPO
   * ============================================================
   */

  db.primaryBots ??= {};

  const primaryRaw =
    db.primaryBots[jid];

  if (!primaryRaw) {

    console.log(
      "❌ SETBOTOWNER: el grupo no tiene primary."
    );

    return sock.sendMessage(
      jid,
      {
        text:
          "❌ Este grupo no tiene un bot primary."
      },
      {
        quoted: msg
      }
    );

  }

  const primaryJid =
    normalizeJid(primaryRaw);

  const socketJid =
    normalizeJid(
      sock?.user?.id
    );

  const primaryNumber =
    normalizeNumber(primaryJid);

  const socketNumber =
    normalizeNumber(socketJid);

  console.log(
    "PRIMARY REGISTRADO:",
    primaryJid
  );

  console.log(
    "SOCKET ACTUAL:",
    socketJid
  );

  /*
   * El socket actual debe ser exactamente el primary.
   */

  if (
    !primaryNumber ||
    !socketNumber ||
    primaryNumber !== socketNumber
  ) {

    console.log(
      "❌ SETBOTOWNER: este socket NO es primary."
    );

    return sock.sendMessage(
      jid,
      {
        text:
          "❌ Este bot no es el primary de este grupo."
      },
      {
        quoted: msg
      }
    );

  }

  /*
   * ============================================================
   * IDENTIFICAR LA SESIÓN
   * ============================================================
   *
   * Ejemplo:
   *
   * sock.user.id
   * 56964620338:3@s.whatsapp.net
   *
   * phone:
   * 56964620338
   *
   * ============================================================
   */

  const botPhone =
    socketNumber;

  if (!botPhone) {

    console.log(
      "❌ SETBOTOWNER: no se pudo obtener número del socket."
    );

    return sock.sendMessage(
      jid,
      {
        text:
          "❌ No se pudo identificar la sesión de este bot."
      },
      {
        quoted: msg
      }
    );

  }

  console.log(
    "BOT PHONE:",
    botPhone
  );

  /*
   * ============================================================
   * CARGAR active.json
   * ============================================================
   */

  let active = {};

  try {

    if (fs.existsSync(ACTIVE)) {

      active =
        JSON.parse(
          fs.readFileSync(
            ACTIVE,
            "utf8"
          )
        ) || {};

    }

  } catch (e) {

    console.log(
      "⚠️ ERROR LEYENDO active.json:",
      e?.message || e
    );

  }

  /*
   * ============================================================
   * BUSCAR SESIÓN
   * ============================================================
   */

  let activeBot = null;
  let activeKey = null;

  for (
    const [key, value]
    of Object.entries(active || {})
  ) {

    const keyNumber =
      normalizeNumber(key);

    const jidNumber =
      normalizeNumber(value?.jid);

    if (
      keyNumber === botPhone ||
      jidNumber === botPhone
    ) {

      activeBot = value;
      activeKey = key;

      break;

    }

  }

  /*
   * ============================================================
   * BUSCAR EN db.subBots
   * ============================================================
   */

  db.subBots ??= {};

  let dbBot = null;
  let dbKey = null;

  for (
    const [key, value]
    of Object.entries(db.subBots || {})
  ) {

    const keyNumber =
      normalizeNumber(key);

    const valueNumbers = [
      value?.phone,
      value?.number,
      value?.jid,
      value?.id,
      value?.user?.id
    ]
      .filter(Boolean)
      .map(normalizeNumber);

    if (
      keyNumber === botPhone ||
      valueNumbers.includes(botPhone)
    ) {

      dbBot = value;
      dbKey = key;

      break;

    }

  }

  console.log(
    "ACTIVE KEY:",
    activeKey || "NO ENCONTRADO"
  );

  console.log(
    "DB KEY:",
    dbKey || "NO ENCONTRADO"
  );

  /*
   * ============================================================
   * OBTENER OWNER DE LA SESIÓN
   * ============================================================
   *
   * PRIORIDAD:
   *
   * 1. active.json
   * 2. db.subBots
   *
   * Si existe ownerUser, ese es el dueño.
   *
   * NO se utiliza OWNER_NUMBER del bot principal.
   *
   * ============================================================
   */

  const registeredOwner =
    activeBot?.ownerUser ||
    dbBot?.ownerUser ||
    null;

  console.log(
    "OWNER REGISTRADO:",
    registeredOwner || "NINGUNO"
  );

  /*
   * ============================================================
   * SI LA SESIÓN NO TIENE OWNER
   * ============================================================
   *
   * Esto evita que cualquiera pueda apropiarse de una sesión.
   *
   * En una sesión nueva creada con /code, manager.js ya debe
   * guardar ownerUser = sender.
   *
   * ============================================================
   */

  if (!registeredOwner) {

    console.log(
      "❌ SETBOTOWNER: sesión sin ownerUser."
    );

    return sock.sendMessage(
      jid,
      {
        text:
          "❌ Esta sesión no tiene un dueño registrado."
      },
      {
        quoted: msg
      }
    );

  }

  /*
   * ============================================================
   * COMPROBAR OWNER
   * ============================================================
   */

  if (
    !sameUser(
      realSender,
      registeredOwner
    )
  ) {

    console.log(
      "❌ SETBOTOWNER: usuario no es owner."
    );

    console.log(
      "SENDER:",
      realSender
    );

    console.log(
      "OWNER:",
      registeredOwner
    );

    return sock.sendMessage(
      jid,
      {
        text:
          "❌ No tienes permiso para usar este comando.\n\n" +
          "Solo el dueño de esta sesión puede cambiar el owner del bot."
      },
      {
        quoted: msg
      }
    );

  }

  /*
   * ============================================================
   * OBTENER NUEVO OWNER
   * ============================================================
   */

  const mentioned =
    msg?.message?.extendedTextMessage?.contextInfo?.mentionedJid ||
    [];

  const quotedParticipant =
    msg?.message?.extendedTextMessage?.contextInfo?.participant ||
    null;

  let target =
    mentioned[0] ||
    quotedParticipant ||
    null;

  target =
    normalizeJid(target);

  /*
   * También soportamos número escrito como argumento.
   *
   * Ejemplo:
   * /setbotowner 56912345678
   */

  if (!target) {

    const possibleArg =
      Array.isArray(args)
        ? args[1] || args[0]
        : "";

    if (
      possibleArg &&
      /[0-9]{7,15}/.test(
        String(possibleArg)
      )
    ) {

      const digits =
        String(possibleArg)
          .replace(/[^0-9]/g, "");

      target =
        digits +
        "@s.whatsapp.net";

    }

  }

  if (!target) {

    return sock.sendMessage(
      jid,
      {
        text:
          "◈ Menciona o responde al usuario que será el nuevo dueño."
      },
      {
        quoted: msg
      }
    );

  }

  /*
   * No permitir asignar el bot como owner.
   */

  if (
    sameUser(
      target,
      socketJid
    )
  ) {

    return sock.sendMessage(
      jid,
      {
        text:
          "❌ No puedes asignarle el owner al propio bot."
      },
      {
        quoted: msg
      }
    );

  }

  /*
   * ============================================================
   * NOMBRE DEL BOT
   * ============================================================
   */

  const botName =
    activeBot?.name ||
    dbBot?.name ||
    "Mavis";

  /*
   * ============================================================
   * GUARDAR NUEVO OWNER
   * ============================================================
   */

  const oldOwner =
    normalizeJid(
      registeredOwner
    );

  const newOwner =
    normalizeJid(
      target
    );

  /*
   * DB
   */

  if (dbBot) {

    dbBot.ownerUser =
      newOwner;

  } else {

    /*
     * Si por alguna razón active.json existe pero db.subBots
     * todavía no tiene la sesión, la registramos.
     */

    db.subBots[botPhone] = {

      ownerUser:
        newOwner,

      owner:
        dbBot?.owner ||
        jid,

      folder:
        dbBot?.folder ||
        activeBot?.folder ||
        "",

      name:
        botName,

      role:
        dbBot?.role ||
        activeBot?.role ||
        "Sub",

      status:
        dbBot?.status ||
        "connected",

      lastConnection:
        Date.now()

    };

  }

  /*
   * Si la clave de DB era diferente, también corregimos.
   */

  if (
    dbKey &&
    dbKey !== botPhone &&
    db.subBots[dbKey]
  ) {

    db.subBots[dbKey].ownerUser =
      newOwner;

  }

  saveDB();

  /*
   * ============================================================
   * active.json
   * ============================================================
   */

  try {

    if (activeBot) {

      activeBot.ownerUser =
        newOwner;

      if (activeKey) {

        active[activeKey] =
          activeBot;

      }

    } else {

      /*
       * Si no estaba en active.json pero sí tenemos información
       * de DB, creamos su entrada mínima.
       */

      active[botPhone] = {

        ownerUser:
          newOwner,

        name:
          botName,

        role:
          dbBot?.role ||
          "Sub",

        jid:
          socketJid,

        online:
          true,

        owner:
          dbBot?.owner ||
          jid,

        groups:
          []

      };

    }

    fs.mkdirSync(
      path.dirname(ACTIVE),
      {
        recursive: true
      }
    );

    fs.writeFileSync(
      ACTIVE,
      JSON.stringify(
        active,
        null,
        2
      )
    );

    console.log(
      "✓ active.json actualizado."
    );

  } catch (e) {

    console.log(
      "⚠️ ERROR GUARDANDO active.json:",
      e?.message || e
    );

  }

  /*
   * ============================================================
   * RESULTADO
   * ============================================================
   */

  console.log(
    "========================================"
  );

  console.log(
    "✓ SETBOTOWNER COMPLETADO"
  );

  console.log(
    "BOT:",
    botName
  );

  console.log(
    "BOT PHONE:",
    botPhone
  );

  console.log(
    "OWNER ANTERIOR:",
    oldOwner
  );

  console.log(
    "OWNER NUEVO:",
    newOwner
  );

  console.log(
    "========================================"
  );

  return sock.sendMessage(
    jid,
    {
      text:
        "# El dueño del bot " +
        botName +
        " ha sido cambiado de @" +
        oldOwner.split("@")[0] +
        " a @" +
        newOwner.split("@")[0],

      mentions: [
        oldOwner,
        newOwner
      ]

    },
    {
      quoted: msg
    }
  );


  }



export async function handleSetBotCurrency(
  sock,
  msg,
  sender,
  args = []
) {
  const jid = msg.key.remoteJid;

  const normalizeNumber = value =>
    String(value || "")
      .split(":")[0]
      .split("@")[0]
      .replace(/\D/g, "");

  const normalizeJid = value => {
    if (!value) return "";
    return String(value)
      .trim()
      .replace(/:.*(?=@)/, "")
      .replace(/@c\.us$/i, "@s.whatsapp.net");
  };

  const sameUser = (a, b) =>
    normalizeJid(a) === normalizeJid(b);

  /*
   * ============================================================
   * IDENTIFICAR LA SESIÓN ACTUAL
   * ============================================================
   */

  const socketNumber = normalizeNumber(
    sock.user?.id
  );

  const botPhone = socketNumber;

  if (!botPhone) {
    return sock.sendMessage(
      jid,
      {
        text:
          "❌ No se pudo identificar la sesión de este bot."
      },
      {
        quoted: msg
      }
    );
  }

  /*
   * ============================================================
   * CARGAR active.json
   * ============================================================
   */

  const ACTIVE_PATH = "./subbot-system/active.json";

  let active = {};

  try {
    if (fs.existsSync(ACTIVE_PATH)) {
      active =
        JSON.parse(
          fs.readFileSync(
            ACTIVE_PATH,
            "utf8"
          )
        ) || {};
    }
  } catch (e) {
    console.log(
      "⚠️ ERROR LEYENDO active.json:",
      e?.message || e
    );
  }

  /*
   * ============================================================
   * BUSCAR SESIÓN
   * ============================================================
   */

  let activeBot = null;
  let activeKey = null;

  for (
    const [key, value]
    of Object.entries(active || {})
  ) {
    const keyNumber =
      normalizeNumber(key);

    const jidNumber =
      normalizeNumber(value?.jid);

    if (
      keyNumber === botPhone ||
      jidNumber === botPhone
    ) {
      activeBot = value;
      activeKey = key;
      break;
    }
  }

  /*
   * ============================================================
   * BUSCAR EN db.subBots
   * ============================================================
   */

  db.subBots ??= {};

  let dbBot = null;
  let dbKey = null;

  for (
    const [key, value]
    of Object.entries(db.subBots || {})
  ) {
    const keyNumber =
      normalizeNumber(key);

    const valueNumbers = [
      value?.phone,
      value?.number,
      value?.jid,
      value?.id,
      value?.user?.id
    ]
      .filter(Boolean)
      .map(normalizeNumber);

    if (
      keyNumber === botPhone ||
      valueNumbers.includes(botPhone)
    ) {
      dbBot = value;
      dbKey = key;
      break;
    }
  }

  /*
   * ============================================================
   * OBTENER OWNER
   * ============================================================
   */

  const isMainBot =
    sock === globalThis.MAIN_BOT_SOCK ||
    !sock?.__subBotPhone;

  let registeredOwner = null;

  if (isMainBot) {
    /*
     * El bot principal utiliza el sistema de owner principal.
     * No se crea ninguna entrada dentro de db.subBots.
     */
    const senderNumber =
      normalizeNumber(sender);

    const isConfiguredMainOwner =
      isMainOwnerId(sender) ||
      senderNumber === OWNER_CONTACT_NUMBER;

    if (!isConfiguredMainOwner) {
      return sock.sendMessage(
        jid,
        {
          text:
            "❌ No tienes permiso para usar este comando.\n\n" +
            "Solo el dueño del bot principal puede cambiar la moneda."
        },
        {
          quoted: msg
        }
      );
    }
  } else {
    /*
     * Cada subbot utiliza exclusivamente el owner registrado
     * para esa sesión.
     */
    registeredOwner =
      activeBot?.ownerUser ||
      dbBot?.ownerUser ||
      null;

    /*
     * Si todavía no existe owner para esta sesión,
     * el primer usuario que configure la moneda queda
     * registrado como dueño de la sesión.
     */
    if (!registeredOwner) {
      registeredOwner = sender;

      if (activeBot) {
        activeBot.ownerUser = registeredOwner;
      }

      if (dbBot) {
        dbBot.ownerUser = registeredOwner;
      }
    }

    if (!sameUser(sender, registeredOwner)) {
      return sock.sendMessage(
        jid,
        {
          text:
            "❌ No tienes permiso para usar este comando.\n\n" +
            "Solo el dueño de esta sesión puede cambiar la moneda del bot."
        },
        {
          quoted: msg
        }
      );
    }
  }

  /*
   * ============================================================
   * VALIDAR MONEDA
   * ============================================================
   */

  const currency =
    Array.isArray(args)
      ? String(args.join(" ")).trim()
      : "";

  if (
    !currency ||
    currency.length < 4 ||
    currency.length > 20
  ) {
    return sock.sendMessage(
      jid,
      {
        text:
`❀《✧》 *ᴅᴇʙᴇs ᴇsᴄʀɪʙɪʀ ᴜɴ ɴᴏᴍʙʀᴇ ᴅᴇ ᴍᴏɴᴇᴅᴀ ᴠáʟɪᴅᴏ › ᴍíɴɪᴍᴏ 4 ⋆ ᴍáxɪᴍᴏ 20 ᴄᴀʀᴀᴄᴛᴇʀᴇs*
> ✧¡ ᴇᴊᴇᴍᴘʟᴏ › \`/setbotcurrency 𝙧፝֟𓂃𓈒☆̲❁. ❝\``
      },
      {
        quoted: msg
      }
    );
  }

  /*
   * ============================================================
   * MONEDA ANTERIOR
   * ============================================================
   */

  const oldCurrency = isMainBot
    ? (
        String(db.primaryCurrency || "oños").trim() ||
        "oños"
      )
    : (
        dbBot?.currency ||
        activeBot?.currency ||
        "oños"
      );

  /*
   * ============================================================
   * GUARDAR MONEDA
   * ============================================================
   */

  if (isMainBot) {
    /*
     * El bot principal NO es un subbot.
     * Su moneda queda guardada directamente en la base principal.
     */
    db.primaryCurrency = currency;
  } else {
    /*
     * Cada subbot conserva su propia moneda.
     */
    if (dbBot) {
      dbBot.currency = currency;
    } else {
      db.subBots[botPhone] = {
        ownerUser: registeredOwner,
        owner: jid,
        folder: activeBot?.folder || "",
        name: activeBot?.name || "Mavis",
        role: activeBot?.role || "Sub",
        status: activeBot?.status || "connected",
        lastConnection: Date.now(),
        currency
      };
    }

    if (
      dbKey &&
      dbKey !== botPhone &&
      db.subBots[dbKey]
    ) {
      db.subBots[dbKey].currency = currency;
    }

    /*
     * ============================================================
     * GUARDAR active.json
     * ============================================================
     */

    try {
      if (activeBot) {
        activeBot.currency = currency;

        if (activeKey) {
          active[activeKey] = activeBot;
        }
      } else {
        active[botPhone] = {
          ...(active[botPhone] || {}),
          ownerUser: registeredOwner,
          currency
        };
      }

      fs.mkdirSync(
        path.dirname(ACTIVE_PATH),
        {
          recursive: true
        }
      );

      fs.writeFileSync(
        ACTIVE_PATH,
        JSON.stringify(
          active,
          null,
          2
        )
      );
    } catch (e) {
      console.log(
        "⚠️ ERROR GUARDANDO active.json:",
        e?.message || e
      );
    }
  }

  saveDB();

  return sock.sendMessage(
    jid,
    {
      text:
`✐ *ᴍᴏɴᴇᴅᴀ ᴀᴄᴛᴜᴀʟɪᴢᴀᴅᴀ ᴄᴏʀʀᴇᴄᴛᴀᴍᴇɴᴛᴇ*
> ᴀɴᴛᴇʀɪᴏʀ ⇏\`${oldCurrency}\`
> ᴀʜᴏʀᴀ ⇏\`${currency}\``
    },
    {
      quoted: msg
    }
  );
}

export async function handleLogout(
  sock,
  msg,
  sender,
  args = []
){

  const jid =
    msg.key.remoteJid;

  db.subBots ??= {};
  db.primaryBots ??= {};

  const normalizeNumber =
    value =>
      String(value || "")
        .split(":")[0]
        .split("@")[0]
        .replace(/\D/g,"");

  const currentBot =
    normalizeNumber(
      sock.user?.id
    );

  const isPrivate =
    !jid?.endsWith("@g.us");

  const mainOwner =
    String(sender || "") ===
    String(OWNER_NUMBER || "");

  const secondaryOwner =
    Array.isArray(db.secondaryOwners) &&
    db.secondaryOwners.some(
      id =>
        String(id) ===
        String(sender)
    );

  const suppliedPassword =
    String(
      args?.[0] ||
      ""
    ).trim();

  const activeFile =
    path.join(
      process.cwd(),
      "subbot-system",
      "active.json"
    );

  let active = {};
  let activeData = null;
  let activeKey = null;

  try{

    if(fs.existsSync(activeFile)){

      active =
        JSON.parse(
          fs.readFileSync(
            activeFile,
            "utf8"
          )
        ) || {};

    }

  }catch(e){

    console.log(
      "ERROR ACTIVE:",
      e?.message || e
    );

  }

  for(
    const [key,value]
    of Object.entries(active)
  ){

    const keyNumber =
      normalizeNumber(key);

    const jidNumber =
      normalizeNumber(value?.jid);

    if(
      keyNumber === currentBot ||
      jidNumber === currentBot
    ){

      activeKey = key;
      activeData = value;
      break;

    }

  }

  let targetPhone = null;
  let targetData = null;

  for(
    const [phone,data]
    of Object.entries(
      db.subBots || {}
    )
  ){

    const number =
      normalizeNumber(phone);

    const valueNumber =
      normalizeNumber(
        data?.jid ||
        data?.phone ||
        data?.number
      );

    if(
      number === currentBot ||
      valueNumber === currentBot
    ){

      targetPhone = phone;
      targetData = data;
      break;

    }

  }

  if(
    !targetData &&
    activeData
  ){

    targetPhone =
      activeKey;

    targetData =
      activeData;

  }

  if(!targetData){

    return sock.sendMessage(
      jid,
      {
        text:
          " Esta sesión no está registrada como subbot."
      },
      { quoted: msg }
    );

  }

  const registeredOwner =
    String(
      targetData?.ownerUser ||
      activeData?.ownerUser ||
      ""
    );

  const storedPassword =
    String(
      targetData?.connectionPassword ||
      targetData?.password ||
      activeData?.connectionPassword ||
      activeData?.password ||
      ""
    );

  const ownerOfThisBot =
    registeredOwner &&
    registeredOwner ===
    String(sender);

  let allowed = false;

  if(mainOwner || secondaryOwner){

    if(
      !suppliedPassword ||
      !storedPassword ||
      suppliedPassword !== storedPassword
    ){

      return sock.sendMessage(
        jid,
        {
          text:
            "◈ Contraseña de conexión incorrecta."
        },
        { quoted: msg }
      );

    }

    allowed = true;

  }
  else if(ownerOfThisBot){

    if(
      suppliedPassword &&
      storedPassword &&
      suppliedPassword !== storedPassword
    ){

      return sock.sendMessage(
        jid,
        {
          text:
            "◈ Contraseña de conexión incorrecta."
        },
        { quoted: msg }
      );

    }

    allowed = true;

  }
  else{

    return sock.sendMessage(
      jid,
      {
        text:
          "◈ No tienes permiso para cerrar esta sesión."
      },
      { quoted: msg }
    );

  }

  if(!allowed){

    return sock.sendMessage(
      jid,
      {
        text:
          "◈ No tienes permiso para cerrar esta sesión."
      },
      { quoted: msg }
    );

  }

  const logoutMessage =
    await sock.sendMessage(
      jid,
      {
        text:
          "☆ Cerrando sesión... @" +
          String(sender || "").split("@")[0],
        mentions: [sender]
      },
      { quoted: msg }
    );

  globalThis.SUBBOT_LOGGING_OUT ??= new Set();
  globalThis.SUBBOT_LOGGING_OUT.add(
    String(currentBot)
  );

  sock.__logoutRequested = true;

  try{
    globalThis.SUBBOT_SOCKETS?.delete(
      String(currentBot)
    );
  }catch(e){
    console.log(
      "ERROR ELIMINANDO SOCKET DE LOGOUT:",
      e?.message || e
    );
  }

  if(
    jid?.endsWith("@g.us") &&
    db.primaryBots?.[jid]
  ){

    const primary =
      normalizeNumber(
        db.primaryBots[jid]
      );

    if(
      primary === currentBot
    ){

      let replacementPrimary = "";

      try{
        const replacement =
          Object.entries(active).find(
            ([key, value]) => {

              const keyNumber =
                normalizeNumber(key);

              const valueNumber =
                normalizeNumber(value?.jid);

              return (
                keyNumber &&
                keyNumber !== currentBot &&
                valueNumber !== currentBot &&
                value?.online === true &&
                Array.isArray(value?.groups) &&
                value.groups.includes(jid)
              );
            }
          );

        if(replacement){
          replacementPrimary =
            String(
              replacement[1]?.jid ||
              replacement[0] ||
              ""
            )
              .trim()
              .replace(/:.*(?=@)/, '')
              .replace(/@c\.us$/i, '@s.whatsapp.net');
        }
      }catch(e){
        console.log(
          "ERROR BUSCANDO PRIMARY DE REEMPLAZO:",
          e?.message || e
        );
      }

      if(replacementPrimary){
        db.primaryBots[jid] =
          replacementPrimary;

        console.log(
          "PRIMARY DE REEMPLAZO:",
          jid,
          "→",
          replacementPrimary
        );
      }else{
      delete db.primaryBots[jid];
      }

    }

  }

  try{

    for(
      const [key,value]
      of Object.entries(active)
    ){

      const keyNumber =
        normalizeNumber(key);

      const valueNumber =
        normalizeNumber(value?.jid);

      if(
        keyNumber === currentBot ||
        valueNumber === currentBot
      ){

        delete active[key];

      }

    }

    fs.mkdirSync(
      path.dirname(activeFile),
      { recursive:true }
    );

    fs.writeFileSync(
      activeFile,
      JSON.stringify(
        active,
        null,
        2
      ),
      "utf8"
    );

  }catch(e){

    console.log(
      "ERROR ACTIVE:",
      e?.message || e
    );

  }

  try{

    const sessionFolder =
      targetData?.folder ||
      path.join(
        process.cwd(),
        "subbot-system",
        "sessions",
        "sub_" + currentBot
      );

    if(
      fs.existsSync(sessionFolder)
    ){

      fs.rmSync(
        sessionFolder,
        {
          recursive:true,
          force:true
        }
      );

      console.log(
        "CARPETA ELIMINADA:",
        sessionFolder
      );

    }

  }catch(e){

    console.log(
      "ERROR SESIÓN:",
      e?.message || e
    );

  }

  for(
    const key
    of Object.keys(
      db.subBots || {}
    )
  ){

    if(
      normalizeNumber(key) ===
      currentBot
    ){

      delete db.subBots[key];

    }

  }

  saveDB();

  try{
    if(logoutMessage?.key){
      await sock.sendMessage(
        jid,
        {
          text:
            "☆ Sesion cerrada @" +
            String(sender || "").split("@")[0],
          mentions: [sender]
        },
        {
          edit: logoutMessage.key
        }
      );
    }
  }catch(e){
    console.log(
      "ERROR EDITANDO MENSAJE DE LOGOUT:",
      e?.message || e
    );
  }

  console.log(
    "LOGOUT COMPLETADO:",
    currentBot,
    "POR:",
    sender,
    "PRIVADO:",
    isPrivate
  );

  try{
    if(sock?.ws?.close){
      sock.ws.close();
    }
  }catch(e){
    console.log(
      "ERROR CERRANDO SOCKET DE LOGOUT:",
      e?.message || e
    );
  }

}

/* ============================================================
 * /ADDALIAS - AGREGAR ALIAS A SERIES
 * ============================================================
 */

export async function handleAddAlias(sock, msg, args, sender) {
  const jid = msg.key.remoteJid;

  if (!isMainOwnerId(sender) && !isSecondaryOwnerId(sender)) {
    return sock.sendMessage(jid, {
      text: "◈ Solo los owners pueden usar /addalias."
    }, { quoted: msg });
  }

  const raw = args.join(" ").trim();

  if (!raw) {
    return sock.sendMessage(jid, {
      text: "◈ Uso:\n\n/addalias Serie Oficial / alias1 / alias2\n\nEjemplo:\n\n/addalias Zenless Zone Zero / zzz / zenless"
    }, { quoted: msg });
  }

  const parts = raw.split("/").map(x => x.trim()).filter(Boolean);

  if (parts.length < 2) {
    return sock.sendMessage(jid, {
      text: "◈ Uso: /addalias Serie Oficial / alias1 / alias2"
    }, { quoted: msg });
  }

  const officialInput = parts.shift();
  const officialLower = officialInput.toLowerCase().trim();

  let officialName = null;

  for (const [key, serie] of seriesCache.entries()) {
    if (key === officialLower || String(serie.name || "").toLowerCase() === officialLower) {
      officialName = serie.name;
      break;
    }
  }

  if (!officialName) {
    const found = findSeries(officialInput);
    if (found) officialName = found.name;
  }

  if (!officialName) {
    return sock.sendMessage(jid, {
      text: "◈ La serie \"" + officialInput + "\" no existe en el sistema.\n\n> Verifica con /slist o crea la serie primero."
    }, { quoted: msg });
  }

  db.seriesAliases ??= {};
  db.seriesAliases[officialName] ??= [];

  const added = [];
  const repeated = [];

  for (const alias of parts) {
    const cleanAlias = String(alias || "").toLowerCase().trim();
    if (!cleanAlias) continue;

    if (db.seriesAliases[officialName].includes(cleanAlias)) {
      repeated.push(cleanAlias);
      continue;
    }

    db.seriesAliases[officialName].push(cleanAlias);
    added.push(cleanAlias);
  }

  saveDB();

  let texto = "✓ Alias actualizados\n\n◈ Serie »\n" + officialName + "\n\n□ Alias actuales\n\n" + db.seriesAliases[officialName].map(x => "➢ " + x).join("\n");

  if (added.length) {
    texto += "\n\n□ Agregados » " + added.length;
  }

  if (repeated.length) {
    texto += "\n◈ Repetidos » " + repeated.length;
  }

  return sock.sendMessage(jid, {
    text: texto
  }, { quoted: msg });
}
